-- ƏVVƏL sxem faylı (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.pregnancy_day_notifications AS x SET title_ka = v.t, body_ka = v.b
FROM (VALUES
  ('e07ed45f-67ec-4ce6-a8d6-4499daea0b9d'::uuid, 'ახალი მოგზაურობა იწყება! 🚀', 'თქვენი სხეული დიდი სასწაულის მისაღებად ემზადება. მზად ხართ?'),
  ('3ff0a063-2126-4cd6-a3ce-f5e944bb5487', 'ვიტამინები დაგავიწყდათ? 💊', 'ფოლიუმის მჟავა ახლა თქვენი საუკეთესო მეგობარია. მომავალი ბავშვის ჯანმრთელობის მყარი საფუძვლისთვის გადახედეთ კვების განყოფილებას!'),
  ('a2855683-73b8-4bf4-af85-cc599724b360', 'დღეს როგორ გრძნობთ თავს? 🌈', 'ახალი ეტაპის დასაწყისში თქვენი ემოციები შეიძლება შეიცვალოს. ჩაინიშნეთ დღევანდელი განცდები განწყობის დღიურში და დააკვირდით საკუთარ თავს.'),
  ('f1a0230f-d87a-49ad-b1c8-d849ef306a7f', 'ჯერ მიკროსკოპული ზომისაა 🔬', 'დიდი ამბები პაწაწინა ნაწილაკებით იწყება. ამჟამად მომავალი ბავშვი მხოლოდ იდეას ჰგავს, თუმცა მისი პოტენციალი უსაზღვროა!'),
  ('137ef65d-9ea9-410c-9d5d-bbb4811b21f8', 'დეტოქსის დროა! 🚫', 'სიგარეტი, ალკოჰოლი ან ზედმეტი კოფეინი? სწორედ ახლაა მათთან დამშვიდობების დრო. ჯანმრთელი დედა = ჯანსაღი დასაწყისი.'),
  ('f4bccccc-158d-4658-9abe-6ea45b62e469', 'წყლის ბოთლი გვერდით გაქვთ? 💧', 'თქვენი ორგანიზმის სათანადო ჰიდრატაცია ახლა ორმაგად მნიშვნელოვანია. არ დაგავიწყდეთ წყლის ყოველდღიური ნორმის მიღება.'),
  ('29fd118b-28ca-4783-a20d-0dfe1f9257be', 'დაგეგმეთ მომავალი 💭', 'არ გსურთ, ორსულობის ალბომში პირველი „საწყისი“ ფოტო ატვირთოთ?'),
  ('aa7e5901-964e-4a5b-a2e3-24bbf3210a04', 'საძირკველს ვყრით 🏗️', 'თქვენი სხეული ახალი სასწაულისთვის ემზადება, მენსტრუაცია დასასრულს უახლოვდება. მომავალი ბავშვის ჯანმრთელობის მყარი საფუძვლისთვის აუცილებელია ფოლიუმის მჟავის (B9) საკმარისი მარაგი. კვების განყოფილებაში სასარგებლო მენიუ უკვე ნახეთ? 🥑'),
  ('9e6d0515-f2ff-48ac-93ec-f1d970c7ffc2', 'ძილი ტკბილია 😴', 'ენერგიის დაგროვება გჭირდებათ. სანამ უძილო ღამეები დაიწყება, ეცადეთ, დღეში სულ მცირე 8 საათი იძინოთ.'),
  ('e9c7a1d0-36f4-4892-aa41-43d1c6c5e948', 'ჩართეთ მწვანე ძალა! 🥦', 'ისპანახი და ბროკოლი უბრალოდ ბოსტნეული კი არა, ვიტამინების ბუნებრივი წყაროა. დღეს თქვენს მენიუს აუცილებლად შემატეთ მწვანე ფერი.'),
  ('95c500c4-d966-4eca-85e3-f43263957e13', 'ექიმი უკვე შეარჩიეთ? 👩‍⚕️', 'უკვე ახლავე მოიძიეთ სპეციალისტი, რომელსაც ენდობით. საბოლოო არჩევანის გასაკეთებლად შეგიძლიათ ექიმებისა და კლინიკების განყოფილებაში შეფასებებს გაეცნოთ.'),
  ('572d6539-f881-4ec9-a3f9-b12c236e3b0d', 'თქვენი სხეული სიგნალს გაძლევთ? 🌡️', 'ოვულაციის პერიოდი ახლოვდება. დააკვირდით სხეულის ტემპერატურას — ახლა დაორსულების შანსი ყველაზე მაღალია!'),
  ('bd4effb9-20aa-4b2c-9886-28f1a8aa42f4', 'კაკლისა და ნუშის დროა 🥜', 'წასახემსებლად ჩიფსების ნაცვლად თხილეული აირჩიეთ. ომეგა-3 როგორც თქვენ, ისე თქვენს მომავალ ბავშვს სჭირდება.'),
  ('186bdc98-bb17-499f-bf7e-d9ff9eaa5492', 'დრო საკუთარ თავსაც დაუთმეთ 💆‍♀️', 'სტრესის ჰორმონებს ვიშორებთ! დღეს უყურეთ საყვარელ ფილმს ან თბილი შხაპი მიიღეთ.'),
  ('caca7263-c7a5-4d9a-92e5-c7d0658633f3', 'ყველაზე პატარა დასაწყისი 🫧', 'ჯერ შეუიარაღებელი თვალით არ ჩანს. მომავალი ბავშვი მხოლოდ ერთი უჯრედია, თუმცა დიდი გეგმები აქვს!'),
  ('c71b2b52-957c-4d0d-918e-02a81d0c792c', 'დადგა ჯადოსნური წამი? ✨', 'განაყოფიერება, ჩვეულებრივ, ამ დღეებში ხდება. მიუხედავად იმისა, რომ ამას ვერ გრძნობთ, სასწაულებრივი პროცესი უკვე დაიწყო.'),
  ('00106d30-5d19-414e-a507-c025fa6d17d2', 'ცილოვანი ბომბი 🍳', 'საუზმეზე კვერცხი გაქვთ? უჯრედების განახლებისთვის ცილა აუცილებელია. გემრიელად მიირთვით!'),
  ('ff01c295-45c4-493a-ab43-5a6c543c478d', 'გავისეირნოთ? 👟', 'სუფთა ჰაერი განწყობას აგიმაღლებთ. ვარჯიშების განყოფილებაში მსუბუქი სიარულის პროგრამა ნახეთ.'),
  ('6f8a4fbb-f3ef-409d-a1cc-75f70eff873b', 'გულისრევა გაწუხებთ? 🤢', 'დილაობით გიჭირთ? ჯანჯაფილის ჩაი ან ლიმონიანი წყალი შეიძლება დაგეხმაროთ. კუჭს ცარიელს ნუ დატოვებთ.'),
  ('d2eb5bbc-3775-4f57-aa9a-087ca149ab57', 'მნიშვნელოვანი მშენებლობა მიმდინარეობს! 🚧', 'ტვინი და ხერხემალი ყალიბდება. განაგრძეთ ფოლიუმის მჟავის მიღება!'),
  ('90d7f6db-e46c-4431-84a4-08c7cb36dff8', 'დილის გულისრევა? 🤢', 'საწოლიდან ადგომამდე მარილიანი კრეკერი მიირთვით. სისხლში შაქრის სტაბილური დონის შესანარჩუნებლად ხშირად და მცირე ულუფებით იკვებეთ.'),
  ('ee028003-7c13-49d6-a074-6279f0809a0e', 'ბაგაბუგი... გესმით? 💓', 'ჩემმა გულმა ცემა დაიწყო! მოუთმენლად ელით ამ პატარა ძრავის ხმის მოსმენას? კალენდარში პირველი ექოსკოპიის დრო მონიშნეთ! 🖊️'),
  ('b0910e0e-cc92-44f5-8046-b09a58173a6b', 'ოფიციალურად დადასტურების დროა! ✅', 'თუ ჯერ არ ყოფილხართ, ექიმთან ვიზიტზე ჩაეწერეთ. თქვენთვის შესაფერისი ექიმი „ექიმების“ განყოფილებაში იპოვეთ.'),
  ('55b6e494-7a56-4309-af7f-8fd6e4c2696c', 'გულის პირველი ცემა 💓', 'მიუხედავად იმისა, რომ ჯერ ვერ გესმით, ეს პატარა გული უკვე ამუშავდა. წუთში 100-ზე მეტჯერ ცემს!'),
  ('4268dd91-2b9a-483a-aa93-8f2b7d7809a9', 'ვიტამინი დაგავიწყდათ? 😬', 'ფოლიუმის მჟავა ჩემი მომავალი ხერხემლის საფუძველია! გადახედეთ მედიკამენტების შეხსენებას — მიიღეთ დღევანდელი დოზა? ✅'),
  ('45bd19ab-fec8-4848-87b2-8afc6fee3b1d', 'ლაქები ნორმალურია? 🩸', 'ნუ შეშინდებით, ეს შეიძლება იმპლანტაციური სისხლდენა იყოს. თუ ეჭვი გეპარებათ, გადახედეთ ექიმების განყოფილებას.'),
  ('549f62ec-94b7-42af-8ae8-87ad5504509a', 'რკინის ლედი ხართ? 🥩', 'თქვენი სისხლის მოცულობა გაიზრდება. მიირთვით წითელი ხორცი ან ოსპი და უთხარით ანემიას „სტოპ“.'),
  ('3829c3d1-13c3-4dcc-9b0a-b1c150f1dbf6', 'მღელვარე მოლოდინი... 🧘‍♀️', 'მენსტრუაციის დრო ახლოვდება. სტრესის შესამცირებლად მოუსმინეთ თეთრი ხმების განყოფილებას.'),
  ('648746b5-1de4-41ff-8fb8-976e17ef9c18', 'კალენდარს გადახედეთ? 🗓️', 'თუ მენსტრუაცია დაგიგვიანდათ, იქნებ ტესტის გაკეთების დროა? გაგვიზიარეთ სასიხარულო ამბავი!'),
  ('df6c4f91-28b1-4f7a-8ab6-64fb294a5ab9', 'სეზამის მარცვლის ზომისაა! 🌱', 'ახლა მას ოფიციალურად ემბრიონი ეწოდება. ის სწრაფად იზრდება, თქვენ კი იცვლებით.'),
  ('1466cb19-fd27-4f75-a79c-d709e1623239', 'ყაყაჩოს მარცვლის ზომის 🌱', 'ბავშვი უკვე იმკვიდრებს ადგილს თქვენს საშვილოსნოში. მიუხედავად იმისა, რომ ჯერ ძალიან პატარაა, მისი გული ფორმირებას იწყებს.'),
  ('ad5cb90c-5ee0-41f0-8e3f-90512dcf6636', 'დნმ-ის პაკეტი მზადაა! 🧬', 'ბავშვის თვალის ფერი, თმა და სქესი უკვე კოდირებულია. როგორ ფიქრობთ, ვის დაემსგავსება?'),
  ('77a7a0c4-cbc4-4060-9824-f3657b9506c0', 'კენკრის ნადიმი 🍓', 'ჟოლო თუ მარწყვი? ანტიოქსიდანტებით მდიდარი ეს ხილი თქვენს იმუნიტეტს გააძლიერებს.'),
  ('c13826a2-03b2-4512-bcfb-084ebb8c2f13', 'ჩუმი რევოლუცია მიმდინარეობს 🤫', 'განაყოფიერებული კვერცხუჯრედი თქვენს საშვილოსნოში იმპლანტირდება. შესაძლოა, ამას ვერ გრძნობდეთ, მაგრამ საოცარი პროცესი მიმდინარეობს.'),
  ('fb1313b6-50fc-44e5-80b6-0c243b450b62', 'კალციუმი ძვლებისთვის 🥛', 'რძე, იოგურტი თუ ყველი? ბავშვის მომავალი ჩონჩხისთვის დღეს აუცილებლად მიირთვით რძის პროდუქტი.'),
  ('33a29a12-915d-4926-a3e0-77d719ad233b', 'სისუსტეს გრძნობთ? ამას თავისი მიზეზი აქვს 🥱', 'პროგესტერონის დონე იმატებს. თუ საწოლი გიხმობთ, უარს ნუ ეტყვით — დაისვენეთ!'),
  ('e7c343f8-73b3-41d3-a74d-ee9ee11dc752', 'ლიმონიანი წყლის სასწაული 🍋', 'ამცირებს გულისრევას და ორგანიზმის გაწმენდას უწყობს ხელს. გაუწყლოებამ შეიძლება თავის ტკივილი გამოიწვიოს.'),
  ('06ad8151-63c5-48be-b794-51e51402550d', 'თქვენი ბატარეა იცლება? 🔋', 'შესაძლოა, ენერგია სწრაფად გამოგელიოთ. შუადღის ხანმოკლე ძილი ძალიან მოგიხდებათ.'),
  ('ae668457-885f-4308-8392-39228dd44060', 'აუზი მჭირდება! 🏊‍♀️', 'წყალს, რომელშიც ვცურავ (ამნიონურ სითხეს), თქვენ ქმნით, დედიკო. გახსენით წყლის ტრეკერი. ერთი ჭიქა წყალი დალიეთ? ✅'),
  ('d2d789ff-23ab-49d2-829b-2a59a12e57ec', 'ემოციების კარუსელი 🎢', 'ჯერ სიცილი, შემდეგ ტირილი... ჰორმონებს არ გაუგიჟებიხართ — ისინი უბრალოდ აქტიურად მუშაობენ.'),
  ('b80da43f-4fa0-465f-a1f5-d415c59577d5', 'სუნების მიმართ მგრძნობიარე ხართ? 👃', 'თავს ნუ აიძულებთ, მიირთვათ საკვები, რომელიც არ მოგწონთ. ალტერნატივებისთვის იხილეთ კვების განყოფილება.'),
  ('e7025bb0-45af-4595-8380-1e2af3adb2b9', 'ტვინი ვითარდება! 🧠', 'ნერვული მილი იხურება. არ შეწყვიტოთ ფოლიუმის მჟავის მიღება — მომავალი გენიოსის საფუძველი ახლა იყრება!'),
  ('1af4d57c-0075-4fda-8ae2-57d6f0df3dd7', 'ჯანჯაფილის ჩაი დაგეხმარებათ! 🍵', 'გულისრევა არ გეშვებათ? ჯანჯაფილი კუჭს ამშვიდებს. რეცეპტებს კვების განყოფილებაში იპოვით.'),
  ('ee6d0fe8-1439-46ca-a99d-71bece3db7ff', 'დაღლილობამ პიკს მიაღწია? 😴', 'თქვენი სხეული ენერგიის ქარხანასავით მუშაობს. შუადღის ხანმოკლე ძილი თქვენი, როგორც მომავალი დედის, უფლებაა!'),
  ('6a854983-edba-4550-9294-f82d79978af6', 'ტკბილი მუხუდოს მარცვალი 🟢', 'დაახლოებით 6 mm. ხელები და ფეხები პატარა კვირტებივით იწყებს ზრდას. პატარა მოცურავე!'),
  ('68d813b6-47ae-4b82-ac7f-506d3dacf437', 'სარბოლო მანქანასავით! 🏎️', 'მისი გული წუთში 100-160-ჯერ ცემს. თქვენსაზე ორჯერ სწრაფად! ეს ხმა თქვენთვის მუსიკასავით ჟღერს.'),
  ('1eea9abf-8e8e-49f8-aca7-b449e73948c5', 'არ დაუშვათ სისხლში შაქრის დონის დაცემა! 📉', 'ცარიელ კუჭზე გულისრევა ძლიერდება. ჩანთაში ყოველთვის იქონიეთ კრეკერი ან ჩირი.'),
  ('83b88cf3-52f6-408b-8331-beef50dfe19f', 'ტუალეტის მარათონი? 🚻', 'ტუალეტში ხშირი სიარული ნორმალურია. თქვენი თირკმელები უფრო ინტენსიურად მუშაობს. მაგრამ წყლის მიღება კი არ შეამციროთ, გაზარდეთ!'),
  ('f2d72cc5-1dfe-472f-b0dd-cab7471cb46d', 'გული გერევათ? მაპატიეთ! 🥺', 'ჰორმონები წვეულებას მართავენ და დამნაშავე მე ვარ. გაწუხებთ? მოდი, მარილიანი კრეკერები ვჭამოთ! 🍪'),
  ('d24fadf2-1d24-4001-b4cd-1006ba1390b4', 'სახე უყალიბდება 👀', 'თვალები, ცხვირი და ყურები უყალიბდება. ჯერჯერობით ისინი შავ წერტილებს ჰგავს, მაგრამ სახის ნაკვთები უკვე იკვეთება.'),
  ('98979663-767c-4d48-9b7b-786f81533442', 'სად გვხვდება ვიტამინი B6? 🍌', 'ბანანში, ავოკადოში ან ქათმის ხორცში... ამ ვიტამინმა შესაძლოა გულისრევა შეამსუბუქოს.'),
  ('b82ae448-8da6-41fb-9588-70bee70788e8', 'ფარული საცეკვაო წვეულება! 💃', 'მიუხედავად იმისა, რომ ჯერ ვერ გრძნობთ, ბავშვი უკვე მოძრაობს. მისი პირველი მოძრაობები უბრალოდ მსუბუქ თრთოლვას ჰგავს.'),
  ('32c29664-93a4-4e94-bb42-a62ada8dcf6a', 'მწნილი თუ შოკოლადი? 🥒', 'უჩვეულო სურვილები ნორმალურია. თუმცა, შაქრის რაოდენობას ყურადღება მიაქციეთ! რაციონში ჯანსაღი ალტერნატივებიც არსებობს.'),
  ('6389a83c-6f25-4ebf-a0ca-cf0883f3ce2a', 'შარვალი მოგიჭირათ? 👖', 'წონის კონტროლის განყოფილებაში საწყისი წონა მიუთითეთ? 📈'),
  ('6ff4b2b8-64a6-4583-a2a6-a17dcd93d858', 'კოფეინი შეამცირეთ? ☕', 'დღეში 1 ფინჯანზე მეტი არ შეიძლება. სცადეთ უკოფეინო ჩაი ან მცენარეული ჩაი.'),
  ('75ccffd0-f3f8-457f-9109-f503ba1c9c27', 'მე ვცეკვავ! 🕺', 'ხელები და ფეხები მეხრება. თქვენს საშვილოსნოში აკრობატიკას ვასრულებ, მაგრამ თქვენ ამას ჯერ ვერ გრძნობთ.'),
  ('471326ec-b4e0-411d-b639-63ddc151da1f', 'ბოსტნეულის სუპი? 🥣', 'თუ თქვენი კუჭი მძიმე საკვებს ვერ იღებს, მსუბუქი სუპი მიირთვით. ის ვიტამინებსაც შეიცავს და სითხესაც!'),
  ('20943f1e-d4df-412e-9bff-ad93646d91c9', 'მოძრაობისას 🧘‍♀️', 'მოძრაობა გსურთ? ვნახოთ, ვარჯიშების განყოფილებაში რა არის თქვენთვის შესაფერისი?'),
  ('3efe947d-4b4b-4c7f-9958-16d89faba8db', 'მამაც ჩართეთ 🗣️', 'ეს მხოლოდ თქვენი თავგადასავალი არ არის. ერთად ნახეთ პირველი ექოსკოპიის სურათი და სამომავლო გეგმებზე ისაუბრეთ.'),
  ('410a1e31-b41d-4130-8526-c1b0f94d7fcb', 'ღრძილები ჯერ არ მექავება... ჯერ! 😬', 'რძე, იოგურტი, ყველი... არის ეს პროდუქტები დღეს თქვენს კვების რაციონში? 🥛'),
  ('a94e0a87-fa0f-44bc-96ea-31a14e8e1954', 'თინეიჯერივით? 😳', 'სახეზე შეიძლება აკნე გაგიჩნდეთ. ეს ჰორმონების ბრალია! კანი სუფთად შეინარჩუნეთ და თვითნებურად წამლებს ნუ მიიღებთ.'),
  ('bb01f67b-68b6-46f0-9ecd-af5b6f80b28b', 'ჩვენი პირველი ფოტო გადაიღეთ? 🤰', 'გალერეაში ორსულობის მუცლის პირველი ფოტო ატვირთეთ! ✨'),
  ('a8178689-8b83-4c18-aed1-047d8befc921', 'შეკრულობა გაწუხებთ? 🚽', 'ბევრი წყალი და ბოჭკოვანი საკვები თქვენი საუკეთესო მეგობრებია. კივიმ და გარგრის ჩირმა შეიძლება სასწაული მოახდინოს.'),
  ('6fc47392-9629-4d33-8e40-e40e2521230e', 'გიჭერთ? მაპატიეთ!', 'მიუხედავად იმისა, რომ წონაში ჯერ არ მოგიმატიათ, ჩემს სახლს ვაფართოებ. მოდით, ის ვიწრო შარვალი გავიხადოთ და რაიმე კომფორტული ჩავიცვათ. 🤰'),
  ('9fae4e34-d2bb-467a-bd40-2f0853238a4e', 'მწნილი თუ შოკოლადი? 🍫', 'გადახედეთ კვების განყოფილებას — დღეს მენიუში რა სასარგებლო საკვებია? 😋'),
  ('c1f145fd-3d01-40af-8a31-7f261ae6105a', 'გემოს შეგრძნება იწყება 👅', 'ბავშვს ენაზე გემოვნების რეცეპტორები უვითარდება. ისიც შეიგრძნობს თქვენ მიერ მიღებული საკვების გემოს.'),
  ('e6b9a24b-da46-4708-9e5b-b659c3de661e', 'ხორცის სუნს გაურბიხართ? 🥩', 'ცილა აუცილებელია! თუ ხორცის ჭამა არ შეგიძლიათ, ჩაანაცვლეთ ოსპით, მუხუდოთი ან თხილეულით.'),
  ('44977c78-f7ae-4f0e-9e98-b634c325ef0b', 'ბიუსტჰალტერი გიჭერთ? 👙', 'თქვენი მკერდი იზრდება და უფრო მგრძნობიარე ხდება. დროა, კომფორტულ, სპორტული სტილის, კარკასის გარეშე ბიუსტჰალტერზე გადახვიდეთ.'),
  ('494e490f-741c-402a-90a1-087cb49feebd', 'თქვენს ორგანიზმს წყალი სჭირდება! 💧', 'წყლის ნაკლებობამ შესაძლოა თავის ტკივილი გამოიწვიოს. შედით წყლის ტრეკერში და დალიეთ ერთი ჭიქა! ✅'),
  ('91f2c1e3-6e09-405e-873b-1c7871ae42d1', 'მას უკვე ადამიანის სახე აქვს! 👶', 'თქვენს სახეზე კი ორსულობის ცნობილი ბრწყინვალება ხომ არ გამოჩნდა? ✨ უკვდავყავით ეს სილამაზე გალერეაში!'),
  ('6632cd55-3fc2-4b5a-99ae-1934d4d07a48', 'C ვიტამინის აფეთქება 🍊', 'ფორთოხალი, კივი ან წიწაკა... შეინარჩუნეთ ფოლადივით ძლიერი იმუნიტეტი — ახლა ავად გახდომა არ შეიძლება!'),
  ('0839dbbd-18f9-4a16-8c8c-024d9b6c0fb5', 'თირკმელები ამუშავდა! 🚽', 'დაუჯერებელია, მაგრამ ბავშვი უკვე შარდავს. ის ამნიონურ სითხეს ყლაპავს და გამოყოფს. ციკლი დაიწყო!'),
  ('d77d400f-027c-4514-b287-ee1cd4aff422', 'გრეიპფრუტის ზომის გახდა! 🍊', 'შესაძლოა, წელი გაგისქელდეთ. ციფრები შეიცვალა? ჩაინიშნეთ წონის მონიტორინგში! 📈'),
  ('5d87369c-e5c4-4b67-b09a-fc38d7a668d6', 'ორმაგი ტესტის დროა? 🗓️', 'ის მნიშვნელოვანია 11-14 კვირას შორის. დაუნის სინდრომის რისკის შესაფასებლად გაესაუბრეთ თქვენს ექიმს.'),
  ('9b258cde-4bf1-416d-abf2-57eb7d09c208', 'გშიათ თუ გწყურიათ? 🤔', 'ზოგჯერ ტვინს შიმშილი და წყურვილი ერთმანეთში ერევა. ჯერ ერთი ჭიქა წყალი დალიეთ. თუ ისევ გშიათ, ესე იგი, ჭამის დროა.'),
  ('827f46df-37d3-4f5e-80af-9e3b8db96d01', 'ტანვარჯიშის დროა! 🤸', 'ის უკვე მუშტებს კრავს და პირს აღებს. მართალია, ამას ვერ გრძნობთ, მაგრამ თქვენს მუცელში ნამდვილი ოლიმპიადა მიმდინარეობს!'),
  ('b247c7cf-7ded-4d8a-b64f-d3854d3be583', 'ჭკვიანი პატარა მოდის! 🧠', 'იოდი ტვინის განვითარებისთვის აუცილებელია. გაქვთ მენიუში იოდირებული მარილი, თევზი ან რძის პროდუქტები?'),
  ('9dfe8f42-50e3-422f-b528-dfdbb8ba5b68', 'ვიჭიმები! 🤸', 'თქვენც ნუ დარჩებით უმოძრაოდ, დედიკო. ვნახოთ მსუბუქი იოგის მოძრაობები ვარჯიშების განყოფილებაში?'),
  ('6d2e668d-18e8-41a3-a260-749a9ad4112f', 'კალციუმი არ მოგაკლდეთ 🥛', 'კბილის ჩანასახები ყალიბდება. ხაჭო, ყველი ან იოგურტი... ეს ყველაფერი მისი მომავალი ღიმილისთვის აუცილებელია!'),
  ('36af91e4-7cdc-478f-b431-003ca4f4075f', 'თავი გტკივათ? 🤕', 'წამლის მიღებას ნუ იჩქარებთ. შესაძლოა, ბნელ ოთახში დასვენებამ, ცივმა კომპრესმა ან მასაჟმა უკეთ გიშველოთ.'),
  ('17a77385-a0f0-43f1-b604-ef36e1b9f457', 'თქვენი სისხლის მიმოქცევა ძლიერდება! 🌊', 'სისხლძარღვებში სისხლის მოცულობა იზრდება და გული უფრო სწრაფად მუშაობს. ორგანიზმის გასაგრილებლად წყალი აუცილებელია. თავბრუ რომ არ დაგეხვათ, წყლის დალევა არ დაგავიწყდეთ! ✅'),
  ('75908864-8ad0-496c-8a26-f45ae3d7e742', 'სამშენებლო სამუშაოები მიმდინარეობს! 🏗️', 'ბავშვს კალციუმი სჭირდება! კვების განყოფილებაში რძის პროდუქტები შეამოწმეთ. 🧀'),
  ('4395d8a1-8cd6-4561-9d88-e944bb78801d', 'თევზის დღეა! 🐟', 'აირჩიეთ ვერცხლისწყლის დაბალი შემცველობის თევზი. ტვინის განვითარებისთვის ომეგა-3 შეუცვლელია.'),
  ('2ba98fa8-fbf2-4460-81c1-96e992eb2cff', 'უთხარით „არა“ სტრიებს! 🧴', 'მიუხედავად იმისა, რომ მუცელი ჯერ არ გამოგკვეთიათ, კანი დაიტენიანეთ. ნუშის ან ქოქოსის ზეთი ქავილსაც ამცირებს.'),
  ('cbca369c-5e1a-4ee2-86f1-c37e9a851106', 'დროა, საიდუმლო გაამხილოთ? 📢', 'პირველი ტრიმესტრი დასასრულს უახლოვდება. რისკი შემცირდა. მზად ხართ, სასიხარულო ამბავი მეგობრებს გაუზიაროთ?'),
  ('c3c5cda3-e24a-4bf6-8134-243e683db4d1', 'ჩონჩხი მყარდება! 🦴', 'რბილი ხრტილები ძვლებად გარდაიქმნება. შეივსეთ კალციუმის მარაგი, რომ თქვენი პატარას ძვლები ძლიერი იყოს!'),
  ('0c81e884-eb3b-459e-9e4c-250ee35d9884', 'თქვენ ოკეანეს ქმნით! 🌊', 'ამნიონური სითხე ახლდება. არ დაგავიწყდეთ ბევრი წყლის დალევა, რომ ბავშვმა სუფთა აუზში იცურაოს.'),
  ('5b178828-ade2-47ab-8de7-afb567ca7a86', 'მუცელი გექავებათ? 🌵', 'კანის გაჭიმვისას ქავილი ნორმალურია. წაისვით ნუშის ზეთი ან სპეციალური კრემი და შვება იგრძენით.'),
  ('113c2ffd-412e-42e7-9340-2d6ba48c6d05', 'ენერგია გიბრუნდებათ? 🔋', 'როგორ გრძნობთ თავს დღეს? ჩაინიშნეთ სიმპტომების დღიურში! ✅'),
  ('a2d117f1-96df-4258-ab55-9a8d07073a66', 'დედას დაგიძახებთ... 🥺', 'ჩემი ხმის იოგები ყალიბდება. ახლა ჯერ ჩუმად ვარ, მაგრამ ოცნებობთ იმ დღეზე, როცა პირველად დაგიძახებთ? მე კი ვოცნებობ...'),
  ('2743aaf7-db86-4143-a5f6-a342a96beb63', 'ბოჭკოვანი საკვები ნამდვილი გმირია 🌾', 'საჭმლის მონელების გასაუმჯობესებლად უპირატესობა მიანიჭეთ შვრიას, ბოსტნეულსა და ხილს. კვების განყოფილებაში გემრიელი სალათების რეცეპტები დაგხვდებათ.'),
  ('0aec0374-a2a9-4f72-92ad-01577161b993', 'სიმძიმეებს წევთ? 🏋️‍♀️', 'ბავშვი უკვე ცხიმის ფენას აგროვებს და მისი ჩონჩხიც მყარდება. სწრაფად ვიმატებთ წონას!'),
  ('0e8f121b-aec8-4bf1-b771-2456d0bdda0c', 'საკვების ნაკადი აჩქარდა!', 'რა სასარგებლო საკვები მიირთვით დღეს? გადაამოწმეთ კვების სია! 🥦'),
  ('e5a543f3-7d41-4d55-8690-ab14ba108363', 'თითს წოვს! 👍', 'ულტრაბგერითი გამოკვლევის დროს შეიძლება დაინახოთ, როგორ წოვს ის ცერა თითს. ასე დაბადების შემდგომი წოვის რეფლექსს ავარჯიშებს.'),
  ('1b07a663-2dbb-41a5-b9a0-2b4b252d015a', 'ცურვა გიყვართ? 🏊‍♀️', 'ის წყალში ცხოვრობს. იმისათვის, რომ ამნიონური სითხე სუფთა და საკმარისი იყოს, დღის განმავლობაში თქვენც ბევრი წყალი უნდა დალიოთ.'),
  ('4e185ebb-b0f4-4552-9a03-4a4c79c95d4f', 'ხმამაღლა ილაპარაკეთ! 🗣️', 'ბავშვს უკვე მკაფიოდ ესმის თქვენი ხმა და გულისცემა. დაიწყეთ მისთვის იავნანას სიმღერა — ეს მას ამშვიდებს. 🎶'),
  ('1228f5ed-c94b-45f8-bf5f-7e475683d6ed', 'თქვენ ნამდვილი რკინის ლედი ხართ! 🦸‍♀️', 'თავბრუსხვევა რომ არ დაგეწყოთ, მიირთვით წითელი ხორცი ან ოსპი. კვების განყოფილებაში რეცეპტებს იპოვით.'),
  ('e7c711cf-139e-409a-9191-4e2baba06f95', 'ვაშლის ზომისაა 🍎', 'შეგიძლიათ, შარვლის ღილი თამამად შეიხსნათ და მოეშვათ! 😄'),
  ('f99f033a-c9d9-464f-8a73-afdf2f8530ec', 'ღრძილებიდან სისხლი მოგდით? 😬', 'ჰორმონები ღრძილებს მგრძნობიარეს ხდის. გამოიყენეთ რბილი კბილის ჯაგრისი და გამოივლეთ მარილიანი წყალი.'),
  ('5b358e1c-fd56-41ad-b947-12dea0b15c36', 'მესმის თქვენი, დედიკო! 👂', 'ყურის ძვლები მყარდება. ბავშვი უკვე ცნობს თქვენი ხმის ტონს, სიცილსა და გულისცემას.'),
  ('e95b0195-5d3f-434c-9f11-c74aa50f4ba5', 'ბავშვის ჩონჩხი მყარდება🦴', 'თქვენი კალციუმის მარაგი რომ არ ამოიწუროს, მიირთვით რძე, იოგურტი ან ნუში.'),
  ('22f8517a-e978-4689-beff-108150f23b01', 'დაიძინეთ მარცხენა გვერდზე 🛌', 'ზურგზე წოლამ შესაძლოა სისხლის მიმოქცევა გაართულოს. მარცხენა გვერდზე წოლა თქვენც და ბავშვსაც მეტ ჟანგბადს აწვდის.'),
  ('bc8843f7-6bd5-46ee-b8a3-e7c54310c8ea', 'კაკლისა და თხილის ძალა 🐿️', 'ტვინის განვითარებისთვის ომეგა-3 მნიშვნელოვანია. ჩანთით თხილეული ატარეთ: ის დანაყრებაშიც გეხმარებათ და ბავშვის გონებრივ განვითარებასაც უწყობს ხელს.'),
  ('6b4229bd-ff86-4124-a6db-5ad3cc3444fe', 'ოქროს ხანა დაიწყო! ✨', 'გილოცავთ! მე-2 ტრიმესტრში გადახვედით. ენერგია გემატებათ, რისკი კი მცირდება. ახლა დროა, ორსულობით დატკბეთ.'),
  ('0e5bf60f-0c98-4770-8559-a9df3a31089c', 'ენერგიის ბომბი გჭირდებათ 💥', 'ბავშვი სწრაფად იზრდება. წითელი ხორცი, კვერცხი ან პარკოსნები... არ დაგავიწყდეთ რკინისა და ცილის მარაგის შევსება.'),
  ('f6a83ba0-02bc-4279-b4c0-86ed3ee5b0ed', 'ლიმონის ზომისაა! 🍋', 'დაახლოებით 7-8 სმ. მას უკვე შეუძლია თავის მობრუნება და შუბლის შეკვრაც კი. მისი მიმიკა ვითარდება!'),
  ('1a084eb2-2d29-44b6-a691-ad102b5c44de', 'გადახედეთ თქვენს გარდერობს 👗', 'ღილები აღარ იკვრება? მჭიდრო შარვლები დროებით გადადეთ. გადადით თავისუფალ, კომფორტულ და ბუნებრივი ქსოვილისგან შეკერილ ტანსაცმელზე.'),
  ('0b20c112-5b84-42c9-aa1a-637151b2cd33', 'გოგოა თუ ბიჭი? 🩷💙', 'სასქესო ორგანოები სრულად ყალიბდება. მიუხედავად იმისა, რომ ექოსკოპიაზე დანახვა ჯერ რთულია, ბავშვმა უკვე იცის, ვინ არის! თქვენ რას ფიქრობთ?'),
  ('000cbfe1-b7f7-4d1c-8e2e-4509f7ace829', 'SPA-ს დღეა? ✨', 'ბავშვის კანი წყალში რომ არ დანაოჭდეს, სპეციალური კრემითაა დაფარული. თქვენ კი? დღეს საკუთარ თავს დრო დაუთმეთ! 💆‍♀️'),
  ('bec50930-1201-4fc9-8c19-535459114067', 'სინათლე დავინახე! 💡', 'მიუხედავად იმისა, რომ ქუთუთოები დახუჭული აქვს, ბავშვი მკვეთრ სინათლეს გრძნობს. თუ მუცელზე ფანარს მიანათებთ, შესაძლოა, სახე მოარიდოს.'),
  ('2781a73f-51c3-4a91-8e1e-4ee828c3f885', 'მოერიდეთ შეკრულობას 🏃‍♀️', 'წამლის ნაცვლად ბევრი წყალი დალიეთ, მიირთვით შავი ქლიავის ჩირი და კივი.'),
  ('fcdb41b2-8b6a-4d75-be79-f72070d4756a', 'გასაღები სად არის? 🔑', 'გულმავიწყობა ნორმალურია. თქვენი ტვინი ახლა უფრო მნიშვნელოვანი საქმითაა დაკავებული: ადამიანს ქმნის! დაიწყეთ სიების შედგენა.'),
  ('2ac8ff81-e925-4d31-8ac2-6b55896aedfb', 'ფეხები გეკრუნჩხებათ? 🦵', 'ამის მიზეზი შესაძლოა მაგნიუმისა და კალციუმის დეფიციტი იყოს. მიირთვით ბანანი, ნუში ან იოგურტი. არც ბევრი წყლის დალევა დაგავიწყდეთ!'),
  ('937d5186-cb49-4a6c-a7a2-0e5731c4ae78', 'უკვე მსხლის ზომისაა! 🍐', 'სიგრძეში იზრდება და სხეული უსწორდება. უკვე შეუძლია, თავი სრულად გამართულად დაიჭიროს. ის იზრდება, თქვენ კი უფრო ლამაზდებით!'),
  ('77993f33-af63-4a22-9cb2-3af058c96f19', 'მუცელი გეჭიმებათ? 😣', 'მოულოდნელ მოძრაობებს მოერიდეთ. თბილმა შხაპმა ან მსუბუქმა მასაჟმა შესაძლოა ტკივილი შეამსუბუქოს.'),
  ('0cc5cbcc-4e89-43b3-8303-b5765d583930', 'თითის ანაბეჭდები მზადაა! 🖐️', 'ეს უნიკალური ხაზები, რომლებიც მსოფლიოში სხვას არავის აქვს, უკვე ჩამოყალიბდა. ის უკვე ინდივიდია. საოცარი არ არის?'),
  ('f36e06df-bab1-456a-b2ec-00d5e38377c7', 'ხშირად გშიათ? 😋', 'მადის მომატება კარგია, მაგრამ ორის მაგივრად ჭამა მითია. აირჩიეთ ხარისხიანი კალორიების წყაროები: თხილეული, ხილი და ბოსტნეული.'),
  ('9c22925e-f028-48cf-85a0-9499c06415cb', 'ცხვირი გაჭედილი გაქვთ? 🤧', 'ავად არ ხართ — ეს ორსულთა რინიტია. გამოიყენეთ მარილიანი წყლის სპრეი და ოთახში ჰაერი დაატენიანეთ.'),
  ('1ea8357f-773e-45c8-a5ce-b632b68c81c2', 'სწრაფი მიწოდება! 🚚', 'როცა მომშივდება, შეიძლება ბიძგებით შეგახსენო თავი. კვების განყოფილებაში დღეს რა სასარგებლო რჩევებია? 😋'),
  ('5efd10b2-de1a-4b0e-b6df-24a9fc762806', 'ცხიმოვანი შრე წარმოიქმნება 🧸', 'ბავშვი სითბოს შესანარჩუნებლად ცხიმის დაგროვებას იწყებს.'),
  ('d03c23f6-2e1d-4083-b90a-157da0e6e6f4', 'ყაბზობა არ გეშვებათ? 🚽', 'ბოჭკოვანი საკვები და ბევრი წყალი საუკეთესო წამალია. უმოძრაოდ ნუ დარჩებით — ყოველდღიური სეირნობა ნაწლავების მუშაობას აუმჯობესებს.'),
  ('0deb48f1-6a30-484b-9569-decc49f2c37c', 'ძვლები მყარდება! 🦴', 'რეზინივით რბილი ხრტილები ძვლებად გარდაიქმნება. შეივსეთ კალციუმის მარაგი, რომ ბავშვის ჩონჩხი ფოლადივით მტკიცე გახდეს!'),
  ('b9294383-8fdd-4af3-9a0e-31820d8761cf', 'თავბრუსხვევას ბოლო მოეღოს! 🛑', 'სისხლის მოცულობის ზრდასთან ერთად რკინაზე მოთხოვნილებაც იზრდება. ისპანახი, წიწიბურა ან წითელი ხორცი... აუცილებლად დაამატეთ თქვენს მენიუს!'),
  ('38d34d85-388f-49ed-9594-2287f8011443', 'მუცელში დისკოთეკაა? 💃', 'აქ შიგნით სალტოების კეთებას ვსწავლობ! იგრძენი?'),
  ('2496cef6-77ee-4345-81fb-7ae6ee89a5c4', 'უცნაურ სიზმრებს ხედავთ? 😴', 'ჰორმონებმა შეიძლება თქვენი ღამეები კინოდ აქციოს. ნუ შეგეშინდებათ, ეს ნორმალურია. ჩაიწერეთ თქვენი სიზმრები განწყობის დღიურში!'),
  ('a0a2da1d-904a-4c50-8ef1-d362ba476da8', 'ბუნებრივი კრემი უსვია! 🧴', 'კანი რომ არ დაუნაოჭდეს, ვერნიქსად წოდებული თეთრი, ყველის მსგავსი ნივთიერებით იფარება. ეს ბუნების შექმნილი დამცავი კრემია!'),
  ('d4b39ae6-9d34-4c4d-8a69-951fc75c6f59', 'ვინ არის რკინის მეგობარი? 🍊', 'თუ რკინას იღებთ, აუცილებლად მიაყოლეთ C ვიტამინი. ასე რკინა უკეთ შეიწოვება.'),
  ('9ad99447-3f71-4bc4-9dff-13a64a93c8f4', 'წელი გტკივათ? 👠', 'მაღალქუსლიანი ფეხსაცმელი კარადაში შეინახეთ — ახლა კომფორტის დროა! აირჩიეთ ორთოპედიული ფეხსაცმელი.'),
  ('a4dafbff-3c24-457e-81b5-bb659a58fa4b', 'გვერდებში დაჭიმულობას გრძნობთ? ⚡', 'შეიძლება უეცარი ჩხვლეტა იგრძნოთ, ნუ შეშინდებით — უბრალოდ ჩემს სახლს ვიფართოებ! ნახეთ დამამშვიდებელი მოძრაობები ვარჯიშების განყოფილებაში. 🤸‍♀️'),
  ('039c5d10-ebc0-436e-9936-a148242fd9a3', 'პასპორტი მზადაა! 🛂', 'თითის ანაბეჭდები სრულად ჩამოყალიბდა. ის უნიკალური ხაზები, რომლებიც მსოფლიოში სხვას არავის აქვს, უკვე მასაც აქვს. უნიკალური ადამიანი მოდის!'),
  ('f1613176-745a-48b4-a20e-1dee77f819cf', 'წყალს გემო არ აქვს? 💧', 'თუ წყლის დალევა გიჭირთ, სცადეთ კიტრის, საზამთროს ან პიტნის წყალი. გაუწყლოება თავის ტკივილს იწვევს.'),
  ('f319fe10-d32c-42c4-938c-e7358782f1f1', 'დედიკო, მესმის შენი! 👂', 'შენი ხმა იავნანასავით ჩამესმის, შენი გულისცემა კი ჩემთვის ყველაზე ლამაზი რიტმია. უფრო ხშირად მელაპარაკე, მინდა გაგიცნო.'),
  ('08cbf45e-1a2d-4043-a7ff-cbce10cda3f8', 'თუთია: ფარული გმირი 🛡️', 'ჩემი უჯრედები სწრაფად იყოფა. სამშენებლო მასალა მჭირდება! არის მენიუში წითელი ხორცი, ყველი ან თხილეული?'),
  ('08979df0-c3a9-4a97-8501-c4fbc032480c', 'უკვე მანგოს ზომის ვარ! 🥭', 'დაახლოებით 15 sm. ჩემი კანი ჯერ კიდევ თხელია, მაგრამ ცხიმოვანი შრე უკვე მიყალიბდება. ახლა უფრო ფუმფულა გამოვიყურები, დედიკო!'),
  ('9cb3f2ab-0aed-4e06-977f-d372f91e236f', 'იგრძენით? დაგარტყით! ⚽', 'დედიკო, მღვიძავს! ის მსუბუქი ფარფატი ჩემი მოკითხვაა. ხელი მუცელზე დაიდეთ, იქნებ კიდევ გავიმეორო?'),
  ('c42cae82-ff16-485c-8a26-23b4bfd30c8b', 'ბიჭი თუ გოგო? 💙💗', 'ახლოვდება ექოსკოპიის დრო, როცა ჩემი სქესის გაგებას შეძლებთ. ღელავთ?'),
  ('6ada1169-9af2-4ce3-bb7e-de40ea64dfd1', 'ჩემი პირველი სათამაშო მაქვს!', 'ჭიპლარს ხელს ვკიდებ და ვეთამაშები, ზოგჯერ კი ვუჭერ კიდეც. ჩემი თითები უკვე მოჭერას სწავლობს.'),
  ('7529d4a8-1e26-4d8b-8bcf-18154f789283', 'დიდი შეხვედრის დროა! 🗓️', '18-22 კვირა ყველაზე დეტალური ექოსკოპიის დროა. ჩემს თითებს, გულსა და ყველაფერს გულდასმით შეამოწმებენ. ექიმთან ჩაეწერეთ?'),
  ('6fb4f290-31ce-473d-a17d-ea607c5d055d', 'ბანანის ზომის ვარ! 🍌', 'დაახლოებით 18-20 სმ. ახლა უკვე თავიდან ფეხებამდე მზომავენ. ვიზრდები და ჩემი სხეულიც ფორმას იძენს.'),
  ('8731dd9d-3325-4b84-b0cd-b6cef3da8f89', 'ფსს, მე მძინავს 😴', 'მეც მაქვს ძილის რეჟიმი, დედიკო. როცა დადიხართ, ვირწევი და ვიძინებ, ხოლო როცა წვებით, ვიღვიძებ და დისკოთეკას ვაწყობ! მაპატიეთ 😇'),
  ('61323e5e-ad2b-4a40-a3f3-72d99e6d77ef', 'გზის ნახევარი გაიარეთ! 🏁', 'გილოცავთ! 20 კვირა უკვე უკან მოიტოვეთ. ორსულობის შუა ეტაპზე ხართ. საოცარი ხართ და ეს აუცილებლად უნდა აღნიშნოთ!'),
  ('5d030bf9-1346-4234-959d-a123523b7611', 'იტვირთება... 50% ⏳', 'გილოცავთ! გზის ნახევარი უკვე გავიარეთ. ამ ისტორიული დღის აღსანიშნავად გალერეას ერთი ფოტო ნამდვილად დაამშვენებდა! ✨'),
  ('5a1b20c0-b4ed-4031-8577-4c8ce7ee3faf', 'მამა ჩემს მოძრაობას იგრძნობს?', 'თუ თქვენს მუცელზე ხელს დაიდებს, იქნებ მასაც მივესალმო.❤️'),
  ('dafe2e2c-e054-4c05-a7f0-7e5828a0bd40', 'ფერად სიზმრებს ხედავთ?', 'ორსულობისას სიზმრები ფილმივითაა, არა? მეც ვარ თქვენს სიზმრებში? 😴'),
  ('5b28b973-6a08-480a-befc-a57bb7fa577b', 'რკინა მჭირდება 🏗️', 'სისხლის წითელი უჯრედების შექმნით ვარ დაკავებული. დამეხმარეთ: მიირთვით საქონლის ხორცი, ისპანახი ან ოსპი.'),
  ('323b3eda-82d0-406d-9ef8-03c3ba37648c', 'ფეხები გიშუპდებათ? 👠', 'შესაძლოა შეშუპება დაგეწყოთ. სამსახურში თუ სახლში, შეძლებისდაგვარად ფეხები მაღლა შემოაწყვეთ. შეარჩიეთ კომფორტული ფეხსაცმელი!'),
  ('e5b18866-69e0-4ac8-9b93-de4b2812e136', 'ჰიკ... ჰიკ... 🤭', 'მუცელი რიტმულად გიხტით? ნუ შეშინდებით, დედა, ეს მხოლოდ სლოკინია! დიაფრაგმას ვავარჯიშებ.'),
  ('fae74e2f-98a8-45d5-8202-44383d0eb18a', 'გემოებს არჩევს! 👅', 'ამნიონური სითხის გემო იმის მიხედვით იცვლება, თუ რას მიირთმევთ. ცხარე წიწაკა შეჭამეთ? ბავშვი ამას იგრძნობს!'),
  ('88a2f76b-bbca-49e6-a2ea-fe93e58a6be7', 'ჩემი თვალები ცეკვავენ...', 'მართალია, ქუთუთოები დახუჭული მაქვს, მაგრამ უკვე სიზმრებს ვხედავ. როგორ ფიქრობთ, რას ვხედავ სიზმარში?'),
  ('302938ba-54dd-42b1-8785-76afddeea091', 'გულძმარვა გაწუხებთ? 🔥', 'საშვილოსნო კუჭს აწვება. მიირთვით მცირე ულუფებით, მაგრამ ხშირად. ჭამის შემდეგ მაშინვე ნუ დაწვებით — გამართულად იჯექით.'),
  ('b707fa58-b376-47be-9e74-acc0d0bc553a', 'თავის მოვლის დღე 💅', 'თუ ორსულობის დროს პიგმენტური ლაქები გაგიჩნდათ, თავი მზისგან დაიცავით. რას იტყვით, დღეს სახის ნიღაბი ხომ არ გაიკეთოთ?'),
  ('b050527e-1e40-44a0-ab00-fb32d6abb570', 'საკუთარ სახეს იკვლევს! 👶', 'ხელებით სახეს, ცხვირს და ჭიპლარსაც კი ეხება. შეხების შეგრძნება უვითარდება. ის საკუთარ თავს იცნობს!'),
  ('866256da-856c-40a8-a2d6-0e562a2b89fa', 'მწნილი და ნაყინი? 🥒🍦', 'უჩვეულო საკვების კომბინაციები მოგინდათ? ეს თქვენი სხეულის სიგნალებია. თუმცა ეცადეთ, შაქარი და მარილი ზომიერად მიიღოთ.'),
  ('b5881822-5bbb-4123-8e83-7e5e1502c2a2', 'ერთი ქოქოსის ზომისაა! 🥥', 'დაახლოებით 28 სმ-ია. მისმა წონამ ნახევარ კილოგრამს გადააჭარბა! ახლა უფრო ძლიერად გირტყამთ ფეხებს.'),
  ('b4b9bd27-17f0-4aee-8b06-793656f6ef67', 'მუსიკა ჩავრთოთ? 🎶', 'დედიკო, გარედან შემოსული ხმები მესმის! მეც მიყვარს შენი საყვარელი სიმღერები. ერთად ვიცეკვოთ?'),
  ('473ac730-c42b-4a8b-8df8-3ff17fbbb8fc', 'ჭიპი წინ წამოგეწიათ? 🔘', 'მუცლის ზრდასთან ერთად ჭიპიც წინ იწევს. ნუ შეშინდებით, მშობიარობის შემდეგ ჩვეულ ფორმას დაუბრუნდება!'),
  ('3993d773-d077-4047-afc5-47cd2550cb94', 'მშობიარობის ტკივილებია თუ ვარჯიში? 🤔', 'მუცელი გეჭიმებათ? ეს შეიძლება ცრუ შეკუმშვები იყოს. საშვილოსნო მშობიარობისთვის ვარჯიშობს. თუ უმტკივნეულოა, ეს ნორმალურია.'),
  ('60d55b22-fbf7-460c-942e-d9f7e0731669', 'მოერიდეთ მარილიან საკვებს 🧂', 'თუ ფეხები გიშუპდებათ, შეამცირეთ მარილის მიღება. ბევრი წყალი და ოხრახუში შეიძლება დაგეხმაროთ. ბეჭედი თითზე ხომ არ გიჭერთ?'),
  ('6de7574a-4dcf-48fd-a091-4641ee581b82', 'პატარა ქარხანა ამუშავდა! 🏭', 'ჩემს სისხლის უჯრედებს უკვე ღვიძლის ნაცვლად ძვლის ტვინი წარმოქმნის. ჩემს დასახმარებლად, კვების რაციონში რკინით მდიდარი რომელი პროდუქტებია?'),
  ('a2eb3d0f-d97b-4159-b6ca-2c03e31ea7ae', 'ჩუმად, მძინავს... 🤫', 'დედიკო, რატომ არ ვმოძრაობ? იმიტომ, რომ დღის უმეტეს ნაწილს ძილში ვატარებ. როცა მე მძინავს, თქვენც დაისვენეთ.'),
  ('cb6d62d7-338e-4fb3-907d-9bfa587ddc19', 'ფარული ვარჯიშის დროა! 🧘‍♀️', 'კეგელის ვარჯიშები არ დაგავიწყდეთ. ჯდომისას დაჭიმეთ და მოადუნეთ მენჯის ფსკერის კუნთები. მშობიარობის დროს გამოგადგებათ!'),
  ('26be4f7a-020a-4656-9916-24ee79dcc7a2', 'სუნთქვის პირველი ვარჯიშები! 🫁', 'ჩემს ფილტვებში სურფაქტანტი წარმოიქმნება. ეს ნივთიერება დაბადების შემდეგ პირველი ჩასუნთქვის გაკეთებაში დამეხმარება. ვვარჯიშობ!'),
  ('ba959c1d-a66b-4198-9703-7d204b6d9029', 'რა ხმა იყო, დედიკო? 🔊', 'უეცარ ხმაურზე ვკრთები. როცა თქვენ მშვიდად ხართ, მეც მშვიდად ვარ. შეგიძლიათ, იავნანა მიმღეროთ?'),
  ('52571825-8dff-470b-9a01-2096ca6a9ef9', 'ჩემი აკვანი თქვენ ხართ... 💤', 'როცა დადიხართ, ვირწევი და მეძინება. გაჩერდებით თუ არა, მაშინვე მეღვიძება! ჩემს დასაძინებლად მსუბუქად სეირნობა განვაგრძოთ? 🚶‍♀️'),
  ('1184b7b9-b4b5-43fa-a2bc-fd09d7701438', 'ტკბილი წყალი დალიეთ? 🥤', 'გესტაციური დიაბეტის ტესტი მნიშვნელოვანია. როგორც ჩემი, ისე თქვენი ჯანმრთელობისთვის აუცილებლად ჩაიტარეთ.'),
  ('27ba2d28-f6c7-4448-bd98-0c87bc789c84', 'მუცელზე ხაზი გაქვთ? ➖', 'Linea Nigra ჰორმონების მოქმედების შედეგია. ნუ შეგეშინდებათ, მშობიარობის შემდეგ გაქრება. თქვენ ყოველთვის ლამაზი ხართ!'),
  ('352b7abf-9862-4591-888e-8f478b7b349c', 'ჩემი გადარჩენის შანსი გაიზარდა! 🌟', '24 კვირის გავხდი! სამედიცინო თვალსაზრისით, უკვე სიცოცხლისუნარიანად ვითვლები. ეს ძალიან მნიშვნელოვანი ეტაპია, დედიკო.'),
  ('48f71f64-0f7f-494d-bb7e-d0d4e9ee139b', 'გულძმარვა გაწუხებთ? 🔥', 'ეს იმიტომ კი არ ხდება, რომ თმა ამომდის, არამედ იმიტომ, რომ საშვილოსნო კუჭს აწვება. ჭამისთანავე ნუ დაწვებით, გამართულად იჯექით.'),
  ('20bf8c66-4b67-4eac-9759-383a08875de7', 'დედიკო, მომენატრე! 🤸', 'როცა მშვიდად ხართ, მე ვიღვიძებ. მუცელზე ხელი გადაისვით — იქნებ პატარა ბიძგით გიპასუხოთ?'),
  ('db0c5fae-71f1-477b-b321-634c423e0906', 'ნესვისოდენა გავხდი! 🍈', 'დაახლოებით 600 გრამს ვიწონი. ახლა ადგილი ცოტა მევიწროება. ჩემი ბიძგები შეიძლება უფრო ძლიერი გახდეს, მაპატიეთ! 🦶'),
  ('526f7ea7-3f69-40d2-905e-c2bffa0601cc', 'ფეხსაცმელი გიჭერთ? 👟', 'თქვენი ფეხსაცმლის ზომა შეიძლება გაიზარდოს. ახლა სტილზე მნიშვნელოვანი კომფორტია. ფართო სპორტულ ფეხსაცმელზე გადადით!'),
  ('2383cc1a-d388-4623-bfbc-9b03b5278f79', 'ჩემი თმა ფერს იძენს! 🎨', 'გენეტიკური ლატარია დაიწყო. ქერა, შავი თუ წითური? ჩემი თმის პიგმენტი ყალიბდება. თქვენი აზრით, ვის დავემსგავსები?'),
  ('d07f0b6e-c86e-44de-8e9f-d89a09f2ec43', 'შეშუპებამ თავი მოგაბეზრათ? 🎈', 'პარადოქსია: წყლის სმა შეშუპებას ამცირებს. წყლით მდიდარი პროდუქტებიც, მაგალითად, კიტრი და საზამთრო, დაგეხმარებათ. მოერიდეთ მარილს.'),
  ('fec31592-3149-479f-9be0-155a720e090b', 'ვარდისფერი ვხდები...', 'ჩემი კანი უკვე მინასავით გამჭვირვალე აღარ არის! კაპილარები სისხლით ივსება და ჩემი კანი ვარდისფერს იძენს. სისხლის მიმოქცევისთვის წყლის ტრეკერის დახმარებით წყლის დალევა არ დაგავიწყდეთ! 🥤'),
  ('5b81d2cf-3568-4e53-b14d-b0aeaec2f43f', 'მამას ხმა მესმის? 🗣️', 'მამაკაცის ხმა უფრო დაბალი ტონით ჟღერს და მე მას უკეთ ვარჩევ. დაელაპარაკეთ მამას და სთხოვეთ, ზღაპარი წამიკითხოს.'),
  ('cf9fd374-f357-4b58-bc32-9c2c7983b9f8', 'თქვენ ჩემი ფარი ხართ!', 'ჩემი იმუნური სისტემა ყალიბდება და თქვენგან ანტისხეულებს ვიღებ. დაავადებებისგან მიცავთ, დედიკო. ❤️'),
  ('6631a482-e880-499b-a108-1eb7cfe533ac', 'კრუნჩხვები გაწუხებთ? 🦶', 'ღამით წვივის კუნთი გეკრუნჩხებათ? შესაძლოა, მაგნიუმი გაკლდეთ. ბანანი, ნუში ან იოგურტი... თქვენს კუნთებს მოდუნება სჭირდება.'),
  ('67d7589f-358a-44b0-9ee8-70aca8b6ffc6', 'თვალები გავახილე! 👀', 'მიუხედავად იმისა, რომ ირგვლივ სიბნელეა, უკვე შემიძლია ქუთუთოების გახელა. წამწამებს ვაფახულებ. იმ დღემდე, როცა სამყაროს დავინახავ, სულ ცოტა დრო დარჩა!'),
  ('6a3d4aec-a08e-46ec-9845-95181acaa958', 'სინათლე შემოდის, დედიკო! ☀️', 'თვალებს ვაფახულებ! თუ თქვენს მუცელს მზის სხივი დაეცემა, ამ ნათებას ვხედავ. ნეტავ, რა ფერისაა სამყარო?'),
  ('79b3dcb1-a984-4729-ab92-c057730e6f8d', 'დატენიანების დროა 🧴', 'თქვენი მუცელი სწრაფად იზრდება და კანიც იჭიმება. ქავილის თავიდან ასაცილებლად ყოველდღე წაისვით დამატენიანებელი კრემი.'),
  ('11db6f3d-a2eb-4392-b358-993a953c992e', 'პირველი აცრა თქვენგან 🛡️', 'თქვენგან მას ანტისხეულები გადაეცემა. ეს დაბადებიდან პირველი თვეების განმავლობაში დაიცავს.'),
  ('ecec560e-f533-42fa-b81c-743ce51e2fa4', 'მწნილი კიტრი? არა! 🚫', 'თუ ფეხები გიშუპდებათ, მარილის მოხმარება მინიმუმამდე შეამცირეთ. მწნილი გემრიელია, მაგრამ შეშუპებას იწვევს. დალიეთ წყალი ლიმონით.'),
  ('eb78f9b1-0793-4172-8289-9ad69826fa75', 'სამყარო ძალიან ხმაურიანია... 🔊', 'ჩემი ყურები იმდენად მგრძნობიარე გახდა, რომ გარედან სიგნალების ხმაც კი მესმის. ცოტა დავმშვიდდეთ? თეთრი ხმებიდან წვიმის ხმა ჩამირთე და ერთად წავუძინოთ. 🌧️'),
  ('23bdc5ce-4bf9-4c06-b27f-3cf7672d0391', 'რიტმს ვაყოლებ 🥁', 'ჩემი გული თანაბრად ძგერს, მე კი სუნთქვას ვვარჯიშობ. ზოგჯერ სლოკინი მეწყება.'),
  ('486ac2e6-38fa-429a-b2e0-197066312def', 'ფინალური მონაკვეთი ახლოვდება! 🏁', 'მეორე ტრიმესტრის ბოლო დღეებია. მესამე ეტაპის დაწყებამდე კარგად გამოიძინეთ!'),
  ('2a7b5422-c620-43f8-9faf-09db6234cc0f', 'კეთილი იყოს თქვენი მობრძანება მესამე ტრიმესტრში! 🏁', 'ბოლო ეტაპი დაიწყო! ახლა თქვენი სხეული უფრო დამძიმდება, მაგრამ ფინიშის ხაზი უკვე ჩანს. მოთმინება, დედიკო!'),
  ('153927df-2197-4033-aa1c-31dfbfdf9083', 'ოჰ! ეს რა ხმა იყო? 😳', 'კარის მოჯახუნებაზე შევკრთი. ძალიან კარგი სმენა მაქვს, დედიკო. მშვიდი მუსიკა ჩართეთ და ერთად დავისვენოთ.'),
  ('4de979ce-b173-440f-bc60-e4d333797f19', 'ცხვირი გამეხსნა! 👃', 'ნესტოები დახშული მქონდა, ახლა კი გამეხსნა. სუნთქვაში ვვარჯიშობ.'),
  ('2efc37a3-7408-4f42-8512-00545c8b1565', 'მონელება შენელდა? 🐌', 'პროგესტერონი ნაწლავების მუშაობას ანელებს. გარგარის ჩირი, ქლიავის ჩირი და ქატოს პური შეიძლება თქვენს მხსნელებად იქცეს.'),
  ('32fe315d-64ad-42bb-8357-047270382c70', 'ბალიშების ციხესიმაგრე ააშენეთ! 🏰', 'კომფორტულად ვერ იძინებთ? ბალიში ფეხებს შორის და მუცლის ქვეშ მოათავსეთ. კარგი საყრდენი აუცილებელია!'),
  ('99d63bff-e50d-4a8d-89f1-525eee8af207', 'იოგას ოსტატი ვარ! 🦶', 'ვერ დაიჯერებთ, მაგრამ ფეხის თითს ვიჭერ და პირში ვიდებ! ძალიან მოქნილი ვარ. თქვენ კი დახრა გიჭირთ?'),
  ('9c19e501-078c-4145-9bf4-28096c2e69da', 'თვალები გავახილე! 👀', 'დედიკო, ვერ დაიჯერებთ, მაგრამ ქუთუთოები ავწიე. მართალია, ირგვლივ ბნელა, მაგრამ მხედველობა უკვე მიყალიბდება. თქვენს ნახვამდე ცოტა დარჩა!'),
  ('c1685f6c-ebb8-432c-88df-49144f8b19c4', 'კუჭში ხანძარია? 🔥', 'საშვილოსნო კუჭს ზემოთ აწვება. რძის დალევა ან ერთი მუჭა უმი ნუშის ჭამა გულძმარვას შეგიმსუბუქებთ.'),
  ('b119316e-3eaf-473d-92b5-cf9d282e6e05', 'ბროკოლის კონისოდენა 🥦', 'ჩემი ცხიმოვანი შრე იზრდება, ხელები და ფეხები კი მეპუტკუნება.'),
  ('0a1c9fc7-d6fb-46ee-b640-782093d821ef', 'ბუდეს ვიწყობთ? 🐣', 'ჩემი საწოლი, პატარა ტანსაცმელი... სია მამასთან ერთად „საერთო საყიდლებში“ შეადგინეთ! 📝'),
  ('f8beb64f-d6c0-4f9c-a2ac-a26ff5b8a6ea', 'თქვენი რეზუს-ფაქტორი უარყოფითია? 🩸', 'უარყოფითი რეზუს-ფაქტორის მქონე დედებისთვის ეს მნიშვნელოვანი კვირაა. შესაძლოა, იმუნოგლობულინის ინექცია დაგჭირდეთ. გაესაუბრეთ ექიმს!'),
  ('6e18672f-c08d-4df7-a33d-ffe41885dcb7', 'წამწამები დამიგრძელდა! 👁️', 'თვალებს ვახელ და ვხუჭავ. სინათლესა და სიბნელეს ერთმანეთისგან ვარჩევ. თუ მუცელზე ფანარს მიანათებთ, სახეს მივაბრუნებ. გსურთ, სცადოთ?'),
  ('382ecc0d-761f-4375-83d6-da7672e029c4', 'თევზი, თევზი, თევზი! 🐟', 'ახლა ჩემი ტვინი ყველაზე სწრაფად ვითარდება. ომეგა-3 მჭირდება. კვირაში 2-ჯერ მიირთმევთ თევზს?'),
  ('6c259c3a-0864-4b21-9205-87b10a98dab6', 'აქ ვარ, დედიკო! 👋', 'ზოგჯერ მშვიდად ვარ, ზოგჯერ კი ვცეკვავ. ჩემს ბიძგებს ითვლით? ყველაფერი რიგზეა, უბრალოდ ადგილი მევიწროვება.'),
  ('90084ac3-06b5-4f06-ab1a-792e7c238804', 'ფეხებზე ბადე გაგიჩნდათ? 🕸️', 'შესაძლოა, ვარიკოზული ვენები გაგიჩნდეთ. დიდხანს ნუ იდგებით ფეხზე. საღამოობით დაწექით და ფეხები კედელზე შემოაწყვეთ.'),
  ('7a6fc4a8-e1e2-4415-a61f-8af42944c1a1', 'სისხლის ქარხანა ამუშავდა 🩸', 'აქამდე სისხლის უჯრედებს ღვიძლი წარმოქმნიდა, ახლა კი მათ ძვლის ტვინი წარმოქმნის. ეს დამოუკიდებელი ცხოვრებისთვის მზადებაა!'),
  ('c0cb44c3-4840-4ac8-9cb6-1e444e960d76', 'რკინისა და C ვიტამინის წყვილი 🥩🍊', 'ანემიის რისკის შესამცირებლად: ხორცთან ერთად ფორთოხლის წვენი დალიეთ. C ვიტამინი რკინის შეწოვას 2-ჯერ ზრდის.'),
  ('5f837347-a4f8-48d6-bc79-6f4d3e4ab2ed', 'დიდი კომბოსტო 🥬', 'კანი გლუვი მიხდება, ლოყები კი მევსება. ერთი სული მაქვს, როდის გნახავთ!'),
  ('a1284943-8afb-4514-a518-910d7434b8db', 'სუნთქვა გიჭირთ? 😮‍💨', 'რაც უფრო ზემოთ ვიწევი, მით მეტად ვაწვები თქვენს დიაფრაგმას. სცადეთ ღრმად ჩასუნთქვა, დედიკო. ცოტაც დარჩა და ქვემოთ დავიწევ.'),
  ('283efed7-5c27-4325-a5d1-abc7b9874001', 'როგორი ხასიათი მექნება? ✨', 'ჯიუტი ვიქნები თუ მგრძნობიარე? რას ამბობს ჩემი ზოდიაქოს ნიშანი დაბადების თარიღის მიხედვით? თქვენს ზოდიაქოს ნიშანს ვეწყობი? მოდით, ვარსკვლავურ ჰოროსკოპს გადავხედოთ! 🌠'),
  ('2d850fd8-33a5-4d99-8d38-9501167a4a14', 'ნეკნები გტკივათ? 🥊', 'ბოდიში, დედიკო, ადგილი აღარ მყოფნის. როცა ფეხებს ვშლი, თქვენს ნეკნებს ვეხები. გამართულად ჯდომა შეიძლება დაგეხმაროთ.'),
  ('881c71cb-32af-4e22-9bf1-839ae870e7a5', 'ჩემს დარტყმებს ითვლით? 🦶', 'უკვე მიყალიბდება მოძრაობის რეჟიმი. შედით დარტყმების მთვლელში და თვალი ადევნეთ ჩემს აქტივობას. ყველაფერი რიგზეა?'),
  ('9d46b716-6bee-4533-9dcb-2ebd6327811f', 'ჩემს ტვინზე ნაოჭები ჩნდება! 🧠', 'ადრე გლუვი იყო, ახლა კი ნაოჭები და ღარები ჩნდება. ეს ნიშნავს, რომ მილიარდობით ნეირონი იწყებს მუშაობას. გენიოსი მოდის!'),
  ('b2fb0049-069a-46c3-bea3-307a0c34873c', 'რეფლუქსი გღლით? 🔥', 'კუჭის მჟავა ყელში ამოგდით? ჭამის შემდეგ საღეჭი რეზინის ღეჭვა ან თბილი რძის დალევა შეიძლება დაგეხმაროთ.'),
  ('88619dd2-a8e1-47a0-8257-5ec0eff6998d', 'გოგრის ზომის ვარ! 🎃', 'დაახლოებით 39-40 sm. უკვე 1.2 kq-ს ვიწონი! მძიმე ვარ თქვენთვის? ბოდიში, დედიკო, მაგრამ წონაში უნდა მოვიმატო.'),
  ('8e4d973a-778f-424e-8c3a-935a1a80329f', 'ჩანთაზე უკვე იფიქრეთ? 👜', 'ჯერ სულაც არ არის ადრე! გადახედეთ სამშობიარო ჩანთის სიას. რაც აკლია, ახლავე მოამზადეთ — ასე სტრესს შეამცირებთ.'),
  ('5e65c444-b9a6-406f-9ff5-56e21f7ef978', 'ერთ საიდუმლოს გაგიმხელთ? 🤫', 'როცა გძინავთ, თქვენი ხმის წარმოდგენაში მეც ვიძინებ. როგორ ფიქრობთ, ვის ვხედავ სიზმარში? რა თქმა უნდა, თქვენ! 🥰'),
  ('d7852d04-73e0-436f-88c1-c1f3779215e1', 'ეს შოკოლადი იყო? 🍫', 'მმმ, მისი გემო აქამდეც კი მოვიდა! ახლა ენერგიით სავსე ვარ. მოდი, ვიცეკვოთ, დედიკო! 💃'),
  ('cbb3164b-a073-4125-89bc-aa96300b8738', 'გოგრისოდენა ვარ! 🎃', 'ლოყები ისე მემრგვალება, რომ მათი მოკბეჩა მოგინდებათ! ადგილი ცოტა მაქვს, მაგრამ თქვენთან ახლოს ყოფნა სასიამოვნოა.'),
  ('24a71b37-df5d-44b3-a005-e5736c2b3038', 'თავით ქვემოთ ვდგავარ! 🙃', 'სამყაროს თავდაყირა დანახვა საინტერესოა! მშობიარობისთვის ვემზადები, დედიკო. ამ პოზაში თქვენთან კიდევ უფრო ახლოს ვარ.'),
  ('2bb496d6-7982-41e7-af5d-07497cf28d32', 'მუცელი გიმაგრდებათ? 🤰', 'ნუ გეშინიათ, ჩემო ანგელოზო! ეს მხოლოდ ვარჯიშია. ჩვენ, როგორც ერთი გუნდი, იმ დიდი დღისთვის ვემზადებით!'),
  ('6c2d3dce-218d-4319-8647-5e91a8fe5c40', 'მამას ხმა გავიგონე! 🧔', 'მის ხმას რომ ვიგონებ, გული უფრო ძლიერად მიცემს. უთხარით, რომ მეც აქ ვარ და ვესალმები! 👋'),
  ('8564b0d7-d9cc-487d-822b-1f8072415eb2', 'ჩემს ძვლებს ძალა შემატეთ! 💪', 'კალციუმი მჭირდება, დედიკო. თუ ერთ ჭიქა რძეს ან მაწონს დალევთ, ორივე სუპერძიერები გავხდებით! 🥛'),
  ('15ce00b6-4caf-41e5-8ad8-51691c8f30be', 'კაკ-კუკ! ვინ არის მანდ? ✊', 'ჩემი ბიძგები ზოგჯერ გტკენთ? მაპატიეთ 🥺 უბრალოდ მინდა, შეგეხოთ.'),
  ('b989ed16-7146-4f41-9b58-332ae708a0f2', 'სუნთქვა გიჭირთ? 😮‍💨', 'ცოტა ზემოთ ავიწიე და ფილტვებს გიჭერთ. მაპატიეთ, დედიკო, მალე ქვემოთ ჩამოვალ და თავისუფლად ამოისუნთქებთ! 🤞'),
  ('030e064d-37b0-4189-9cde-718dbc4298a7', 'თქვენს სურნელს შევიგრძნობ...', 'ფიქრობთ იმ წამზე, როცა გულში ჩამიკრავთ? მე კი ყოველდღე იმ წამზე ოცნებით ვიზრდები, დედიკო! 🌸'),
  ('e03f95b4-ad0c-4331-ae04-096968066425', 'ჩემი სახლი ვიწროვდება... 🏠', 'ჩემი მოძრაობები მუშტებისა და იდაყვების ბიძგებად იქცევა. ყველაფერი რიგზეა? მოდით, ერთად შევამოწმოთ ბიძგების მრიცხველი!'),
  ('76a21abd-5509-4070-92f1-19d3342eec20', 'სუფთა ჰაერი გჭირდებათ 🌿', 'დღეს სახლიდან გავიდეთ და მყუდრო, სუფთა ჰაერზე ჩაი დავლიოთ? გადახედეთ დედებისთვის მეგობრულ სივრცეებს!'),
  ('24bc4a35-8099-475a-bea1-67cccf403b8e', 'ის დიდი დღე... ✨', 'ნუ ვიჩქარებთ, მაგრამ ნელ-ნელა დავიწყოთ ჩანთის მომზადება. ვნახოთ, რა შედის სამშობიარო ჩანთის სიაში?'),
  ('e0c08939-6705-4af3-8c21-9e0d55be665b', 'შშშ... მე მძინავს 😴', 'ჩემი ტვინი იმდენად სწრაფად ვითარდება, რომ დროის უმეტეს ნაწილს ძილში ვატარებ. თქვენც დაისვენეთ, დედიკო.'),
  ('c28b4b45-5df1-4c21-963d-2cd627f1bb02', 'რას დამარქმევთ? 👶', 'თუ ჯერ არ გადაგიწყვეტიათ, მამასთან ერთად გადახედეთ ბავშვის სახელების სიას. რომელი სახელი მომიხდება ყველაზე მეტად?'),
  ('c121195f-505c-434b-b2d9-c9f6d23b400a', 'ჩემი ოთახი, საწოლი, პატარა ნივთები... 🐣', 'იყიდეთ ყველაფერი, რაც გვჭირდება? გადახედეთ რეკომენდებულ პროდუქტებს — იქნებ რამე გამოგრჩათ.'),
  ('c3f0f3b0-ee69-4cef-beda-1bb1348e7009', 'საშვილოსნოს კუნთები მშობიარობისთვის ემზადება.', 'ნუ შეშინდებით, ეს მხოლოდ ვარჯიშია. თუ შეკუმშვები გახშირდა, შეკუმშვების მრიცხველით შეამოწმეთ მათ შორის ინტერვალი!'),
  ('8dfa3145-c829-45b1-afeb-aa3c0845ee68', 'ჩემი მანიკიური მზადაა!', 'ვერ დაიჯერებთ, მაგრამ ჩემი ფრჩხილები უკვე თითის წვერებამდე აღწევს.'),
  ('59ee96ac-8001-4e85-87e8-bcbd686717cb', 'ექიმთან ვიზიტები გახშირდა! 🩺', 'უკვე შეარჩიეთ სამშობიარო და ექიმი? გადახედეთ ექიმებისა და კლინიკების სიას! ✅'),
  ('ca64b110-70d5-455b-a30e-4c256cab3188', 'ხან გეცინებათ, ხან გეტირებათ?', 'ჰორმონები ისევ ოინებს გიწყობენ. მშობიარობის შიში და შეხვედრის სიხარული ერთმანეთში ირევა. გული გადაუშალეთ განწყობის დღიურს და შვება იგრძენით. ❤️'),
  ('715eeefe-c617-4bf3-bb6a-6c3fba21c1f5', 'თქვენგან სუპერძალა გადმომეცემა! 🛡️', 'არ გახდეთ ავად, დედიკო! თქვენი იმუნიტეტი ჩემი პირველი ჯავშანი იქნება. ჩვენ უძლეველი გუნდი ვართ! 💪'),
  ('c1070439-01ff-45b2-8b26-5012c32a3638', 'ისევ არ გეძინებათ? 🥺', 'მე კი ტკბილად მძინავს. დახუჭეთ თვალები და ჩემზე იფიქრეთ... იქნებ სიზმარში შევხვდეთ? 🌙'),
  ('8be6aa28-e9ad-4b76-b7b7-9a3182c371dc', 'ჩემი ძვლები ქვასავით მაგრდება! 🦴', 'მაგრამ ამისთვის თქვენს მარაგს გპარავთ... მაპატიეთ! 🙈 ერთ ჭიქა რძეს თუ დალევთ, შევრიგდებით? 🥛'),
  ('80a0c6d7-ffbe-49de-90ea-da3074257deb', 'ის სიმღერა კიდევ ერთხელ იმღერეთ! 🎶', 'თქვენი ხმა ისე მამშვიდებს... როცა მღერით, აქ, შიგნით, ვცეკვავ — გრძნობთ? 💃'),
  ('8a02111b-8b8b-4912-a2f8-2e33ed9f29ac', 'კედლები სულ უფრო მავიწროებს! 🏠', 'აქ უკვე ძალიან ვიწროა, დედიკო. ფეხს რომ ვშლი, თქვენს ნეკნებს ვეხები... თუ გატკინეთ, გაკოცოთ და გაგიაროთ? 💋'),
  ('d8af3bb6-0839-43e8-86c1-22d12e84c887', 'ჩემი ტანსაცმელი დაუთოეთ? 👗', 'მათი სურნელი უკვე ცხვირში მცემს. ვიცი, ერთი სული გაქვთ, როდის მნახავთ იმ ტანსაცმელში! 🥰'),
  ('54999531-d81c-49ad-a8e5-0a766a343a4f', 'ჩემს აუზში წყალი შემცირდა... 💧', 'მე სუფთა და უხვ წყალში ცურვა მიყვარს. ჩემთვის ერთ ჭიქა წყალს დალევთ? 🥺'),
  ('2c4aee4a-e8a9-4bb3-96b6-16fd76a9994b', 'გზას ვამოწმებ! 🔦', 'თავით ქვემოთ ვარ და გასასვლელს ვუყურებ. თქვენ უბრალოდ ღრმად ისუნთქეთ, ყველაფერი შესანიშნავად იქნება!'),
  ('1f094983-199a-44c0-ba29-5474fcd1ba0b', 'ვისი თბილი ხელია? 🖐️', 'მამასია? მის შეხებას რომ ვგრძნობ, ვმშვიდდები. უთხარით, მეც ხელი მოვამზადე — ხელი ხელს შემოვკრათ! ✋'),
  ('586cf1f5-c7b6-4014-aa9e-8da51416de7e', 'თვალები ფართოდ მაქვს გახელილი! 👀', 'მართალია, აქ ბნელა, მაგრამ ყველაფერს თვალს ვადევნებ. ნეტავ თქვენ გგავართ თუ მამას? სანაძლეო ხომ არ დაგიდიათ? 😄'),
  ('450a79a5-c3df-4f37-ba9e-30274759f7a8', 'ჩშშ... მე მძინავს! 😴', 'ჩემი ტვინი იმდენად სწრაფად ვითარდება, რომ ბევრი ძილი მჭირდება. თქვენც დაიძინებთ ჩემთან ერთად, დედა? 🛌'),
  ('be58ff2d-88eb-4c07-a49c-bb64ed9da351', 'სახლში ცვლილებებს აწყობთ? 🌪️', 'გინდათ, ყველაფერი დაალაგოთ, კარადები მოაწესრიგოთ... ეს ბუდის მოწყობის ინსტინქტია! მაგრამ თავს ნუ გადაიღლით, მე დასვენებული დედა მჭირდება.'),
  ('d4a9673c-e78e-49b9-8680-f5a870142dec', 'აქ უკვე ძალიან ვიწროა! 🏠', 'გადაბრუნება მინდა, მაგრამ ადგილი აღარ მაქვს. იდაყვი რომ გამოვყო, თქვენი მუცელი ცალ მხარეს გამოიბურცება. რომ დაინახავთ, გაგეცინებათ! 😄'),
  ('ad62dd64-4e59-4e08-8d87-d88f11192fd8', 'ცხიმები მჭირდება! 🥑', 'ავოკადო, ნიგოზი ან ზეითუნის ზეთი... ჩემი ფუმფულა ლოყები თქვენს ხელშია!'),
  ('7ab48424-114b-4f93-bf60-a6a791cf5a3b', 'თქვენი გულისცემა ჩემთვის იავნანაა... 💓', 'თავით ქვემოთ ვარ და ყური თქვენს გულთან უფრო ახლოს მაქვს. ეს რიტმი ერთადერთი მუსიკაა, რომელიც მამშვიდებს.'),
  ('1eaf3d66-fce7-4349-aeaf-3af62fb5c512', 'ჩემი ოთახი მზადაა? 🧸', 'ჩემს საწოლს უყურებთ და ოცნებებში იძირებით? მოუთმენლად ველი, როდის ჩავეხუტები სათამაშოს, რომელიც იქ დამიდეთ! 🥰'),
  ('23ae0c73-2d4e-42be-98d5-a256a7fc152c', 'ქვემოთ ვეშვები, გრძნობთ? ⬇️', 'მენჯის ძვლებს შორის ვთავსდები. ახლა უფრო თავისუფლად ისუნთქებთ, მაგრამ ტუალეტში ხშირად მოგიწევთ სირბილი! 🤭'),
  ('10bb8281-56bc-44a1-b78e-8cb23edb7f86', 'ჩემი იმუნიტეტი ძლიერდება 🛡️', 'თქვენგან ჩემამდე გადმოსული ანტისხეულები მიკრობების სამყაროსთან შესახვედრად მამზადებს. თქვენი რძეც დამიცავს, დედიკო!'),
  ('2e44c870-ae65-48e2-ad71-57a350b34616', 'სად არის ჩემი პირველი ტანსაცმელი? 👕', 'საავადმყოფოს ჩანთა ჩაალაგეთ? ხელი გადაუსვით იმ პატარა კომბინეზონს, რომელსაც ჩამაცმევთ...')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.pregnancy_day_notifications AS x SET title_ka = v.t, body_ka = v.b
FROM (VALUES
  ('deba1190-6096-4dec-88eb-70e669fb3ccb'::uuid, 'თქვენი ნახვა მინდა! 👀', 'თვალები გახელილი მაქვს, მაგრამ აქ სიბნელეა. დღეებს ვითვლი, როდის ვიხილავ თქვენს სახესა და ღიმილს. სულ ცოტა დარჩა! ⏳'),
  ('eff2a55b-f3e4-4d2a-b53a-483716c9d978', 'ჩემი კანი გლუვდება! 🧖‍♀️', 'ბუსუსები მცვივა, ცხიმოვანი შრე კი მატულობს. თქვენი ნაზი შეხებისთვის ვემზადები, დედიკო. რბილი ვიქნები! ☁️'),
  ('b4ebdd4a-9196-4b7e-a71f-fdfdc053ec32', 'ძალას ვიკრებ! ⚡', 'ბევრს არ ვმოძრაობ? ნუ გეშინიათ. ახლა ძილი მჭირდება. დიდი დღისთვის ენერგიას ვაგროვებ. თქვენც დაისვენეთ! 🛌'),
  ('222ef9f4-b496-4bfc-b795-b205f25d7c39', 'ჩემი იდაყვი იგრძენით? 💪', 'მაპატიეთ, დედა! გაზმორება მინდა, მაგრამ ადგილი აღარ მაქვს. როცა თქვენი მუცელი უცნაურ ფორმებს იღებს, ჩემზე გეცინებათ? 😄'),
  ('4659f949-94b4-4bda-af43-5053a4d85dd9', 'პინგვინივით დადიხართ? 🤭', 'ჩემ დაბლა დაწევასთან ერთად თქვენი სიარულიც შეიცვალა. მაგრამ როგორიც უნდა იყოთ და როგორც უნდა დადიოდეთ, მაინც მსოფლიოში ყველაზე ლამაზი დედა ხართ! ❤️'),
  ('fa6077ec-5cef-4d3a-887a-ecb99696e48f', 'სლოკ... სლოკ... 😲', 'ისევ დამასლოკინა! დიაფრაგმას ვავარჯიშებ. თუ თქვენი მუცელი რიტმულად ხტუნავს, იცოდეთ, რომ ეს მე ვარ!'),
  ('ac593045-989b-4db2-a1c0-5cf1b85a8800', 'ექიმს შევხვდით? 👩‍⚕️', 'როცა ის ცივი გელი თქვენს მუცელს ეხება, მეღუტუნება! 🙈 მაგრამ ვიცი, რომ ჩემი გულისცემის მოსმენა სიმშვიდეს განიჭებთ.'),
  ('f1b0e4ba-30ba-4a1d-82af-0d740c3ae044', 'ჩვენ ერთი გუნდი ვართ! 🤝', 'როცა შეკუმშვები დაგეწყებათ, ნუ შეგეშინდებათ. ღრმად ჩაისუნთქეთ. ამას ერთად შევძლებთ, გპირდებით!'),
  ('8bb10475-6f0a-4fa8-839d-6d4d4f784276', 'ჩანთები კართანაა? 🎒', 'ნებისმიერ წამს შეიძლება „სიურპრიზი!“ ვთქვა. ის პირველი ქუდი, რომელიც უნდა დამახურო, ჩანთაში ჩადე? არ მინდა, შემცივდეს. 🧢'),
  ('884382e7-c971-4251-a601-ff9e5d8d7bc2', 'ფინიშამდე ცოტაღა დარჩა! 🏆', '37 კვირა სრულდება! ახლა უკვე ადრეული სრულვადიანობის პერიოდში ვართ. ანუ დღეს რომ დავიბადო, ჩემი ფილტვები უკვე მზადაა სუნთქვისთვის!'),
  ('9848ae06-dfd4-4fde-8a6f-3787325bfeb8', 'სიზმარში გნახე... 💤', 'შენი ხმა, სურნელი, სითბო... ერთი სული მაქვს, როდის გავიღვიძებ და მართლა ჩაგეხუტები, დედიკო!'),
  ('7461f26e-8ba4-4a54-a57e-84bed4745dfc', 'მუცელი დაგეჭიმათ? 🤰', 'ეს მხოლოდ ვარჯიშია თუ უკვე მოვდივარ? თუ ეჭვი გეპარებათ, შეკუმშვების ტაიმერი გახსენით. ის ზუსტად გეტყვით: საავადმყოფოში უნდა წახვიდეთ თუ დასაძინებლად დაწვეთ?'),
  ('0e2e37ee-dd10-44ae-98a1-2379b737ce2b', 'მე ჯერ კიდევ აქ ვარ! 👋', 'ძალიან ცოტა ადგილი მაქვს, ამიტომ ნაკლებად ვმოძრაობ. მაგრამ თუ ღელავთ, ბიძგების მთვლელი გახსენით. მოდი, ერთად დავითვალოთ! 🦶'),
  ('0add760f-e392-4d33-9e33-dd2c593a0a0c', 'ჩემი წინდები ჩადე? 🧦', 'არ მინდა, შემცივდეს, დედიკო! კიდევ ერთხელ გადაამოწმეთ საავადმყოფოს ჩანთის სია. ჩემი პირველი კომბინეზონი იქ არის? 🥰'),
  ('c98ad2e9-dab2-435c-b719-03a62f1368f2', 'ვერ იძინებთ? 🥺', 'ძილი არ მოგდით? მოდით, უკვე ახლა მოვუსმინოთ იმ ხმებს, რომლებსაც დაბადების შემდეგ მომასმენინებთ. „თეთრი ხმების“ განყოფილება ორივეს დაგვამშვიდებს. 🌊'),
  ('73f5c761-83f4-4b9c-ab8c-ebbbc23c1ad2', 'ჩემოდანი ჩავალაგე და კართან გელოდებით! 🚪', '38 კვირა! უკვე ოფიციალურად მზად ვარ დასაბადებლად. ჩემი ფილტვები, ტვინი და მთელი ორგანიზმი სრულად განვითარებულია.'),
  ('b02641e8-c8b3-4941-8bbc-12e86e7720ae', 'რას გააკეთებთ, თუ წყლები დაგეღვრებათ? 💦', 'არ აჰყვეთ პანიკას! ბლოგის განყოფილებაში წაიკითხეთ სტატია „მშობიარობის 3 ძირითადი ნიშანი“.'),
  ('8013f167-1549-4b4a-8e28-e01b854ddc4c', 'ქვემოთ ვიწევ... ⬇️', 'ვიცი, რომ მენჯის ძვლებზე გაწვებით. მაგრამ ეს ერთადერთი გზაა, რომ შეგხვდეთ. როგორი გამძლე ხარ, დედიკო! ❤️'),
  ('d154d2c7-ec75-47ac-ba69-4fbe92885614', 'უძილო ღამეები? 🥱', 'მშობიარობის მოახლოებასთან ერთად ჩაძინება შეიძლება გაგიჭირდეთ. ასე თქვენი სხეული ბავშვის რეჟიმისთვის გამზადებთ.'),
  ('b3effc18-3aca-4ae1-9929-0aa55b124180', 'როგორ ძგერს ჩემი გული? 💓', 'როცა მოგენატრებით, ხელი მუცელზე დაიდეთ. ჩვენი გულები ერთ რიტმში ძგერს. ყველაფერი კარგადაა, უბრალოდ შეხვედრის დღეს ველოდებით. 🗓️'),
  ('777b97b8-95e9-4f43-a5c2-c68495d48777', 'კაკ-კუკ, მე ვარ! ✊', 'მუცელში ტკივილი პერიოდულად გეწყებათ და გივლით? დრო არ დაკარგოთ — დააჭირეთ ღილაკს „შეკუმშვების მთვლელი“. თუ შუალედები მცირდება, ესე იგი დიდი დღე დღესაა! 🚑'),
  ('23425b07-63ff-4191-a065-718ed3a783d1', 'ოქროს რძე უკვე გაქვთ? ✨', 'ძუძუდან შესაძლოა მოყვითალო სითხე გამოვიდეს — ეს ხსენია, ბავშვის პირველი ბუნებრივი დაცვა. ბლოგებში წაიკითხეთ ძუძუთი კვების შესახებ. 📖'),
  ('85c5a987-f8eb-414a-99b9-ec981bbc08cd', 'ცრუ თუ ნამდვილი? 🤔', 'მუცელი გეჭიმებათ და შემდეგ გეშვებათ? თუ შეკუმშვები რეგულარული არ არის, ისინი ცრუ შეკუმშვებია. დასარწმუნებლად გახსენით „შეკუმშვების მთვლელი“ და შეამოწმეთ!'),
  ('55b51f8f-337f-485f-a7bb-0d388895d70b', 'ლორწოვანი საცობი ჩამოვიდა? 🩸', 'თუ სქელი გამონადენი შენიშნეთ, ესე იგი საშვილოსნოს ყელი გახსნას იწყებს. ნუ შეშინდებით — ეს მხოლოდ მზადების სიგნალია.'),
  ('e3c60e6b-f031-49de-9d1e-df5e6adaec56', 'შხაპ! ეს რა ხმა იყო? 💦', 'თუ სანაყოფე წყლები დაგეღვარათ, პანიკაში ნუ ჩავარდებით. უბრალოდ ღრმად ჩაისუნთქეთ და ექიმს შეატყობინეთ. მე მოვდივარ! 🌊'),
  ('a7c9fb31-732f-48c9-869e-cb25de2cc6bf', 'სტრესი უნდა განდევნოთ! 😮‍💨', 'ღელავთ? ვარჯიშების განყოფილებაში მშობიარობის დროს სუნთქვის ტექნიკები ახლავე ისწავლეთ. შეკუმშვების დროს ისინი ძალიან გამოგადგებათ.'),
  ('508da239-e1ff-41bc-b69e-7ac41310e57b', 'ჩემი ბიძგები შემცირდა? 🦶', 'ადგილი აღარ მაქვს, დედიკო! მაგრამ ჩემს მოძრაობებს უნდა გრძნობდეთ. თუ ეჭვი გეპარებათ, მიირთვით რამე ტკბილი და გახსენით ბიძგების მთვლელი.'),
  ('94a030ca-34dd-44fe-9971-596b00948ae5', 'საბუთები მზად გაქვთ? 📄', 'პირადობის მოწმობა, ანალიზების პასუხები... კიდევ ერთხელ გადაამოწმეთ ჩანთა. სამშობიარო ჩანთის სიაში ყველაფერი მონიშნეთ? ✅'),
  ('8d62f4d6-0c1f-4d76-ad37-4f81f9b3a9c0', 'დახუჭეთ თვალები... 😌', 'მშობიარობის ნუ შეგეშინდებათ. უბრალოდ წარმოიდგინეთ ის წამი, როცა პირველად ჩამიკრავთ გულში. ჩემი სურნელი ყველა ტკივილს დაგავიწყებთ.'),
  ('c87d28dc-caee-4571-989c-8e696b1ae968', 'საშვილოსნოს ყელი 🗝️', 'ფარული პროცესი მიმდინარეობს! საშვილოსნოს ყელი რბილდება, თხელდება და იხსნება. შეიძლება ამას ვერ გრძნობდეთ, მაგრამ თქვენი სხეული ჩემთვის კარს აღებს.'),
  ('76e46ae6-114d-4692-9572-4e285ec80590', 'დღეს ის დღეა? 🗓️', '40 კვირა შესრულდა! კალენდარი სწორედ დღევანდელ დღეს აჩვენებს. მოვდივარ თუ კიდევ ცოტა გაგაწვალოთ? სიურპრიზი ნებისმიერ წამს შეიძლება მოგიწყოთ! მზად იყავით! 🎁'),
  ('98686d18-af97-4647-942d-188f1dec2753', 'არ დამიგვიანია! 👑', 'უბრალოდ ვარსკვლავები სცენაზე ბოლოს გამოდიან, დედიკო! კიდევ ცოტას გაგაწვალებთ და მერე მოვალ. მოთმინება იქონიეთ! 😌'),
  ('0247f27e-7ddb-489d-b670-ca491d8ccd50', 'მე ხომ ვიმატებ წონაში! ⚖️', 'აქ გატარებულ ყოველ დღეს ცოტათი უფრო ვფუმფულდები. ლოყები უფრო საყვარელი მიხდება, თქვენ კი უფრო გიჭირთ. მაპატიეთ! 🙈'),
  ('87267b60-6c8e-4a16-ba93-8c4128e465bd', 'ჩანთაში წასახემსებელი ჩადეთ? 🍫', 'მშობიარობის შემდეგ ძალიან მოგშივდებათ! სამშობიარო ჩანთაში თქვენი საყვარელი ორცხობილა ან შოკოლადი ჩადეთ.'),
  ('8ec6da93-6997-4754-83f8-6c1f12fd0335', 'პლაცენტა ბერდება? 🍂', 'ექიმი სანაყოფე წყლების რაოდენობას ამოწმებს? თუ ჟანგბადი კვლავ მომეწოდება, ესე იგი პრობლემა არ არის. უბრალოდ, ჩვენი ბოლო დღეებია.'),
  ('5b55999e-5ad0-4f78-afa8-f94623d8adca', 'ღამით შეკუმშვები დაგეწყოთ? 🌙', 'ის ტკივილი, რომელმაც ძილიდან გაგაღვიძათ... ნამდვილი სამშობიარო შეკუმშვაა? დრო არ დაკარგოთ, შეკუმშვების მთვლელი ჩართეთ. იქნებ სწორედ ეს ღამეა ის ღამე! 🚑'),
  ('1f7612ce-6ffd-41c2-b5d1-de2a40214c65', 'ევაკუაციის ბრძანება მოვიდა? 📢', 'ექიმი მშობიარობის ხელოვნურად გამოწვევას გთავაზობთ? ნუ შეგეშინდებათ. მთავარია, თქვენს მკლავებში ჯანმრთელი და უვნებელი აღმოვჩნდე. გზას მნიშვნელობა არ აქვს!'),
  ('4f2c691b-071d-4e41-bb69-0e7f415e73df', 'თქვენი ბოლო ორსულობის ფოტო... 📸', 'ამ მუცელს უკანასკნელად შეხედეთ. ხვალ შეიძლება უკვე თქვენს მკლავებში ვიყო. იამაყეთ თქვენი სასწაულებრივი სხეულით, დედა!'),
  ('e6c910e7-1cd4-4a57-af91-421a76624e12', 'ბუნებრივი გზით დახმარება 🍍', 'ამბობენ, რომ ფინიკი და ანანასი საშვილოსნოს ყელს არბილებს. დღეს კვების განყოფილებაში თქვენს მენიუს ეს პროდუქტებიც დაამატეთ. 🥗'),
  ('0b2b54c8-9ff4-43bd-80a3-8a3a373a1975', 'გულისცემა... ❤️', '40 კვირის გადაცილებისას პლაცენტის მდგომარეობის შესამოწმებლად KTG (NST) გამოკვლევა მნიშვნელოვანია. დარწმუნდით, რომ ყველაფერი წესრიგშია.'),
  ('52d95173-f625-471a-8fd4-bc36c2714133', 'კიბეზე ავიდეთ? 🪜', 'გზა მაჩვენეთ! კიბეზე ასვლა ან ჩაჯდომები შეიძლება დამეხმაროს, რომ ქვემოთ დავეშვა. გადახედეთ ვარჯიშების განყოფილებას.'),
  ('c54d6aec-cbfd-44de-8deb-f24fc551c345', 'აქ ძალიან კარგად ვარ 🌡️', 'თბილა, ბნელა და კომფორტულია... რომ გითხრათ, გამოსვლა არ მინდა-მეთქი, ხომ არ გამიბრაზდებით? 🥺 ვხუმრობ, მოვდივარ!'),
  ('e0f642a2-57ae-48a0-88a3-c592939d5139', 'როგორ მიცემს გული? 💓', 'ექიმთან NST გამოკვლევაზე ვართ? ჩემს გუპ-გუპს რომ ისმენთ, როგორ მშვიდდებით...'),
  ('a43fd2c0-9279-47da-b7ee-4898765553ab', 'ფინიკს მიირთმევთ? 🌴', 'ბუნებრივი მშობიარობისთვის ამ გემრიელი საშუალების მოსინჯვა ღირს!')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ka = v.t, body_ka = v.b
FROM (VALUES
  ('1af46170-3a5b-41ea-bb18-ce899698f996'::uuid, 'გილოცავთ პირველ დღეს! 🥳', 'ბავშვის ძილისა და კვების რეჟიმის გასაკონტროლებლად დაიწყეთ Anacan-ის აპში არსებული ტაიმერის გამოყენება.'),
  ('96187549-321c-4f4b-8ab6-e849804b2e3f', 'დაისვენეთ, სანამ თქვენს ბავშვს სძინავს! 😴', 'არ დაგავიწყდეთ, განწყობის დღიურში ჩაწეროთ, როგორ გრძნობთ თავს დღეს.'),
  ('c21d305d-a798-46f7-a57b-5ee7fc159b60', 'ხსენი პირველი ვაქცინაა! 🤱', 'აპში არსებული კვების კონტროლის ხელსაწყოს მეშვეობით მარტივად აღრიცხეთ კვების ნორმა.'),
  ('1de2111f-1bc3-4ba2-9e4a-c85aa4453abb', 'ნუ მოიწყენთ იმის გამო, რომ ცოტა რძე გაქვთ! 🥛', 'თქვენი ბავშვის კუჭი ჯერ ალუბლის ზომისაა. კვების ყოველდღიური სტატისტიკის ნახვა აპში შეგიძლიათ.'),
  ('75f8bf1f-a1b6-48ed-8282-db88f2b4b621', 'დაუთმეთ დრო საკუთარ თავს. 💆‍♀', '️ თქვენი საშვილოსნოს კუნთები აღდგენის პროცესშია. განტვირთვისთვის დღევანდელი ემოციები განწყობის დღიურში ჩაიწერეთ.'),
  ('ee814c6a-2fd2-46fc-a3a3-6fece315052e', 'ბავშვის კანზე არსებული თეთრი ფენა მას იცავს. 👶 ნუ შეშფოთდებით.', 'საფენის შეცვლისას არ დაგავიწყდეთ, ეს Anacan-ში აღრიცხოთ და ნორმები შეამოწმოთ!'),
  ('0ed5afeb-bfa9-4fba-a6c1-40d487f8789c', 'თქვენი ბავშვის წოვის რეფლექსი ძალიან ძლიერია! 🍼', 'კვების თითოეული მონაკვეთი ტაიმერით აკონტროლეთ, რათა დარწმუნდეთ, რომ ბავშვი საკმარისად დანაყრდა.'),
  ('da08e82c-f1b1-4615-9a78-803ac91a2d92', 'უმიზეზოდ გეტირებათ? 😢', 'ეს სრულიად ბუნებრივია! შეგიძლიათ, თქვენი გრძნობები Anacan AI-ს ან ჩვენს საზოგადოებას გაუზიაროთ და მხარდაჭერა მიიღოთ.'),
  ('fee5ed13-dd9c-4182-b62b-254289a55cec', 'ბავშვის დაძინება გიჭირთ? 🎶', 'ჩართეთ ჩვენს აპში თეთრი ხმაურის ფუნქცია, რათა თქვენს ბავშვს ისეთივე ღრმა ძილით დაეძინოს, როგორც დედის მუცელში.'),
  ('45b225f1-1304-44c7-93ed-fd6649d6138a', 'ჭიპლარი მშრალი და სუფთა უნდა დარჩეს. ⏱️', 'თუ ჭიპლარი დასველდა, აუცილებლად უნდა გაამშრალოთ და ყოველდღიურად გამოიყენოთ ექიმის მიერ დანიშნული ანტისეპტიკური ხსნარი.'),
  ('a63353e6-5360-4f33-ba4b-ae8f83d9831a', 'დედებისთვის ვიტამინებით მდიდარი კვება ძალიან მნიშვნელოვანია! 🥗', 'გაეცანით ჯანსაღი რეცეპტების განყოფილებას და აღიდგინეთ ძალები.'),
  ('e8719824-5aaa-4cf3-a9a0-c265fa3bf36c', 'ბავშვი სუნითა და ხმით გცნობთ! 👃', 'ამიტომ, როცა ოთახიდან გადიხართ, თქვენი ბავშვი მოუსვენრად გრძნობს თავს და საფრთხეს აღიქვამს.'),
  ('28500aa6-3ac1-4fd2-a987-e74e0b2bccb8', 'არ დაიჯეროთ მითი, რომ ბავშვი ხელში აყვანას მიეჩვევა! 🤗', 'ხშირად ჩაეხუტეთ. ეს თქვენს კავშირსაც გააძლიერებს და რძის რაოდენობასაც გაზრდის.'),
  ('2df49d87-7d2b-44bb-bb5a-a25b24863389', 'დღე და ღამე აერია? 🛌', 'ძილის რეჟიმსა და ყოველდღიურ ნორმებს აპლიკაციაში ადევნეთ თვალი, ხოლო როცა მას სძინავს, თქვენც დახუჭეთ თვალები.'),
  ('2e317973-be56-4e35-b4da-81c9dc7b1f3d', 'გეგმური შემოწმებები იწყება. 💉', 'შეიყვანეთ თქვენი ბავშვის სიმაღლისა და წონის მონაცემები განვითარების ტრეკერში და შექმენით მისი განვითარების ინდივიდუალური გრაფიკი!'),
  ('6401ca5a-6403-42c9-b967-6741dd863d7c', 'ტაიმერი აქ არის, რათა შუალედები არ დაგავიწყდეთ. 🍼', 'საფენის გამოცვლისა და კვების დრო მარტივად დაგეგმეთ Anacan-ის დახმარებით.'),
  ('c61401b5-5ca0-4aea-9f3d-ce4b09083a8c', 'თქვენ არ ხართ ვალდებული, სუპერდედა იყოთ! 🦸‍♀', '️ დახმარების თხოვნას ნუ მოერიდებით. მოტივაციისთვის წაიკითხეთ სტატიები ჩვენს ბლოგების განყოფილებაში.'),
  ('ded576fe-d3fa-4078-9b83-36eaf5b495d5', 'თვალი ადევნეთ განვითარებას ნაბიჯ-ნაბიჯ. 📏', 'დაგავიწყდათ თავის გარშემოწერილობის, სიმაღლისა და წონის მონაცემების წონის ტრეკერში შეყვანა? შეიყვანეთ ახლავე.'),
  ('3258a482-400c-485d-af7c-ccb221416732', 'ღამით გაღვიძება გღლით? 😴', 'განწყობის დღიურში დღევანდელი გრძნობები ჩაინიშნეთ და Anacan AI სასარგებლო რჩევებს მოგცემთ.'),
  ('80a2cd79-a6d6-4c87-b540-c42931228485', 'თქვენი ბავშვის კუჭი იზრდება. 🍒', 'კვების კონტროლის ხელსაწყოთი ჩაინიშნეთ, რამდენი მიირთვა ბავშვმა და შეამოწმეთ მისი დღიური ნორმა.'),
  ('cdd7b6ae-f340-479e-9d33-221c6775ebb3', 'ბავშვს მჭიდროდ ნუ გაახვევთ — თავისუფლად იმოძრაოს! 🚫', 'სასარგებლო ინფორმაციისა და თანამედროვე მიდგომების შესახებ მეტის წასაკითხად ეწვიეთ ჩვენს ბლოგებს.'),
  ('1b82205e-3e0a-48f0-abf7-dac783f4bce8', 'თქვენი რძე უკვე უფრო კალორიულ, მწიფე რძედ გარდაიქმნება. 🥛', 'ჩართეთ ძუძუთი კვების ტაიმერი და ზუსტად განსაზღვრეთ, რამდენი ხანი იკვება თქვენი ბავშვი დღეს!'),
  ('9a18572b-e386-4df8-ba20-b5eb78b8f99f', 'როგორ ჩაიარა პირველმა 10 დღემ? 📸', 'უძილობა, შიშები, ზოგჯერ ცრემლები და სიყვარულის დიდი ქარიშხალი... პირველი 10 დღე — ყველაზე რთული დასაწყისი — უკვე უკან მოიტოვეთ! თქვენ საოცარი ხართ.'),
  ('ffd7ff0c-bf80-4552-8a28-8d30f0674b07', 'დღეს 15 წუთი მაინც დაუთმეთ მხოლოდ საკუთარ თავს. 🛁', 'მიიღეთ თბილი შხაპი და თავი აპლიკაციაში მოცემული ჯანსაღი რეცეპტებით გაინებივრეთ.'),
  ('0240c7db-30e2-4d5b-86a4-0b27f230557c', 'მამის მკლავები 🫂', 'პირველი კვირის დაღლილობა უკვე ძვლებშიც გაქვთ გამჯდარი. ამ საღამოს ბავშვი მამამ დაიძინოს მკერდზე და თეთრი ხმები ჩართოს. თქვენ კი თბილი შხაპი მიიღეთ და დახურულ კარს მიღმა, სულ რაღაც 15 წუთით, წყლის ქვეშ ყველაფერი დაივიწყეთ. თქვენ ამას შეძლებთ.'),
  ('7449500c-dd2f-4529-a9a7-67ddeee4fe31', 'მუცელზე წოლის დროა! 🐢', 'სიფხიზლის დროს ბავშვი 1-2 წუთით მუცელზე დააწვინეთ, რათა კუნთები გაუმაგრდეს.'),
  ('74dae015-c762-4d96-ad34-7d706065ef5f', 'გილოცავთ, უკვე 1 კვირის დედა ხართ! 🥳', 'გილოცავთ, უკვე 1 კვირის დედა ხართ! 🥳 ისარგებლეთ ბავშვის ფოტოსესიის განყოფილებით და ამ განსაკუთრებული დღის სამახსოვრო ფოტო შექმენით.'),
  ('7c7a5fbe-09ea-4f4c-a054-883ad490f939', 'გადავხედოთ პირველი კვირის მონაცემებს? 📊', 'გსურთ, Anacan აპში ძილის, საფენების გამოცვლისა და კვების ყოველკვირეული სტატისტიკა შეამოწმოთ?'),
  ('d06a4b75-fad1-4ee5-9c5c-c70d98373c0c', 'ფიზიკური აღდგენა 🩹', 'თქვენი სხეული ჯერ კიდევ აღდგენის პროცესშია და შესაძლოა, ნაკერებიც გტკიოდეთ. საკუთარ თავს სრულყოფილებას ნუ მოსთხოვთ.'),
  ('d83a6f20-2dc5-45c9-9550-38fedec5c042', 'ნაწლავის მიკროფლორა ყალიბდება! 🦠', 'თუ ბავშვს აირების გამო ჭვალი ეწყება, Anacan-ის თეთრი ხმების განყოფილებაში მოცემული რიტმები მის დამშვიდებაში დაგეხმარებათ.'),
  ('092f30cd-002d-4c4e-a83e-0b13c38cc743', 'თქვენი ბავშვის მხედველობა უფრო მკაფიო ხდება! 👀', 'ის უკვე უკეთ არჩევს თქვენს სახეს. ჩაიწერეთ განწყობის დღიურში, რა ემოციებს იწვევს თქვენში ეს სასიამოვნო წუთები.'),
  ('20684bd3-d3fb-479e-89f1-9adf84e485af', 'როგორ მიდის კვების რუტინა? 🤱', 'ჩართეთ აპლიკაციაში ტაიმერი და კვების მონიტორინგის ხელსაწყოს საშუალებით მარტივად აკონტროლეთ კვების ნორმა.'),
  ('7797557a-9277-450c-98b3-b0fa58923513', 'საღამოს აბაზანის შემდეგ ძილის დროა! 🛁', 'იმისთვის, რომ თქვენმა ბავშვმა მშვიდად დაიძინოს, ღამის ძილის წინ მისი დაბანა ძალიან სასარგებლოა.'),
  ('8c6679da-fafd-4f32-9db9-54953d4a08fe', 'აკონტროლებთ დღიურად გამოცვლილი საფენების რაოდენობას? 🧷', 'საფენები საუკეთესო მაჩვენებელია იმისა, რომ ბავშვი საკმარისად იკვებება. ყოველი გამოცვლისას არ დაგავიწყდეთ ამის Anacan-ში აღნიშვნა!'),
  ('bbcb238e-ee32-4e4b-a429-0c4d99613140', 'გავაანალიზოთ ძილის რეჟიმი. ⏱️', 'როდესაც ბავშვს სძინავს, ჩართეთ ძილის ტაიმერი და გრაფიკზე ნახეთ, რამდენად შეესაბამება მისი ძილი ყოველდღიურ ნორმას.'),
  ('c8038ed4-40d8-4c96-b84d-dd22d681496c', 'გემრიელი და სასარგებლო არჩევანი დედებისთვის! 🍲', 'გაეცანით ჯანსაღი რეცეპტების განყოფილებას, რომელიც ენერგიის აღდგენაში დაგეხმარებათ, და იზრუნეთ საკუთარ თავზე.'),
  ('2ef0546f-a471-4ef1-833d-3a8427b3c92c', 'თქვენი ბავშვი სწრაფად იზრდება! ⚖', '️ ყოველკვირეული წონა შეიყვანეთ განვითარების მონიტორში და აპლიკაციაში თვალყური ადევნეთ მისი ჯანსაღი ზრდის მრუდს.'),
  ('84bd0c91-57d2-4afc-a090-33645f6c3336', 'რაიმე შეკითხვა გაქვთ? 🤖', 'Anacan AI ღამის საათებშიც თქვენ გვერდითაა! დასვით თქვენთვის საინტერესო შეკითხვები და დაუყოვნებლივ მიიღეთ დახმარება.'),
  ('ba7edb24-6da8-4a69-9b59-da2faf81dfa6', 'პირველი გასეირნებები ერთად! 🌳', 'თუ კარგი ამინდია, გარეთ გადით. ძალიან მნიშვნელოვანი და სასარგებლოა, რომ თქვენმა ბავშვმა ყოველდღე ისუნთქოს სუფთა ჰაერი.'),
  ('0d572d8d-fc2a-4534-aab4-0054197f9297', 'უკვდავყავით ეს წამი! 📸', 'დღევანდელი საყვარელი მომენტები ბავშვის ალბომში ატვირთეთ და შექმენით მოგონებები, რომლებსაც მომავალში ღიმილით გაიხსენებთ.'),
  ('2c1d3bb2-7e3e-4938-89fb-c5a7a19e27a2', 'ბალანსი ძილსა და კვებას შორის. 📚', 'უკვე წაიკითხეთ ბლოგების განყოფილებაში ჩვენი უახლესი სტატია ახალშობილთა განვითარების შესახებ?'),
  ('7bc61271-cc44-4b34-a12b-faa852a23b6c', 'გილოცავთ, თქვენი ბავშვი უკვე 2 კვირისაა! 🎈', 'ამ პატარა იუბილეს აღსანიშნავად გამოიყენეთ ბავშვის ფოტოსესიის განყოფილებაში შემოთავაზებული საინტერესო თემები.'),
  ('78429eb3-1c37-4e59-ba1f-884cf298f9f6', 'ზოგჯერ კვებას შეიძლება მეტი დრო დასჭირდეს. 🍼', 'ტაიმერის გამოყენებით გააანალიზეთ პროცესი. მთავარია, თქვენც და თქვენი ბავშვიც თავს კომფორტულად გრძნობდეთ.'),
  ('ade4c5f5-2712-4328-ae1d-961b6a95f615', 'როგორ გრძნობთ თავს? 🧘‍♀', '️ დედობა მშვენიერიცაა და დამღლელიც. შედით განწყობის დღიურში და შეაფასეთ დღევანდელი დღე.'),
  ('da011889-3632-43ce-aa11-c46cc9ffe260', 'რა გაკლიათ ბავშვის მოვლისთვის? 🧴', 'სხვა დედების მიერ გამოცდილი და მოწონებული პროდუქტები იპოვეთ რეკომენდებული პროდუქტების განყოფილებაში.'),
  ('515f484e-8ce4-4442-bca4-24b38a77b194', 'საფენის გამოცვლა უკვე რუტინის ნაწილია! 👶', 'ყოველდღიურად მონიშნეთ შარდვა და განავალი საფენების ტრეკერში, რათა აკონტროლოთ თქვენი ბავშვის ჯანმრთელობა.'),
  ('76b75bd8-766d-4f01-b3d1-e6a56e5ad949', 'დედამაც უნდა დაისვენოს! 🛋', '️ თუ ბავშვის ძილის რეჟიმი ტაიმერით აღრიცხეთ, ახლა თქვენი ჯერია. დაისხით ჩაი და დაისვენეთ.'),
  ('7e8ac4ba-1fc8-4ac4-92f2-b519b8fbd60b', 'ბავშვს აირები აწუხებს? 🌪️', 'ნუ აჰყვებით პანიკას. ნაზად დაუმასაჟეთ მუცელი და ყურადღების გადასატანად ფონურად ჩართეთ თეთრი ხმაური.'),
  ('228ed9a7-6c09-4e18-b632-934b4149caf5', 'მუცელზე წოლის დროა! 🐢', 'დღეში რამდენიმე წუთით მუცელზე წოლა ბავშვის კისრის კუნთებს აძლიერებს.'),
  ('b42303f7-3c77-46e1-97e5-9a1b1e60430c', 'ღამის ძილისთვის მომზადება. 🌙', 'დაძინებამდე დაარეგულირეთ ოთახის ტემპერატურა და ჩართეთ Anacan-ის ძილის ტაიმერი.'),
  ('f833f5dd-8e28-4c1e-a3cb-e9f3a3133ca5', 'რძის რაოდენობის გაზრდის საიდუმლოებები! 🥛', 'ჯანსაღი რეცეპტების განყოფილებაში რძის გამომუშავების ხელშემწყობი ბუნებრივი პროდუქტები და სმუზის რეცეპტები გელოდებათ.'),
  ('403b119e-e637-45fc-b072-cf84725abb35', 'შესაძლოა, განვითარების ნახტომია. 📈', 'უმიზეზოდ ხმამაღლა ტირის? მე-3 კვირის განვითარების ნახტომი ასევე ემთხვევა პერიოდს, როდესაც გაზებით გამოწვეული ჭვალი პიკს აღწევს. ნუ შეშინდებით.'),
  ('844e0b7f-c62a-4e7b-b863-965ea3061be3', 'მუდამ ხელში ყოფნა 🛋️', 'როგორც კი ბავშვს საწოლში აწვენთ, იღვიძებს და ტირის? დღეს შეიძლება თავი ოთხ კედელს შორის გამოკეტილად და ბავშვის მუდმივად ხელში ჭერისთვის განწირულად იგრძნოთ. მაგრამ გახსოვდეთ, რომ თქვენი ბავშვისთვის ყველაზე უსაფრთხო ადგილი თქვენი მკლავებია. მოთმინება გამოიჩინეთ.'),
  ('f3dc49b8-e32b-422e-80b3-e76c0488dc0f', 'პროცესში თქვენი მეუღლეც ჩართეთ. 👨‍👩‍👦', 'ამ საღამოს საფენის გამოცვლა ან თეთრი ხმაურის ფონზე ბავშვის დაძინება მას მიანდეთ, თავად კი დაისვენეთ.'),
  ('04916f68-94af-484d-968d-c1e05636c373', 'კანის მოვლის დროა. 🛁', 'ეძებთ თქვენი ბავშვის მგრძნობიარე კანისთვის შესაფერის კრემებს? რეკომენდებული პროდუქტების სია დაგეხმარებათ.'),
  ('17096c26-bde5-4bba-9013-08a06133ab4f', 'რეფლექსები ვითარდება! 🖐️', 'რამდენად მაგრად გიჭერთ თქვენი ბავშვი თითზე? მეტი ინფორმაციის მისაღებად გაეცანით ჩვენს სტატიებს ბლოგში.'),
  ('d935b5ec-1166-4c5b-a013-19977086a00b', 'თქვენი ყოველდღიური ანგარიში მზადაა! 📊', 'შედით Anacan აპში და გაეცანით ძილის, კვებისა და საფენების გამოცვლის დღევანდელი გრაფიკების ანალიზს.'),
  ('4ad69c28-25c9-4155-a875-498e8858786c', 'თვალს ვადევნებთ ზრდის ეტაპს! 📏', 'მომდევნო თვე ახლოვდება. შედით აპის განვითარების მონიტორინგის განყოფილებაში და დარწმუნდით, რომ მონაცემები განაახლეთ.'),
  ('58f18841-d6c8-49e1-84e7-3ca2b96787a6', 'უკვე 20 დღეა, რაც ერთად ხართ! 🥰', 'თქვენ შესანიშნავი დედა ხართ! ბავშვის ფოტოსესიის ხელსაწყოთი ეს დღე ლამაზ მოგონებად აქციეთ.'),
  ('e9631c46-1105-44f2-b850-b1671ee6df45', 'დღეს მხოლოდ დადებითი ემოციები! ✨', 'გახსენით განწყობის დღიური და ჩაინიშნეთ მომენტი, როცა თქვენმა ბავშვმა ყველაზე მეტად გაგაცინათ. Anacan AI გისმენთ!'),
  ('1961895f-8e5d-4529-9dd1-eba3d3c72045', 'განვითარების ნახტომის პერიოდია! 📈', 'თქვენს ბავშვს შეიძლება უფრო ხშირად მოშივდეს. კვების ტაიმერის საშუალებით აკონტროლეთ და თვალყური ადევნეთ პროცესს.'),
  ('2450c51d-55f8-4e27-b691-cd2f503d7dd4', 'საღამოს მოუსვენრობა იმატებს? 🎶', 'ამის მიზეზი შეიძლება აირებისგან გამოწვეული ტკივილი ან დაღლილობა იყოს. დაამშვიდეთ იგი თეთრი ხმაურის განყოფილებაში მოცემული ბუნების ხმებით.'),
  ('43caac7d-8fec-4815-a021-c436856ae779', 'ზუსტად 3 კვირისაა! 🎉', 'ბავშვის ამ პატარა იუბილეს აღსანიშნავად გამოიყენეთ ბავშვის ფოტოსესიის განყოფილება და საყვარელი მომენტი სამუდამოდ აღბეჭდეთ.'),
  ('2421fc4d-6878-4078-87b3-b7d35e8743ea', 'ნუ დაივიწყებთ საკუთარ თავს! 🥗', 'თქვენი ჯანმრთელობა მისი ჯანმრთელობაა. ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან აირჩიეთ ენერგიის აღმდგენი წასახემსებელი.'),
  ('4600773a-c43e-4163-a5da-2b2294833f5c', 'ძილის დღიური ნორმა მნიშვნელოვანია. 😴', 'როდესაც ბავშვს სძინავს, ჩართეთ ძილის ტაიმერი და შეამოწმეთ, რამდენად შეესაბამება მისი ძილი დღიურ ნორმას.'),
  ('bd3843ff-7d20-45e7-9e12-a76db028322e', 'თავის აწევას ცდილობს! 🐢', 'მუცელზე წოლისას (tummy time) შესრულებული მოძრაობები ვიდეოს სახით დაამატეთ ბავშვის ალბომში.'),
  ('592aca51-491e-44f3-b426-3734a638d0f9', 'კითხვა გაქვთ? 🤖', 'რატომ იღვიძებს ღამით ხშირად? — ასეთ და სხვა თქვენთვის საინტერესო კითხვებზე პასუხის გასაცემად Anacan AI ყოველთვის მზადაა.'),
  ('70951e1d-e161-4f61-adb6-2b3b015c6f79', 'როგორია საფენების ყოველდღიური რაოდენობა? 🧷', 'იმის გასაგებად, იღებს თუ არა თქვენი ბავშვი საკმარის საკვებს, ყველაზე მარტივი გზა საფენის გამოცვლის ჩანაწერების წარმოებაა. დაამატეთ ჩანაწერი აპლიკაციაში ახლავე!'),
  ('9b230269-a517-40c2-a23b-f2bd57a211d4', 'პირველი ღიმილი ახლოვდება! 😊', 'არ გამოგრჩეთ მომენტები, როცა ბავშვი თქვენს სახეს ყურადღებით აკვირდება. ამ წუთებით გამოწვეული ემოციები განწყობის დღიურში ჩაიწერეთ.'),
  ('6b6f1411-38ea-47b2-b82b-7ec0af1fa9ed', 'ვიწყებთ დღის რეჟიმის ჩამოყალიბებას! 🌙', 'აბანავეთ და ძუძუთი კვებეთ ყოველდღე ერთსა და იმავე დროს, ჩართეთ თეთრი ხმები და გაუშვით ძილის ტაიმერი.'),
  ('b2ff3f80-95a8-44a7-96b9-573095f4b7ba', 'ნუ დაივიწყებთ თქვენს საჭიროებებს დედობის პერიოდში. 🛍', '️ძუძუსთავების კრემი და მკერდის საფენები თავს უფრო კომფორტულად გაგრძნობინებთ და საჭირო დაცვასაც უზრუნველყოფს.'),
  ('ef4b3736-bd78-46e0-af19-3bceb15bf443', 'სუფთა ჰაერზე გასეირნების დროა! ☀️', 'ეძებთ ბავშვთან ერთად წასასვლელად შესაფერის ადგილს, სადაც კომფორტულად დაისვენებთ? აუცილებლად გაეცანით ჩვენს ბლოგს დედებისთვის მეგობრული ადგილების შესახებ.'),
  ('498afb20-12cf-4e99-872a-93ae66ffadf8', 'როცა დრო გექნებათ, წაიკითხეთ და ისწავლეთ. 📚', 'ახალშობილთა განვითარებისა და მოვლის შესახებ ყველაზე სასარგებლო სტატიები ბლოგების განყოფილებაში გელოდებათ.'),
  ('a1d43ae2-7007-4910-b05d-6c1d71529cf9', 'პირველი თვის შემოწმება ახლოვდება. ⚖️', 'დარწმუნდით, რომ თქვენი ბავშვის წონისა და სიმაღლის მატება განვითარების მონიტორინგის განყოფილებაში გაქვთ აღრიცხული.'),
  ('eabf6802-121e-4850-8036-ab2dbabaf84e', 'ნუ მოგერიდებათ თქვენი გრძნობების გაზიარება. 📝', 'დაღლილი ხართ თუ ბედნიერი? მნიშვნელობა არ აქვს — ჩაინიშნეთ დღევანდელი ემოციები განწყობის დღიურში და შვება იგრძენით.'),
  ('2b4adff1-6ebf-471c-9dc4-e4e39cc16323', 'ყურადღება უმახვილდება! 👀', 'ის უკვე უკეთ არჩევს შავ-თეთრ კონტრასტულ ფერებს. მუცელზე წოლის დროს არ დაგავიწყდეთ განმავითარებელი ბარათების გამოყენება.'),
  ('5e1b47e3-2994-433f-a7c8-b1e6a121de30', 'დაგავიწყდათ, რომელი ძუძუდან აჭამეთ? 🤱', 'ტაიმერის საშუალებით მონიშნეთ მარჯვენა ან მარცხენა ძუძუ, კვების მონიტორინგის ინსტრუმენტი კი ყველაფერს დაიმახსოვრებს!'),
  ('8152dc55-7f72-41b2-bb12-02cf7745f75a', 'პროცესში მამებსაც ვრთავთ! 👨‍🍼', 'პარტნიორის რეჟიმის საშუალებით მამებსაც შეუძლიათ, ბავშვის განვითარებას თვალი ადევნონ.'),
  ('77ad5a07-cc0a-4fb4-b323-d177412300b1', 'თქვენი კვირის სტატისტიკა მზადაა! 📊', 'შედით აპში და გააანალიზეთ, ბოლო დღეებში რამდენად იცავდით ძილისა და კვების ნორმებს.'),
  ('8fac7e6d-3d63-4646-99a7-c927a088e849', 'სუფთა ჰაერი მადას აუმჯობესებს! 🌳', 'ეცადეთ, ბავშვი ყოველდღე სუფთა ჰაერზე გაიყვანოთ. ეს ძალიან სასარგებლოა როგორც თქვენთვის, ისე თქვენი ბავშვისთვის.'),
  ('dd0fbf42-9f2a-4cb9-8c66-db4c46ee2124', 'გაიუმჯობესეთ რძის ხარისხი. 🍲', 'ჯანსაღად და გემრიელად კვებისთვის გაეცანით აპში განყოფილებას „ჯანსაღი რეცეპტები“.'),
  ('15d59560-fd44-4273-9de7-62fd70c1a0dd', '1 თვის მაჩვენებლები! 📏', 'სიმაღლისა და წონის ახალი მონაცემები დაამატეთ განვითარების ტრეკერში, გადახედეთ ჯანსაღი ზრდის გრაფიკს და იამაყეთ.'),
  ('22b47ac3-665d-4f67-b497-67efe6238be4', 'გილოცავთ, უკვე 1 თვის გავხდით! 🥳', 'ამ მნიშვნელოვანი დღის აღსანიშნავად შექმენით საინტერესო ფოტოები განყოფილებაში „ბავშვის ფოტოსესია“.'),
  ('ed8acfc1-dd31-48da-a8f2-04bd91f60de7', 'მადლობა გადაუხადეთ საკუთარ თავს! 💖', 'პირველი და ყველაზე რთული თვე უკან მოიტოვეთ. შედით განწყობის დღიურში და აღნიშნეთ ამ თვეში გამოჩენილი თქვენი გმირობა.'),
  ('2037f6e8-905d-4847-8172-fdba3ba09cf5', 'საღამოს რუტინა ირღვევა? 🌙', 'არ ინერვიულოთ. თეთრი ხმებიდან გულისცემის ხმა აირჩიეთ, რათა ბავშვმა თავი ისეთივე დაცულად იგრძნოს, როგორც დედის მუცელში.'),
  ('63fcc8ee-0343-4d14-8f0d-e6d98a5377e8', 'ზოგჯერ უბრალოდ შესვენება გვჭირდება. ☕', 'სანამ თქვენს ბავშვს სძინავს, ჩართეთ ძილის ტაიმერი და მშვიდი დრო საკუთარ თავს დაუთმეთ.'),
  ('b61a8e62-d1c0-449f-9d5b-6bb72079c512', 'ფხიზლად ყოფნის დრო იზრდება. ⏱️', 'მასთან სათამაშოდ და მისი განვითარების ხელშესაწყობად წაიკითხეთ თამაშების რეკომენდაციები ბლოგების განყოფილებაში.'),
  ('111e6f27-8aef-4cfb-a5ab-60fea52474e0', 'მზადება მომდევნო თვისთვის. 🛒', 'თუ ახალი თვისთვის შესაფერის საფენებსა და მოვლის საშუალებებს ეძებთ, რეკომენდებული პროდუქტები აუცილებლად დაგეხმარებათ.'),
  ('713d2aac-0316-483d-9c46-781631bb7e21', 'თქვენ არაჩვეულებრივი დედა ხართ! ✨', 'უკვე 30 დღეა, რაც ერთად ხართ. ბავშვის ალბომში დაამატეთ კოლაჟი, რომელიც პირველ დღესა და დღევანდელობას შორის განსხვავებას აჩვენებს.'),
  ('ef07a5ff-817b-4b0a-ad2a-706e799bad22', 'ახალი თვე, ახალი გვერდი. 📊', 'გადახედეთ კვების, ძილისა და საფენების ყოველთვიურ სტატისტიკას და ნახეთ, როგორ შესანიშნავად ჩამოუყალიბეთ ბავშვს რეჟიმი!'),
  ('5bfad78e-cb6a-405d-8517-a356018909ca', 'როგორია სიმაღლისა და წონის მატება? 📏', 'განვითარების მონიტორინგის განყოფილებაში შეიყვანეთ ახალი მაჩვენებლები და გააანალიზეთ ბავშვის განვითარების ინდივიდუალური გრაფიკი.'),
  ('d87d1938-6445-47b1-b0eb-19c7a9941726', 'სუფთა ჰაერის ძიებაში! 🌳', 'ბავშვთან ერთად კომფორტულად გასასეირნებლად აირჩიეთ ახლომდებარე ადგილი, სადაც საბავშვო ეტლით შესვლა შესაძლებელია.'),
  ('fa1d2aaa-c80f-46e8-82ed-6c8fa2ce54f1', 'Anacan AI ყოველთვის თქვენს გვერდითაა! 🤖', 'ძილის რეჟიმის შესახებ კითხვები გაქვთ? მისწერეთ ჩვენს ხელოვნურ ინტელექტს და პასუხს დაუყოვნებლივ მიიღებთ.'),
  ('0ac0ad4d-776b-416d-a345-c0bddd639ff1', 'ყურადღების კონცენტრირების უნარი უმჯობესდება! 👀', 'დააკვირდით, როგორ აყოლებს თვალს ოთახში არსებულ საგნებს. განვითარების შესახებ მეტის წასაკითხად ეწვიეთ ბლოგებს.'),
  ('1a8980b4-ba5e-4179-adce-580423431a55', 'ძილის ნორმების ცოდნა მნიშვნელოვანია. ⏱️', 'როცა ბავშვს სძინავს, ჩართეთ ძილის ტაიმერი და ნახეთ, იცავს თუ არა ის ძილის დღიურ ნორმას.'),
  ('c7ce3717-a6e8-4d86-ba21-d6964fb4fd5f', 'დედებს ენერგია სჭირდებათ! 🍳', 'აღიდგინეთ ენერგია ჯანსაღი რეცეპტებიდან შერჩეული მარტივად მოსამზადებელი, გემრიელი სმუზით.'),
  ('282baeb2-eb26-44cb-9eff-2eb2d88677a2', 'მოიშორეთ დღის დაღლილობა. 🛁', 'დრო დაუთმეთ საკუთარ თავს და განიტვირთეთ — დღევანდელი ემოციები განწყობის დღიურში ჩაიწერეთ.'),
  ('5366cee2-8491-4a45-8d5c-88d78aa6eee0', 'უკვე მეორე თვეში გადავედით! 🎊', 'ბავშვის განვითარების ხელშესაწყობად დღის განმავლობაში ხშირად ესაუბრეთ მას.'),
  ('c5b12eaa-4012-417b-bf89-d5bd9d26aee9', 'კვების რეჟიმი შეიძლება შეიცვალოს. 🍼', 'ბავშვის მადის გასაკონტროლებლად ჩართეთ Anacan-ის ტაიმერი და შეამოწმეთ დღიური ნორმა.'),
  ('24927359-7877-4f99-9dea-0460583a0880', 'ყოველდღიურად გამოყენებული საფენების რაოდენობას ვაკვირდებით. 🧷', 'იმის დასადგენად, იღებს თუ არა ბავშვი საკმარის საკვებს, განაგრძეთ საფენის ყოველი გამოცვლის მონიშვნა Anacan-ში.'),
  ('77d01c80-0ffb-4089-a192-db04bf909aa1', 'ჩაძინება უჭირს? 🌙', 'თეთრი ხმებიდან აირჩიეთ ოკეანის ტალღების ხმა და სანამ ბავშვს ღრმად სძინავს, თქვენც დაისვენეთ.'),
  ('afe3841b-76da-4cfe-9cf7-b2077153f607', 'პირველი „აღუ“ ხმები ისმის! 🗣️', 'მეტყველების განვითარების ხელშესაწყობად გაიმეორეთ მის მიერ გამოცემული ხმები და ესაუბრეთ.'),
  ('22e06076-dd91-4e1b-834c-b78c42879a13', 'კომფორტი სახლის გარეთაც. ☕', 'მეგობრებთან შეხვედრას გეგმავთ? სახლიდან გასვლამდე აუცილებლად გადახედეთ დედებისთვის მეგობრული ადგილების ჩვენს რუკას.'),
  ('367f3154-4760-43d6-b507-b914372b7538', 'მოემზადეთ ღიმილისთვის! 😊', 'ბავშვმა შეიძლება ნებისმიერ დროს დაიწყოს საპასუხოდ ღიმილი. ტელეფონი მზად გქონდეთ.'),
  ('56603835-e00b-48c0-82ab-bbdf1844d6ac', 'რუტინა ძილის ხარისხს აუმჯობესებს. 🛁', 'აბანავეთ, ძუძუთი კვებეთ და ძილის ტაიმერი ჩართეთ, რათა აპლიკაციაში ყოველდღიურად გააანალიზოთ ბავშვის ძილი.'),
  ('173da4aa-4d6e-4106-ab0c-34773a383b02', 'მუცელზე წოლის დრო იზრდება! 🐢', 'ბავშვი უკვე უფრო გამართულად იჭერს თავს. კისრის კუნთების გასაძლიერებელი ეს ვარჯიშები ყოველდღიურ რუტინაში ჩართეთ.'),
  ('3c5122e2-a92c-4444-baa3-d7b7fdd4786f', 'გადავხედოთ საფენების გამოცვლის სტატისტიკას? 📊', 'შედით Anacan აპლიკაციაში და შეადარეთ ბოლო დღეების მონაცემები საფენების შესახებ. ყველაფერი რიგზეა?'),
  ('f653426f-c687-4b5c-806e-74f597e75cf2', 'იმისთვის, რომ დარწმუნდეთ — ყველაფერი რიგზეა. 🤖', 'ნებისმიერი საკითხი, რომელიც გაღელვებთ, შეგიძლიათ ღამის საათებშიც კი ჰკითხოთ Anacan AI-ს.'),
  ('041b2f2c-3594-4ff1-96a1-f589206d267b', 'კვება და შუალედები. 🤱', 'კიდევ უფრო დახვეწეთ თქვენი რეჟიმი — კვების კონტროლის ხელსაწყოს მეშვეობით გაზომეთ ყოველი ძუძუთი კვების ხანგრძლივობა.'),
  ('bae9c6f0-b7fe-4fe9-ba7a-7ba60aceb9ec', 'როგორ ხასიათზე ხართ, ძვირფასო დედიკო? 💖', 'ზოგჯერ შეიძლება ყველაფერი ერთდროულად დაგატყდეთ თავს. გახსენით თქვენი განწყობის დღიური და თავისუფლად გადმოიტანეთ მასში თქვენი გრძნობები.'),
  ('cb8cc6b6-0d64-4498-81ae-bc15f03ad73b', 'განსაკუთრებული მოვლა თქვენი ბავშვის კანისთვის. 🧴', 'ხავერდოვანი კანისთვის საუკეთესო საშუალებები აღმოაჩინეთ ჩვენს ბლოგში „რეკომენდებული პროდუქტები“, სადაც დედების რჩეული პროდუქტებია წარმოდგენილი.'),
  ('47a30b46-d385-4b3c-979c-5465d481ef29', 'ვარჯიში მუცლის შებერილობის წინააღმდეგ! 🚴', 'ველოსიპედის მოძრაობების შესრულებისას ფონად ჩართეთ თეთრი ხმები, რათა ბავშვი გაერთოს და ამავდროულად დამშვიდდეს.'),
  ('a7868664-8e30-4849-9648-70deec39cf3a', 'მე-6 კვირის განვითარების ნახტომი ახლოვდება! 📈', 'თქვენმა ბავშვმა შეიძლება ჩვეულებრივზე მეტად იტიროს. განვითარების ამ ეტაპისა და მისი მიზეზების გასაცნობად გადახედეთ ბლოგების განყოფილებას.'),
  ('ba4d5548-5eb3-44e1-bb68-bbab9deb11ee', 'ბავშვზე მამასთან ერთად ზრუნვის დროა. 👨‍🍼', 'საღამოს კვების შემდეგ ბავშვისთვის ბოყინის ამოშვების ჯერი მამას დაუთმეთ, თქვენ კი ცოტა ხნით წაიძინეთ.'),
  ('2a04ee0c-770e-425b-8987-e6ab25472f0b', 'რძის მოსამატებელი ბუნებრივი გზები. 🥛', 'მეტი რძისთვის სცადეთ „ჯანსაღი რეცეპტების“ განყოფილებაში მოცემული ნოყიერი სუპებისა და სასმელების რეცეპტები.'),
  ('6a605601-9da6-47e9-8d07-a1f552eb5fc0', 'ყოველდღიური კვებისა და ძილის ბალანსი. ⚖', '️ გააანალიზეთ დღევანდელი სტატისტიკა კვების კონტროლისა და ძილის გრაფიკების დახმარებით და დაგეგმეთ მომდევნო დღე.'),
  ('756d2914-ecb6-4838-adb6-d312a4bc59a2', 'თავის ხელებს აღმოაჩენს! 👐', 'მას უკვე შეუძლია ხელები პირთან მიიტანოს.'),
  ('2dcd9888-3b4b-4cb6-a25a-51c4642e3c54', 'დღეს ორმოცი დღე გვისრულდება! 🧿', 'ამ განსაკუთრებული და ტრადიციული დღის სამახსოვროდ „ბავშვის ფოტოსესიის“ განყოფილებიდან შეარჩიეთ საინტერესო თემები და გადაიღეთ ფოტოები.'),
  ('92e4d1aa-c4f4-477c-ab81-176ef4f03a16', 'მშვიდ ძილზე გადასვლა. 🌙', 'ამ განსაკუთრებული დღის ბოლოს ჩააბნელეთ ოთახი, ჩართეთ თეთრი ხმები და, სანამ თქვენს ბავშვს ღრმად ჩაეძინება, თქვენც ტკბილად დაიძინეთ.'),
  ('ba92608f-780e-4381-a0e7-3f6af86021be', 'როგორ გრძნობთ თავს? ✨', 'თქვენ 40-დღიანი მნიშვნელოვანი და განსაკუთრებული პერიოდი დაასრულეთ! თქვენ ნამდვილი გმირი ხართ!'),
  ('6dd4f975-8504-4871-83c4-a6f7bc24a950', 'როგორ ჩაიარა დღევანდელმა დღემ? 📝', 'დაისხით ფინჯანი ყავა, დღევანდელი შინაგანი განცდები განწყობის დღიურში ჩაინიშნეთ და განიტვირთეთ.'),
  ('c6c2469c-d36e-4ffe-a532-bee6050f4bac', 'ორმოცი დღის შემდეგ ახალი ეტაპი იწყება! 🌸', 'თქვენი ბავშვი გარემოს მიმართ უფრო მეტ ინტერესს იჩენს. მის გარშემო განმავითარებელი ბარათების განთავსება ბავშვისთვის სასარგებლოა.'),
  ('d647162e-98ae-41c0-81b4-cc5ca3e15dff', 'როგორ მიდის კვების რეჟიმი? 🍼', 'აპში არსებული კვების მონიტორინგის ხელსაწყოსა და ტაიმერის მეშვეობით შეამოწმეთ, რამდენად იცავთ დღიურ ნორმას.'),
  ('06dbea83-4e3d-4be5-8968-0961033df8d5', 'ფერებს უკეთ არჩევს! 🔴', 'დააკვირდით, როგორ აყოლებს თვალს ოთახში არსებულ მკვეთრი ფერის საგნებს.'),
  ('295afbf2-1104-44c2-abf4-fb0e41a0ff0e', 'სუფთა ჰაერი ორივეს სასიკეთოდ წაგადგებათ. 🌳', 'გასეირნებისთვის დედებისთვის მეგობრული ადგილების რუკაზე შეარჩიეთ ადგილი, სადაც ბავშვის ეტლით შესვლა მოსახერხებელია.'),
  ('9f7dfdf1-83be-4fad-a93a-817e105844ce', 'გაუადვილეთ ჩაძინება. 🌙', 'საღამოს აბაზანის შემდეგ თეთრი ხმებიდან ფენის ან წვიმის ხმა შეარჩიეთ და ბავშვი ღრმა ძილისთვის მოამზადეთ.'),
  ('431cbe5a-0f52-442d-a6e8-ab53cd482a5f', 'თქვენი დღიური სტატისტიკა მზადაა! 📊', 'აპლიკაციაში გააანალიზეთ თქვენი გრაფიკები, რათა ნახოთ, დღეს რამდენ ხანს ეძინა და როგორ იკვება ბავშვი.'),
  ('c4adf9ce-d711-4011-af60-94f404f59ae5', 'თვალყურს ვადევნებთ სიმაღლისა და წონის მატებას! 📏', 'განვითარების მონიტორინგის განყოფილებაში განაახლეთ ბოლო მონაცემები, გადახედეთ ჯანსაღი განვითარების გრაფიკს და იამაყეთ მიღწევებით.'),
  ('ffb18a7a-0d53-482c-b130-00223f89efd3', 'ენერგიის წყარო დედებისთვის! 🥗', 'ძალების აღსადგენად აპლიკაციაში ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან ვიტამინებით მდიდარი და გემრიელი კერძი შეარჩიეთ.'),
  ('40712cc0-bb4b-4d42-9a36-7942cb47a970', 'ხმებზე მისი რეაქცია ძლიერდება! 🎶', 'ამჩნევთ, როგორ მშვიდდება თქვენი ხმის გაგონებისას? უკვდავყავით ეს ტკბილი წუთები ბავშვის ალბომში.'),
  ('aa025645-c5cd-4f2b-840e-6fb50bb6398b', 'საყიდლები გჭირდებათ? 🛍', '️გაეცანით რეკომენდებული პროდუქტების სიას, სადაც ბავშვის ახალი ასაკობრივი ეტაპისთვის შესაფერის მოვლის საშუალებებსა და სათამაშოებს იპოვით.'),
  ('c6ae0bdf-11e6-43d9-a0ab-d021b7461194', 'განაგრძეთ საფენების დათვლა! 🧷', 'Anacan-ში ყოველდღიურად ჩაინიშნეთ გამოცვლილი საფენების რაოდენობა, რათა დარწმუნდეთ, რომ თქვენი ბავშვი საკმარისად იკვებება.'),
  ('99125d76-b832-4f75-8c29-6320b71e5e67', 'მე-6 კვირის განვითარების ნახტომი! 📈', 'დღეს ბავშვი შეიძლება ცოტა უფრო მომთხოვნი იყოს. ნუ ინერვიულებთ — მხარდაჭერისთვის Anacan AI-ს მიმართეთ.'),
  ('9f56ae7d-2431-4cb2-8d79-fa19be16c242', 'ღამით გაღვიძებას რუტინად ვაქცევთ. 😴', 'ყოველი გაღვიძებისას შუქს ნუ აანთებთ. გამოიყენეთ Anacan-ის ტაიმერი კვებისთვის, შემდეგ კი თეთრი ხმების დახმარებით ბავშვი კვლავ დააძინეთ.'),
  ('bef1515a-3c39-4799-b9d9-717742d94d5f', 'სანამ მას სძინავს, თქვენც დაისვენეთ. ⏱️', 'ჩართეთ ძილის ტაიმერი და სანამ თქვენს ბავშვს სძინავს, თქვენც დახუჭეთ თვალები ან წიგნი წაიკითხეთ.'),
  ('3deddca7-0eae-4a46-a2c9-5a8e2ac8b32c', 'პირველ ღუღუნს ახალი ბგერები ემატება! 🗣️', 'აღბეჭდეთ, როგორ ცდილობს თქვენთან საუბარს. ბავშვის ფოტოსესიის განყოფილებაში ამ მომენტისთვის შესაფერისი ჩარჩო შეარჩიეთ.'),
  ('48e4fdbb-6f6b-4c2d-90c9-ebe6d10f8179', 'საკვები, რომელიც რძის გამომუშავებას უწყობს ხელს. 🍲', 'ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტების განყოფილებაში შეარჩიეთ რძის გამომუშავების ხელშემწყობი წვნიანები და სასმელები და საკუთარ თავზე იზრუნეთ.'),
  ('bcfe1987-8bea-4b53-a1dc-7ef7e234e755', 'მართეთ თქვენი ემოციები. 💖', 'დედობა შეიძლება დამღლელი იყოს. გახსენით განწყობის დღიური, დაწერეთ, რამ შეგაწუხათ დღეს, და შვება იგრძენით.'),
  ('4c289cf6-60de-4ba6-9f14-eae4086d8d21', 'შუალედებს ვაწესრიგებთ. 🍼', 'კვების დროისა და კვებებს შორის შუალედების გასაკონტროლებლად გამოიყენეთ კვების კონტროლის ხელსაწყო და თქვენი ბავშვისთვის იდეალური რეჟიმი შეადგინეთ.'),
  ('7f93cf2f-abf0-4b16-9f93-396050a7ddb9', 'კიდევ გაქვთ შეკითხვები? 🤖', 'ჩემს ბავშვს დღეს ცოტა ეძინა, ეს ნორმალურია? – თქვენთვის საინტერესო შეკითხვები საზოგადოებაში სხვა დედებს დაუსვით.'),
  ('c505d849-65c8-4ead-80b3-2648f5feaa49', 'მუცელზე წოლის ვარჯიშები! 🐢', 'მას უკვე შეუძლია, თავი უფრო დიდხანს ეჭიროს. კისრის კუნთების გასავითარებლად ეს ვარჯიშები ყოველდღე გაიმეორეთ.'),
  ('65d67a55-0ffc-4c5f-8c78-443c16c7f697', 'მამებიც ჩავრთოთ პროცესში. 👨‍🍼', 'საღამოს კვების შემდეგ ბავშვისთვის ბოყინის ამოშვება და დაძინება მამას მიანდეთ, თავად კი საკუთარ თავს დაუთმეთ დრო.'),
  ('c7ab2e50-8e71-4df1-97cc-6432f40c4349', 'ღიმილი სულ უფრო მეტია! 😍', 'არ გამოტოვოთ ის ჯადოსნური წამი, როცა ბავშვი გიყურებთ და გიღუღუნებთ! ფოტო გადაუღეთ და ბავშვის ალბომის ყველაზე ლამაზ ადგილას შეინახეთ.'),
  ('dba00752-8e14-4710-8793-6a828172c915', 'მეგობრებთან ერთად ყავის შესვენება? ☕', 'დედებისთვის მეგობრულ ადგილებში იპოვეთ უახლოესი და კომფორტული კაფეები, სადაც ბავშვთან ერთად შეძლებთ წასვლას.'),
  ('503a0808-7061-4b7d-ae17-f65b9abb87de', 'თვალი ადევნეთ განვითარებას ნაბიჯ-ნაბიჯ. 📚', 'იმის გასაგებად, თუ რა უნარებს იძენენ ახალშობილები ამ თვეში, წაიკითხეთ ჩვენი უახლესი სტატია ბლოგების განყოფილებაში.'),
  ('aeea52a4-dd88-4cf1-a812-0c13b4f98004', 'ძილის ყოველდღიური ნორმა. 🛌', 'როდესაც თქვენს ბავშვს ჩაეძინება, ჩართეთ ძილის ტაიმერი და შეამოწმეთ, ასრულებს თუ არა ის ყოველდღიურ 14-17-საათიან ნორმას.'),
  ('c86bd995-9231-4eae-b8e0-8f84d6a46b62', 'თქვენ ძალიან ძლიერი ხართ! ✨', 'მიუხედავად იმისა, რომ ზოგჯერ რთულია, თქვენ არაჩვეულებრივი დედა ხართ!'),
  ('8e6d5e26-758c-4169-81b6-bd9cbcc10cc5', 'მშვენიერი დღის ტკბილი დასასრული. 🌙', 'ჩააქრეთ ოთახის განათება, თეთრი ხმებიდან ჩართეთ დედის მუცელში მოსმენილი ხმა და უყურეთ, როგორ იძინებს თქვენი ბავშვი ტკბილად.'),
  ('9d97fdbc-edef-4830-93ad-c388f586d909', 'უკვე ზუსტად 50 დღეა ერთად ხართ! 🎈', 'აღნიშნეთ ეს შესანიშნავი იუბილე ბავშვის ფოტოსესიის ხელსაწყოთი განსაკუთრებული ფოტოს შექმნით!'),
  ('cb1a5cad-e167-45a8-b0b1-4e8ebe455866', 'ბოლო 50 დღის ანალიზი. 📈', 'გახსენით განვითარების მონიტორინგისა და კვების კონტროლის განყოფილება და ნახეთ, როგორ შესანიშნავად გაიზარდა თქვენი ბავშვი ამ 50 დღის განმავლობაში.'),
  ('10f8db02-014b-4a08-8d7a-e5cbbb260125', 'ღრმა ძილში გადასვლა. 😴', 'თეთრი ხმებიდან აირჩიეთ ფენის ხმა და სანამ ბავშვს მშვიდად სძინავს, განწყობის დღიურში თქვენი გრძნობების ჩაწერით განიტვირთეთ.'),
  ('2cd12a68-4486-435f-ad24-55a11a2f62a2', 'ყოველდღიური კვების ანალიზი. 🍼', 'აპლიკაციაში არსებული ტაიმერით გაზომეთ ძუძუთი კვების ხანგრძლივობა და ნორმა კვების კონტროლის განყოფილებაში შეამოწმეთ.'),
  ('b67a89c9-d8cf-40c2-97a2-43b27081ed44', 'მხედველობის არე ფართოვდება! 👀', 'მას უკვე შეუძლია, საგნებს უკეთ მიადევნოს თვალი.'),
  ('917836b6-b023-4945-8e64-bc144ba97f42', 'ახალ ბგერებს აღმოაჩენს! 🗣️', 'ჩაიწერეთ მისი საყვარელი ღუღუნი. მეტყველების განვითარების შესახებ მეტის გასაგებად წაიკითხეთ ბლოგები.'),
  ('d31b874f-e957-475e-a461-b294c96db59f', 'ღამით გაღვიძებები გრძელდება? ⏱️', 'ძილის ტაიმერში ყოველი გაღვიძების აღნიშვნით გააანალიზეთ ძილის საერთო რეჟიმი და დღიური ნორმა.'),
  ('d491dc2d-f6b9-49dd-8461-5cbffee476e5', 'ნუ დაივიწყებთ საკუთარ თავს! 🥗', 'დედის ენერგია ძალიან მნიშვნელოვანია. ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან აირჩიეთ ვიტამინებით მდიდარი კერძი და ძალები აღიდგინეთ.'),
  ('6ca1ad26-9f01-4a3a-9164-e9f0d68cc33c', 'რა გაწუხებთ? 🤖', 'ღამის საათებშიც კი დაუსვით ნებისმიერი შეკითხვა ჩვენს Anacan AI ასისტენტს და მიიღეთ სპეციალისტის მხარდაჭერა.'),
  ('f710f746-b942-4fd7-a8ca-dd9b5a248195', 'შევამოწმოთ საფენების აღრიცხვა. 🧷', 'ყოველდღიურად გამოყენებული საფენების რაოდენობა Anacan-ში აღრიცხეთ და დარწმუნდით, რომ თქვენი ბავშვი საკმარისად იკვებება.'),
  ('fa5fc8d8-4263-4a99-9f46-297b1d6ea219', 'თავს უფრო მყარად იჭერს! 🐢', 'მუცელზე წოლის ვარჯიშები სახალისო აქტივობად აქციეთ.'),
  ('42ca0f3b-8083-4338-bf16-9998a33b15c6', 'სუფთა ჰაერზე გასვლის დროა! 🌳', 'გახსენით დედებისთვის კომფორტული ადგილების რუკა და იპოვეთ ყველაზე მოსახერხებელი ადგილი, სადაც ბავშვთან ერთად წასვლას შეძლებთ.'),
  ('7fc52d97-b36d-4c5e-a169-0eadba238b0e', 'წონისა და სიმაღლის კონტროლი. 📏', 'როგორ იზრდება თქვენი ბავშვი? შეიყვანეთ ახალი მონაცემები წონის ტრეკერში და თვალი ადევნეთ მისი განვითარების პერსონალურ გრაფიკს.'),
  ('df56b34d-b5f8-476f-a65e-11a244242a2f', 'ძილისწინა რუტინა. 🛁', 'აბანავეთ, ძუძუთი კვებეთ და ძილის ტაიმერი ჩართეთ. დაე, ყველაფერმა გეგმის მიხედვით და მშვიდად ჩაიაროს!'),
  ('0c1e843a-b2dc-4995-89cf-7af4230d574e', 'ხელებს აღმოაჩენს! 👐', 'ის უკვე აკვირდება თავის თითებს და პირში იდებს.'),
  ('3cf29d40-9703-4e58-8a17-b7e68f86c3fa', 'მოვლის საშუალებას ან სათამაშოს ეძებთ? 🧸', 'მისი განვითარების ხელშემწყობ უსაფრთხო პროდუქტებს მარტივად იპოვით ჩვენს რეკომენდებული პროდუქტების სიაში.'),
  ('e6e49938-5987-45e7-8021-a8d016100be4', 'როგორ გრძნობთ თავს? 💖', 'მთელი დღე დაღლილი იყავით თუ ენერგიულად გრძნობთ თავს? გახსენით განწყობის დღიური და ჩაინიშნეთ, როგორ ჩაიარა დღემ.'),
  ('814305c3-77b7-491e-ae0f-134875923d1a', 'რომელი ძუძუდან აჭამეთ? 🤱', 'Anacan-ის ტაიმერი თქვენ ნაცვლად იმახსოვრებს, მარჯვენა თუ მარცხენა ძუძუდან აჭამეთ. დაიწყეთ კვება ახლავე!'),
  ('910b6936-83b0-441d-abe5-33c85153dffe', 'დილის ღიმილი! 😊', 'მისი სოციალური ღიმილი დღეს ალამაზებს. ბავშვის ფოტოსესიით ეს სიხარული მოგონებად აქციეთ.'),
  ('fcecf920-146e-4152-abc5-066ce8392fd8', 'დამამშვიდებელი ხმოვანი თერაპია. 🎶', 'თუ ბავშვს აირები აწუხებს ან დაღლილია, თეთრი ხმებიდან გულისცემის ხმა მას მყისიერად დაამშვიდებს, თითქოს ისევ დედის საშვილოსნოშია.'),
  ('2776b020-9972-4e23-acb7-6a529664582d', 'თქვენს ხმას ეძებს! 👂', 'ხშირად ესაუბრეთ და თვალით კონტაქტი დაამყარეთ. მისი განვითარებისთვის სხვადასხვა აქტივობის შესახებ ბლოგების განყოფილებაში შეიტყვეთ.'),
  ('72abc90e-b301-468a-9629-3f3bb7949709', 'ბავშვის მოვლასთან დაკავშირებით ეჭვები გაქვთ? 🤖', 'Anacan-ის საზოგადოება განსჯის გარეშე მოგისმენთ და ყველაზე შესაფერის რჩევას მოგცემთ.'),
  ('816ef2cf-32b6-4eba-b12b-4e8f7936a78f', 'ხელი შეუწყვეთ რძის გამომუშავებას. 🥛', 'არ დაგავიწყდეთ ბევრი წყლის დალევა! დამატებით, ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან რძის გამომუშავების ხელშემწყობი სასმელი მოამზადეთ.'),
  ('1501b0ff-9742-40e2-9aae-ff2e8f8e5188', 'ოჯახური გასვლის გეგმა! ☕', 'თავისუფალი დროის სასიამოვნოდ გასატარებლად დედებისთვის კომფორტული ადგილებიდან მყუდრო კაფე ან რესტორანი შეარჩიეთ.'),
  ('427917df-21f2-46c9-a030-52d511e37ce5', 'დღიური ანგარიში. 📊', 'დღეს რამდენ ხანს ეძინა და რამდენჯერ იკვება? აპლიკაციაში მოცემული გრაფიკებიდან დღევანდელ საერთო სტატისტიკას გადახედეთ.'),
  ('c555165e-a5c9-4e8c-9a72-cf4d0a16a367', 'არც მამები გვავიწყდება! 👨‍🍼', 'დააფასეთ ის საყვარელი და მხიარული წუთები, როდესაც თქვენი ბავშვი მამასთან თამაშობს.'),
  ('052bbdef-be6b-4b3f-bf88-905af0d4abc5', 'ზოგჯერ დასვენება საჭიროა. 🛋', '️ სანამ მას სძინავს, ჩართეთ ძილის ტაიმერი, არაფერი აკეთოთ და უბრალოდ საკუთარ თავს დაუთმეთ დრო.'),
  ('1053981f-f622-407a-ade7-529fc27bb2ff', 'ვაკვირდებით ზრდის ეტაპს! ⚖️', 'მეორე თვე სრულდება. შედით აპში წონის მონიტორინგის განყოფილებაში და დარწმუნდით, რომ უახლესი მონაცემები განაახლეთ.'),
  ('8f5fde4a-3542-4bb1-be02-6df262d75b50', 'ყველაფერი რიგზეა? 📝', 'როგორ ხასიათზე ხართ? დაღლილი ხართ თუ ენერგიული? Anacan-ის განწყობის დღიური თქვენი საუკეთესო ციფრული მესაიდუმლეა.'),
  ('292a637a-a0ca-4e58-8523-7b2c8b754743', 'მშვენიერი თვის დასასრული. ✨', 'ჩააქრეთ ოთახში სინათლე, ჩართეთ თეთრი ხმაური და სანამ თქვენს ბავშვს სძინავს, იამაყეთ მისით. თქვენ იდეალური დედა ხართ!'),
  ('39c9a98b-8f4e-4896-9385-5588121bd72d', 'გილოცავთ, უკვე ზუსტად 2 თვის ვართ! 🎈', 'ამ შესანიშნავი მომენტის აღსანიშნავად ბავშვის ფოტოსესიაში სამახსოვრო ფოტო შექმენით!'),
  ('3c5f5d9f-939f-4c7e-9bc8-1feef640d854', 'ორი თვის განვითარების ანგარიში. 📈', 'გადახედეთ წონის მონიტორინგის, საფენებისა და კვების სტატისტიკას და ნახეთ, რამდენად ჯანმრთელად გაიზარდა ბავშვი ამ 60 დღის განმავლობაში.'),
  ('1ef4e046-ea34-4d3c-b7c9-53017c12e5ae', 'მოიშორეთ დღის დაღლილობა. 🛁', 'დრო დაუთმეთ საკუთარ თავს და განიტვირთეთ — დღევანდელი შინაგანი განცდები განწყობის დღიურში ჩაინიშნეთ.'),
  ('59aa01c0-7e8d-4375-9fcd-733a242d640c', 'ვიცავთ კვების რეჟიმს. 🍼', 'ბავშვს შესაძლოა მადა გაეზარდოს. ჩართეთ Anacan-ის ტაიმერი და კვების ნორმა კვების კონტროლის ხელსაწყოს მეშვეობით შეამოწმეთ.'),
  ('a19b5a5e-db95-4571-b0b8-5f50fabb0b6a', 'მესამე თვის პირველი დღეა! 🎉', 'თქვენი ბავშვი გარემოს უკვე უფრო გააზრებულად აკვირდება.'),
  ('8d26cab1-ebfd-469f-9ae0-aa66e0f36761', 'ბავშვს ჩაძინება უჭირს? 🌙', 'ჩააბნელეთ ოთახი, თეთრი ხმებიდან ოკეანის ტალღების ხმა აირჩიეთ და ბავშვი ღრმა ძილისთვის მოამზადეთ.'),
  ('92c57c1c-b876-4895-9dd9-de2d4fc5b8a4', 'სუფთა ჰაერზე გასეირნების დროა. 🌳', 'სუფთა ჰაერზე სეირნობა ძალიან მნიშვნელოვანია თქვენი ბავშვის განვითარებისა და სიმშვიდისთვის.'),
  ('b6825824-6eff-4740-b6c1-dc607b41b996', 'ხელებს სათამაშოებისკენ იწევს! 🧸', 'რა სასიამოვნოა ამ პატარა აღმოჩენებზე დაკვირვება! ბავშვთან თამაშის დროს გადაღებული ვიდეოები ბავშვის ალბომში ატვირთეთ.'),
  ('1ed5f326-68dd-494e-a31c-2d3466644cd0', 'ენერგიის წყარო დედებისთვის! 🥗', 'ძალების აღსადგენად და რძის გამომუშავების ხელშესაწყობად „ჯანსაღი რეცეპტების“ განყოფილებიდან ვიტამინებით მდიდარი რეცეპტი შეარჩიეთ.'),
  ('59041ede-10ec-4754-8f5f-31f415db3701', '„ა-გუ“ ბგერები უფრო ხშირად ისმის! 🗣️', 'თქვენი ბავშვი სულ უფრო ხშირად ცდილობს თქვენთან ურთიერთობას. მეტყველების განვითარების ხელშესაწყობად წაიკითხეთ სტატიები „ბლოგების“ განყოფილებაში.'),
  ('d7b0c908-0d97-40c6-a82a-c5283f30a1d8', 'თვალი ადევნეთ ძილის ნორმებს. ⏱️', 'როდესაც თქვენს ბავშვს სძინავს, ჩართეთ ძილის ტაიმერი და გააანალიზეთ, იცავს თუ არა ის ძილის დღიურ ნორმას.'),
  ('5309698d-6050-4993-9a68-ab592375ed60', 'სანერწყვე ჯირკვლები მუშაობას იწყებს! 💧', 'მას უკვე შეიძლება მეტი ნერწყვი გამოეყოს.'),
  ('83d11db6-0443-4d69-8d55-9ea20f0cf905', 'თვალყურს ვადევნებთ ზრდის ეტაპს! 📏', 'განაახლეთ ბავშვის განვითარების პირადი გრაფიკი მომდევნო კვირის წონისა და სიმაღლის მონაცემების „წონის ტრეკერში“ შეყვანით.'),
  ('ca5bc974-1377-4065-9dfa-50549135eb55', 'რამე გაწუხებთ? 🤖', 'კითხვები, როგორიცაა „დღეს რატომ ეძინა ასე ცოტა?“, ღამის საათებშიც კი დაუსვით ჩვენს Anacan AI ასისტენტს.'),
  ('5a4dd587-0176-4bbf-bb1c-d0eab0227cdc', 'დროა, მამაც ჩაერთოს ბავშვის მოვლაში. 👨‍🍼', 'საღამოს კვების შემდეგ ბავშვისთვის ბოყინის ამოშვებასა და დაძინებაზე ზრუნვა მამას მიანდეთ, თქვენ კი დაისვენეთ.'),
  ('a6843443-e0f6-4ec7-a4ec-03cb5d81d392', 'მუცელზე წოლის ვარჯიშები უფრო მარტივი ხდება. 🐢', 'ბავშვს უკვე შეუძლია თავი უფრო სწორად და დიდხანს დაიჭიროს. ეს აქტივობა თქვენს ყოველდღიურ რუტინაში ჩართეთ.'),
  ('c2daa58e-e7ee-4f2b-917b-6e5273ca2c1d', 'შევამოწმოთ ყოველდღიურად გამოცვლილი საფენები. 🧷', 'იმის დასადგენად, იღებს თუ არა ბავშვი საკმარის საკვებს, Anacan-ში საფენის ყოველი გამოცვლის აღრიცხვა განაგრძეთ.'),
  ('7764e41d-176a-41d8-8f87-2a21677a36ee', 'ვქმნით ყოველდღიურ რუტინას. 🛁', 'ყოველ საღამოს ერთსა და იმავე დროს აბანავეთ, ძუძუთი კვებეთ და ძილის ტაიმერი ჩართეთ, რათა ბავშვს ძილის ჯანსაღი რეჟიმი ჩამოუყალიბოთ.'),
  ('9754280d-c633-46e8-94c9-6f16ff032551', 'ნუ დაივიწყებთ საკუთარ თავს, ძვირფასო დედიკო! 🍲', 'გადახედეთ Anacan-ის აპში ჯანსაღი რეცეპტების განყოფილებას და დღეს საკუთარი თავისთვის რაიმე გემრიელი მოამზადეთ.'),
  ('c1c4c9b0-cdd8-4321-a494-3bb43739df94', 'თქვენ და თქვენს ხმას გცნობთ! 😍', 'დააკვირდით, როგორ უხარია ბავშვს, როდესაც ოთახში შედიხართ. 😊'),
  ('149e95b1-a682-4369-8b74-5827cc5d31dc', 'ნუ მოგერიდებათ თქვენი გრძნობების გაზიარება. 📝', 'დაღლილი ხართ თუ ენერგიით სავსე? ამას მნიშვნელობა არ აქვს — ჩაინიშნეთ დღევანდელი ემოციები განწყობის დღიურში და შვება იგრძენით.'),
  ('79b7fb29-fa37-4176-9ae5-409d73ee982e', 'კომფორტი სახლის გარეთაც. ☕', 'გსურთ მეგობრებთან ერთად ყავის დალევა? სახლიდან გასვლამდე აუცილებლად გადახედეთ დედებისთვის მეგობრული ადგილების რუკას.'),
  ('818c91c1-bd54-42c5-8ac8-1505ae1830ab', 'სოციალური ღიმილი! 😊', 'მისი ტკბილი ღიმილი მთელ დაღლილობას გავიწყებთ.'),
  ('998faa86-f9bb-47df-aa71-acba217766a9', 'თქვენი ყოველკვირეული სტატისტიკა მზადაა! 📊', 'შედით აპში და გააანალიზეთ, რამდენად კარგად იცავდით ბოლო დღეებში ძილისა და კვების რეჟიმს.'),
  ('aba537d3-5a0f-4b17-b02b-4754b93f711f', 'დაგავიწყდათ, რომელი ძუძუთი აჭამეთ ბავშვს? 🤱', 'ტაიმერის საშუალებით მონიშნეთ მარჯვენა ან მარცხენა ძუძუ და Anacan ყველაფერს თქვენ მაგივრად დაიმახსოვრებს!'),
  ('b4eb6af7-758b-41ff-a277-ea0ef21a9fb8', 'დღის ძილის რეჟიმი იცვლება. ⏱️', 'გაზომეთ ფხიზლად ყოფნის ხანგრძლივობა და შუალედები კვების კონტროლისა და ძილის ტაიმერებით და შექმენით ახალი რეჟიმი.'),
  ('32ff20f3-f1f8-47fd-b3be-c14bea1452a2', 'ხმოვანი თერაპია მოუსვენრობის წინააღმდეგ. 🎶', 'თუ ამ საღამოს თქვენი ბავშვი მოუსვენრადაა, ყურადღების გადასატანად „თეთრი ხმებიდან“ გულისცემის ხმა ჩაურთეთ.'),
  ('a061022a-6a47-4aae-8590-2f0f328fbf09', 'თამაშის დროა! 🎈', 'წაიკითხეთ ბლოგების განყოფილებაში მოცემული განმავითარებელი თამაშების რჩევები და გაიგეთ, როგორ გაატაროთ მასთან დრო ხარისხიანად.'),
  ('b95ca7be-8491-4bbc-afb0-321f795780ea', 'რაიმეს შეძენა გჭირდებათ? 🛍', 'ჩვენს რეკომენდებული პროდუქტების სიაში მარტივად იპოვეთ თქვენი ბავშვის ამ ასაკისთვის შესაფერისი უსაფრთხო სათამაშოები და ნივთები.'),
  ('633e342d-82b1-442c-9da8-5c5326907322', 'დღის ანალიზი. 📈', 'გააანალიზეთ კვების მონიტორინგისა და ძილის გრაფიკები და ნახეთ, როგორ შესანიშნავად ყალიბდება თქვენი რეჟიმი.'),
  ('8655d498-c5d9-40f8-bd47-346f815d3e75', 'მშვენიერი დღის ტკბილი დასასრული. 🌙', 'ჩააქრეთ ოთახში სინათლე, „თეთრი ხმებიდან“ დედის საშვილოსნოს ხმა ჩაურთეთ და უყურეთ, როგორ ტკბილად იძინებს თქვენი ბავშვი.'),
  ('97e88a0b-26cf-486d-a17f-2c34cfc6b47d', 'უკვე ზუსტად 70 დღეა, რაც ერთად ხართ! ✨', 'თქვენ არაჩვეულებრივი დედა ხართ! ბავშვის ალბომში დაამატეთ კოლაჟი, რომელიც პირველ დღესა და დღევანდელობას შორის განსხვავებას აჩვენებს.'),
  ('0c5e05bb-e0ba-4c0b-a9c9-f1f210abb37a', 'ჩვენ ერთი გუნდი ვართ! 💪', 'ზოგჯერ თავს მარტოსულად და გაუგებრად გრძნობთ? შეუერთდით Anacan-ის საზოგადოებას. იქ ათასობით დედაა, რომლებიც იმავეს გრძნობენ, რასაც თქვენ. დღეს გაუზიარეთ მათ თქვენი გამოცდილება.'),
  ('60059890-bf5b-4e0b-ba41-fedc82fa6a43', 'მამის ჯერია 👨‍🍼', 'მოიშორეთ დღის დაღლილობა. ბავშვი მამას მიაბარეთ და ამ საღამოს მან დააძინოს. თქვენ კი უბრალოდ დაისხით ცხელი ჩაი და ამ სანახაობას შორიდან უყურეთ.'),
  ('b1778419-cb70-4711-96e0-a612732e8575', 'ნერწყვიანი ღიმილი 🤤', 'თქვენს ბავშვს ხშირად მოსდის ნერწყვი და ხელები სულ პირში აქვს? დაიწყეთ პირველი ჩანაწერების გაკეთება კბილების ამოჭრის ტრეკერში. დიახ, ეს ამაღელვებელი მზადება ადრე იწყება!'),
  ('0eb4da19-cb98-497a-a36b-a4934f47e071', 'სიჩუმის კონტროლი 🤫', 'თქვენს ბავშვს ახლახან ჩაეძინა, მაგრამ სახლში ხმაურის გეშინიათ? ჩართეთ ხმის საზომი, აკონტროლეთ ოთახში დეციბელების დონე და დაიცავით მისი ძილი.'),
  ('9cab0c58-8a4f-4869-b607-be3e284373f0', 'კითხვა გაქვთ? 🤖', 'ყოველდღიურ საზრუნავში რაიმე კითხვა გაგიჩნდათ? კვება, ძილი თუ გაზები... მნიშვნელობა არ აქვს — დაუყოვნებლივ ჰკითხეთ Anacan AI-ს და მიიღეთ ზუსტი, მეცნიერულად დასაბუთებული პასუხი.'),
  ('e6d33eab-abbe-4eca-94e9-c05138d06c07', 'შემომხედე, აქ ვარ! 👀', 'ახლა უკვე ოთახის მეორე კუთხიდანაც კი ყურადღებით გაკვირდებათ. განვითარების ტრეკერში მონიშნეთ ეს შესანიშნავი წინსვლა თვალით კონტაქტში და იამაყეთ მისი ზრდით!'),
  ('05925891-b678-4a87-8f54-39f692aa9143', 'მარაგი იწურება? 🛒', 'საფენები ან სველი ხელსახოცები გითავდებათ? ყველაფრის დამახსოვრება არ გჭირდებათ. ახლავე დაამატეთ საყიდლების სიაში, რათა თქვენმა პარტნიორმა საღამოს, შინ დაბრუნებისას იყიდოს.'),
  ('41007feb-f415-4088-b094-428b2275abbf', 'ხმების ჯადოსნური სამყარო 📖', 'შეიტანეთ სიახლე საღამოს რუტინაში. ჭკვიანი ზღაპრების დახმარებით შეუქმენით მას დამამშვიდებელი ამბავი და ორივესთვის გაამარტივეთ დაძინება.'),
  ('e23c6a5f-2a6d-45e5-af3a-8681c3bb9e03', 'დილის კონცერტი 🎶', 'პირველ ღუღუნს იწყებს? ესაუბრეთ მის ენაზე და გამოეხმაურეთ მის ბგერებს. დღეს უბრალოდ დატკბით ამ ტკბილი წამით და ნურაფერს იჩქარებთ.'),
  ('62fbb893-6a1c-4847-a99e-981afea8fa87', 'განსხვავებული ტირილი 😭', 'შიმშილის გამო ტირის თუ ეძინება? ნუ ინერვიულებთ, ტირილის ანალიზის ხელსაწყოს დახმარებით ერთად გავარკვიოთ წამებში, რის თქმას ცდილობს ამ ხმებით.'),
  ('83a0ab90-d44d-4758-bd3f-c7126ae6e20f', 'გულწრფელი იყავით საკუთარ თავთან 📝', 'დღეს ძალიან დაიღალეთ? გულწრფელად ჩაწერეთ თქვენი გრძნობები განწყობის დღიურში. არ ხართ ვალდებული, ყოველდღე იდეალური იყოთ — თქვენც უბრალოდ ადამიანი ხართ.'),
  ('d9e30a3e-ad9b-4b4b-85a6-bcaa444e488c', 'რა ჩავაცვა? ⛅', 'ამინდი ცვალებადია და გეშინიათ, ბავშვი არ გაცივდეს ან არ გაოფლიანდეს? დაუყოვნებლივ გადახედეთ ამინდისა და ჩაცმულობის ხელსაწყოს და გაიგეთ, ტანსაცმლის რომელი კომბინაციაა იდეალური დღევანდელი ამინდისთვის.'),
  ('6cefc0b3-6f91-4329-bd4c-bf6671e0e8aa', 'ვარსკვლავებით მოჭედილი სიზმრები 🌌', 'ბავშვებს რუტინა უყვართ. ჭკვიანი ზღაპრების განყოფილებაში მისთვის განსაკუთრებული ზღაპარი შექმენით.'),
  ('dacdc0bf-3562-4ab5-be87-7acb17a3f2f9', 'თქვენ საოცარი ხართ! 🌸', 'ზოგჯერ გგონიათ, რომ ვერაფერს უმკლავდებით? მაგრამ შეხედეთ, როგორ მშვიდად და თანაბრად სუნთქავს ბავშვი... თქვენ ყველაფერს აკეთებთ, რაც შეგიძლიათ!'),
  ('faace99e-5074-497e-b5c0-f25a9880f5b0', 'დედის ენერგია 🍲', 'ყოველდღიურ ქაოსში საკუთარი კვება ხომ არ დაგავიწყდათ? ჯანსაღი რეცეპტების განყოფილებიდან აირჩიეთ სწრაფი სუპის რეცეპტი, რომელიც ენერგიის აღდგენაშიც დაგეხმარებათ და რძის გამომუშავებასაც შეუწყობს ხელს.'),
  ('1cd41578-3422-4bf8-9401-e9a058dcad6f', 'მხოლოდ 15 წუთი 🛁', 'ბავშვმა დაიძინა? ახლა პარტნიორის რეჟიმში ყველა შეტყობინება თქვენს პარტნიორთან გადაამისამართეთ. თავად კი სააბაზანოში შედით და 15 წუთით დატკბით თბილი წყლითა და სიმშვიდით.'),
  ('73a10da9-aef9-4c21-b8d7-bca1f62e8528', 'გამოცდილების გაზიარება 💬', 'ბოლო დღეებში მისი რომელი ქცევა გაცინებთ ყველაზე მეტად? შეუერთდით Anacan-ის საზოგადოებას და ეს მომენტი პოსტის სახით გააზიარეთ. სხვა დედების ისტორიების წაკითხვაც კარგ განწყობაზე დაგაყენებთ.'),
  ('acfd33be-87a0-41a3-858d-d5921f61d9a4', 'ხელების აღმოჩენა 👋', 'საკუთარი ხელები აღმოაჩინა და საათობით აკვირდება? არ გამოტოვოთ განვითარების ეს სახალისო და საოცარი მომენტი — დაუყოვნებლივ გადაიღეთ ბავშვის ფოტოსესიის ფუნქციით და სამუდამოდ შეინახეთ!'),
  ('36b1e2d3-b43a-467e-b08f-870a612d1bb5', 'ტირილის კოდი 🧩', 'არ შია, საფენი სუფთაა, მაგრამ მაინც მოუსვენრადაა? თუ მიზეზის გარკვევა გიჭირთ, გამოიყენეთ ტირილის ანალიზი და გაიგეთ, რა რეალური საჭიროება იმალება ამ ხმის მიღმა.'),
  ('384efd2a-d9fb-48b6-8e4a-eca7c3a0d8ee', 'დაღლილობის გულწრფელობა 💖', 'სახლი არეულია, საჭმელი კი ონლაინ შეუკვეთეთ? არაფერია. ამ გზაზე მარტო არ ხართ.'),
  ('8f6c6637-de06-4b9d-8e44-d9e85864f3c8', 'დილის ვარჯიში 🐢', 'ბავშვს უკვე უფრო გამართულად უჭირავს თავი! მუცელზე წოლის დრო გართობად აქციეთ. სარკის წინ მოათავსეთ და დააკვირდით, როგორ რეაგირებს საკუთარ ანარეკლზე.'),
  ('049d3744-b2ac-49ea-bf86-ad5e8d0bcb74', 'სამახსოვრო სია 📝', 'სახლში საჭირო ნივთების სია არასდროს იწურება. ფიქრით თავს ნუ გადაიღლით — გახსენით საყიდლების სია, ჩაწერეთ, რაც გჭირდებათ, და ერთი შეხებით გაუზიარეთ სია თქვენს პარტნიორს.'),
  ('12a076b6-d8dc-4bec-a8af-ddc523182bad', 'ზღაპრის დრო 📖', 'თქვენი ბავშვის დიდ მეოცნებედ ქცევა უკვე ახლა იწყება. ჭკვიანი ზღაპრების დახმარებით შექმენით და წაუკითხეთ ჯადოსნური ზღაპარი, შემდეგ კი უყურეთ, როგორ ეხუჭება ნელ-ნელა თვალები.'),
  ('58ce6bd9-90fd-4e98-a133-ddfda6d59177', 'პედიატრი თქვენს ჯიბეში 🤖', 'წონას კარგად იმატებს? განავალი უჩვეულო ფერისაა? სანამ შეშფოთდებით, მისწერეთ Anacan AI-ს, გაარკვიეთ პრობლემის არსი და მიიღეთ სანდო, დამამშვიდებელი ინფორმაცია.'),
  ('5543e602-8610-44ac-8995-56ec74a0576e', 'ჭკვიანური სიჩუმე 🤫', 'საღამოს ჭირვეულობის მინიმუმამდე შესამცირებლად მნიშვნელოვანია, ოთახში სიჩუმე აკონტროლოთ. ჩართეთ ხმაურის საზომი, მოერიდეთ ზედმეტად ხმაურიან გარემოს და მოამზადეთ ბავშვი მშვიდი დასვენებისთვის.'),
  ('81600590-d6f0-495d-b852-9afcf35b137a', 'პატარა მკვლევრის ჩაცმულობა ⛅', 'გასეირნება გსურთ, მაგრამ ზუსტად არ იცით, როგორი ამინდი იქნება? ამინდისა და ჩაცმულობის ასისტენტის დახმარებით წამებში შეარჩიეთ დღევანდელი ტემპერატურისთვის ყველაზე შესაფერისი კომბინაცია.'),
  ('fbf2b91a-0a2a-4aa9-9404-589ba5628b25', 'დილის ღიმილი ☀️', 'თვალების გახელისთანავე შემოგხედათ და ფართოდ გაგიღიმათ? თქვენ მსოფლიოში ყველაზე ძვირფასი საჩუქარი მიიღეთ. დღეს მხოლოდ ამ წამზე იფიქრეთ და პოზიტიური განწყობა შეინარჩუნეთ.'),
  ('1f2c4967-df72-43b6-91d0-25ece4f2331b', 'წვეულებამდე 10 დღე დარჩა! 🎂', 'მოემზადეთ — 3 თვის შესრულებამდე სულ რაღაც 10 დღე დარჩა! ერთ-ერთი პირველი დიდი თარიღი ახლოვდება. სწორედ ახლაა საუკეთესო დრო, მოიფიქროთ ლამაზი კონცეფცია და ტორტი შეუკვეთოთ!'),
  ('488e046f-44fb-4fcc-80e0-064c20288a56', 'გუნდური სადღეგრძელო 🥂', 'ამ საღამოს პარტნიორს მადლობა გადაუხადეთ და ერთმანეთი 80 დღის შრომისთვის დააფასეთ. თქვენ ეს შეძელით!'),
  ('720785a0-3423-4036-a26d-bba9419b8cb2', 'არაჩვეულებრივი 80-ე დღე! 🎉', 'უკვე ზუსტად 80 დღეა, რაც ერთად ხართ! გადადით ბავშვის ფოტოსესიის განყოფილებაში, სპეციალური 80-ე დღის სტიკერებით უკვდავყავით ეს რიცხვი და სამახსოვროდ საზოგადოებაში გააზიარეთ!'),
  ('7d54b8de-cc42-4891-b97a-5856eefffe9d', 'თქვენი პირადი ზღაპარი იქმნება 🪄', 'ამ საღამოს მთავარი როლი თქვენს ბავშვს ეკუთვნოდეს! გახსენით ჭკვიანი ზღაპრების ხელსაწყო და ჩაწერეთ თემა: „პატარა რაინდის თავგადასავალი, რომელსაც ღამით დაძინება არ სურდა“. მიეცით ხელოვნურ ინტელექტს საშუალება, სპეციალურად თქვენთვის უნიკალური და საყვარელი ამბავი შექმნას.'),
  ('d5c6a987-139f-4c65-bdd8-e9dc3eb4c43a', 'დიალოგისთვის მზად ხართ? 🗣️', 'ბავშვი უკვე უბრალოდ ბგერებს კი არ გამოსცემს, არამედ ცდილობს, თქვენს ხმას სხვადასხვა ტონით უპასუხოს! გახსენით განვითარების ტრეკერი, მონიშნეთ კომუნიკაციის ეს საოცარი წინსვლა და მის ენაზე ესაუბრეთ.'),
  ('f027a882-3827-4905-9807-216432d88e53', 'დედის მეხსიერების ბურუსი 🌫️', 'არ გახსოვთ, გუშინ რა მიირთვით? დედების გულმავიწყობა (Baby brain) სრულიად რეალურია. ნუ გადატვირთავთ გონებას — სახლისთვის საჭირო ყველაფერი საყიდლების სიაში ჩაწერეთ და დანარჩენი თქვენს პარტნიორს მიანდეთ.'),
  ('2e536117-6f18-4388-b1bd-29587c89d3cb', 'აწეწილი თმის რეალობა 💇‍♀️', 'სარკეში ჩახედვისას თმის ცვენა გაშინებთ? ეს მშობიარობის შემდგომი პერიოდის ერთ-ერთი ყველაზე გამაღიზიანებელი რეალობაა! მარტო არ ხართ — ახლავე შეუერთდით Anacan-ის საზოგადოებას და წაიკითხეთ, როგორ უმკლავდებიან ამ კრიზისს სხვა დედები.'),
  ('41393920-01a7-42fe-a049-e26e1148a375', 'სიმშვიდის ძიებაში 🤫', 'ზოგჯერ სახლში არსებული ხმაური, რომელსაც ვერც კი ამჩნევთ, ბავშვს დაძინებაში ხელს უშლის. ჩართეთ ხმის საზომი, შეამოწმეთ ოთახის აკუსტიკა და ბავშვისთვის იდეალურად მშვიდი გარემო შექმენით.'),
  ('acb2ca22-b3e3-4ac0-b344-a63734056dfa', 'ღრძილები ექავება? 🦷', 'თქვენს ბავშვს ყველაფერი, განსაკუთრებით კი საკუთარი ხელები, პირში მიაქვს? გაძლიერებული ნერწყვდენა დაეწყო? დაუყოვნებლივ მონიშნეთ პირველი ნიშნები კბილების ამოჭრის ტრეკერში და ამ ხანგრძლივი პროცესისთვის მოემზადეთ.'),
  ('357bed80-6ac0-481c-9f5b-22bc1c97e3fe', 'ხელების აღმოჩენა 🤲', 'შეგნებულად ცდილობს ჩამოკიდებულ სათამაშოებს მისწვდეს? მისი მოტორული უნარები ვითარდება. რეკომენდებული პროდუქტების განყოფილებაში დაათვალიერეთ უსაფრთხო ჩასაჭიდი სათამაშოები, რომლებიც მის ამ ახალ ინტერესს ხელს შეუწყობს.'),
  ('3c4bae00-6309-4214-a502-aa8dcb398a77', 'ამინდის სიურპრიზი ⛅', 'გარეთ გასვლა გსურთ, მაგრამ ფანჯრიდან ვერ ხვდებით, როგორი ამინდია? ნუ ჩააცმევთ ბავშვს ზედმეტად ბევრ ფენას და ნუ გააოფლიანებთ. ამინდისა და ტანსაცმლის ხელსაწყო წამებში გირჩევთ დღევანდელი ტემპერატურისთვის ყველაზე შესაფერის სამოსს.'),
  ('42bfdf13-2735-49dc-b527-89506330c670', 'მამის მხრები 👨‍👧', 'მოთმინება გამოგელიათ და ხელებიც მოგწყდათ? ამ საღამოს ჩართეთ პარტნიორის რეჟიმი. ბავშვისთვის ბოყინის ამოღებინება და ოთახში ტარება მთლიანად მამას მიანდეთ. თქვენ კი უბრალოდ დივანზე დაისვენეთ.'),
  ('3d2a21ef-6e5b-4f36-9011-f9c3474762a4', 'არ შია, მაშ რატომ ტირის? 🧩', 'რაც უნდა გააკეთოთ, ვერ მშვიდდება და მისი ტირილიც უჩვეულოდ ჟღერს? შეწყვიტეთ გამოცნობა — ტირილის ანალიზს მოასმენინეთ ხმა და დაუყოვნებლივ გაიგეთ, პრობლემა აირების დაგროვებაა თუ უძილობა.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ka = v.t, body_ka = v.b
FROM (VALUES
  ('b092d275-f2d6-47ce-b8d0-3f8ced210589'::uuid, 'ყურსასმენები და ყავა 🎧', 'დღევანდელი დღე მართლაც ძალიან რთული იყო. ემოციების დღიურში გადმოიტანეთ თქვენი გრძნობები. შემდეგ კი გაიკეთეთ ყურსასმენები, ჩართეთ საყვარელი მუსიკა და 10 წუთის განმავლობაში ნამდვილ სიმშვიდეში მიირთვით ცხელი ყავა.'),
  ('c6fb2576-7fa6-4e01-b8a4-ec89ac753089', 'დილის კატასტროფა 💩', 'თვალის გახელისთანავე დაგხვდათ ყელამდე მოსვრილი ბავშვი და გამოსაცვლელი თეთრეული? საფენის მონიტორში სიცილით აღრიცხეთ ეს დიდი კატასტროფა. დიახ, დედობაც სწორედ ეს არის!'),
  ('022a6d7a-76fe-47e7-aae6-a35dad3d3555', 'გაზომეთ დრო ⏱️', 'არარეგულარული კვება გღლით? კვების კონტროლის ტაიმერით გაზომეთ, რამდენ ხანს ატარებს ბავშვი ძუძუსთან ან ბოთლთან, და გაეცანით მის ახლად ჩამოყალიბებულ რუტინას.'),
  ('62da6149-1edf-4e2a-abc6-d69d21a43fa4', 'დილის ვარჯიშის სიჯიუტე 🐢', 'ბავშვს მუცელზე წოლა (Tummy time) არ სურს და ტირის? ნუ აიძულებთ. ჰკითხეთ Anacan AI-ს: „როგორ ვაქციო მუცელზე წოლა სახალისოდ 3 თვის ბავშვისთვის?“ და სწრაფად მიიღეთ რჩევები.'),
  ('938dd21f-e30f-4b2b-b3e0-d79140f44b59', 'კიდევ ერთი ზღაპარი შევქმნათ! 🪄', 'ამჯერად ჭკვიან ზღაპრებს უფრო სახალისო დავალება მივცეთ: „მამის წვერში დამალული ჯუჯის ამბავი“. ხელოვნური ინტელექტის მიერ შექმნილი ეს ზღაპარი თქვენს პარტნიორს გაახმოვანებინეთ და ოთახი სიცილით აავსეთ.'),
  ('1f0c7fc3-49b6-44d6-a78b-152d7ead7adc', 'ოთხ კედელს გაექეცით 🏃‍♀️', 'სახლში ყოფნა გთრგუნავთ, მაგრამ არ იცით, ბავშვთან ერთად სად წახვიდეთ? დედებისთვის მეგობრულ ადგილებში იპოვეთ უახლოესი კაფე, სადაც ბავშვის ეტლით ადვილად შეხვალთ და ძუძუთი კვების ოთახიც დაგხვდებათ, და ცოტათი განიტვირთეთ საზოგადოებაში.'),
  ('55bafaf5-82ef-4f88-880d-836cf89145d0', 'ბგერების ძალა 🌊', 'საღამოობით უმიზეზოდ დაწყებული ტირილისა და ჭირვეულობის საათები დამღლელია. ბავშვი ოთახში შეიყვანეთ, თეთრი ხმებიდან ოკეანის ტალღების ან თმის საშრობის ხმა აირჩიეთ და გარემო მყისიერად დაამშვიდეთ.'),
  ('a6e787a8-1712-42a4-9b2a-4f48a9e5fc87', 'სად არის დედის ენერგია? 🔋', 'სარკეში თქვენს დაღლილ თვალებს რომ შეხედავთ, თავს ნუ დაიდანაშაულებთ. ყურადღებას აქცევთ თქვენს კვებას? ჯანსაღი რეცეპტებიდან შეარჩიეთ რკინით მდიდარი სმუზი დედებისთვის, რომელიც 10 წუთში მზადდება, და ენერგია აღიდგინეთ.'),
  ('13035ad4-af08-4b79-ba71-a42ceb60fe5b', 'გუნდური განხილვა 🛋️', 'ბავშვის დაძინების შემდეგ, განწყობის დღიურში მოცემულ თქვენს ყოველკვირეულ სტატისტიკას პარტნიორთან ერთად გადახედეთ. რომელ დღეებში იყავით უფრო მეტად დაძაბული? რისი გაკეთება შეგიძლიათ სხვაგვარად? თქვენ ერთი გუნდი ხართ!'),
  ('400a0bc6-f5e7-4dd0-9d49-d6e66ce5c9b6', 'დაბლა ჩაიხედეთ! 👣', 'ის უკვე საკუთარ ფეხებს აღმოაჩენს! არ გამოტოვოთ ის სასაცილო და საყვარელი წამი, როცა ფეხის თითების დაჭერას ცდილობს. გახსენით ბავშვის ფოტოსესია, გააფორმეთ სტიკერებით და აღნიშნეთ განვითარების ეს მნიშვნელოვანი მომენტი.'),
  ('daf9dd68-0ed6-4ada-9b16-84c4ff46a8e8', 'კბილის სათამაშოს ძიება 🦷', 'ნერწყვდენა არ წყდება და ყველაფერს ღრღნის? კბილების ამოჭრის ტრეკერი გაფრთხილებთ. სწორედ ახლაა დრო, რეკომენდებული პროდუქტების განყოფილებაში სუფთა სილიკონის ან ხის კბილის სათამაშოები შეარჩიოთ.'),
  ('0d132ba6-d6e9-44f6-a85d-e139c66b9760', 'სწრაფი დიალოგი 🤖', 'რატომ ამბობს ბავშვი მოულოდნელად უარს დღის ძილზე? გრძელი სტატიების წასაკითხად დრო არ გაქვთ. შეკითხვა პირდაპირ Anacan AI-ს დაუსვით და 3 თვის ასაკში ძილის რეგრესიის შესახებ კონკრეტული, მოკლე პასუხი მიიღეთ.'),
  ('3d40ac30-86f9-4dfc-9db8-efd1a5dd1198', 'ზღაპრის ფილოსოფია 🪄', 'ჭკვიანი ზღაპრები კვლავ საქმეშია! სისტემაში ჩაწერეთ: „ზღაპარი ფერიაზე, რომელიც დღისით თამაშით დაიღალა, ღამით კი მშვენიერ სიზმრებს ხედავდა“. კითხვისას შეიძლება თავადაც ჩაგეძინოთ.'),
  ('6c6289cf-6e7c-4e83-a178-d01d67cef488', 'შეუსაბამო ჩაცმულობა 👗', 'ხან ბავშვს ზედმეტად თხლად აცმევთ, ხან კი ზედმეტად თბილად? ნუ იყოყმანებთ. ფანჯრიდან გახედვის ნაცვლად, დაუყოვნებლივ შეამოწმეთ ამინდი და ჩაცმულობა და მშვიდად იყავით სისტემის მიერ შემოთავაზებული ფენებად ჩაცმის რეკომენდაციის წყალობით.'),
  ('132d4620-5085-4072-ac1e-81f46dc4e74c', 'დაიცავით მისი ძილი ხმის საზომით 🤫', 'აღელვებული ხართ და სახლში სამზადისი მიმდინარეობს, მაგრამ ბავშვის ძილიც არ უნდა დაირღვეს. ოთახში ხმის საზომი ჩართული დატოვეთ და მაშინვე შეიტყვეთ, თუ ხმაური დასაშვებ ზღვარს გადააჭარბებს.'),
  ('32bd9b1c-365c-405d-addd-9a30d6295abc', 'დღეს დალაგება არ არის! 🛑', 'ვალდებული არ ხართ, ყველაფერი დაალაგოთ. ჩართეთ პარტნიორის რეჟიმი: დღეს სახლის დალაგებასა და საკვების შეკვეთაზე თქვენი პარტნიორი იზრუნებს. თქვენ კი უბრალოდ დაგეგმეთ ხვალინდელი, 3 თვის აღსანიშნავი ფოტოსესია.'),
  ('a4183b3c-1979-434f-a71f-64b50e2e618c', 'მომზადების დროა! 🎂', 'ყურადღება! ხვალ დიდი დღეა — ზუსტად 3 თვის ხდება! ხომ არ დაგავიწყდათ ტორტის შეკვეთა ან პატარა თემატური გარემოს მომზადება, რათა 90-ე დღეს განსაკუთრებული განწყობა შემატოთ? იჩქარეთ!'),
  ('10a571b7-6bc2-4092-a70f-a265883d71ba', 'ზუსტად 3 თვე! სრული 90 დღე! 🎉', 'თქვენ ეს შეძელით! უძილო ღამეების, კრიზისებისა და შიშების მიუხედავად, მთელი 90 დღის განმავლობაში შესანიშნავი გუნდური მუშაობა აჩვენეთ. გახსენით ბავშვის ფოტოსესია, აირჩიეთ 3 თვის სტიკერი და ეს სიხარული დაუყოვნებლივ გაუზიარეთ სხვა დედებს Anacan-ის საზოგადოებაში!'),
  ('9877e456-4a5e-45a3-aee9-e9703be5cf91', 'გილოცავთ! 🥂', 'გადახედეთ თქვენს ყველა ჩანაწერსა და განვითარების გრაფიკს. დაინახეთ, რამდენად გაიზარდა ბავშვი და რამდენად გაძლიერდით თქვენ. სწორედ ახლაა დრო, საკუთარი თავით იამაყოთ!'),
  ('9b7b163b-1de2-4ecd-becc-21f1f3c0e10e', 'თქვენი გუნდის გამარჯვების წამი 💖', 'ბავშვი სპეციალური ძილის ტაიმერის დახმარებით დააძინეთ. ახლა კი თქვენს პარტნიორთან პირისპირ დაჯექით. მადლობა გადაუხადეთ ერთმანეთს ამ 90 დღის თითოეული მომენტისთვის. ეს არა მხოლოდ ბავშვის, არამედ თქვენი მშობლობის 3 თვეცაა!'),
  ('5c67089a-581e-455d-b113-f87f427babb2', 'თქვენი განსაკუთრებული ზღაპარი 🪄', 'ამ საღამოს „ჭკვიანი ზღაპრების“ ხელსაწყოს საყვარელი თემა შევთავაზოთ: „ციდან ჩამოვარდნილი ყველაზე საყვარელი ვარსკვლავის ამბავი“. დაე, ოთახში მხოლოდ ამ ზღაპრის ხმა და სრული სიმშვიდე სუფევდეს.'),
  ('66bd508e-0413-4d01-9ea7-c369b0d8cafa', 'მამას დროა 👨‍👧', 'მოთმინება გეწურებათ? დღეს ცოტა ხნით მშობლობის მორიგეობა თქვენს პარტნიორს გადააბარეთ. მიეცით მათ საშუალება, ცოტა ხანი ერთად გაატარონ, თქვენ კი უბრალოდ ფეხები გაშალეთ და დაისვენეთ.'),
  ('8474a75e-7aaf-420e-b5ab-acd7d55ac51c', 'გულიანი სიცილის დროა! 😂', 'ახლა ის უბრალოდ კი აღარ იღიმის, არამედ ხმამაღლა იცინის! ეთამაშეთ და მუცელზე მოუღიტინეთ. ეს ხმა უძილოდ გატარებული ყველა ღამისთვის ყველაზე მშვენიერი ჯილდოა.'),
  ('0027b4ad-2816-4a79-ae3a-7ddbdcf29e4b', 'ძილის ნიშნები 🥱', 'თვალებს ისრესს, ყურს ექაჩება ან სივრცეს გაშტერებული უყურებს? ნუ დაელოდებით ღამის ჭირვეულობას. როგორც კი ამ ნიშნებს შეამჩნევთ, მაშინვე ჩააბნელეთ ოთახი და ძილის რუტინა დაიწყეთ.'),
  ('1867104a-7fa8-428a-ad5d-dd10e6890f0f', 'სამყაროს პირით შეცნობა 🤤', 'ხელები, სათამაშოები და ყველაფერი, რასაც იპოვის, პირდაპირ პირში მიაქვს? ასე შეისწავლის ის სამყაროს. ყველაფერს ნუ წაართმევთ, უბრალოდ დარწმუნდით, რომ მის გარშემო არსებული ნივთები სუფთაა.'),
  ('4ad3cf84-0aac-46cb-bfdf-5a928764105a', 'რატომ არის სახლი ასე არეული? 🌪️', 'ოთახის შუაში დაყრილ სათამაშოებსა და გაურეცხავ ჭურჭელს უყურებთ და საკუთარ თავს ადანაშაულებთ? დღეს ეს ჭურჭელი იქვე დატოვეთ. ბავშვის გაზრდა ისედაც საკმაოდ დიდი საქმეა!'),
  ('2e4ec0c9-5de6-407d-9e5d-26c67a8ecc5b', 'გადაბრუნების ვარჯიშები 🤸‍♂️', 'ის ზურგიდან მუცელზე გადაბრუნებას ცდილობს! ეს პატარა სხეულის დიდი ბრძოლაა. მხარი დაუჭირეთ მის ამ სახალისო მცდელობებს, თუმცა საწოლის კიდეებთან აუცილებლად ფრთხილად იყავით.'),
  ('91aad506-9119-4c1d-9011-ca750f77b2da', 'თქვენ საკმარისი ხართ! 💖', 'ამ დილით სარკეში ჩაიხედეთ და თავი დაღლილად, შესაძლოა არასაკმარისადაც იგრძენით? ღრმად ჩაისუნთქეთ. ბავშვის იმ უმანკო თვალებისთვის, რომლებიც თქვენ შემოგყურებენ, თქვენ მსოფლიოში ყველაზე სრულყოფილი ადამიანი ხართ. თქვენ საკმარისი ხართ!'),
  ('cc5d4a21-5a6c-4726-9656-04a48085588c', 'რამდენად დავიღალეთ? 🛋️', 'ბავშვმა დაიძინა, თქვენ კი? გახსენით განწყობის დღიური და პარტნიორთან ერთად დღევანდელი ქაოსი იუმორით ჩაინიშნეთ. რთული დღეები გაივლის, გუნდური სულისკვეთება კი დარჩება.'),
  ('8557b605-4ddd-4ff9-9e9a-646d4a26ea63', 'ძილის რეგრესია კარს მოგვადგა? 🤖', 'ბავშვმა მოულოდნელად ღამით ხშირად გაღვიძება დაიწყო? ნუ შეშინდებით, მე-4 თვის ძილის რეგრესია ახლოვდება. Anacan AI-სგან დაუყოვნებლივ მიიღეთ მოკლე, დამამშვიდებელი ინფორმაცია ამ ბიოლოგიური პროცესის შესახებ.'),
  ('88a16b76-764f-4acc-b335-0aa3f126d25a', 'გარეთ გასვლის დროა ⛅', 'ჩაცმა შეიძლება რთულად გეჩვენებოდეთ, მაგრამ სუფთა ჰაერზე 20 წუთით გასეირნება შესანიშნავად იმოქმედებს როგორც ბავშვზე, ისე თქვენს ფსიქოლოგიურ მდგომარეობაზე. შეამოწმეთ ამინდი, შეარჩიეთ შესაბამისი ტანსაცმელი, ჩაიცვით და ფანჯარა კი არა, კარი გააღეთ!'),
  ('bb5697de-df9c-4558-a606-a7acef72c755', 'მამა — ღამის გმირი 🦸‍♂️', 'პირველი თვეების საუკეთესო წესი: ბავშვისთვის ბოყინის ამოშვება და იავნანას სიმღერა მორიგეობით უნდა აკეთოთ! ამ საღამოს ბავშვი მამას ჰყავს ხელში, თქვენ კი ყურსასმენებს იკეთებთ და მუსიკით ტკბებით.'),
  ('4696c250-45bb-4765-b4bf-ee4e94f6361c', 'დედის ფინჯანი ☕', 'დღეს საკუთარი თავისთვის რა გააკეთეთ? არაფერი? როგორც კი ბავშვი დღის ძილს დაიწყებს, ტელეფონი გვერდზე გადადეთ. დაისხით ცხელი ყავა (ან ჩაი) და 10 წუთის განმავლობაში არაფერზე იფიქროთ.'),
  ('7831318d-6b24-4373-9578-2c2a43ef02bf', 'თმის მოქაჩვის ხელოვნება 💇‍♀️', 'თქვენი ბავშვი ხელებს პირდაპირ თმაში გიცურებთ და მთელი ძალით გქაჩავთ? ჩაჭიდების რეფლექსი გაუძლიერდა! განვითარების ეს სასაცილო, თუმცა მტკივნეული ეტაპი აუცილებლად გადაიღეთ ვიდეოზე და სამახსოვროდ შეინახეთ.'),
  ('d66ea07a-276e-489b-bd8f-3ff80abe7258', 'სხეულით კონტაქტის სასწაული 🫂', 'არაფრით იძინებს და საწოლში ჩაწვენისთანავე ტირილს იწყებს? ზოგჯერ არანაირი დამხმარე საშუალება არ არის საჭირო. გულზე მიიკარით და იგრძენით, როგორ გაწყნარებთ ორივეს კანით კანთან კონტაქტი.'),
  ('a99309cf-e0e5-4d40-9004-a8b08226861a', 'საყელო ყოველ 10 წუთში უსველდება?', 'კბილების ამოჭრის ტრეკერში ნაჩვენები პირველი ნიშნები რეალობად იქცევა. ხშირად შეუმოწმეთ ქვედა ღრძილი — შესაძლოა, პირველი თეთრი მარგალიტი უკვე გზაშია!'),
  ('b14018ad-b2b5-4374-a785-9d281ebdd7e0', 'სულ რაღაც 15 წუთი სიჩუმე 🤫', 'მთელი დღის დაღლილობისგან თავი გისკდებათ? როცა ბავშვს დააძინებთ, ჩართეთ ხმის საზომი და აკონტროლეთ გარემო, სახლში ყველას სიჩუმისკენ მოუწოდეთ და გონება დაასვენეთ.'),
  ('c69510ed-a6e2-4456-a462-211d3917dec3', 'რას აკეთებენ სხვა დედები? 💬', 'ფიქრობთ: „ნუთუ მხოლოდ ჩემი ბავშვი იქცევა ასე?“ მარტო არ ხართ! შედით Anacan-ის საზოგადოებაში, წაიკითხეთ დედების რეალური ისტორიები და შვებით ამოისუნთქეთ.'),
  ('51cd27c2-62e8-409d-8a08-48c1ba2f8c3b', 'მეგობარი სარკეში 👀', 'მიიყვანეთ ბავშვი სარკესთან. დააკვირდით, როგორ უყურებს საკუთარ ანარეკლს გაოცებული და ღიმილით. მან ჯერ არ იცის, რომ სარკეში თავადაა, თუმცა ეს თამაში შესანიშნავია მისი გონებრივი განვითარებისთვის.'),
  ('6f416e63-4acf-4dd2-8216-6601a8c26df5', 'გათავისუფლდით დანაშაულის გრძნობისგან 🛑', 'დღეს მოთმინება დაკარგეთ, იქნებ ცოტათი გაბრაზდით კიდეც და ახლა სინდისი გაწუხებთ? შეჩერდით. რობოტი ხართ? არა. მიიღეთ თქვენი ემოციები, აპატიეთ საკუთარ თავს და ხვალ ახალი დღე დაიწყეთ.'),
  ('d584b1c4-e42a-483d-b585-e83a9ab20c88', 'ენერგიის წყარო დედისთვის 🍲', 'ბავშვის დაპურებისას თავად მშიერი დარჩით? ჯანსაღი რეცეპტების განყოფილებიდან მოამზადეთ ადვილად მოსანელებელი და ენერგიის მომცემი წასახემსებელი. თქვენ ძალა გჭირდებათ, რათა ბავშვსაც მისცეთ ძალა.'),
  ('014e3f07-72e8-47f8-b62e-ff583a9df29e', 'მელაპარაკეთ! 🗣️', 'გიყურებთ და უცნაურ მარცვლებს წარმოთქვამს? გამოეხმაურეთ მის ხმებსა და პაუზებს. ის ახლა თქვენთან ნამდვილ დიალოგს მართავს! ეს მეტყველების განვითარების ერთ-ერთი ყველაზე მნიშვნელოვანი საწყისი ნაბიჯია.'),
  ('c290d85d-0e02-4b4e-aaab-db6ae8bfcaef', 'შეუმჩნეველი საჭიროებები 🛒', 'ყოველდღიურ ქაოსში ხომ არ გამოგელიათ რამე? ტუალეტის ქაღალდი, ბავშვის საფენები, შამპუნი? სანამ დაგავიწყდებათ, ახლავე დაამატეთ საყიდლების სიას, რათა თქვენს პარტნიორს ტელეფონზე შეტყობინება მიუვიდეს.'),
  ('e8ec2cd2-3417-4383-8892-bb623cb07365', 'შეაჩერეთ დრო 📸', 'ის ისე სწრაფად იზრდება... ამ საღამოს, როცა დაიძინებს, ყურადღებით დააკვირდით მისი სახის ნაკვთებს. ბავშვის ფოტოსესიის საშუალებით გადაიღეთ მისი პატარა ხელებისა და სახის ფოტო და დროის სვლას შეეწინააღმდეგეთ.'),
  ('2a23a61b-4ca6-48f6-8845-f47a357eed0f', 'რას ნიშნავს ეს ხმა? 🧩', 'თვალების გახელისთანავე წუწუნებს და ტირის? თუ მიზეზს ვერ პოულობთ, წამებში გამოიყენეთ ტირილის ანალიზი და გაშიფრეთ, რა იმალება ამ კრიზისის უკან.'),
  ('43fbc1cb-7e93-4983-b59f-f5bc67650d3e', 'ზღაპარი არასდროს მთავრდება 📖', 'ამ საღამოს ჭკვიან ზღაპრებს უფრო შემოქმედებითი დავალება მიეცით: „პატარა დათვის ამბავი, რომელიც დედის სურნელს ეძებს“. დაასრულეთ საღამო სიყვარულით სავსე და მშვიდი ფინალით.'),
  ('b8cf3d8c-2c7c-497e-8657-18fd989a1928', 'სახლიდან გასვლის გეგმა! 🌳', 'არ იცით, ბავშვთან ერთად სად წახვიდეთ? პარკში სეირნობა დამღლელია? დედებისთვის მეგობრულ ადგილებში აღმოაჩინეთ სივრცე, სადაც ბავშვთან ერთად კომფორტულად მოკალათდებით და ყავასაც დალევთ.'),
  ('1c648ce0-799c-41f0-964a-90e59cbddc3d', 'დიდი გამარჯვება, საერთო სიამაყე 🥂', '100 ღამე, 100 დღე... შეხედეთ თქვენს პარტნიორს, რომელმაც ეს დიდი ტვირთი თქვენთან ერთად იტვირთა. განწყობის დღიურში ჩაწერეთ მე-100 დღის სიამაყე და ერთმანეთს ფეხზე წამოდგომით დაუკარით ტაში. ეს თქვენი გუნდის გამარჯვებაა!'),
  ('52155593-73d7-4bb9-861d-d87a0ca100e9', '100-დღიანი სასწაული! 🎉', 'დიახ, დღეს ზუსტად 100 დღე გავიდა მას შემდეგ, რაც თქვენი ცხოვრება ძირეულად შეიცვალა! თქვენ საოცარ საქმეს აკეთებთ.'),
  ('7c63492d-1515-406a-bd31-b41ece7e0412', 'ტაში დაუკარით საკუთარ თავს 👏', 'უკან მოხედვისას ხედავთ, რამდენად შემაშინებელი იყო პირველი დღეები და რამდენი რამ გასწავლათ ამ დრომ. იამაყეთ საკუთარი თავით. ამ 100 დღის განმავლობაში მხოლოდ ბავშვი კი არ გაიზარდა — თქვენც გაიზარდეთ.'),
  ('724659ec-f59f-4bfe-b20d-efdd3d977217', 'თავისუფალი დრო 🛋️', 'როცა ბავშვი დამოუკიდებლად თამაშობს, მაშინვე საქმეების კეთებას ნუ შეუდგებით. ჩამოჯექით, უბრალოდ 5 წუთის განმავლობაში შორიდან უყურეთ და ყავა დალიეთ.'),
  ('aaed3963-e8dd-47d4-93bd-9b307c2b65fd', 'დილის ენერგია ⚡', 'თვალების გახელისთანავე ღუღუნებს? მას თქვენთან საუბარი სურს. გაუღიმეთ და უპასუხეთ — ეს მისი მეტყველების განვითარების საფუძველია.'),
  ('d1e64fb7-d149-4fd0-afca-834eed2264d1', 'ძილის რეგრესი? 🌙', 'ღამით ხშირად იღვიძებს? შესაძლოა, ეს მე-4 თვის ძილის რეგრესის ნიშნები იყოს. მოთმინება გამოიჩინეთ, ესეც დროებითი ეტაპია.'),
  ('13cad6d0-aa0a-426b-9515-1e96e73e716a', 'ახალი აღმოჩენები 🤲', 'ყველაფერს, რასაც ხელს მოჰკიდებს, პირში იდებს? ნუ შეშინდებით — ასე შეიცნობს ის სამყაროს. უბრალოდ გარემო სუფთად შეინარჩუნეთ.'),
  ('bfab4a59-c162-47a2-9035-51b03b7fe911', 'საოჯახო საქმეები მოიცდის 🛑', 'არეულ ოთახს რომ შეხედავთ, ნუ დაიძაბებით. თქვენ ადამიანს ზრდით და არ ხართ ვალდებული, იდეალური დიასახლისი იყოთ.'),
  ('ca9affc4-d638-41a2-8dc7-75447d9ea222', 'მამის ჯერია 👨‍🍼', 'ამ საღამოს ბავშვისთვის ბოყინის ამოშვებაში დახმარება და იავნანას სიმღერა მამის საქმეა. თქვენ კი წადით და დაისვენეთ.'),
  ('0695fd99-0b0d-4896-bd12-4ec8e6b49a4e', 'ნუ დაივიწყებთ საკუთარ თავს 🍲', 'ბავშვი დანაყრდა, თქვენ კი? ენერგიის აღსადგენად სრულფასოვნად უნდა იკვებოთ. დღეს თქვენთვის გემრიელი და ნოყიერი კერძი შეუკვეთეთ.'),
  ('957a90d0-61dc-45f5-a2da-ef7086521cd5', 'ოთახში უეცრად ხმამაღალი სიცილი გაიგონეთ? 😂', 'დიახ, ბავშვი უკვე ხმამაღლა იცინის! ამ ხმის მოსმენა მთელ თქვენს დაღლილობად ღირს.'),
  ('dd50206e-acee-43ac-8f19-c5dd29cf7e62', 'კანი კანთან კონტაქტი 🫂', 'ბავშვი ძალიან მოუსვენრადაა? თუ არაფერი შველის, მკერდზე მიიკარით. თქვენი გულისცემა მისთვის საუკეთესო დამამშვიდებელია.'),
  ('2c73f922-1b22-4eb6-922b-215d8e623242', 'თმის მოქაჩვის თამაში 💇‍♀️', 'თითებს თმაში გიხვევთ და ძლიერ გქაჩავთ? მას ჩაჭიდების რეფლექსი უვითარდება. ეცადეთ, განვითარების ამ ოდნავ მტკივნეულ მომენტს ღიმილით შეხვდეთ.'),
  ('f32eaadc-b85c-4f36-b182-6f6665e1eaae', 'სრული სიჩუმე 🤫', 'ჩაძინება უჭირს? ოთახი სრულად დააბნელეთ და ყოველგვარი ხმა გამორთეთ. სიბნელე და სიჩუმე ძილისთვის მისი საუკეთესო მეგობრებია.'),
  ('f4e3cb01-431f-4e52-a62b-ab96cbc1de4b', 'პირველი კბილები ამოდის? 🦷', 'ნერწყვდენა გაუძლიერდა? ჩაინიშნეთ კბილების ამოჭრის ტრეკერში და სუფთა კბილების მოსაფხანი სათამაშოები ყოველთვის ხელთ გქონდეთ.'),
  ('1e555e61-fac2-4756-83d5-5c2a2ceaa400', 'თქვენი განსაკუთრებული ზღაპარი 🪄', 'საღამოს დაძინება ჭკვიანი ზღაპრებით გაამარტივეთ. შექმენით მისთვის განსაკუთრებული, საყვარელი ამბავი და წაუკითხეთ.'),
  ('a4146327-bb44-44e0-9860-d8e3c1abe5c4', 'ჩვენ ერთი გუნდი ვართ! 💪', 'თავს მარტოსულად და დაღლილად გრძნობთ? ღრმად ჩაისუნთქეთ. თქვენ ამ ქარიშხლიანი დღეების ყველაზე ძლიერი გმირი ხართ.'),
  ('e3c0355b-40c6-476a-8c2d-f69c78debdb1', 'შთამბეჭდავი გადაბრუნება 🤸‍♂️', 'ზურგიდან მუცელზე გადაბრუნებას ცდილობს? ის ძალიან მონდომებულია! თვალყური ადევნეთ ამ მცდელობებს, მაგრამ საწოლზე არასდროს დატოვოთ მარტო.'),
  ('532d58e2-50f3-422a-818a-36c88094bb87', 'რა ჩავაცვა? ⛅', 'გარეთ გასვლისას აღარ იფიქროთ, რა ჩააცვათ. გაეცანით ამინდისა და ტანსაცმლის ხელსაწყოს და იდეალური შეხამება წამებში იპოვეთ.'),
  ('f37039a0-f7af-487a-827e-622e2d9e4d05', 'ძალების გამოლევა ნორმალურია 🔋', 'როცა მოთმინება გეწურებათ, თავს ცუდ დედად ნუ იგრძნობთ. ეს დაღლილობა ბუნებრივია. ნუ მოგერიდებათ პარტნიორისთვის მხარდაჭერის თხოვნა.'),
  ('f94cdd25-2b6b-47df-81dc-6e3cab221652', 'თქვენ საკმარისი ხართ! 🌸', 'დღეს ყველაფერი ცუდად მიდის? არა უშავს. თქვენს ბავშვს თქვენ გარდა არავინ სჭირდება. მისთვის სრულიად საკმარისი ხართ.'),
  ('18211145-ceeb-48f3-8053-1e2ff686e384', 'ხმების მაგია 🌊', 'თუ საღამოობით ტირილის შეტევები იწყება, ნუ შეშფოთდებით. ჩაურთეთ თქვენს ბავშვს თეთრი ხმები და ოთახის ატმოსფერო მყისიერად შეცვალეთ.'),
  ('49d00520-8368-4f13-9074-fbe894888b76', 'ჰკითხეთ ხელოვნურ ინტელექტს 🤖', 'ათასობით კითხვა გაწუხებთ? ნუ დაკარგავთ დროს ძიებაში — პირდაპირ ჰკითხეთ Anacan AI-ს და მიიღეთ ზუსტი, მეცნიერულად დასაბუთებული პასუხი.'),
  ('e6ea83f7-b8a5-46f7-ba44-81c58175071e', 'დაბლა შეხედეთ! 👣', 'მან უკვე აღმოაჩინა საკუთარი ფეხის თითები! ყურადღებით დააკვირდით ამ სახალისო და საოცარ მომენტს და დატკბით მისი განვითარებით.'),
  ('53a91083-d8e0-4baf-9f90-46ce72a9291d', 'მეგობარი სარკეში 👀', 'მიიყვანეთ ბავშვი სარკესთან. შესანიშნავი გასართობია, უყუროთ, როგორ აკვირდება გაოცებული საკუთარ ანარეკლს და იცინის.'),
  ('96d4756e-270f-426b-9e78-f2a573accdac', 'გარეთ გასვლის დროა 🌳', 'ოთხ კედელში ყოფნამ შეიძლება დაგღალოთ. ჩასვით ბავშვი ეტლში და თუნდაც 15 წუთით გაისეირნეთ სუფთა ჰაერზე. ეს ორივეს ძალიან წაგადგებათ.'),
  ('de11a3ea-d3e5-4374-adb5-b6c04fb6fc41', 'ღამის გმირი 🦸‍♂️', 'ღამით გაღვიძებამ დაგღალათ? ნუ მოგერიდებათ მამის გაღვიძება. გუნდურად მოქმედება ტვირთის თანაბრად განაწილებას ნიშნავს.'),
  ('07f48fa2-56fd-416e-adda-88c824f2bd6f', 'ღრმა ძილისთვის მზადება 🛀', 'თბილი აბაზანა, ნაზი მასაჟი და ოთახის ჩაბნელება... ძილის რუტინის დაცვა მშვიდი, უწყვეტი ღამეების საიდუმლოა.'),
  ('828415f3-317f-4e76-8caf-753026dcf9f1', 'თავს ნუ დაიდანაშაულებთ 💖', 'ფიქრობთ, რომ ბავშვს ცოტა დროს უთმობთ? ღიმილითა და ყურადღებით გატარებული 10 წუთი სტრესით სავსე 1 საათზე უფრო ძვირფასია.'),
  ('f4730701-e02f-4cf0-9730-df8b7e034297', 'მე თვითონ დავიჭერ! 🧸', 'ჩამოკიდებული სათამაშოებისკენ ზუსტად იწვდის ხელს? ეს ნიშნავს, რომ თვალისა და ხელის კოორდინაცია უმჯობესდება. წაახალისეთ სხვადასხვა ფერის ნივთებით.'),
  ('70597740-ab51-4b20-b743-042bccb768a6', 'დილის ვარჯიში 🐢', 'მუცელზე წოლა კისრის კუნთებს აძლიერებს. თუნდაც იტიროს, ყოველდღე გააგრძელეთ მცირე ხნით მაინც.'),
  ('81a8fffa-561b-48b8-9be0-ff9b930a7bac', 'ემოციური განტვირთვა 📝', 'დღეს გრძნობთ, რომ ყველაფერი ერთდროულად დაგატყდათ თავს? განწყობის დღიურში ჩაწერეთ ყველა სირთულე და დაღლილობა. ნუ ჩაახშობთ თქვენს გრძნობებს.'),
  ('87db18be-f6b3-443d-9d07-0e305836d90b', '110-ე დღის გამარჯვება! 🥂', 'უკვე ზუსტად 110 დღეა, რაც ახალ ცხოვრებას უძღვებით. მადლობა გადაუხადეთ ერთმანეთს და ამ საღამოს პარტნიორთან ერთად სიმშვიდით დატკბით.'),
  ('2226c745-19bb-4270-8e5c-a438c71816d4', 'რას აკეთებენ სხვა დედები? 💬', 'ნერვიულობთ? შეუერთდით Anacan-ის საზოგადოებას და დასვით თქვენი შეკითხვა. გვერწმუნეთ, ყველა დედა მსგავს გზას გადის.'),
  ('31bb23a0-6713-4c06-9f74-65b7a51a3dd9', 'დამამშვიდებელი ხმა 📖', 'დღეს საღამოს ბავშვს უბრალოდ თქვენი ხმით წაუკითხეთ პატარა ზღაპარი. სხვა არაფერი გჭირდებათ — დედის ხმა ყველაზე დიდი ჯადოსნობაა.'),
  ('34253cb9-0e01-47a7-9def-03c3b3e05aba', 'სახალისო თამაშები 🎈', 'წოლისას ფეხებს ჰაერში ისე ამოძრავებს, თითქოს ველოსიპედს ატარებს? ეს მისი ახალი გასართობია. აჰყევით თამაშში და მოუღუტუნეთ.'),
  ('4eb27952-4f25-4c0d-8e25-cf21169fe3eb', 'გაუფრთხილდით თავს 🥑', 'მშობიარობის შემდგომ პერიოდში ძვლები და კბილები უფრო მგრძნობიარე ხდება. არ დაგავიწყდეთ, რაციონში კალციუმით მდიდარი პროდუქტები დაამატოთ. კარგად იზრუნეთ საკუთარ თავზე.'),
  ('5e90ebc0-15bf-465f-ae64-eff8a7b0a00c', 'დღეს დილიდან არაფერი მოსწონს? ☁️', 'შესაძლოა, ზრდის ნახტომის პერიოდი ჰქონდეს. უბრალოდ უფრო ხშირად ჩაიხუტეთ და აგრძნობინეთ, რომ უსაფრთხოდაა.'),
  ('813f6345-1636-47fd-9a6b-aee16d069800', 'ძილის ნიშნები 🥱', 'ნუ დაელოდებით, სანამ თვალების ფშვნეტას და მთქნარებას დაიწყებს. როგორც კი მზერა გაუშტერდება, მაშინვე დაიწყეთ ძილის რუტინა.'),
  ('1063f207-152c-4454-9267-2e05e30929d8', 'ჭკვიანური სიჩუმე 🤫', 'ჩაძინებისას მოულოდნელი ხმები აღვიძებს? ხმის საზომით აკონტროლეთ ოთახში დეციბელების ზღვარი.'),
  ('17c1a37e-ab5c-4032-afa2-27e4d0964076', 'შია თუ დაიღალა? 😭', 'უმიზეზოდ ტირის და მისი ხმა განსხვავებულად ჟღერს? შესაძლოა, მიზეზი შიმშილი კი არა, უბრალოდ გამოუძინებლობა იყოს. ყურადღებით აკონტროლეთ მისი ძილის რეჟიმი.'),
  ('93512cbe-adab-49c7-8e82-4466bf0e00ad', '10 წუთი დედისთვის ☕', 'როგორც კი ბავშვი დაიძინებს, მაშინვე საოჯახო საქმეებს ნუ მივარდებით. ჩამოჯექით დივანზე, დალიეთ ყავა და 10 წუთის განმავლობაში უბრალოდ კედელს უყურეთ და დაისვენეთ.'),
  ('8bc219eb-803c-491e-9625-0efec17a7dad', 'გადააბარეთ მორიგეობა 🛋️', 'თუ ბავშვის დაძინებისთანავე თქვენც დაწოლა და ჩაძინება გინდათ, დანარჩენი საოჯახო საქმეები პარტნიორს გადააბარეთ. თქვენი ჯანმრთელობა ყველაფერზე მნიშვნელოვანია.'),
  ('924ff591-18ec-4c20-80af-4008cda2fc41', 'განსხვავებული ტონები 🗣️', 'მისი ღუღუნი უფრო ხმამაღალი და მრავალფეროვანი გახდა. მოუსმინეთ, მიბაძეთ და გააცინეთ.'),
  ('be9ad5fd-195c-40e7-99c6-7f5f91e01526', 'სამახსოვრო სია 🛒', 'უძილობამ მეხსიერება დაგიქვეითათ? ნუ შეეცდებით, სახლში საჭირო ყველაფერი გონებაში დაიმახსოვროთ — ჩაწერეთ საყიდლების სიაში.'),
  ('088b061c-e51f-4931-8636-b06152d7eaff', 'რაღაც გაწუხებთ? 🤖', 'ფორუმების საათობით კითხვის ნაცვლად, დაუსვით თქვენი შეკითხვა Anacan AI-ს და სწრაფად მიიღეთ პასუხი.'),
  ('5e878638-6613-43f0-b734-dd308940758d', 'ზუსტად 5 დღე დარჩა 4 თვემდე! 🎂', 'თუ ტორტთან ფოტოს გადაღების ტრადიცია გაქვთ, ახლა სწორედ მისი შეკვეთის დროა.'),
  ('616fd04c-b736-454a-9242-b3c011b0cdc5', 'მოთმინება გეწურებათ და ხელები დაგეღალათ? 👨‍👧', 'დღეს საღამოს ბავშვი მამას დაუტოვეთ, კარი დახურეთ და 15 წუთი საკუთარ თავს დაუთმეთ.'),
  ('232de7cd-2ff6-4b62-8cee-002063d545fd', 'არეული სამოთხე 🌪️', 'ბავშვის ნივთები მთელ სახლშია მიმოფანტული? დაე, ასე იყოს. არეული სახლი იმას კი არ ნიშნავს, რომ ცუდი დედა ხართ, არამედ იმას, რომ თქვენი მთავარი პრიორიტეტი ბავშვია.'),
  ('2cbef83d-a5f1-4b69-858b-9d1310e2cac3', 'სახლში ყოფნა მოგბეზრდათ? ☕', 'სახლში ყოფნა მოგბეზრდათ? დედებისთვის მეგობრული ადგილებიდან შეარჩიეთ ახლომდებარე კაფე, სადაც ბავშვის ეტლით შესვლა მოსახერხებელია.'),
  ('ff5950e2-aed4-41ca-bc9a-64a1b039968a', 'ჭკვიანი ზღაპრის დროა 🪄', 'ჭკვიან ზღაპრებში შექმენით ამ საღამოსთვის განსაკუთრებული ამბავი: ღრუბლებზე მძინარე მამაცი პატარას ისტორია.'),
  ('37346c6c-3239-4e07-bcc0-24af9be99f3f', 'ნერწყვდენის შემოტევები 🤤', 'მისი საყელო წამებში მთლიანად სველდება? ღრძილები ნელ-ნელა კბილების ამოსვლისთვის ემზადება. სილიკონის წინსაფრები საუკეთესო გამოსავალია.'),
  ('86a98c8a-884a-4567-83c1-4d206dccead9', 'სუფთა ჰაერი წამალია 🌳', 'თუ ბავშვი ძალიან მოუსვენარია, მაშინვე სუფთა ჰაერზე გაიყვანეთ. სუფთა ჰაერი ასეთი შემოტევების დროს ყველაზე მარტივი და ეფექტური საშუალებაა.'),
  ('ae291c04-b5c7-4ff1-937e-2b2b6d502624', 'ჩვენ ერთი გუნდი ვართ! 💖', 'რთული დღის შემდეგ პარტნიორთან პირისპირ დაჯექით და გულწრფელად ისაუბრეთ. ერთმანეთის მხარდაჭერა ტვირთს ანახევრებს.'),
  ('5fcfd433-5086-40d6-89d5-0d756fb06e17', 'მუსიკის ძალა 🎶', 'სცადეთ, საღამოსკენ დაწყებული უმიზეზო ტირილი ნელი ტემპის კლასიკური მუსიკით დაამშვიდოთ. ხშირად ეს ნამდვილად ჭრის.'),
  ('b4113857-b164-4ab8-b41d-4e516341edad', 'ცდილობს! 🤸‍♂️', 'მუცელზე წოლისას ხელებს ეყრდნობა და ცდილობს, თავი ასწიოს და ზემოთ გაიხედოს. მისი კუნთები დღითი დღე ძლიერდება — ყოჩაღ!'),
  ('ec61705b-0071-49b5-a6b0-3849dfa461ac', 'დროის გაჩერება 📸', 'ის ისე სწრაფად იზრდება... ლამაზად გამოაწყვეთ და ბავშვის ფოტოსესიით ეს წამები სამუდამოდ შემოინახეთ.'),
  ('72b166c9-a8f9-4dc5-be7f-5911ccda18ea', 'სიცილის რაოდენობა იზრდება 😂', 'თქვენს ყოველ სასაცილო მოქმედებას ხმამაღალი სიცილით პასუხობს. არ დაგავიწყდეთ ამ საოცარი მომენტის ვიდეოზე გადაღება!'),
  ('968ec1c9-36e5-4127-8374-922149e153dc', 'ძილის საფუძველი ⏱️', 'მეოთხე თვეში ძილის სწორი რეჟიმის ჩამოყალიბება ძალიან მნიშვნელოვანია. არასოდეს დაარღვიოთ რუტინა, რათა ღამეები მშვიდად გაატაროთ.'),
  ('e3d8f3ea-e67f-48ce-87e1-b51ae00dba4f', 'ყველაფერი წესრიგშია ✔️', 'ზოგჯერ გგონიათ, რომ ვერაფერს აკეთებთ. მაგრამ შეხედეთ მის სუფთა ტანსაცმელსა და დანაყრებულ მუცელს. თქვენ ყველაფერს შესანიშნავად ართმევთ თავს!'),
  ('4f713889-2b51-4db7-8d5d-7ee8676555a4', 'არაჩვეულებრივი 4 თვე! 🎉', 'შეგიძლიათ დაიჯეროთ? უკვე ზუსტად 120 დღეა, რაც ამ ჯადოსნურ გზას ერთად მიუყვებით! ბავშვის ფოტოსესიით ეს მომენტი დაუვიწყარ მოგონებად აქციეთ!'),
  ('8d072236-96cb-4886-b83d-b2d8d6523abb', 'უკან გაიხედეთ 📈', 'გაიხსენეთ პირველი დღეების შიშები. ახლა კი შეხედეთ, როგორი გამოცდილი დედა გახდით. იამაყეთ საკუთარი თავით!'),
  ('cfb7b283-3b96-44ef-84b8-0eca1ae74852', 'დატკბით 4 თვის სიამაყით.  🥂', 'დღეს საღამოს, ბავშვის დაძინების შემდეგ, არ დაგავიწყდეთ პარტნიორთან ერთად თქვენი გუნდური გამარჯვების აღნიშვნა!'),
  ('0fa7eced-c60c-4055-8da1-5df4e54ec1ce', 'მე ვლაპარაკობ! 🗣️', '„ბა-ბა“, „მა-მა“ — ასეთ მარცვლებს წარმოთქვამს? გახსენით განვითარების ტრეკერი, მონიშნეთ მეტყველების განვითარების ეს მნიშვნელოვანი ეტაპი და ხშირად ესაუბრეთ.'),
  ('19b9faef-1d59-42d5-bcb0-12290f627a1f', 'სიმშვიდის წუთი ☕', 'ოთახში არეულობა არსად გაქრება. სანამ ბავშვი დამოუკიდებლად თამაშობს, უბრალოდ მიირთვით ყავა და დატკბით ოთახში გამეფებული სიმშვიდით.'),
  ('65cb82a7-67e0-48b5-80b8-74e806b2980e', 'თქვენი განსაკუთრებული ზღაპარი 🪄', 'ამ საღამოს გახსენით „ჭკვიანი ზღაპრები“, ბავშვისთვის განსაკუთრებული ზღაპარი შექმენით და წაუკითხეთ.'),
  ('290cd0a7-b2db-4a34-8b28-f8d9bbc37b62', 'მუცელზე უფრო დიდხანს რჩება?  🐢', 'მისი კუნთები დღითი დღე ძლიერდება. წინ ფერადი სათამაშო დაუდეთ და ეს პროცესი კიდევ უფრო სახალისო გახადეთ.'),
  ('431c0c7a-2968-4edd-9882-df9a926adf72', 'ნერწყვის ჩანჩქერი 🤤', 'საყელო ხშირად უსველდება? აუცილებლად იქონიეთ ხელთ სილიკონის კბილების საჭრელი სათამაშო.'),
  ('5817fca0-3cbb-4276-a47d-9383c042597d', 'დეციბელების კონტროლი 🤫', 'როცა ბავშვს სძინავს, სახლში ყოველი ხმა გაფრთხობთ? ჩართეთ ხმის საზომი, შეამოწმეთ ოთახის აკუსტიკა და დაიცავით მისი ძილი.'),
  ('df219eb3-fe33-48d7-81df-3e2d39df4620', 'რამდენი რამ შეგიძლიათ! 💖', 'სარკეში თქვენს დაღლილ თვალებს შეხედეთ და გაიღიმეთ. ყოველგვარი ინსტრუქციის გარეშე ნამდვილ სასწაულს ზრდით!'),
  ('f8c399ff-a31e-4e77-a55d-5aab198bafaa', 'გასეირნების დროა ⛅', 'ამინდისა და ტანსაცმლის ხელსაწყოს დახმარებით წამებში შეარჩიეთ ამინდისთვის ყველაზე შესაფერისი ჩაცმულობა და სუფთა ჰაერზე გაისეირნეთ.'),
  ('fb3d810e-9135-4194-bb47-9ce9e588d70c', 'მამის მხრები 👨‍👧', 'დღეს საღამოს ოთახში ბავშვის ტარება და მისთვის ბოყინში დახმარება მთლიანად მამას ევალება.'),
  ('09081d67-84a7-403e-b876-3cc97106eb52', 'ჩაჭიდების ოსტატი 🧸', 'უკვე ზუსტად ეჭიდება ჩამოკიდებულ სათამაშოებს? მისი მოტორული უნარები შესანიშნავად ვითარდება. სიყვარულით დააკვირდით მის მცდელობებს და წაახალისეთ.'),
  ('15b0ec22-2156-4080-ad64-7a588de85fc5', 'არ ინერვიულოთ სახლის არეულობის გამო. 🌪️', 'თქვენი მთავარი საზრუნავი იდეალურად დალაგებული სახლი კი არა, ჯანმრთელი და ბედნიერი ბავშვია. მოდუნდით.'),
  ('e8181dea-ccff-4ba2-ae33-93fa07ea8c28', 'კითხვა გაქვთ? 🤖', 'ძილთან, კვებასთან ან აირებთან დაკავშირებით დაიბენით? ნუ დაკარგავთ დროს ფორუმებზე — უბრალოდ მისწერეთ Anacan AI-ს და მიიღეთ კონკრეტული, მეცნიერულად დასაბუთებული პასუხი.'),
  ('0140116f-1e50-4656-93a0-277a1645b1ba', 'ემოციური განტვირთვა 📝', 'რთული დღე იყო? გულწრფელად ჩაწერეთ განწყობის დღიურში ყველაფერი, რამაც დაგღალათ.'),
  ('1f632261-0ec6-4f1f-be74-71aaaaf4c706', 'მარაგი იწურება? 🛒', 'საფენები ან სველი ხელსახოცები გითავდებათ? სანამ დაგავიწყდებათ, დაამატეთ საყიდლების სიაში, რათა თქვენს პარტნიორს ტელეფონზე შეტყობინება მიუვიდეს.'),
  ('f2dc5d57-91a4-45de-b81b-0b2998a8593b', 'მხიარული კისკისი 😂', 'თქვენს საყვარელ ჟესტებს ხმამაღალი სიცილით პასუხობს? აუცილებლად გადაიღეთ ეს ვიდეოზე და მისი სიცილიც აღბეჭდეთ.'),
  ('1c68be5f-505e-4c46-be58-571a7196e98d', 'გააზიარეთ გამოცდილება 💬', 'ფიქრობთ: „ნეტავ მხოლოდ მე ვარ ასე?“ შეუერთდით Anacan-ის საზოგადოებას და გულწრფელად ესაუბრეთ დედებს, რომლებსაც მსგავსი განცდები აქვთ.'),
  ('4b6ccde7-7cce-4142-8822-fa952592f465', 'ძილის ნიშნები 🥱', 'თვალებს იფშვნეტს ან ყურს ექაჩება? ნუ დაელოდებით გადაღლილობით გამოწვეულ ჭირვეულობას — მაშინვე ჩააბნელეთ ოთახი და დაიწყეთ საღამოს რუტინა.'),
  ('7b3662bc-d715-468b-a32f-326c023ef66e', 'გადაბრუნების ჩემპიონი 🤸‍♂️', 'ცდილობს ზურგიდან მუცელზე და მუცლიდან ზურგზე გადაბრუნებას? საწოლზე არასოდეს დატოვოთ მარტო და დატკბით ამ აქტიური პერიოდით.'),
  ('0aded6bb-b0fa-4cac-b297-4311bcd7f798', 'არ ხართ ვალდებული, ყველაფრის გაკეთება მოასწროთ. 🌸', 'ბავშვის სიყვარულით სავსე თვალებისთვის, რომლებითაც ის გიყურებთ, თქვენ მსოფლიოში ყველაზე სრულყოფილი ადამიანი ხართ.'),
  ('658bd674-cc84-4d51-8a7e-822b9255b9d7', 'აღმოაჩინეთ ახალი ზღაპარი 📖', 'მოდით, ეს საღამო განსხვავებული გავხადოთ. ჭკვიან ზღაპრებში შექმენით ამბავი ქალთევზაზე, რომელიც წყალქვეშა სამყაროს აღმოსაჩენად გაემგზავრა, და ოთახი ჯადოსნობით აავსეთ.'),
  ('b8b57297-f4b4-4473-87af-9acfeee74dd3', 'არ შია — მაშ, რატომ ტირის? 🧩', 'რაც არ უნდა გააკეთოთ, ვერ მშვიდდება? შეწყვიტეთ გამოცნობა, ტირილის ანალიზს მისი ხმა მოასმენინეთ და დაუყოვნებლივ გაარკვიეთ, რა აწუხებს.'),
  ('9ce62e84-5124-421b-bdd6-3fa7c590aa1a', 'ფერების ახალი სამყარო 👀', 'ახლა ის ფერებს უფრო მკაფიოდ და ხასხასად ხედავს. აჩვენეთ კონტრასტული ფერების სათამაშოები.'),
  ('b42e7a75-4fab-45bd-89fe-f334b8181757', 'საკუთარი თავიც არ დაგავიწყდეთ 🍲', 'თუ ბავშვი დანაყრდა, ახლა თქვენი ჯერია. ჯანსაღი რეცეპტებიდან შეარჩიეთ ენერგიით სავსე წასახემსებელი, რომელიც 10 წუთში მზადდება, და საკუთარ თავზე იზრუნეთ.'),
  ('cf65b961-f3be-4509-9af3-0b6c17f757e7', 'მამისა და ბავშვის დრო 🫂', 'მამებსაც სჭირდებათ ბავშვთან სხეულებრივი კონტაქტი. საღამოს ისინი მარტო დატოვეთ, რათა ერთმანეთთან კავშირი გაამყარონ, თქვენ კი დაისვენოთ.'),
  ('132a3a1b-1001-4fec-a775-7883117a6988', 'როგორ მიდის რეჟიმი? 📈', 'გააანალიზეთ ბოლო დღეების სტატისტიკა კვების კონტროლისა და ძილის ტაიმერის მონაცემების მიხედვით.'),
  ('61f15500-8617-42e1-b833-c482f6ae935c', 'სათამაშოებს ხშირად იატაკზე აგდებს? 🧸', 'ასე ბავშვი მიზეზშედეგობრივ კავშირს სწავლობს. ახალი სათამაშოების სანახავად შეგიძლიათ რეკომენდებულ პროდუქტებს გადახედოთ.'),
  ('92d9f590-3160-4e15-966d-3ee82f9db1d0', 'სამყაროს პირით შეცნობა 🦷', 'ყველაფერს, განსაკუთრებით კი საკუთარ თითებს, გამუდმებით ღეჭავს? კბილების ამოჭრის თვალის მიდევნების ფუნქცია გაფრთხილებთ! დროა, სუფთა კბილების ამოსაჭრელი რგოლები მოამზადოთ.'),
  ('02654c5d-e5dc-4168-b20f-e995771e2a24', 'ერთობის ძალა 💬', 'დღეს საღამოს ეწვიეთ Anacan-ის საზოგადოებას და განვითარების პროცესი თქვენთან იმავე თვეში მყოფ დედებს გაუზიარეთ და განიხილეთ.'),
  ('158eaa65-78bb-40d6-8e0b-a66fa8dda6b3', 'იამაყეთ საკუთარი თავით 👏', 'მიმოიხედეთ ოთახში და დაფიქრდით, რამხელა გზა გაიარეთ. პირველი კვირების შიში უკვე ნამდვილ დედობრივ თავდაჯერებად იქცა. თქვენ საოცარი ხართ!'),
  ('50a6a489-6955-49c4-9f2c-e768f813dd17', 'ფეხის თითები პირში 👣', 'ბავშვი საკუთარ ფეხებს აღმოაჩენს და მათ პირში ჩადებას ცდილობს! აუცილებლად გადაიღეთ განვითარების ეს სახალისო და საოცარი მომენტი, რათა თქვენს ახლობლებს გაუზიაროთ.'),
  ('4a91e0c3-a4cb-4e5c-b68a-474b7d153369', 'განაგრძეთ საფენების თვლა! 🧷', 'Anacan-ში ყოველდღიურად გამოყენებული საფენების რაოდენობის აღრიცხვით დარწმუნდით, რომ თქვენი ბავშვი საკმარის საკვებს იღებს.'),
  ('4d4822a8-2d08-4775-b1d8-71202fa22509', 'ენერგია დედისთვის 🔋', 'ძუძუთი კვებისას თქვენც წვავთ კალორიებს. ახლავე ჯანსაღ რეცეპტებში სცადეთ რძის გამომუშავების ხელშემწყობი, მსუბუქი წვნიანის რეცეპტი.'),
  ('dac4f6ca-f7b7-40a3-a427-dece1b15eaf7', 'ვაკვირდებით სიმაღლისა და წონის მატებას! 📏', 'განვითარების მონიტორინგის განყოფილებაში განაახლეთ ბოლო მონაცემები, გადახედეთ თქვენი ბავშვის ჯანსაღი განვითარების გრაფიკს და იამაყეთ მისი წინსვლით.'),
  ('648c9f9b-15f6-49e6-933c-3da395b58c88', 'დაჟინებული მცდელობები 🐢', 'მუცელზე წოლისას წინ გახოხებას ცდილობს და ბრაზდება? მას უკვე გადაადგილება სურს! სათამაშოებით წაახალისეთ, რომ წინ გაიწიოს.'),
  ('903de81c-9443-4b1e-8662-d8cbed1ca54e', 'კბილის საკვნეტები საქმეში ერთვება! 💧', 'მას ყველაფრის პირში ჩადება სურს. უსაფრთხოებისა და განვითარების შესახებ მეტის გასაგებად გადახედეთ ბლოგებს.'),
  ('9dd94bee-b76e-43ec-94c9-51937e10ad6e', 'დღეს დალაგება არ იქნება 🛑', 'დაიღალეთ? უთხარით თქვენს პარტნიორს. დღეს არც სახლში მომზადებული საჭმელი იქნება და არც დალაგება. დღეს უბრალოდ დედის დასვენების დღეა!'),
  ('1a9e3246-5c48-4c5d-9be8-b35243065267', 'რა გვაკლია სახლში? 🛒', 'შამპუნი გათავდა თუ ბავშვის ზეთი? ფიქრი არ არის საჭირო. შეავსეთ საყიდლების სია, დანარჩენი კი თქვენს პარტნიორს მიანდეთ.'),
  ('6e836ffa-475e-446a-bc5a-eddbd0eeeec4', 'გაფილტრეთ ხმები 🤫', 'ქუჩიდან შემოსული ხმები ღრმა ძილს უშლის ხელს. შეამოწმეთ ხმის საზომი და, საჭიროების შემთხვევაში, ფონად თეთრი ხმაური ჩართეთ.'),
  ('e31b222d-5c34-45e3-b291-c3f8c8989d13', 'ლამაზი და ნამდვილი 💇‍♀️', 'შეიძლება პერანგზე ლაქა გქონდეთ, თმა კი აჩეჩილი. მაგრამ თქვენი ბავშვის თვალში მსოფლიოში ყველაზე ლამაზი ხართ. ნუ გაკიცხავთ საკუთარ თავს.'),
  ('29aebaa9-a1ae-4a00-8854-a771800bf560', 'შუალედებს ვარეგულირებთ. 🍼', 'კვების კონტროლის ხელსაწყოს საშუალებით თვალყური ადევნეთ კვებისა და სიფხიზლის პერიოდებს და იდეალური რეჟიმი შექმენით.'),
  ('3942c763-be60-481b-bb4e-1a53687a8d34', 'მამის თავდადება 💖', 'მანაც მთელი დღე იმუშავა, მაგრამ ახლა მამის მორიგეობაა. გვერდიდან უყურეთ, როგორ ფრთხილად აძინებს ბავშვს, და დატკბით ამ ბედნიერებით.'),
  ('3cd07d9d-076c-4523-8ba1-47b8737d6bbf', 'მე აქ ვარ! 👀', 'ოთახის ერთი კუთხიდან სახელით დაუძახეთ. დაინახავთ, როგორ მაშინვე შემობრუნდება ხმისკენ და შემოგხედავთ. სმენა და ყურადღება შესანიშნავად აქვს განვითარებული!'),
  ('25015c8c-0ca6-43bc-a465-c8490ee6d808', 'თქვენზე შეყვარებულია! 🥰', 'ძუძუთი კვებისას ან ჭამის დროს თვალს არ გაშორებთ? ის თქვენი სახის ნაკვთებს სწავლობს და ძალიან უყვარხართ!'),
  ('565cbb4c-39dd-4c69-980a-b02d63f6cdb4', 'ცოტაოდენი სიმშვიდე 🛋️', 'რთული დღის შემდეგ განწყობის დღიურში თქვენი ემოციები ჩაიწერეთ. გახსოვდეთ, წერა და გულის გადაშლა საუკეთესო უფასო ფსიქოლოგია.'),
  ('f0338702-1ba5-495b-840d-9ad790085c24', 'პედიატრი თქვენს ჯიბეში 🤖', 'ბავშვის განავალი უჩვეულო ფერისაა ან სხეულზე მცირე გამონაყარი აქვს? პანიკაში ჩავარდნამდე Anacan AI-ს მისწერეთ და შესაძლო გამომწვევი მიზეზები გაიგეთ.'),
  ('5996a5e8-c639-4f34-8f02-ccaebf8a96eb', 'ხელები საქმეშია 👐', 'ცდილობს, დიდი საგნები ორივე ხელით ერთდროულად დაიჭიროს? ეს დეტალი განვითარების ტრეკერში აღნიშნეთ და შესამოწმებლად რბილი ბურთი მიეცით.'),
  ('6dd3138c-1bd5-4dac-80d8-a5b5ffa166ee', 'სცივა თუ სცხელა? ⛅', 'ტანსაცმლის შერჩევა ყოველთვის პრობლემაა? ამინდისა და ტანსაცმლის ინსტრუმენტი ზუსტად გეტყვით, რამდენ ფენად ჩააცვათ. თავს ნუ გადაიღლით.'),
  ('a1ca42ca-05ed-42dc-af4a-99af31043623', 'დედის ხმის ჯადოსნური ძალა 🎶', 'ვერცერთი აპლიკაცია ვერ შეცვლის დედის იავნანას. ამ საღამოს უბრალოდ გულში ჩაიკარით და ჩუმად უმღერეთ მისი საყვარელი იავნანა.'),
  ('b0613bc2-510c-4582-8829-fd09f1ed2898', 'გემოებით დაინტერესდა? 🍽️', 'როცა ჭამთ, ყურადღებით აკვირდება თქვენს თეფშსა და პირს? მყარი საკვებისადმი (დამატებითი კვებისადმი) ინტერესი ნელ-ნელა იღვიძებს!'),
  ('cd2a678b-9234-4910-9725-95b0b9e3443e', 'საღამოს რუტინა ძილის მატარებლის ბილეთია.🚂', 'თბილი აბაზანა, მასაჟი და ოთახის ჩაბნელება... არასოდეს დაარღვიოთ ეს რუტინა.'),
  ('cfb5c864-525c-4db1-869c-94c18824f78e', 'ყოველდღიურ სირბილში სადილი ფეხზე მდგომმა არ მიირთვათ. 🥑', 'ჯანსაღი რეცეპტებიდან მარტივი სალათი მოამზადეთ, დაჯექით და გემრიელად მიირთვით.'),
  ('3325dc87-cd45-494c-a42f-d923bde10bc2', 'გულიანი სიცილის კადრი 📸', 'ის ყოველდღე უფრო მეტს იცინის! მოაწყვეთ ბავშვის ფოტოსესია და გადაიღეთ მისი მხიარული, გულიანი სიცილი, რომელიც დღევანდელ ნეგატიურ განწყობას გაფანტავს.'),
  ('37ba096d-4d60-4d73-9c8d-1e0fc44ce8b8', 'დამამშვიდებელი ზღაპარი 🪄', 'შექმენით კეთილი ზღაპარი პატარა გმირზე, რომელიც სულ მალე 5. თვის გახდება, და ოთახში სასიამოვნო ატმოსფერო შექმენით.'),
  ('b25cbe8a-634a-4863-b56c-19ebbb878905', '5. თვისკენ! 🎂', 'ყურადღება! სულ რაღაც 10 დღის შემდეგ დიდი დღეა — 5. თვის შესრულება! ხომ არ დაგვიწყებიათ განსაკუთრებული ტორტის შეკვეთა ან თემატური გაფორმების დაგეგმვა? სამზადისი ახლავე დაიწყეთ!'),
  ('0b47b1a5-bf87-49ea-bae7-b0bb8b0e46f2', 'ბავშვი ვერ მშვიდდება და თქვენ საშინლად დაიღალეთ?  🛑', 'ბავშვი უსაფრთხოდ ჩააწვინეთ საწოლში და 5 წუთით სხვა ოთახში გადით. თქვენც გაქვთ სულის მოთქმის უფლება.'),
  ('1f6b52bc-5331-4372-8c65-f0f6ee109098', 'ხმის ანალიზატორი 😭', 'ოთახში დაბრუნდით და ბავშვი ისევ ტირის. ნუ დაიძაბებით! მისი ტირილი დაუყოვნებლივ მოასმენინეთ ტირილის ანალიზატორს, გაარკვიეთ, რა სჭირდება და დაამშვიდეთ.'),
  ('90149fde-54c0-4d98-ba95-374230a626e1', 'ხელები სულ პირში აქვს 🦷', 'ყველაფერს გამალებით ღეჭავს? თბილი და სუფთა ტილოები მის ღრძილებს დაამშვიდებს.'),
  ('6065edb3-ae62-4429-96cf-e894b4e2c7d8', 'ღამის გმირები 🦸‍♀️', 'ვიცით, ღამით ხშირი გაღვიძება ძალას გაცლით. განწყობის დღიურში ჩაწერეთ, რამდენად დაღლილი ხართ, და პარტნიორს მხარდაჭერა სთხოვეთ.'),
  ('ad21218a-5e7d-436c-9c74-264990c096bd', 'მხედავ? 🧸', 'სათამაშო სანახევროდ დამალეთ საბნის ქვეშ. ეძებს და პოულობს? ეს შესანიშნავი ნაბიჯია იმის გააზრებისკენ, რომ საგანი მაშინაც არსებობს, როცა არ ჩანს!'),
  ('faba44da-b2fb-4aa7-a374-4d5f04ad9d27', 'გასეირნება აუცილებელია ⛅', 'შეამოწმეთ ამინდისა და ტანსაცმლის ხელსაწყო, ჩააცვით ბავშვს და პარკში მინიმუმ 20 წუთით გაისეირნეთ. ეს აუცილებლად გჭირდებათ თქვენც და ბავშვსაც.'),
  ('46a6fe4d-c7d7-4c66-88f8-3a6a534cd295', 'ექიმივით ჭკვიანი 🤖', 'ბავშვის მოძრაობაში რამე უცნაური შენიშნეთ? ინტერნეტში შემაშფოთებელი ამბების კითხვას სჯობს, ზუსტი პასუხი Anacan AI-სგან მიიღოთ.'),
  ('ac9907ff-b075-4451-8252-dbc842968901', 'იავნანა მამისგან 👨‍🍼', 'პარტნიორის რეჟიმში შეტყობინებები თქვენს პარტნიორს მიუვა. ამაღამ ძილის წინ ზღაპარი და იავნანა მან წაიკითხოს, თქვენ კი მსმენელი იყავით.'),
  ('aedfce5f-449d-49c9-8f9b-a5ac88f1e750', 'დილის კონცერტი 🎶', 'გიყურებთ, ფართოდ იღიმის და სხვადასხვა მარცვალს წარმოთქვამს. ახლა ოთახში ყველაზე მშვენიერ დილის კონცერტს მართავს — ყურადღებით მოუსმინეთ!'),
  ('46db3cbc-ae0b-4520-b12e-5586db9977cf', 'ძილის რეჟიმთან დაკავშირებით ეჭვები გაქვთ? 🤖', 'მეხუთე თვის მოახლოებასთან ერთად ძილის ცვლილებების შესახებ თქვენი კითხვები Anacan-ის საზოგადოებაში დაწერეთ და სხვა დედებისგან მხარდაჭერა მიიღეთ.'),
  ('b203fb94-1780-44e0-8f8f-1e6840729e68', 'ხმის კონტროლი 🤫', 'მეოთხე თვის ბოლოს დაძინება ზოგჯერ რთულდება. ჩართეთ ხმის საზომი, შეამოწმეთ ხმის ლიმიტი და ოთახი აუცილებლად დააბნელეთ.'),
  ('d7985574-7fae-4ef9-b025-2442a8b0b3a6', 'თქვენ საუკეთესო ხართ! 💖', 'სრულყოფილი ადამიანი არ არსებობს, მაგრამ თქვენი ბავშვისთვის საუკეთესო დედა სწორედ თქვენ ხართ.'),
  ('2e9ea238-ddc7-4932-b1bd-be8b8ed87bc9', 'მოიმარაგეთ ენერგია 🍲', 'თუ თქვენ ჯანმრთელი ხართ, ბავშვიც ჯანმრთელია. ჯანსაღი რეცეპტებიდან შეარჩიეთ გემრიელი კექსის რეცეპტი, რომელიც ენერგიით აგავსებთ, და ყავასთან ერთად მიირთვით.'),
  ('9ee15fcc-d37a-4d63-9556-1032868e91e8', 'ტორტი შეუკვეთეთ? 🎂', 'სულ რაღაც 5 დღეში თქვენი პატარა 5 თვის გახდება! ახლავე შეუკვეთეთ 5 თვის თემატიკის განსაკუთრებული ტორტი ან სამოსი!'),
  ('d25e75e7-0029-43b9-b1e7-c401d6b9ca28', 'ჭკვიანი ისტორიების ოსტატი 🪄', 'ამ საღამოს „ჭკვიან ზღაპრებში“ შექმენით განსაკუთრებული, ემოციური ისტორია იმის შესახებ, თუ როგორ სწრაფად გაიზარდა თქვენი პატარა 5 თვის განმავლობაში.'),
  ('6a21d9c4-96ab-4453-9d5f-d8979016e2cc', 'დამოუკიდებლობისკენ 🤸‍♂️', 'უკვე თავისუფლად ბრუნდება ზურგიდან მუცელზე? მისი კუნთები სწრაფად ვითარდება. რეგულარულად დააწვინეთ ხალიჩაზე, რათა თავისუფლად იმოძრაოს.'),
  ('c057830d-8790-40ec-a09d-53a252d3ee15', 'გათავისუფლდით დანაშაულის გრძნობისგან 🛑', 'დღეს მოთმინება დაკარგეთ და ხმას აუწიეთ? თავს ცუდად ნუ იგრძნობთ. თქვენ დაუღალავი რობოტი არ ხართ. ხვალ კვლავ სცდით.'),
  ('fd786e6d-a723-4c95-b0ff-52e01e6ccb8a', 'მარტო არ ხართ 💬', 'გადახედეთ, რას წერენ Anacan-ის საზოგადოებაში სხვა დედები, რომელთა ბავშვებიც 5 თვის არიან. ყველა ოჯახში ერთნაირი ქაოსი, უძილობა და სიყვარულია!'),
  ('05aab0a6-c49b-4d4d-bd26-b20d5c9af4d5', 'ნუ გამოგრჩებათ ძილის ნიშნები 🥱', 'თუ ბავშვი მზერას სიცარიელეს მიაპყრობს, მაშინვე ყველაფერს თავი დაანებეთ. სანამ ძილის დრო გადაუვა, საწოლში დააწვინეთ.'),
  ('0ecae509-0e89-4406-80e4-d01161b92754', 'კბილების ამოსაჭრელი სათამაშო — ნამდვილი მხსნელი 🦷', 'ყველაფრის კბენას ცდილობს? გაგრილებული სილიკონის კბილების ამოსაჭრელი სათამაშოები მის ღრძილებს სწრაფად დაამშვიდებს.'),
  ('60bbb8df-cb46-4930-8422-5f0c6fa7daad', 'მე თქვენ გიცნობთ! 🥰', 'ოთახში შესვლისას განსაკუთრებულად, უფრო აღტაცებულად და სხვაგვარად გიღიმით? დიახ, ბავშვი სხვებისგან გამოგარჩევთ და თქვენი სურნელი ძალიან უყვარს!'),
  ('adbfecc6-7186-41fe-a870-83cf6809ec00', 'დრო საკუთარ თავსაც დაუთმეთ 🛋️', 'როცა ბავშვს სძინავს, დრო საოჯახო საქმეებს კი არა, საკუთარ თავს დაუთმეთ. ოთახი შეიძლება მოუწესრიგებელი დარჩეს, მაგრამ თქვენი ენერგიის აღდგენა აუცილებელია.'),
  ('ba61a641-e703-4b01-b161-601cf36add7a', 'ბუნების მაგია ⛅', 'ძალიან მოუსვენრადაა? არცერთი სათამაშო არ შველის? შეამოწმეთ ამინდი და ბავშვის ტანსაცმელი, შემდეგ კი დაუყოვნებლივ გაიყვანეთ სუფთა ჰაერზე. ბუნება საუკეთესო დამამშვიდებელია.'),
  ('e97550d4-794b-4a9e-94da-881338077d81', 'ისევ რატომ ტირის? 😭', 'ტირილის შეტევები, რომელთა მიზეზსაც ვერ ადგენთ, ძალიან დამღლელია. თავს ნუ გადაიღლით — გამოიყენეთ ტირილის ანალიზი და აღმოაჩინეთ ბავშვის ხმაში დამალული გზავნილი.'),
  ('5e32b8c3-c1c2-4dbd-a394-96bbfe39e0ed', 'დედების ძალა 🤖', 'მოავლეთ ოთახს თვალი და იამაყეთ, როგორ მიაღწიეთ ამ 5 თვემდე. თუ რაიმე გაშინებთ, მისწერეთ Anacan AI-ს და მიიღეთ მხარდაჭერა.'),
  ('792511a4-1d02-4324-a33c-59bacedb4645', 'იუბილემდე 1 დღე დარჩა! 🎈', 'ხვალ დიდი დღეა! 5 თვის შესრულების აღსანიშნავად ტორტი მზადაა და ტანსაცმელი დაუთოებულია? გახსენით ბავშვის ფოტოსესიის ინსტრუმენტი და საცდელი კადრები ახლავე გადაიღეთ!'),
  ('af763c83-7a14-4218-b3c2-49cdc7255b18', 'გულახდილად ისაუბრეთ პარტნიორთან 🥂', 'ამ საღამოს პარტნიორთან ერთად გაიხსენეთ პირველი დღეები და იცინეთ. თქვენ დიდი გზა გამოიარეთ!'),
  ('3e771dfa-0468-483a-a4d1-a848e1eff82d', 'ზუსტად 5 თვე! 🎉', 'დაუჯერებელია! უკვე ზუსტად 150 დღეა, სრული 5 თვეა, რაც გუნდურად ზრდით ამ სასწაულს. ბავშვის ფოტოსესიით დაუყოვნებლივ უკვდავყავით ეს განსაკუთრებული დღე!'),
  ('8b9fb477-8954-40e0-aa32-b586b125f806', 'ტაში დაუკარით საკუთარ თავს 👏', 'გადახედეთ ყველა თქვენს ჩანაწერსა და განვითარების გრაფიკს. ნახეთ, რამდენად გაიზარდა ბავშვი და თქვენ რამდენად პროფესიონალი გახდით!'),
  ('bd07ae62-d716-4470-a226-d2dc1c918f7c', 'გამარჯვების საღამო 🪄', 'ამ საღამოს ჭკვიან ზღაპრებში უბრალოდ ჩართეთ სიყვარულით სავსე ამბავი და პარტნიორთან ერთად აღნიშნეთ თქვენი გუნდური გამარჯვება!'),
  ('2668e59c-6b79-42c7-903c-24806c9559de', 'დედისთვის 10 წუთი ☕', 'სახლში არეულობა არსად გაიქცევა. სანამ ბავშვს სძინავს, მაშინვე საქმეებს ნუ შეუდგებით. დაისხით ცხელი ყავა და 10 წუთის განმავლობაში უბრალოდ კედელს უყურეთ.'),
  ('99274040-6797-4a0d-b6f8-4369e3e3436d', 'ერთი ხელიდან მეორეში გადატანა 🧸', 'შეუძლია სათამაშოს ერთი ხელიდან მეორეში გადატანა? ეს იმის დასტურია, რომ ტვინის ორივე ნახევარსფერო შესანიშნავად მუშაობს! აღნიშნეთ ეს მნიშვნელოვანი უნარი განვითარების ტრეკერში.'),
  ('cbbe11e5-f7e4-422b-8d0e-cf2a181684c8', 'გაგვიზიარეთ თქვენი განწყობა 📝', 'დღეს ძალიან დაიღალეთ თუ ენერგიულად გრძნობთ თავს? გულწრფელად ჩაწერეთ თქვენი ემოციები განწყობის დღიურში. გულის გადაშლა თავს უკეთ გაგრძნობინებთ.'),
  ('503f1c6e-f32e-42d4-96c5-cf663fbb57cd', 'ხმოვანი ისტორიები 🪄', 'მოდით, ამ საღამოს ოთახში განსხვავებული ჯადოსნური განწყობა შევქმნათ. ჭკვიან ზღაპრებში შექმენით ისტორია მამაცი კატის შესახებ, რომელიც მთვარეზე გაფრინდა, და ძილის რუტინა უფრო სახალისო გახადეთ.'),
  ('b7efef49-9c1d-49fe-9e2d-4889969cd685', 'ბუნებრივი დამამშვიდებელი ⛅', 'ძალიან მოუსვენრადაა და სახლში გაჩერება არ სურს? შეამოწმეთ ამინდი, შესაფერისად ჩაიცვით და მაშინვე პარკში გადით. სუფთა ჰაერი ორივესთვის საუკეთესო წამალია.'),
  ('fa1bb3e3-66d0-4cc7-8d63-61478e045e39', 'ყველაფერს, რასაც ხელს მოჰკიდებს, პირში იდებს? 🤤', 'ეს სამყაროს შეცნობის მისი გზაა. უბრალოდ ყურადღება მიაქციეთ, რომ მის გარშემო არსებული ნივთები სუფთა და უსაფრთხო იყოს.'),
  ('dcb350dc-49ff-4c0f-b6e7-e4777138873a', 'ტირილის კოდი 😭', 'დილაობით ჭირვეულობა შიმშილითაა გამოწვეული თუ კბილების ამოსვლით? ნუ გამოიცნობთ — მოასმენინეთ ხმა ტირილის ანალიზს და დაუყოვნებლივ გაიგეთ, რა სჭირდება ბავშვს.'),
  ('e9e20fa8-2ecc-4e20-8e3b-90ed8d74e1e4', 'მოთმინება გეწურებათ?  👨‍👧', 'ამ საღამოს ბავშვზე ზრუნვა მთლიანად მამას მიანდეთ, თქვენ კი ყურსასმენები გაიკეთეთ და დაისვენეთ.'),
  ('eb92cfef-308b-40f6-9214-f36986bb10ba', 'ჩვენ ერთი გუნდი ვართ! 🌟', 'თავს მარტოდ და სხვებისგან გაუგებრად გრძნობთ? ღრმად ჩაისუნთქეთ. თქვენ ამ ქარიშხლიანი დღეების ყველაზე ძლიერი გმირი ხართ და ყველაფერს შესანიშნავად უმკლავდებით.'),
  ('20b556a3-1b9a-4c51-bc18-a68bea6af134', 'სრული სიჩუმე 🤫', 'ჩაძინება გართულდა? ხმის საზომით შეამოწმეთ ოთახში ხმაურის დონე დეციბელებში. ტელევიზორს ხმა გამოურთეთ და ოთახი მთლიანად დააბნელეთ.'),
  ('5cbbbe44-8dae-45f7-8369-18aae825551b', 'ღრძილები ექავება? 🦷', 'თითები მუდმივად პირში აქვს და უხვად მოსდის ნერწყვი? დროა, გაცივებული კბილების ამოსაჭრელი სათამაშოები გამოიყენოთ.'),
  ('f00bd5bd-287a-46fb-8532-9655a797aab3', 'საკუთარი თავი არ დაგავიწყდეთ 🥑', 'ბავშვის დაპურებისას თავად მშიერი დარჩით? ჯანსაღი რეცეპტებიდან შეარჩიეთ ენერგიის მომცემი კერძი, რომლის მომზადებაც 10 წუთში შეიძლება.'),
  ('0ed5ca13-9d93-489b-99e3-a198862dd467', 'ძილის რეგრესია? 🤖', 'უეცრად ღამით გაღვიძებებმა იმატა? შესაძლოა, ეს განვითარების ნახტომი იყოს. მიიღეთ ინფორმაცია Anacan AI-სგან 4-5 თვის ასაკში ძილის რეგრესიის შესახებ.'),
  ('4d2be2fb-f7bc-4bd9-a340-7f3c456ff87c', 'ღამის იავნანა 🎶', 'არცერთი ხმა არ არის დედის ხმასავით დამამშვიდებელი. ამ საღამოს უბრალოდ გულში ჩაიკარით და ხმადაბლა უმღერეთ მისი საყვარელი იავნანა.'),
  ('57873aa1-acb0-439b-98e9-70fd8b575b47', 'ოთახი სათამაშოებითაა სავსე? 🌪️', 'ოთახი სათამაშოებითაა სავსე? ნუ ინერვიულებთ იმის გამო, რომ სახლში არეულობაა. თქვენ შესანიშნავი დედა ხართ — თქვენი პრიორიტეტი ბავშვია და არა დალაგება.'),
  ('bb854fb5-befa-49e1-bf95-4f811865fe4f', 'რას აკეთებენ სხვა დედები? 💬', 'ნერვიულობთ? შეუერთდით Anacan-ის საზოგადოებას. იმის დანახვა, რომ იქ სხვა დედებიც იმავე უძილობასა და სირთულეებს უმკლავდებიან, დაგამშვიდებთ.'),
  ('23720343-b8a6-4414-a95b-f2b2afa5cab1', 'მარაგი იწურება 🛒', 'საფენები ან ბავშვის ზეთი გაგითავდათ? ნუ გადატვირთავთ გონებას წვრილმანებით — ჩაწერეთ საყიდლების სიაში, რათა თქვენმა პარტნიორმა დაბრუნებისას იყიდოს.'),
  ('77df7526-5d53-4e7e-8d03-ef3224240fd5', 'კითხვა გაქვთ? 🤖', 'ბავშვის განვითარებასთან დაკავშირებით ათასობით კითხვა გაქვთ? ფორუმების საათობით კითხვის ნაცვლად, მისწერეთ Anacan AI-ს და მიიღეთ მოკლე, მეცნიერულად დასაბუთებული პასუხი.'),
  ('ffb2dcc3-196c-4439-b233-ee14c9337ae5', 'ყოველდღიურად გამოყენებულ საფენებს ვაკვირდებით. 🧷', 'იმის დასადგენად, იკვებება თუ არა ბავშვი საკმარისად, და მისი საჭმლის მომნელებელი სისტემის შესაფასებლად, Anacan-ში საფენის ყოველი გამოცვლა აღრიცხეთ.'),
  ('450e1ee4-0ee2-4568-acc9-22677b87903d', 'ის მე მიყურებს! 📸', 'ოთახის რომელ ნაწილშიც არ უნდა იყოთ, ის თვალებით გამოგაყოლებთ.'),
  ('297cb03f-f4bc-4fe0-aba8-dc539d62bcce', 'ერთობის ძალა 🛋️', 'რთული დღის შემდეგ პარტნიორთან პირისპირ დაჯექით და გულწრფელად ისაუბრეთ. ერთმანეთის მხარდაჭერა და გუნდურობის განცდა ტვირთს ანახევრებს.'),
  ('3f28d490-5c17-44cf-b02a-a0a5ea44e564', 'იამაყეთ საკუთარი თავით 👏', 'გაიხსენეთ, როგორ გეშინოდათ პირველ კვირებში. ახლა კი ყველაფერს ნამდვილი პროფესიონალივით უმკლავდებით! თქვენ საოცარი ხართ!'),
  ('bdd2cc62-7f55-4558-bc57-531c376128b9', 'გემრიელ აღმოჩენებამდე ცოტა დარჩა! 🥦', 'დამატებითი კვების დაწყებამდე მოსამზადებლად, განყოფილებაში „რეცეპტები“ გაეცანით ჩვილებისთვის განკუთვნილი პირველი პიურეების იდეებს.'),
  ('1325aee8-211f-49a3-af39-fd0cef6023c0', 'პედიატრი თქვენს ჯიბეში 🤖', 'ძილის რეჟიმი უეცრად შეიცვალა? სანამ შეშფოთდებით, Anacan AI-სგან მიიღეთ ინფორმაცია და რჩევები 5 თვის ასაკში ძილის რეგრესის შესახებ.'),
  ('6692c328-0a11-48ba-9a13-0443aeead27c', 'დამოუკიდებლად გადაბრუნება 🤸‍♂️', 'ის უკვე თავისუფლად ბრუნდება ზურგიდან მუცელზე? ფართო ხალიჩაზე დააწვინეთ, რათა კუნთები თავისუფლად ავარჯიშოს.'),
  ('e22900db-05e9-4ef6-8e2b-3f0d3690dce5', 'შეაჩერეთ დრო 📸', 'ის ისე სწრაფად იზრდება... ძილის დროს მისი ტკბილი, მშვიდი სახე ბავშვის ფოტოსესიის მეშვეობით აღბეჭდეთ და მოგონებად შეინახეთ.'),
  ('696eaa28-30b3-4a02-87e3-0cd00d185f07', 'მხოლოდ 10 წუთი 🛀', 'ბავშვმა დაიძინა და თქვენც სიმშვიდე მოიპოვეთ. ჭურჭლის სარეცხი მანქანის დაცლის ნაცვლად, თბილი შხაპის ქვეშ შედით და 10 წუთის განმავლობაში წყლის ხმას მოუსმინეთ.'),
  ('27873a53-69de-4c27-a20c-c15256739b9a', 'ჩვენ ერთი გუნდი ვართ! 🌟', 'ღამით გაღვიძებებმა დაგღალათ? ნუ მოგერიდებათ მამის გაღვიძება. გუნდად ყოფნა ნიშნავს ტვირთის სიყვარულით გაზიარებას.'),
  ('77e7ae70-0ff1-4b56-a2eb-2e4ed43e460c', 'ამინდის სიურპრიზი ⛅', 'სასეირნოდ გასვლისას ამინდმა შეცდომაში არ შეგიყვანოთ და არ გაცივდეთ. ამინდისა და ჩაცმულობის დამხმარის საშუალებით მარტივად მიიღეთ გარეთ არსებულ პირობებთან ყველაზე შესაფერისი გადაწყვეტილება.'),
  ('82b46290-c3d6-4ad5-8d94-600e0311ba33', 'ჩამეხუტე — სიჯიუტე 🛋️', 'არ სურს თქვენი ხელებიდან ჩამოსვლა? ეს განებივრება არ არის — მას თქვენი სურნელი სჭირდება. მაგრად ჩაიხუტეთ, ეს დღეები სწრაფად გაივლის.'),
  ('42fb5186-3443-4ea8-b1d1-54ac0c1a9ccb', 'ღამით გაღვიძებებს რუტინად ვაქცევთ. 😴', 'ყოველი გაღვიძებისას შუქს ნუ აანთებთ. აჭამეთ Anacan-ის ტაიმერის გამოყენებით და თეთრი ხმების დახმარებით კვლავ დააძინეთ.'),
  ('b460ef96-b60f-4ef0-893f-50bb64397d11', 'დღეს დალაგება არ იქნება 🛑', 'დაიღალეთ? უთხარით თქვენს პარტნიორს. დღეს არც სახლში მომზადებული საჭმელი იქნება და არც დალაგება. დღეს დედის დასვენებისა და ყავის დღეა!'),
  ('f10c4519-156b-4eca-8117-28c233b11129', 'მელაპარაკეთ! 🗣️', 'ყურადღებით გისმენთ და სხვადასხვა ბგერას გამოსცემს? ის თქვენთან ნამდვილ დიალოგს მართავს. უპასუხეთ მის ხმებს და ხელი შეუწყვეთ ამ კომუნიკაციას.'),
  ('01ae2fd5-6c02-4d2d-8691-089f2f85a502', 'ჯდომის პირველი მცდელობები 🪑', 'როდესაც მხარდაჭერით სვამთ, თავსა და ზურგს უფრო სწორად იჭერს? ეს კუნთების გაძლიერებაზე მიუთითებს. დაიწყეთ მხარდაჭერით ჯდომის ხანმოკლე ვარჯიშები.'),
  ('3ae0359c-235f-4ea4-9a97-929da4740dc7', 'ოთხი კედლიდან გაქცევა ☕', 'სახლში ყოფნა უკვე გაწუხებთ? იპოვეთ უახლოესი კაფე, სადაც ბავშვის ეტლით მარტივად შეხვალთ, და ყავა განსხვავებულ გარემოში მიირთვით.'),
  ('a66c05d0-980d-472a-8187-902f12cc0e87', 'ძილის ნიშნები 🥱', 'თუ თვალებს ისრესს და ერთ წერტილს მიშტერებია, ნუ დაელოდებით, სანამ ჭირვეულობას დაიწყებს. დაუყოვნებლივ დააბნელეთ ოთახი და ძილის რუტინა დაიწყეთ.'),
  ('5cacab5c-c142-4162-9118-942fa6678db3', 'შია თუ დაიღალა? 🧩', 'რაც არ უნდა გააკეთოთ, მაინც არ ჩუმდება? შესაძლოა, უბრალოდ ძალიან დაიღალა. დასარწმუნებლად გამოიყენეთ ტირილის ანალიზი და გაარკვიეთ, რა მიზეზი იმალება ამ ხმის უკან.'),
  ('92894378-2736-426b-99c1-d408f0e76945', 'ხმის კონტროლი 🤫', 'ჩაძინებისას უეცარი ხმები აღვიძებს? ხმის საზომის მეშვეობით აკონტროლეთ ოთახში ხმაურის დონე.'),
  ('aab86ddb-de4e-46b1-a168-2145a68d243b', 'დედის ენერგია 🔋', 'შუადღისთვის ენერგია გამოგელიათ? ჯანსაღ რეცეპტებში გაეცანით სმუზის რეცეპტს, რომელიც ხელს შეუწყობს როგორც რძის გამომუშავებას, ისე თქვენს მხნეობას.'),
  ('2f79ccaf-9886-4cc5-8de6-c8151fcbc753', 'მუსიკის ძალა 🎶', 'სცადეთ, საღამოსკენ დაწყებული უმიზეზო ტირილი ნელი ტემპის კლასიკური მუსიკით ან თეთრი ხმაურით დაამშვიდოთ.'),
  ('6ac04f2a-cb0e-47b2-91d7-757e201eec80', 'ამინდის სიურპრიზი ⛅', 'სასეირნოდ გასვლისას ამინდმა არ მოგატყუოთ და ბავშვი არ გააციოთ. ამინდისა და ჩაცმის დამხმარის მეშვეობით შეარჩიეთ გარემო პირობების შესაბამისი სამოსი.'),
  ('e458b23e-9cff-4743-b31b-4ce87556944c', 'საკვების მიმართ ინტერესი? 🍽️', 'როცა ჭამთ, თქვენს თეფშს თვალს ვერ აშორებს? მყარ საკვებზე გადასვლისთვის მზადყოფნის ნიშნები ჩნდება. თუმცა ჯერ ნუ იჩქარებთ — დაელოდეთ მე-6 თვეს.'),
  ('25b7edd7-55ed-4b9f-b931-91fdbbe75fb4', 'გამოცდილების გაზიარება 💬', 'ბავშვის ახალმა მოძრაობამ გაგაოცათ? შეუერთდით Anacan-ის საზოგადოებას და ეს აღმოჩენა სხვა დედებთან განიხილეთ.'),
  ('6e3db4e0-169c-4b26-92b7-3281435ce439', 'ზღაპარი არასდროს მთავრდება 📖', 'ამ საღამოს ჭკვიან ზღაპრებს შესანიშნავი დავალება მიეცით: მოყევით ცისარტყელაზე მძინარე ფერიის ამბავი.'),
  ('91c0efe1-1cc1-4adc-a7d5-398c2cd0f5c8', 'თქვენ საკმარისი ხართ! 💖', 'დღეს ყველაფერი ცუდად წავიდა? თავს ნუ დაიდანაშაულებთ. რობოტი ხომ არ ხართ? არა. მიიღეთ თქვენი გრძნობები, აპატიეთ საკუთარ თავს და გაიღიმეთ.'),
  ('0a102f68-6cd0-452b-9fa2-0aa24ccb1814', 'ნახევარი წლისკენ 📈', 'გჯერათ? მე-6 თვის დასრულებამდე სულ ცოტა დრო დარჩა! გახსენით განვითარების მონიტორინგის ფუნქცია და სიამაყით გადახედეთ ამ თვემდე განვლილ საოცარ გზას.'),
  ('f295eaa8-f2fa-42e3-9941-4e98a42703f5', 'გადააბარეთ მორიგეობა 🛋️', 'თუ ბავშვის დაძინებისთანავე თქვენც წამოწოლა და დაძინება გინდათ, დანარჩენი საოჯახო საქმეები პარტნიორს გადააბარეთ.'),
  ('ff9ff3bc-de2b-4add-9a4b-7f31e78329bd', 'მეხსიერების ნისლი 📝', 'გულმავიწყობა მშობიარობის შემდგომი პერიოდის ნაწილია. აქტიურად გამოიყენეთ საყიდლების სია, რათა არაფერი დაგავიწყდეთ.'),
  ('05c1eaa2-4a23-478a-a816-f6e336bf8650', 'მეგობარი სარკეში 👀', 'მიიყვანეთ ბავშვი სარკესთან. საკუთარ ანარეკლზე დაკვირვება და ღუღუნი მისი გონებრივი განვითარებისთვის შესანიშნავი და სახალისო აქტივობაა.'),
  ('5e7b7a68-8be5-48ad-9672-e4c1e4de4125', 'გუნდური განხილვა 🥂', 'გახსენით განწყობის დღიური, დღევანდელი ნეგატივი უკან მოიტოვეთ და პარტნიორთან ერთად ერთი გუნდად ყოფნით დატკბით.'),
  ('d8a2fadb-f854-4f00-9556-bd2eb305be92', 'კბილის ამოსაჭრელი სათამაშოს ძიება 🦷', 'ნერწყვდენა და ღრძილების ქავილი იმატებს. სუფთა კბილის ამოსაჭრელი რგოლები თქვენი საუკეთესო დამხმარეა.'),
  ('06a86ce4-2e7a-4f35-a865-7e585114d78f', 'მხედავ? 🧸', 'დამალეთ სათამაშო საბნის ქვეშ. ეძებს და პოულობს? ეს შესანიშნავი მომენტია იმის გასააზრებლად, რომ საგანი მაშინაც არსებობს, როცა არ ჩანს!'),
  ('478917cd-56f0-483c-b59c-a9eb5ad87e67', 'ღამის გმირი მამაა 🦸‍♂️', 'პირველი თვეების საუკეთესო წესი: იავნანის სიმღერისას ერთმანეთს უნდა შეენაცვლოთ! ამ საღამოს ბავშვი მამას ჰყავს ჩახუტებული, თქვენ კი ისვენებთ.'),
  ('b31044ce-8042-4a44-af14-b71856994efe', 'გარეთ გასვლის დროა 🌳', 'ჩასვით ბავშვი ეტლში და თუნდაც 15 წუთით სუფთა ჰაერზე გაისეირნეთ. სუფთა ჰაერი ორივეს გჭირდებათ.'),
  ('43a61a10-16d2-4518-b6bc-479ff5985526', 'დილის კონცერტი 🎶', 'გიყურებთ, ფართოდ იღიმის და ახალ ხმებს გამოსცემს. ახლა ოთახში ყველაზე ლამაზ კონცერტს მართავს — ყურადღებით მოუსმინეთ!'),
  ('d26efa64-1d4b-4147-ad2c-7a309dc2c5a4', 'ძილის საფუძველი ⏱️', 'თბილი აბაზანა, მასაჟი და ოთახის ჩაბნელება... არასოდეს დაარღვიოთ ძილის რუტინა, რათა ღამეები მშვიდად გაატაროთ.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ka = v.t, body_ka = v.b
FROM (VALUES
  ('ddef2887-0bec-40c8-91a4-05edb188b86b'::uuid, 'ექიმივით ჭკვიანი 🤖', 'ინტერნეტში შემაშფოთებელი ამბების კითხვის ნაცვლად, დამატებითი კვების დაწყებასთან დაკავშირებული კითხვები Anacan AI-ს დაუსვით და დამშვიდდით.'),
  ('6b3cb5c5-1970-4fdc-b099-5f91eda48758', 'ჭკვიანური სიჩუმე 🤫', 'ჩაძინებისას მოულოდნელი ხმები აღვიძებს? ხმის საზომით აკონტროლეთ ოთახში დეციბელების დონე.'),
  ('7bed8f71-075d-414c-be3c-9bf2c4a82ea3', 'ჩაცმის დილემა 👗', 'ხან ძალიან თხლად, ხან კი ზედმეტად თბილად აცმევთ? ნუ იფიქრებთ ბევრს. შეამოწმეთ ამინდი და ჩაცმულობა და თავდაჯერებით ჩააცვით.'),
  ('dcc95e44-9688-48db-a64f-a544e0720dec', 'ნადიმი დედისთვის 🥑', 'ყოველდღიურ ფუსფუსში სადილი ფეხზე დგომით არ მიირთვათ. ჯანსაღი რეცეპტებიდან მარტივი სალათი მოამზადეთ, დაჯექით და გემრიელად მიირთვით.'),
  ('0b493cb3-45ff-4a4a-8782-40ce3d792d2c', 'გაუფრთხილდით თავს 🛋️', 'როცა ბავშვს სძინავს, დრო სახლის საქმეებს კი არა, საკუთარ თავს დაუთმეთ. ოთახი შეიძლება მოუწესრიგებელი დარჩეს, მაგრამ თქვენი ენერგია უნდა აღდგეს.'),
  ('6c45dc56-f21e-446c-bca9-3243c5189d5e', 'სათამაშოებს ძირს ყრის და აკვირდება? 🎯', 'ასე ბავშვი მიზიდულობის ძალასა და მიზეზ-შედეგობრივ კავშირს შეისწავლის! მოთმინებით დაუბრუნეთ სათამაშო.'),
  ('fe300d0f-4fab-4b71-8cf4-cb6e9825b2b9', 'თქვენ მარტო არ ხართ 💬', 'ღელავთ? შეუერთდით Anacan-ის საზოგადოებას და დასვით თქვენი შეკითხვა. გვერწმუნეთ, ყველა დედა მსგავს გზას გადის.'),
  ('3cf67221-c8f7-4a51-b0e0-23076d4cd531', 'დამატებითი კვებისთვის მზადება 🥣', 'მე-6 თვემდე ცოტა დრო დარჩა. პირველი პიურეების შესახებ ინფორმაციის მიღება გსურთ? დამატებით კვებაზე გადასვლის შესახებ ძირითადი ინფორმაცია Anacan AI-ს ჰკითხეთ.'),
  ('9d27d38e-2ae9-4b74-ae13-5eaab2d9f776', 'ერთობის ძალა 🥂', 'ამ საღამოს პარტნიორთან ერთად გაიხსენეთ, როგორ მიაღწიეთ ამ მნიშვნელოვან ეტაპს. როგორც გუნდმა, შესანიშნავად გაართვით თავი.'),
  ('c09a3abb-6f75-4a5a-99d6-fbc4e4f2425f', 'ნახევარ წლამდე 10 დღე დარჩა! 🎂', 'მოემზადეთ! ზუსტად 10 დღეში თქვენი პატარას 6 თვე შეუსრულდება — ანუ ნახევარი წლის გახდება! სწორედ ახლაა ნახევარი წლის იუბილესთვის ტორტის შეკვეთისა და განსაკუთრებული სამოსის შერჩევის დრო!'),
  ('989db48b-e318-47e6-9019-f4f957b60d59', 'ტირილის შეტევები, რომელთა მიზეზსაც ვერ ხვდებით, ძალიან დამღლელია. 😭', 'თავს ნუ გადაიღლით — გამოიყენეთ ტირილის ანალიზი და გაიგეთ, რა იმალება ბავშვის ხმაში.'),
  ('a6d43603-e416-4760-8a3f-176e42bf2dc7', 'ჭიტას თამაში ყველაზე მეტად უყვარს! 🙈', 'სახე ხელებით დაიფარეთ, შემდეგ გამოაჩინეთ და ნახეთ, როგორ გაუხარდება. მეტი ასეთი თამაში ბლოგების განყოფილებაში აღმოაჩინეთ.'),
  ('a85c19d5-09d8-4302-9d52-6f63acdaebee', 'ღამის იავნანა 🎶', 'ვერცერთი ხმა ვერ ამშვიდებს ისე, როგორც დედის ხმა. ამ საღამოს გულში ჩაიკარით და ხმადაბლა უმღერეთ.'),
  ('2fc6e816-81b8-4662-85f5-ea7fd4e748a8', '10 წუთი დედისთვის ☕', 'არეული ოთახი არსად გაიქცევა. როგორც კი ბავშვი დაიძინებს, საქმეს მაშინვე ნუ შეუდგებით. დაისხით ყავა და უბრალოდ 10 წუთით დაისვენეთ.'),
  ('8dd01cdf-8e98-4b6a-91ce-2edcc5e6a4df', 'გაფილტრეთ ხმაური 🤫', 'ქუჩიდან შემოსული ხმაური ღრმა ძილს ხელს უშლის. შეამოწმეთ ხმაურის საზომი და საჭიროების შემთხვევაში თეთრი ხმაური გამოიყენეთ.'),
  ('9bb7f096-5daa-4e1c-9f5e-688698945f7a', 'კბილები ამოდის? 🦷', 'ქვედა ღრძილი სტკივა ან შეშუპებულია? პირველი კბილები შესაძლოა დაახლოებით 6 თვის ასაკში გამოჩნდეს.'),
  ('3259939c-e2bd-4126-abc3-d15439051dda', 'სუფთა ჰაერის ძალა 🌳', 'თუ ბავშვი ძალიან მოუსვენარია, მაშინვე სუფთა ჰაერზე გაიყვანეთ. სუფთა ჰაერი ასეთი კრიზისების შესამსუბუქებლად ყველაზე მარტივი და ეფექტური საშუალებაა.'),
  ('382370f5-d970-4100-b0bc-f8460c0758ae', 'ჩაჭიდების ოსტატი 👐', 'ცდილობს ორივე ხელით ერთდროულად დაიჭიროს დიდი საგნები? შესამოწმებლად რბილი ბურთი მიეცით.'),
  ('ccbcf153-8cbf-48df-8422-b2c8e63c5f2d', 'ხმოვანი ისტორიები 🪄', 'ამ საღამოს „ჭკვიან ზღაპრებში“ შექმენით ისტორია მამაც რაინდზე, რომელიც უკვე 6 თვის გახდა.'),
  ('0e21a1c5-4a15-41e9-abfe-8342adaebb92', 'სრულყოფილება არ არსებობს 🛑', 'დღეს მოთმინება დაკარგეთ ან იქნებ გაბრაზდით? თავს ცუდად ნუ იგრძნობთ. ჩაწერეთ თქვენი ემოციები განწყობის დღიურში და დამშვიდდით.'),
  ('31e88909-0b90-49e0-8727-857efb6836f3', 'იავნანა მამისგან 👨‍🍼', 'პარტნიორის რეჟიმში შეტყობინებები თქვენს პარტნიორს გაეგზავნება. ამაღამ დასაძინებლად იავნანა მან უმღეროს.'),
  ('a24757f2-97fa-405f-9959-e4c715aa8ed8', 'გეძებ! 👀', 'როცა ოთახიდან გადიხართ, თვალებით გეძებთ და ტირის? შესაძლოა, განშორების შფოთვა ნელ-ნელა იწყებოდეს. აგრძნობინეთ, რომ უსაფრთხოდ არის.'),
  ('081951c6-0b7d-4045-b641-a4716f751a3d', 'მამის მხრები 👨‍👧', 'მოთმინება გეწურებათ? ჩართეთ პარტნიორის რეჟიმი. ამ საღამოს ბავშვზე ზრუნვა მთლიანად მამას მიანდეთ.'),
  ('b099b3d8-9148-450c-8795-4ab16ea72b2c', 'კიდევ გაქვთ შეკითხვები? 🤖', 'პირველად რომელი ბოსტნეულის პიურე შევთავაზო? – ეს და სხვა შეკითხვები Anacan AI-ს დაუსვით და ზუსტი ინფორმაცია მიიღეთ.'),
  ('e3aafd70-c5f0-4254-ba79-e24f4dca3567', 'ნერწყვის ჩანჩქერი 🤤', 'საყელო ხშირად უსველდება? მოამზადეთ სილიკონის კბილების ამოსაჭრელი სათამაშოები.'),
  ('34eb8ef4-b7a5-4969-916d-abfccb27c775', 'დეციბელების კონტროლი 🤫', 'როცა ბავშვს სძინავს, სახლში ყოველი ხმა გაფრთხობთ? ჩართეთ ხმის საზომი და შეამოწმეთ ოთახის აკუსტიკა.'),
  ('da48ef6d-1a19-4a32-9bdc-d912779edf22', 'არეული სახლი, ბედნიერი ბავშვი 🌪️', 'ოთახი მთლიანად სათამაშოებითაა მოფენილი? დალაგებაზე უფრო მნიშვნელოვანია მასთან ღიმილით გატარებული 10 წუთი.'),
  ('ec6f8334-a2ec-4274-9ce3-07c0a3276622', 'დამოუკიდებლად გადაბრუნება 🤸‍♂️', 'უკვე სრულად აითვისა ზურგიდან მუცელზე და მუცლიდან ზურგზე გადაბრუნება? მონიშნეთ ეს გამარჯვება განვითარების ტრეკერში!'),
  ('27dc11b4-8fdd-4bba-a87f-5fa9b264f28d', 'ძილის ნიშნები 🥱', 'თვალებს იფშვნეტს? ნუ დაელოდებით, სანამ ძალიან გადაიღლება — დაუყოვნებლივ ჩააბნელეთ ოთახი და ძილისწინა რუტინა დაიწყეთ.'),
  ('a9165256-d8d7-431e-ac72-e7ef065f4e1f', 'ენერგია დედისთვის 🍲', 'ხვალინდელი იუბილესთვის ენერგია დაგჭირდებათ. ჯანსაღი რეცეპტებიდან ნოყიერი წასახემსებელი შეარჩიეთ და დაისვენეთ.'),
  ('febb037e-33e6-4760-bc42-cae9b6c70a8a', 'ბოლო სამზადისი! 📸', 'ხვალ დიდი დღეა! ნახევარი წლის აღსანიშნავი ტორტი მზად არის? ბავშვის ფოტოსესიისთვის ყველაზე ლამაზი ტანსაცმელი მოამზადეთ — ხვალ ბევრ ფოტოს გადავიღებთ!'),
  ('1ac47b8c-1167-4ac1-a522-104b832c25b0', 'უკვე 6 თვისაა! ნახევარი წლისაა! 🎉', 'გილოცავთ! უკვე ზუსტად 180 დღეა, რაც ამ საოცრებას ზრდით. ახლავე შექმენით ბავშვის ფოტოსესიაში ამ განსაკუთრებული დღისადმი მიძღვნილი ფოტო და გააზიარეთ Anacan-ის საზოგადოებაში!'),
  ('788697fe-7a57-4c4c-a3dc-514298d952ed', 'საკუთარ თავს ტაში დაუკარით 👏', 'გადახედეთ ყველა თქვენს ჩანაწერს. ნახეთ, რამდენად გაიზარდა ბავშვი და თქვენ რამდენად დახელოვნდით! შესანიშნავი გუნდი ხართ.'),
  ('7f7b88ee-089c-4ccc-9849-c2f4117d4833', 'გამარჯვების საღამო 🥂', 'ამ საღამოს, ბავშვის დაძინების შემდეგ, თქვენს პარტნიორთან პირისპირ დასხედით. იამაყეთ ამ 180 დღით და ერთმანეთს ჩაეხუტეთ!'),
  ('2ecd0a8e-2817-4551-98e0-4276739c7da9', 'ჩვენ ერთი გუნდი ვართ! 💖', '6 თვის განმავლობაში უძილო ღამეებში ერთმანეთს მხარში ედექით. გახსენით განწყობის დღიური და პარტნიორს გუნდური მუშაობისთვის მადლობა გადაუხადეთ.'),
  ('ce877206-0633-48d8-aa8f-9241cfab27c3', 'დამატებითი კვების სკამი 🪑', 'საბავშვო კვების სკამის შეძენას ფიქრობთ? რეკომენდებული პროდუქტების განყოფილებაში დაათვალიერეთ ერგონომიული და ადვილად გასაწმენდი სკამები.'),
  ('e6e852b1-bfb4-4197-aa7b-70b6b2367f30', 'ნახევარ წლამდე 5 დღე დარჩა! 🎈', 'ნახევარ წლამდე სულ რაღაც 5 დღე დარჩა! ტორტი უკვე შეუკვეთეთ? ბავშვის ფოტოსესიის ხელსაწყოში წინასწარ შეარჩიეთ სპეციალური 6 თვის ჩარჩოები და დაგეგმეთ ფოტოსესია.'),
  ('1297700e-9cfd-4ca4-a9de-fc8b3c3e36fd', 'ახალი ზღაპრის აღმოჩენა 📖', 'მოდით, ეს საღამო განსხვავებულად გავატაროთ. ჭკვიანი ზღაპრების განყოფილებაში შექმენით განსაკუთრებული ამბავი და ოთახი ჯადოსნობით აავსეთ.'),
  ('9d58451e-ede3-4a05-ba21-dd4e0b7f4086', 'ყოველდღიურად ვაკვირდებით საფენის შიგთავსს. 🧷', 'დამატებით კვებაზე გადასვლამდე, საჭმლის მომნელებელი სისტემის გამართულად მუშაობაში დასარწმუნებლად, Anacan-ში საფენის ყოველი გამოცვლა აღრიცხეთ.'),
  ('edc6faba-a997-408a-a40b-e590a39a3721', 'მე უკვე ვზივარ! 🪑', 'ბავშვი დახმარებით ჯდომისას უკვე უფრო თავდაჯერებულია? ბალიშებით დაეხმარეთ და ჯდომისკენ წაახალისეთ, თუმცა მხოლოდ მცირე ხნით.'),
  ('7d616a8c-c926-4291-9221-42ee50e15fd5', 'ახალი ეტაპი: დამატებითი კვება! 🥣', '6 თვე შესრულდა! უკვე დროა, ბავშვმა ბოსტნეულის პიურეები გაიცნოს. Anacan AI-სგან მიიღეთ ინფორმაცია 3-დღიანი საცდელი წესის შესახებ (ალერგიის შესამოწმებლად).'),
  ('936424c3-1b30-4fc1-924e-920162d0d5bd', 'სრული სიჩუმე 🤫', 'ჩაძინება გართულდა? ხმის საზომით შეამოწმეთ ოთახში დეციბელების დონე და ოთახი მთლიანად დააბნელეთ.'),
  ('e0613a64-c64f-491d-8c87-72276f72849e', 'დალაქავებული ტანსაცმელი 👗', 'დამატებითი კვება ნიშნავს, რომ ყველაფერი დაისვრება. ნუ გაღიზიანდებით, გამოიყენეთ სილიკონის წინსაფრები და დატკბით ამ სახალისო მომენტებით.'),
  ('6dad4f0a-8c98-4797-a95f-50aab81d4662', 'ამინდის სიურპრიზი ⛅', 'სასეირნოდ გასვლისას ამინდმა შეცდომაში არ შეგიყვანოთ და არ გაცივდეთ. ამინდისა და ჩაცმის დამხმარის საშუალებით გარეთ არსებულ პირობებს შესაბამისი გადაწყვეტილება მიიღეთ.'),
  ('affd2ecc-89d1-4649-8b63-63dfe9a1ced9', 'გეძებ! 👀', 'ოთახიდან გასვლისთანავე ტირილს იწყებს? განშორების შფოთვა უკვე სრულად ყალიბდება. ბავშვს უბრალოდ ეშინია, რომ აღარ დაბრუნდებით. თქვენი ხმით დაამშვიდეთ და თავი უსაფრთხოდ აგრძნობინეთ.'),
  ('c4e8f9e9-c94b-41fc-a23a-61a8c7026386', 'ცვლილებები საჭმლის მომნელებელ სისტემაში. 🧷', 'დამატებითი კვების დაწყებასთან ერთად განავალიც შეიცვლება. ყოველი საფენის გამოცვლა Anacan-ში აღრიცხეთ და მდგომარეობას ყურადღებით დააკვირდით.'),
  ('3bd59fce-abbd-4e13-ab2d-4379b5c89cac', 'პიურეს არ ჭამს და პირიდან აფურთხებს?', 'თავს უუნაროდ ნუ იგრძნობთ. მისთვის ეს სრულიად ახალი გამოცდილებაა, ამიტომ მოთმინება გამოიჩინეთ.'),
  ('48005ac4-750b-4fca-b0cd-2711d3eb3c21', 'ხმოვანი ზღაპრები 🪄', 'ამ საღამოს ჭკვიან ზღაპრებში ზღაპარი შექმენით და დღე მხიარულად დაასრულეთ.'),
  ('ae1cbea0-aaaf-49ff-9518-967813809e3b', 'ღრძილები ექავება? 🦷', 'დამატებითი კვების პერიოდში კბილების ამოჭრით გამოწვეული დისკომფორტიც შეიძლება გაძლიერდეს. ექიმის რეკომენდაციით გამოიყენეთ კბილების ამოსაჭრელი გელი.'),
  ('4beff801-d69f-40c0-bed1-2e8938edb5f2', 'რას აკეთებენ სხვა დედები? 💬', 'თქვენს ბავშვს გოგრის პიურე არ მოსწონს? შეუერთდით Anacan-ის საზოგადოებას და გაეცანით სხვა დედების გამოცდილებასა და განსხვავებულ რეცეპტებს.'),
  ('7df7f58f-05e6-4afb-aa2c-73438e6504d4', 'ძილის ნიშნები 🥱', 'თუ თვალებს ისრესს და ერთ წერტილს უყურებს, ნუ დაელოდებით, სანამ ჭირვეულობას დაიწყებს. დაუყოვნებლივ ჩააბნელეთ ოთახი და ძილის რუტინა დაიწყეთ.'),
  ('8afe4995-9e98-44a1-a9cc-5c970d87a396', 'დამოუკიდებლად დაჯდომის მცდელობები 🪑', 'ბალიშებს უკვე ნაკლებად ეყრდნობა? სულ მალე სრულიად დამოუკიდებლად დაჯდება!'),
  ('34c92908-0941-4c15-a946-75240f0ea7f7', 'გაგვიზიარეთ თქვენი განწყობა 📝', 'დღეს ძალიან დაიღალეთ? გულწრფელად ჩაწერეთ თქვენი ემოციები განწყობის დღიურში. გულის გადაშლა თავს უკეთ გაგრძნობინებთ.'),
  ('cd45d0d2-bf31-47be-adf8-84c3b1895339', 'ტკივა თუ აირები აწუხებს? 😭', 'დამატებით კვებაზე გადასვლამ შეიძლება შეკრულობა ან აირების დაგროვება გამოიწვიოს. თუ რაც უნდა გააკეთოთ, მაინც არ მშვიდდება, გამოიყენეთ ტირილის ანალიზი და გაარკვიეთ, რა იმალება მისი ტირილის უკან.'),
  ('e67730b8-4981-4bba-b868-fe6cf9b7e3da', 'მარაგი იწურება 🛒', 'პიურესთვის ახალი ბოსტნეული გჭირდებათ? ჩაწერეთ საყიდლების სიაში, რათა თქვენმა პარტნიორმა სამსახურიდან დაბრუნებისას ახალი პროდუქტები იყიდოს.'),
  ('1f9cc7dc-a0b4-41a4-983b-794c5917ee08', 'ხელიდან ხელში — ახალი აღმოჩენა 🧸', 'სათამაშოს თავისუფლად გადააქვს ერთი ხელიდან მეორეში? ეს ნიშნავს, რომ თავის ტვინის ორივე ნახევარსფერო შესანიშნავად მუშაობს. მიეცით სხვადასხვა ფაქტურის ნივთები.'),
  ('298934a2-9d12-42b8-8c9c-6098d3709ab4', 'საუბრები გრძელდება! 🗣️', 'და-და-და, ბა-ბა-ბა — ეს ხმები მთელ სახლში ექოდ ისმის. მისი მეტყველების განვითარების შესახებ მეტის გასაგებად ეწვიეთ ბლოგების განყოფილებას.'),
  ('89ff16e6-d11a-4deb-ae4f-1ba03e76271d', 'ღამის გმირი მამაა 🦸‍♂️', 'პირველი თვეების საუკეთესო წესი: იავნანას სიმღერა მორიგეობით უნდა იყოს! ამ საღამოს ბავშვი მამას ჰყავს ხელში, თქვენ კი ისვენებთ.'),
  ('5378180a-aa43-4728-9384-08bbcf8838ee', 'მელაპარაკე! 🗣️', '„ბა-ბა“, „მა-მა“ და მსგავს მარცვლებს უფრო მკაფიოდ წარმოთქვამს? გამოეხმაურეთ მის ხმებს და ხელი შეუწყვეთ ამ კომუნიკაციას.'),
  ('a4be80bb-cd06-42ba-b875-78d5a32af3ba', 'გუნდური საუბარი 🛋️', 'რთული დღის შემდეგ პარტნიორთან პირისპირ დაჯექით და გულწრფელად ისაუბრეთ. ერთმანეთის მხარდაჭერა ტვირთს ანახევრებს.'),
  ('efa880a4-37d0-4521-93db-df2495a01243', 'იამაყეთ საკუთარი თავით 👏', 'გაიხსენეთ, როგორ გეშინოდათ პირველ კვირებში. ახლა კი პიურეს მომზადების ნამდვილი პროფესიონალი დედა ხართ!'),
  ('5be2b9be-dabd-44b8-93f3-30aaaab56ccf', 'ღამის იავნანა 🎶', 'არცერთი ხმა არ ამშვიდებს ისე, როგორც დედის ხმა. ამ საღამოს უბრალოდ გულში ჩაიკარით და ჩუმად უმღერეთ.'),
  ('98621899-f977-46d0-ba01-3a49123c5aef', 'ცოცვის პირველი მცდელობები! 🐢', 'მუცელზე წოლისას ტრიალებს, უკან-უკან ხოხავს ან მუხლებზე წამოდგომას ცდილობს? განვითარების ეს აქტიური მომენტები დაუყოვნებლივ დაამატეთ ბავშვის ალბომში.'),
  ('f5a121b8-a795-4ca6-87d9-f17351b40bec', 'ბავშვის განვითარებაზე ეჭვები გაქვთ? 🤖', '„ჩემი ბავშვი ჯერ კიდევ არ ცოცავს, ეს ნორმალურია?“ – ეს და სხვა კითხვები დაუსვით Anacan AI-ს და მიიღეთ სპეციალისტის პასუხი.'),
  ('6f0575b2-9379-4dca-bf05-d518a93aead1', 'დაგავიწყდათ, რომელი ძუძუდან აჭამეთ? 🤱', 'ტაიმერში მონიშნეთ, მარჯვენა თუ მარცხენა ძუძუდან აჭმევთ, დანარჩენი კი Anacan-ს მიანდეთ — ის ყველაფერს დაიმახსოვრებს!'),
  ('a134dfa9-2e73-4246-a281-0577e4411534', 'მიეცით საკვებით თამაშის უფლება! 🥦', 'მიეცით საშუალება, შეეხოს საკვებს, მოსრისოს და შეისწავლოს. ეს საყვარელი და ცოტა არეული მომენტები ბავშვის ფოტოსესიით აღბეჭდეთ და სამახსოვროდ შეინახეთ!'),
  ('d9470e5a-6317-45d8-9bd1-419a7827e3e6', 'ღამის გაღვიძებებს რუტინად ვაქცევთ. 😴', 'ყოველი გაღვიძებისას შუქს ნუ აანთებთ. აჭამეთ Anacan-ის ტაიმერის დახმარებით და თეთრი ხმებით კვლავ დააძინეთ.'),
  ('07efb31a-2639-41f8-b1c7-f3807d010a8f', 'გააჩერეთ დრო 📸', 'ის ისე სწრაფად იზრდება... სანამ სძინავს, ბავშვის ფოტოსესიით აღბეჭდეთ მისი საყვარელი, მშვიდი სახის ნაკვთები და სამახსოვროდ შეინახეთ.'),
  ('7deb7b07-a963-4605-b27c-7714e980157d', 'კითხვა გაქვთ? 🤖', 'დამატებითი კვებისა და წყლის მიცემასთან დაკავშირებით უამრავი კითხვა გაქვთ? მისწერეთ Anacan AI-ს და მიიღეთ ზუსტი პედიატრიული რჩევები.'),
  ('ab8df92e-4241-44fb-8ac7-10559ea60a6f', 'მე თქვენ გიცნობთ! 🥰', 'როცა სახლში უცხო ადამიანი მოდის, თქვენ გეკვრებათ? ნუ შეშინდებით — მას უბრალოდ ახლობლებისა და უცხოების ერთმანეთისგან გარჩევა შეუძლია. ეს ჯანსაღი გონებრივი განვითარების ნიშანია.'),
  ('0e6fe355-3307-4562-8e24-f479625f3ff6', 'სუფთა ჰაერი ორივეს წაგადგებათ. 🌳', 'შეარჩიეთ უახლოესი პარკი და დატკბით დღით.'),
  ('4085929a-ec71-4c5c-a693-62bb796910ba', 'შეუსაბამო ჩაცმულობა 👗', 'ხან ზედმეტად თხლად აცმევთ, ხან კი — ზედმეტად თბილად? ნუ იდარდებთ. შეამოწმეთ ამინდი და ჩაცმულობა და ბავშვი თავდაჯერებულად ჩააცვით.'),
  ('e7ddb2bb-cbd6-4f99-9f52-7fc0bb34e7ba', 'ჭკვიანური სიჩუმე 🤫', 'ჩაძინებისას უეცარი ხმები აღვიძებს? ხმის საზომით აკონტროლეთ ოთახში დეციბელების დონე.'),
  ('3e7220fc-a665-4ed2-8b95-f202d84e92a8', 'მე თვითონ დავიჭერ! 🧸', 'ჩამოკიდებულ სათამაშოებს ზუსტად სწვდება? მისი თვალისა და ხელის კოორდინაცია უმჯობესდება. წაახალისეთ სხვადასხვა ფერის ნივთებით.'),
  ('747238a1-853b-4e40-a51e-30b2b6d818ac', 'თავს ნუ დაიდანაშაულებთ 💖', 'ფიქრობთ, რომ ბავშვს ცოტა დროს უთმობთ? ხალისიანად და ხარისხიანად გატარებული 10 წუთი სტრესით სავსე 1 საათზე მეტად ღირებულია.'),
  ('a8ca5021-abaf-413e-abe5-95d715e5127d', 'ღრმა ძილისთვის მზადება 🛀', 'თბილი აბაზანა, ნაზი მასაჟი და ოთახის ჩაბნელება... ძილის რუტინა ოქროს წესია.'),
  ('17a57fd8-a4e1-4a40-b13f-cad6191dae2a', 'ახალი გემოების აღმოჩენა! 🍎', 'დღეს რომელ ხილს ან ბოსტნეულს გაასინჯებთ? შთაგონებისთვის აუცილებლად გაეცანით დამატებითი კვების დამწყები ბავშვებისთვის განკუთვნილ რეცეპტებს.'),
  ('b98f5eb2-8b81-4c72-8526-61cc728e9e49', 'ზღაპარს დასასრული არ აქვს 📖', 'დღეს საღამოს „ჭკვიან ზღაპრებში“ მამაცი და გონიერი ბავშვის ამბავი შექმენით.'),
  ('baf623af-022a-4483-b233-e77e915f194b', 'ნამდვილი გურმანი 🥣', 'პიურეს უკვე სიამოვნებით მიირთმევს? ის იზრდება!'),
  ('0ced9920-5225-4ffc-81ba-de83e31f1bd2', 'დილის კონცერტი 🎶', 'გიყურებთ და სხვადასხვა მარცვალს იგონებს. ახლა ოთახში ყველაზე მშვენიერ დილის კონცერტს მართავს — ყურადღებით მოუსმინეთ!'),
  ('db243270-0483-44d0-9aef-b63565c06a9e', 'ექიმივით ჭკვიანი 🤖', 'მყარი საკვების დაწყების შემდეგ განავალი შეეცვალა? ნერვიულობის ნაცვლად, ჰკითხეთ Anacan AI-ს, ნორმალურია თუ არა ეს.'),
  ('f06a8dcb-51df-4b58-a9ac-01e5154e736a', 'ჯანსაღი ძილის საფუძველი ⏱️', 'თბილი აბაზანა, მასაჟი და ოთახის ჩაბნელება... არასოდეს დაარღვიოთ ძილის რუტინა, რათა ღამეები მშვიდად გაატაროთ.'),
  ('19aba970-f2bf-4842-9b69-4aed1781aeec', 'დაბლა ჩაიხედეთ! 👣', 'მან უკვე აღმოაჩინა თავისი ფეხის თითები და პირში იდებს! აუცილებლად დააკვირდით ამ სახალისო მომენტს და დატკბით მისი განვითარებით.'),
  ('6b5eb8f2-b9ae-4f72-adf0-630e10588b7d', 'დედის რძე კვლავ უმთავრესია! 🍼', 'დამატებითი კვების მიუხედავად, ჩართეთ კვების ტაიმერი და დარწმუნდით, რომ ბავშვი რძის დღიურ საჭირო რაოდენობას იღებს.'),
  ('c2924eec-8b24-41b0-b28a-f63497f548c2', 'გამოცდილების გაზიარება 💬', 'დამატებითი კვების რეცეპტებს ეძებთ? ეწვიეთ ჯანსაღი რეცეპტების განყოფილებას და ისარგებლეთ.'),
  ('2d910805-1ce0-44fc-88f6-f3f6dfe16cea', 'ცოცვის მცდელობები გახშირდა! 🐢', 'მუცელზე დაწოლილი უკან-უკან მიცოცავს ან მუხლებზე წამოდგომას ცდილობს? უკვდავყავით მისი აქტიური განვითარების ეს მომენტები ბავშვის ალბომში.'),
  ('8f5769c4-aeb4-4cd1-acf0-052c7e0df753', 'ჭკვიანი ზღაპრის დროა 🪄', 'ჭკვიანი ზღაპრების განყოფილებაში შექმენით სპეციალურად ამ საღამოსთვის განკუთვნილი ამბავი.'),
  ('f175db80-862d-40e7-9aed-5b0a0c4423e3', 'წყლის სმის ჩვევას ვაყალიბებთ. 💧', 'არ დაგავიწყდეთ, დამატებით საკვებთან ერთად წყლიც შესთავაზოთ.'),
  ('21fef948-0fab-41a2-932d-5efc89cc4b78', 'ჯანსაღი ძილის საფუძველი ⏱️', 'ძილის სწორი რეჟიმის ჩამოყალიბება ძალიან მნიშვნელოვანია. არასოდეს დაარღვიოთ რუტინა, რათა ღამეები მშვიდად გაატაროთ.'),
  ('29cfcc36-87ce-4b4b-b753-dcd4b0ef2352', '200 დღემდე 1 დღე დარჩა! 🎂', 'ხვალ 200 დღის ხდებით! უკვე მოიფიქრეთ, როგორ აღნიშნავთ ამ შთამბეჭდავ და ლამაზ რიცხვს? დაიწყეთ მზადება!'),
  ('76b44761-7bef-4f9c-b984-97e78f4d78cb', 'ყველაფერი რიგზეა ✔️', 'ზოგჯერ გეჩვენებათ, რომ ვერაფერს აკეთებთ. მაგრამ შეხედეთ მის სუფთა ტანსაცმელსა და დანაყრებულ მუცელს. თქვენ ყველაფერს შესანიშნავად აკეთებთ!'),
  ('01da84b5-ee27-4d08-b8e5-12f1d6a1b6e2', 'გაიხედეთ უკან 📈', 'გაიხსენეთ თქვენი შიშები პირველ დღეებში. ახლა კი შეხედეთ, როგორ იქეცით დამატებითი კვების ნამდვილ პროფესიონალ დედად. იამაყეთ საკუთარი თავით!'),
  ('87133947-89a5-414b-a6d4-637285ff301e', 'არაჩვეულებრივი 200 დღე! 🎉', 'გჯერათ? უკვე ზუსტად 200 დღეა, რაც ამ ჯადოსნურ გზას ერთად მიუყვებით! ბავშვის ფოტოსესიაზე ეს მომენტი სპეციალური სტიკერით საზეიმოდ აღნიშნეთ და საზოგადოებაში გააზიარეთ!'),
  ('e7927d9c-8cbd-4c7d-b3cf-e5df983f4169', 'იზეიმეთ 200 დღის სიამაყე. 🥂', 'ამ საღამოს, ბავშვის დაძინების შემდეგ, არ დაგავიწყდეთ პარტნიორთან ერთად აღნიშნოთ თქვენი გუნდის ეს დიდი გამარჯვება!'),
  ('14f79c92-38f1-4965-a9d0-fbcb8e236840', 'ნერწყვის მოჭარბება 🤤', 'საყელო წამებში მთლიანად უსველდება? ღრძილები კბილების ამოსვლისთვის ემზადება. გამოიყენეთ სილიკონის წინსაფრები.'),
  ('173f7149-2567-449f-9693-a462d1148849', 'ჩვენ ერთი გუნდი ვართ! 💖', 'რთული დღის შემდეგ მეუღლესთან პირისპირ დასხედით და გულწრფელად ისაუბრეთ. ერთმანეთის მხარდაჭერა ტვირთს განახევრებთ.'),
  ('1af66eec-0d7d-4dcd-9326-d4155d237a55', 'უცხო ადამიანების შიში ეწყება? 🙈', 'თუ ბავშვი ტირის, როცა ვერ გხედავთ ან უცხო ადამიანს ხედავს, ეს განვითარების ბუნებრივი ნაწილია. ამის შესახებ რჩევისთვის მიმართეთ Anacan AI-ს.'),
  ('23068177-6d18-4649-91f5-5ac9ecb37933', 'სწრაფი პასუხები 🤖', 'რამემ დაგაბნიათ? ფორუმების საათობით კითხვის ნაცვლად, დაუსვით თქვენი შეკითხვა Anacan AI-ს და სწრაფად მიიღეთ პასუხი.'),
  ('52b2efdc-0a49-4bfa-8a7e-21a3342254cb', 'ცდილობს! 🤸‍♂️', 'მუცელზე წოლისას წინ გახოხებას ცდილობს. მისი კუნთები დღითი დღე ძლიერდება — წინ სათამაშო დაუდეთ და წაახალისეთ.'),
  ('97716c97-1bb3-4784-acfc-a5f0354d1864', 'მუსიკის ძალა 🎶', 'სცადეთ, საღამოს დაწყებული უმიზეზო ტირილი ნელი ტემპის კლასიკური მუსიკით დაამშვიდოთ.'),
  ('05e938a0-adb4-413b-992b-19bbd78f0925', 'იუბილესთვის მზადება! 🎂', 'სულ რაღაც 9 დღეში 7 თვის გახდება! ამ თვისთვის განსხვავებული გაფორმება ან განსაკუთრებული ტორტი ხომ არ მოგიფიქრებიათ? მზადება ახლავე დაიწყეთ, რათა ბოლო დღისთვის არ შემოგრჩეთ.'),
  ('9c5c6958-af17-4420-aa80-95cd295c8995', 'ხელები თავისუფალია 👐', 'მუცელზე წოლისას ერთი ხელით სათამაშოსკენ იწევს, მეორეს კი საყრდენად იყენებს? კუნთების ბალანსი სულ უფრო უმჯობესდება!'),
  ('acd2495b-eae5-4005-8f31-3fdfdc4738aa', 'მამიკოს დროა 👨‍👧', 'დღეს დედის მოვალეობები მცირე ხნით თქვენს პარტნიორს გადააბარეთ. მიეცით მათ ერთად თამაშის საშუალება, თქვენ კი უბრალოდ ფეხები გაშალეთ და დაისვენეთ.'),
  ('094a764e-f3f1-4dd1-8a87-04126b16323f', 'ნუ დაივიწყებთ საკუთარ თავს 🍲', 'ბავშვმა თავისი პიურე შეჭამა, თქვენ კი? ენერგიის აღსადგენად სრულფასოვნად უნდა იკვებოთ. დღეს საკუთარი თავისთვის ნოყიერი კერძი შეუკვეთეთ.'),
  ('734bd8a8-49ec-4c9f-bb8c-17a8d1fc50b6', 'მე გიცნობ 👀', 'როცა სახლში სტუმარი მოდის, ბავშვი გეკვრით და მას ეჭვით უყურებს? განშორების შფოთვა იწყება. ის უბრალოდ დედასთან გრძნობს თავს უსაფრთხოდ — პატივი ეცით მის ამ განცდას.'),
  ('740c028d-4797-4507-a894-816747e5301d', 'თქვენი განსაკუთრებული ზღაპარი 🪄', 'ამ საღამოს „ჭკვიანი ზღაპრების“ ხელსაწყოს საყვარელი თემა შევთავაზოთ: „ციდან ჩამოვარდნილი ყველაზე საყვარელი ვარსკვლავის ამბავი“. დაე, ოთახში მხოლოდ ამ ზღაპრის ხმა ისმოდეს.'),
  ('1175cce8-f8b8-4dcc-a8b2-c864d9349ad6', '7 თვემდე სულ რაღაც 3 დღე დარჩა! 🎂', 'ტორტის შეკვეთა მზად არის? ტანსაცმელი შერჩეულია? 7 თვის შესრულებამდე ძალიან ცოტა დრო დარჩა. დაგეგმეთ ამ მშვენიერი თარიღის აღნიშვნა სახლში პატარა ფოტოსესიით!'),
  ('6496f6e2-60a8-4932-a5d1-b8cb0c9682cf', 'მეგობარი სარკეში 👀', 'მიიყვანეთ ბავშვი სარკესთან. ძალიან სასიამოვნო და დამამშვიდებელია იმის ყურება, თუ როგორ აკვირდება გაოცებული საკუთარ ანარეკლს და იცინის.'),
  ('f998fac0-0a6b-42d2-b200-7a956f147c9a', 'მამის ჯერია 👨‍🍼', 'დღეს საღამოს ბავშვის დაბანა და დასაძინებლად მომზადება მამას მიანდეთ.'),
  ('06cfdff1-da31-4945-b562-a0c104f43d15', 'მესმის შენი 🗣️', 'ყურადღებით გისმენთ და ცდილობს მსგავსი მარცვლების (მა-მა, ბა-ბა) წარმოთქმას? ის თქვენ გესაუბრებათ! უპასუხეთ ბევრი ღიმილით.'),
  ('83caf542-3e86-4833-b9bd-0befb15b04d7', 'გარეთ გასვლის დროა 🌳', 'ჩასვით ბავშვი ეტლში და 20 წუთით სუფთა ჰაერზე გაისეირნეთ. ეს ორივეს ძალიან კარგად გამოგადგებათ.'),
  ('fca627d6-9c72-4d82-999a-3b13347100cd', 'ღამის გმირი 🦸‍♂️', 'ღამით გაღვიძებამ დაგღალათ? ნუ მოგერიდებათ მამის გაღვიძება. გუნდურობა პასუხისმგებლობის თანაბრად განაწილებას ნიშნავს.'),
  ('4335b974-a43c-4ba3-b369-2006056301ed', 'დამოუკიდებლად ჯდომა 🪑', 'უკვე შეუძლია ბალიშების გარეშე, თუნდაც მცირე ხნით, გამართულად ჯდომა? უსაფრთხოდ დაიჭირეთ და ყურადღებით დააკვირდით მისი კუნთების განვითარებას.'),
  ('5bc047d7-1539-47af-a21f-c1df4aa3461d', 'შუადღის კვებას ფეხზე დგომისა და ჩქარობისას ნუ მიირთმევთ. 🥑', 'მოიმზადეთ გემრიელი სალათი და 15 წუთი მხოლოდ საკუთარ თავს დაუთმეთ.'),
  ('8d02cce6-aec5-439c-aadf-52670f1abd08', 'ღრმა ძილისთვის მომზადება 🛀', 'თბილი აბაზანა, ნაზი მასაჟი და ოთახის ჩაბნელება... ძილის რუტინის დაცვა უწყვეტი ღამეების საიდუმლოა.'),
  ('347526cf-7568-4464-ab1e-f2a4e4f4b799', 'ზუსტად 7 თვისაა! 🎉', 'დაუჯერებელია! უკვე ზუსტად 7 თვეა, რაც გუნდურად ზრდით ამ სასწაულს. ახლავე უკვდავყავით ეს დღე ბავშვის ფოტოსესიაში და გააზიარეთ საზოგადოებაში!'),
  ('a649650d-baa3-4dab-9158-780252d27ef4', 'მშვენიერი დღის დასასრული. ✨', 'თქვენ ძალიან ძლიერი დედა ხართ! განწყობის დღიურში დაწერეთ, რომ საკუთარი თავით ამაყობთ, თეთრი ხმებით კი სიმშვიდე მოიპოვეთ და კარგად გამოიძინეთ.'),
  ('f5e18de7-aba2-4bda-84e9-b3a568ce950b', 'გაიხედეთ უკან 📈', 'გაიხსენეთ, როგორი გამოუცდელი იყავით პირველ დღეებში. ახლა კი შეხედეთ, როგორ პროფესიონალ დედად იქეცით. იამაყეთ საკუთარი თავით!'),
  ('4650c8e1-3011-45f0-9997-0c6decd79a65', 'სია თქვენი მხსნელია 🛒', 'ყოველდღიურ ქაოსში რამე დაგავიწყდათ? თავს ნუ გადაიტვირთავთ — სახლისთვის საჭირო ყველაფერი საყიდლების სიაში ჩაწერეთ.'),
  ('8c057f2d-32f2-4561-9ca5-5bc651edddcc', 'თვალს ვადევნებთ საჭმლის მონელებას. 🧷', 'მყარი საკვები განავლის გამოყოფას ცვლის. Anacan-ში საფენის ყოველი გამოცვლა მონიშნეთ და გააანალიზეთ, როგორ რეაგირებს თქვენი ბავშვი ახალ საკვებზე.'),
  ('9fc39323-52a1-4045-aa65-bf5c16fac78f', 'შია თუ დაიღალა? 😭', 'უმიზეზოდ ტირის და მისი ხმა განსხვავებულად ჟღერს? ნუ ინერვიულებთ. ხმა დაუყოვნებლივ მოასმენინეთ ტირილის ანალიზის ფუნქციას და გაარკვიეთ პრობლემის მიზეზი.'),
  ('05f5ce2b-27c1-4d94-b681-3d4e9ce809b6', 'უსაფრთხოების ზომები სახლში! 🛡', '️ რაც უფრო მოძრავი ხდება, მით მეტი საფრთხე ჩნდება. გაეცანით ჩვენს რეკომენდებული პროდუქტების სიას, სადაც ბავშვებისგან დამცავ საკეტებსა და კუთხის დამცავებს იპოვით.'),
  ('a0d08200-8263-43d9-90a3-313dda8dadc9', 'თითებით საჭმელად განკუთვნილ საკვებზე გადასვლა? 🥦', 'უკვე სურს, საკვები თავად აიღოს? უსაფრთხო ვარიანტებისთვის გაეცანით დამატებითი კვების დამწყები ბავშვებისთვის განკუთვნილ რეცეპტებს.'),
  ('ef507e65-7f14-47a2-8b48-8ce6e3e1fc96', 'ხოხვის ვარჯიშები! 🐢', 'მუცელზე წოლისას უკან-უკან ხოხავს ან ცდილობს, მუხლებზე წამოიწიოს? ხოხვის ხელშემწყობი სასარგებლო ვარჯიშების შესახებ ჰკითხეთ Anacan AI-ს.'),
  ('52134c06-b272-4f5f-93b6-cf014fc0e867', 'დედის რძე კვლავ მთავარი საკვებია! 🍼', 'დამატებითი კვების მიუხედავად, ჩართეთ კვების ტაიმერი და დარწმუნდით, რომ ბავშვი რძის დღიურ საჭირო რაოდენობას იღებს.'),
  ('62cb9c93-e0de-4d15-8d33-e81c1723d1db', 'ენერგიის ბომბი დედებისთვის! 🥗', 'აუცილებელია, თქვენც ჯანსაღად იკვებოთ! ჯანსაღი რეცეპტებიდან მოამზადეთ ვიტამინებით სავსე სალათი ან სმუზი, რომელიც ენერგიას შეგმატებთ.'),
  ('f25f7637-e945-4232-a1c1-f7594c81a0b3', 'დამამშვიდებელი ხმა 📖', 'დღეს საღამოს ბავშვს უბრალოდ თქვენი ხმით წაუკითხეთ მოკლე ზღაპარი. დედის ხმა ბავშვისთვის ყველაზე საყვარელი მუსიკაა.'),
  ('2a37fc3a-8b98-420a-99ba-c491a8c0f435', 'ძილის ნიშნები 🥱', 'ნუ დაელოდებით, სანამ ბავშვი თვალების სრესას და მთქნარებას დაიწყებს. როგორც კი მზერა გაეფანტება, დაუყოვნებლივ დაიწყეთ ძილის რუტინა.'),
  ('74e14338-c8e1-4b5c-b426-24332f30b919', '10 წუთი დედისთვის ☕', 'როგორც კი ბავშვი დაიძინებს, ნუ იჩქარებთ საოჯახო საქმეების კეთებას. დაჯექით დივანზე, დალიეთ ყავა და 10 წუთის განმავლობაში უბრალოდ კედელს უყურეთ და მშვიდად ისუნთქეთ.'),
  ('bb4d4aaf-f143-4aa9-b4e0-7b7a4fc4ea1f', 'ჭირვეული დილა ☁️', 'დღეს დილით არაფერი მოსწონს? შესაძლოა, ამის მიზეზი კბილების ამოჭრა ან განვითარების ნახტომი იყოს. უბრალოდ უფრო ხშირად ჩაიხუტეთ და აგრძნობინეთ, რომ უსაფრთხოდ არის.'),
  ('6ac03f7c-34a8-46f5-96a4-c1aa521476a5', 'ობიექტის მუდმივობის თამაში! 🧸', 'დამალეთ მისი სათამაშო გადასაფარებლის ქვეშ და მიეცით საშუალება, იპოვოს. ამ განმავითარებელი თამაშის დროს ბავშვის სიხარული „ბავშვის ფოტოსესიით“ აღბეჭდეთ.'),
  ('746b1115-b7ff-4fd7-b04a-46935d1a6f43', 'ბავშვის ნივთები მთელ სახლშია მიმოფანტული? 🌪️', 'ბავშვის ნივთები მთელ სახლშია მიმოფანტული? არა უშავს. არეული სახლი იმას კი არ ნიშნავს, რომ ცუდი დედა ხართ, არამედ იმას, რომ თქვენი მთავარი საზრუნავი თქვენი ბავშვია.'),
  ('bc99d2a9-e4a6-4af7-937f-bb0a7a91d292', 'ხმოვანი თერაპია მოუსვენრობის წინააღმდეგ 🎶', 'თუ ამ საღამოს თქვენს ბავშვს ახალი უნარებით გამოწვეული აღელვების გამო დაძინება უჭირს, „თეთრი ხმებიდან“ ჩაურთეთ საშვილოსნოში არსებული ხმები.'),
  ('5b09b018-664d-4b58-86b9-31b6e1d3baf2', '„ეს ჩემია!“ — სიჯიუტე 🛑', 'ბრაზდება, როცა ხელიდან რაიმე სახიფათო ნივთს ართმევთ? აკრძალვის ნაცვლად, მისი ყურადღება სხვა, უფრო ხმაურიან და ფერად სათამაშოზე გადაიტანეთ და ამ მცირე კრიზისებს მარტივად გაუმკლავდით.'),
  ('698ffa60-da73-4003-9656-db865993d1b5', 'ხელოვნების ნიმუში თეფშზე 🥦', 'პიურეს არ ჭამს? ზოგჯერ პრობლემა გემო კი არა, გარეგნობაა. ჯანსაღი რეცეპტების გამოყენებით, ფერადი ბოსტნეულისგან სახალისო სახეები შექმენით და ბავშვს მადა გაუღვიძეთ.'),
  ('eec20c49-b219-4211-8916-1e602a8ceafb', 'ძილის დროს მომატებული მგრძნობელობა 🤫', 'როგორც კი დაიძინებს, უმცირეს ხმაურზეც კი კრთება? ხმის საზომით ოთახის აკუსტიკა შეამოწმეთ და ფანჯრიდან შემოსული ხმების გასანეიტრალებლად თეთრი ხმაური ჩართეთ.'),
  ('a2641bfd-0346-425a-86be-0a5a6822a3d8', 'მამის ხმის ტონი 📖', 'ამ საღამოს ოთახში განსხვავებული ატმოსფერო შევქმნათ. ჭკვიან ზღაპრებში მამაცი ტყის ბინადრის შესახებ ამბავი შექმენით და მისი წაკითხვა მამის ბოხ, დამაჯერებელ ხმას მიანდეთ.'),
  ('ba28583a-a3f1-40f6-9657-b7b38af17c60', 'ოთხ კედელს მიღმა ☕', 'სახლის რუტინამ უკვე დაგღალათ. დღეს რაიმე განსხვავებული გააკეთეთ. შეარჩიეთ ახლომდებარე კაფე, სადაც ბავშვის ეტლით თავისუფლად შეხვალთ, და ყავა გემრიელად მიირთვით.'),
  ('ea94213c-026e-4de0-be12-a192e4d22b19', 'თქვენი ბავშვი ყოველდღიურად ვითარდება🤏', 'ცდილობს, იატაკზე ყველაზე პატარა ლაქა ან ნამცეციც კი ცერა და საჩვენებელი თითებით აიღოს? მისი ნატიფი მოტორული უნარები პიკზეა!'),
  ('2ab7b4ab-59b4-4e96-8271-8ddcc86f1911', 'ავეჯზე აცოცება 🧗‍♂️', 'დივანს ან სკამს ეჭიდება და ცდილობს, ზემოთ აიწიოს? მისი ფეხის კუნთები დამოუკიდებლად დგომისთვის ემზადება. დაიცავით ბავშვი, თუმცა ამ პატარა ალპინისტის მცდელობებს ხელს ნუ შეუშლით.'),
  ('82e71311-374a-4306-bcfc-4f69bc54da1b', 'ღამის ქარიშხალი 😭', 'შუაღამისას თითქოს უმიზეზოდ ტირილით გაიღვიძა? ტირილის ანალიზის დახმარებით მიზეზი იპოვეთ და დაამშვიდეთ.'),
  ('c7aadd23-e889-42f2-a761-3f955cb9600f', 'ტვინს ნუ გადაიღლით 🛒', 'უძილობამ მეხსიერება დაგიქვეითათ და მაღაზიაში საყიდელი ნივთები გავიწყდებათ? ყველაფერი საყიდლების სიაში ჩაწერეთ, რათა თქვენმა პარტნიორმა დაბრუნებისას იყიდოს.'),
  ('4d7eb303-e249-46ed-8460-db2f0a519240', 'ბუნება საუკეთესო წამალია ⛅', 'ძალიან მოუსვენარია და ვერაფრით ართობთ? გახსენით ამინდისა და ჩაცმულობის ინსტრუმენტი, ჩააცვით ამინდის შესაბამისად და დაუყოვნებლივ წაიყვანეთ პარკში 20-წუთიან სასეირნოდ.'),
  ('4dcbbcf9-87b6-44f2-9ce0-d8fdd1caacf7', 'ჩუმი ცრემლები 📝', 'დღეს ყველაფერი ერთდროულად დაგატყდათ თავს და ტირილი გინდათ? ეს სრულიად ბუნებრივია... განწყობის დღიურში მთელი თქვენი დაღლილობის შესახებ დაწერეთ. გულის გადაშლა შვებას მოგგვრით.'),
  ('e8e53d71-abc7-400d-80a7-8cf91f3339ab', 'პირველი მარცვლების გამეორება 🗣️', 'ხშირად იმეორებს ისეთ ბგერებს, როგორებიცაა „და-და“ და „ბა-ბა“? ის მეტყველების აპარატს ცდის. ღიმილით გაუმეორეთ მის მიერ წარმოთქმული თითოეული მარცვალი, რათა დიალოგის წარმართვა ისწავლოს.'),
  ('27772b37-d653-4081-a4d8-e2d8e3036d19', 'პედიატრიული კითხვები 🤖', 'ნორმალურია თუ არა ძილის რეჟიმის დარღვევა მე-8 თვისთვის? ინტერნეტში საათობით ძიების ნაცვლად, Anacan AI-სგან შეიტყვეთ კონკრეტული სამეცნიერო ფაქტები მე-8 თვის ძილის რეგრესის შესახებ.'),
  ('e5b5ed3f-01d7-4566-8860-0dc049a710b5', 'საღამოს მელოდია 🎶', 'როდესაც ბავშვი დაძინებას ეწინააღმდეგება, ოთახში მშვიდი კლასიკური მუსიკა ჩართეთ. მუსიკის ტალღები მის დაძაბულ ნერვულ სისტემას ადვილად დაამშვიდებს.'),
  ('ea452c1a-6484-41b5-9042-60a3abcf409d', 'წარმოსახვითი თამაშების დასაწყისი 🧸', 'ცდილობს სათამაშო დათვს ან თოჯინას წყალი დაალევინოს? მისი წარმოსახვა ვითარდება და სიმბოლური თამაშები იწყება. სიამოვნებით დააკვირდით ამ საყვარელ რეჟისორს.'),
  ('3a7b24a5-41c6-4c5d-a602-8a4582791ae2', 'ყოველდღიურ სირბილში სადილი ფეხზე ნუ მიირთმევთ. 🥑', 'მის დასანაყრებლად ყველაფერს აკეთებთ. თქვენ კი? საკუთარი თავისთვის მოამზადეთ ნოყიერი, რკინით მდიდარი განსაკუთრებული კერძი.'),
  ('61d3770b-ac23-4b61-a0c4-be4c333cc55a', 'გულახდილი საუბრები 💬', 'გაწუხებთ კითხვა: „ჩემი ბავშვი ჯერ რატომ არ ხოხავს?“ დაუყოვნებლივ შეუერთდით Anacan-ის საზოგადოებას. წაიკითხეთ ათასობით დედის რეალური ისტორია ან დასვით შეკითხვა და დარწმუნდით, რომ ყველა ბავშვი უნიკალურია.'),
  ('a8ecb50a-232f-401a-97bc-3fbfc63cc92b', 'განშორების შფოთვა 🥺', 'როცა ოთახიდან გადიხართ, თქვენ გამო ტირის? მას ჰგონია, რომ აღარასდროს დაბრუნდებით. ხშირად უთხარით: „მე ყოველთვის აქ ვარ“ და თქვენი ხმით დაცულობის განცდა აგრძნობინეთ.'),
  ('6666dee6-8da7-4982-b6e5-9cdc982b4a75', 'ღრძილების ქავილი გრძელდება 🦷', 'ყველაფერს გამეტებით ღეჭავს და ნერწყვი მოსდის? მაცივარში გაგრილებული კბილების ამოსაჭრელი რგოლები ამ დღეებში ნამდვილი ხსნაა.'),
  ('bedd9e86-f764-4777-9e49-e315e75433fd', 'მამის პასუხისმგებლობა 👨‍🍼', 'ღამით ბავშვის გაღვიძებასთან გამკლავება მთლიანად საკუთარ თავზე ნუ აიღებთ. გააღვიძეთ პარტნიორიც, რადგან გუნდურობა ამ პასუხისმგებლობის თანაბრად განაწილებას ნიშნავს.'),
  ('c36dcca2-2b51-424c-b39c-c98f7988d549', 'გიპოვე! 🙈', 'როცა ხელებით სახეს იფარავთ და „ჭიტას“ ეუბნებით, ხმამაღლა იცინის? მას ობიექტის მუდმივობის აღქმა სრულად უყალიბდება. ეს თამაში თქვენი ყოველდღიური რუტინის ნაწილად აქციეთ.'),
  ('3f339310-d600-43dc-81a3-1b609288885e', 'ჯიუტი ლაქები 👗', 'დამატებითი კვების პერიოდი ნიშნავს, რომ სახლი და ტანსაცმელი მუდმივად დაისვრება. ამაზე ნუ გაბრაზდებით. გამოიყენეთ სილიკონის წინსაფრები და უბრალოდ დატკბით ამ მხიარული, ფერადი მომენტებით.'),
  ('60071670-7fa4-4f9f-829f-892d281a9741', 'ნუ დაიდანაშაულებთ თავს. 🛑', 'დღეს ბავშვმა ეკრანთან ზედმეტად ბევრი დრო გაატარა ან სახლი მოუწესრიგებელი დარჩა? თქვენ უბრალოდ დაღლილი ადამიანი ხართ და ყველაფერს აკეთებთ, რაც შეგიძლიათ.'),
  ('fe5cb47e-9f22-41f9-a236-1db4b224e518', 'ნივთების იატაკზე გადაყრის თამაში 🥄', 'ბავშვი კვების სკამიდან სათამაშოს იატაკზე აგდებს და ელოდება, რომ თქვენ აიღებთ? ის მიზიდულობის ძალასა და მიზეზშედეგობრივ კავშირს შეისწავლის. მოიკრიბეთ მოთმინება და გაიღიმეთ.'),
  ('28d590c8-c8a6-4c89-b78b-e70f2f482c0d', 'სიბნელესთან შეგუება 🌙', 'ბავშვმა უფრო სწრაფად რომ დაიძინოს, ოთახში ყველა დამატებითი განათება და ეკრანი გამორთეთ. ჰორმონ მელატონინის გამომუშავება მხოლოდ მშვიდ და ბნელ გარემოში ჩქარდება.'),
  ('31783568-6230-449d-98c8-e7b1b046a34e', 'ჭირვეული დილა ☁️', 'თვალების გახელისთანავე ყველაფერზე ტირის და ვერაფრით კმაყოფილდება? შესაძლოა, სწორედ ზრდის ნახტომის შუაგულში იყოს. უბრალოდ ხშირად ჩაეხუტეთ და თავი უსაფრთხოდ აგრძნობინეთ.'),
  ('38c7f3dd-4cf4-4758-8006-37d59832bac8', 'როგორც კი ბავშვი დაიძინებს, ჭურჭლის სარეცხი მანქანის დასაცლელად ნუ გაიქცევით! 🛋️', 'წამოწექით დივანზე, დახუჭეთ თვალები და 15 წუთის განმავლობაში დატკბით სახლში გამეფებული იმ იშვიათი, სრული სიჩუმით.'),
  ('3b5314f5-fa59-44ed-9fa8-b6cf2bce9e2d', 'გუნდის შეხვედრა 🥂', 'რთული დღე უკან მოიტოვეთ. ბავშვის დაძინების შემდეგ პარტნიორთან ერთად ჩაი დაისხით და არ დაგავიწყდეთ, ერთმანეთს უთხრათ: „ჩვენ მართლაც შესანიშნავი გუნდი ვართ“ და ერთმანეთი დააფასოთ.'),
  ('579d5966-d49f-4125-a264-8acd785d0a8d', 'მეგობარი სარკეში 👀', 'ბავშვი სარკესთან მიიყვანეთ. დააკვირდით, როგორ უყურებს გაოცებული საკუთარ ანარეკლს და როგორ ცდილობს მასთან შეხებას. ეს შესანიშნავი აქტივობაა საკუთარი თავის აღქმის განვითარებისთვის.'),
  ('9099f274-aa9c-4fe9-8624-5cd611699d2d', 'სწრაფი მომარაგება 🛒', 'ბავშვის ზეთი ან სველი ხელსახოცები გითავდებათ? საყიდლების სია აპში გელოდებათ. საჭირო ნივთები იქ ჩაინიშნეთ, რათა თქვენმა პარტნიორმა სამსახურიდან დაბრუნებისას შეიძინოს.'),
  ('1d706879-d02b-44cf-bac5-4f53776477d3', 'ამინდის სიურპრიზი ⛅', 'სასეირნოდ გასვლისას ამინდმა არ მოგატყუოთ და ბავშვს არ შესცივდეს. მხოლოდ ფანჯრიდან გახედვით ნუ გადაწყვეტთ — ამინდისა და ჩაცმულობის დამხმარის მეშვეობით ზუსტად შეარჩიეთ გარეთ არსებული პირობებისთვის ყველაზე შესაფერისი ჩაცმულობა.'),
  ('acd7fb31-0c36-4f0b-9849-cf983e0b0e95', 'მე თვითონ შევჭამ! 🥦', 'მას უკვე აღარ სურს პიურეს კოვზით ჭამა და ურჩევნია, ბოსტნეული საკუთარი ხელით დაიჭიროს და ისე მიირთვას? ხელი შეუწყვეთ მის დამოუკიდებლობას. დიახ, ირგვლივ ყველაფერი დაისვრება, მაგრამ მისი განვითარება დაჩქარდება.'),
  ('e1819391-1d2d-450e-ac14-9ecfa65465d4', 'ზღაპრის ჯადოსნური სამყარო 🪄', 'დღეს საღამოს ჭკვიან ზღაპრებში სრულიად განსხვავებული რამ სცადეთ. თქვენი ხმის ტონი ზღაპრის რიტმს შეუსაბამეთ.'),
  ('aff9ba8d-8d8a-4d80-9363-09474c73609e', 'პატარა მკვლევარი 👣', 'მან უკვე აღმოაჩინა თავისი ფეხის თითები და ცდილობს, ისინი პირში ჩაიდოს!'),
  ('d79d065c-4399-4ac9-8bd9-d4970a686fba', 'მამის ღამის მორიგეობა 👨‍🍼', 'დღის დაღლილობაც გეყოფათ. საღამოს ბავშვის დასაძინებლად მომზადება და მისთვის პიჟამის ჩაცმა მამას მიანდეთ, თავად კი უბრალოდ გვერდიდან უყურეთ.'),
  ('ea309314-6720-4ddf-9fe1-7a4fb805b43f', 'შეკითხვა გაქვთ? 🤖', 'მე-8 თვის მოახლოებასთან ერთად ბავშვის სიმაღლისა და წონის გრაფიკი გაშფოთებთ? ინტერნეტში შემაშინებელი სტატიების კითხვის ნაცვლად, Anacan AI-ს ზუსტი და მეცნიერულად დასაბუთებული ცხრილი სთხოვეთ.'),
  ('1c1e068a-2609-422f-991f-68ad50839ea3', 'აღიდგინეთ ენერგია 🍲', 'დაღლილობას მთელი სხეულით გრძნობთ? ჯანსაღი რეცეპტებიდან შეარჩიეთ განსაკუთრებული სმუზი, რომელიც 10 წუთში მზადდება, ხელს შეუწყობს რძის გამომუშავებას და ენერგიით აგავსებთ.'),
  ('51badc42-c8bc-4aa3-b0b8-ec576b19fa07', 'გაფილტრეთ ხმაური 🤫', 'ჩაძინებიდან პირველი ნახევარი საათი ყველაზე მგრძნობიარე პერიოდია. ხმაურის საზომით შეამოწმეთ გარემო და თავიდან აიცილეთ მეზობელი ოთახიდან ან ტელევიზორიდან მომავალი უეცარი ხმაური.'),
  ('69f05aef-6a67-462b-8173-638d2cb174d5', 'მიზანმიმართული ხოხვა 🐢', 'ახლა უკვე მიზანს ირჩევს და მისკენ სწრაფად მიცოცავს. ოთახში იატაკის დონეზე არსებული ყველა პატარა, გადაყლაპვადი და სახიფათო ნივთი დაუყოვნებლივ მოაშორეთ.'),
  ('7405692f-45e1-45fa-9dd9-b527045b5e7d', 'გამოცდილების გაზიარება 💬', 'ბავშვის ახალმა ქცევამ (მაგალითად, კედელზე თავის დარტყმამ) შეგაშინათ? დაწერეთ Anacan-ის საზოგადოებაში და წაიკითხეთ, როგორ გაიარეს ეს ეტაპი სხვა დედებმა.'),
  ('cad415e5-9ff2-468b-bfee-aaed538d25a0', 'გაბედული ნაბიჯები 🧗‍♂️', 'დივანს ეჭიდება და ერთი ხელის გაშვებას ცდილობს? წონასწორობის შეგრძნება სწრაფად უვითარდება. ღიმილით ადევნეთ თვალი მის უშიშარ მცდელობებს და უსაფრთხოება დისტანციიდან უზრუნველყავით.'),
  ('e2523211-afd7-48c7-8227-2ec7b0b2f0f7', 'მიეცით ემოციებს თავისუფლება 📝', 'თავს ძალიან მარტოსულად გრძნობთ და გგონიათ, რომ თქვენი არავის ესმის? ეს სრულიად ბუნებრივი განცდაა. განწყობის დღიურში გულწრფელად, ყოველგვარი ფილტრის გარეშე ჩაიწერეთ თქვენი გრძნობები.'),
  ('16c8c619-fdcd-4a82-a21a-ff965106a15f', 'ქაოსი სახლში 🌪️', 'მთელი ოთახი სათამაშოებითაა სავსე? დალაგებაზე უფრო მნიშვნელოვანია მასთან მხიარულად გატარებული 10 წუთი. სათამაშოები ხვალაც იქ იქნება, თავს ნუ გადაიღლით.'),
  ('4bcc0503-2fe9-4f95-83e9-1eb9c7b5e773', 'მე-8 თვისთვის მზადება! 🎂', 'ყურადღება! სულ რაღაც 10 დღეში თქვენი პატარა ზუსტად 8 თვის გახდება! განვითარების ტრეკერში გადახედეთ განვლილ გზას. ამ პატარა იუბილესთვის უკვე ახლა იფიქრეთ Anacan-ისგან პატარა ტორტის შეკვეთაზე.'),
  ('724d9097-f64c-406e-8895-2982258b710d', 'მუსიკით ძილისთვის მომზადება 🛀', 'საღამოს რუტინა გართულდა? თბილი აბაზანის მიღებისას ფონად დამამშვიდებელი მუსიკა ჩართეთ. წყლისა და მელოდიის ჰარმონია ყველაზე ჭირვეულ ბავშვსაც კი ამშვიდებს.'),
  ('12b2ddaa-17a1-4692-8574-725c962b0e1b', 'კრიზები, რომელთა მიზეზსაც ვერ პოულობთ, ძალას გაცლით. 😭', 'კრიზები, რომელთა მიზეზსაც ვერ პოულობთ, ძალას გაცლით. შეწყვიტეთ გამოცნობა — გამოიყენეთ ტირილის ანალიზი და დაუყოვნებლივ ამოიცანით ხმის მიღმა დამალული გზავნილი (ტკივილი, დაღლილობა).'),
  ('19b095ff-5334-4011-abd1-b8df6c79520c', 'გარეთ გასვლის დროა 🌳', 'ოთხ კედელში ყოფნა გახრჩობთ. ჩასვით ბავშვი ეტლში და თუნდაც 20 წუთით გაისეირნეთ სუფთა ჰაერზე. ბუნების სიმშვიდე შესანიშნავად იმოქმედებს როგორც ბავშვზე, ისე თქვენს ემოციურ მდგომარეობაზე.'),
  ('b6194099-d4e6-4061-b3f2-d6bc5cce0529', 'საჩვენებელი თითი ☝️', 'შორეულ საგანზე თითით მიგანიშნებთ და შემდეგ თქვენ გიყურებთ? ამით გეუბნებათ: „შემომხედე“ ან „ეს მინდა“. ეს კომუნიკაციაში დიდი წინსვლაა! უთხარით ბავშვს ამ საგნის სახელი.'),
  ('b78498d9-706c-458c-aa0f-d6081c7746c6', 'ღამის იავნანა 🎶', 'ვერცერთი აპლიკაცია ან ჩანაწერი ვერ შეცვლის დედის იავნანას. ამ საღამოს უბრალოდ გულში ჩაიკარით ბავშვი და ხმადაბლა უმღერეთ მისი საყვარელი იავნანა, რომელიც სიმშვიდისა და დაცულობის განცდას ანიჭებს.'),
  ('d08b308d-00d3-45c9-9840-df7ac1047703', 'ტაშის გუნდი 👏', 'სიხარულს ტაშის დაკვრით გამოხატავს? როგორც კი ამ შესანიშნავ მოტორულ მიღწევას შეამჩნევთ, სახლში პატარა გამარჯვების ცეკვა მოაწყვეთ და ბავშვს შეუერთდით!'),
  ('dd6cc7ba-db6f-403b-93e6-2447dbb967dc', 'სია სასურველი კი არა, აუცილებელია 🛒', '8 თვის აღსანიშნავი წვეულებისთვის საჭირო დეკორაციები არ დაგავიწყდეთ! ზედმეტად ნუ დაიტვირთავთ თავს — ყველაფერი დაუყოვნებლივ ჩაწერეთ საყიდლების სიაში და პარტნიორთან შეთანხმებულად იმოქმედეთ.'),
  ('7227b833-2ecd-472c-a074-7273a66732d9', 'ნაცნობი სახეები 🥰', 'ოთახში შესვლისას შენიშნეთ მის სახეზე ის დიდი, განსაკუთრებული ღიმილი? ის თქვენ და თქვენს პარტნიორს სხვებისგან გამოარჩევს. მისი ეს უპირობო სიყვარული უდიდესი მოტივაციაა.'),
  ('90341333-a47d-4dc8-b1bb-8fcf07c769b0', 'მამის სასაცილო სახეები 🤡', 'ბავშვის გაცინების ყველაზე სწრაფი გზა მამის უცნაური ხმები და მიმიკებია. ამ საღამოს მის მხიარულ კისკისს მოუსმინეთ და ამასობაში თავადაც დაისვენეთ.'),
  ('d4f1084b-2a25-422f-954c-038d4cf53bd2', 'ფორუმებში ნუ დაიკარგებით 🤖', 'დამატებით კვებასთან დაკავშირებით ეჭვი გეპარებათ და ფიქრობთ: „შეიძლება ამის მიცემა?“ საათობით ნუ ეძებთ პასუხს — დაე, Anacan AI-მ, როგორც თქვენს ჯიბეში მოთავსებულმა ციფრულმა პედიატრმა, უპასუხოს თქვენს შეკითხვებს.'),
  ('11c30298-2c39-4c7f-bfc1-dcf22c8e2ebc', 'სივრცე დედისთვის ☕', 'სახლში ყოფნამ ენერგია გამოგაცალათ? დედებისთვის მეგობრულ სივრცეებში შეარჩიეთ მშვიდი კაფე, სადაც ბავშვის ეტლით კომფორტულად განთავსდებით, და საკუთარ თავს პატარა პაემანი მოუწყვეთ.'),
  ('66c8660e-b8ca-4046-9e3f-578e25572ec7', 'ნაგვის მკვლევარი 🗑️', 'რაც უნდა იპოვოს იატაკზე ან ხალიჩის კიდესთან, ყველაფერს დიდი ინტერესით აკვირდება. ნუ გაღიზიანდებით და ყველაფერს ხელიდან ნუ წაართმევთ — ის ხომ პატარა მკვლევარია. უბრალოდ ყურადღებით იყავით, რომ პირში ჩასადები და გადასაყლაპი ნივთები არ მოხვდეს.'),
  ('8d417480-194b-431c-987a-b0b5216ea151', 'დღეს ჭკვიან ზღაპრებში 🪄', 'ჭკვიან ზღაპრებში შექმენით დიდი გმირის ისტორია, რომელიც სულ რამდენიმე დღეში 8 თვის გახდება. დაე, ღამის სიჩუმე მხოლოდ ამ ჯადოსნურმა ისტორიამ შეავსოს.'),
  ('5d8608e7-e1cb-4a71-9c73-7f6dde65adfe', '8 თვემდე 5 დღე დარჩა! 🎈', 'მღელვარება მატულობს! სულ რაღაც 5 დღეში პატარას 8 თვე შეუსრულდება! თუ სპეციალური ტორტის შეკვეთას ან თემატური წვეულების დაგეგმვას აპირებთ, ბოლო დღისთვის ნუ გადადებთ.'),
  ('7a0d5b5d-2b7e-42a8-a73b-a50ead526d05', 'სიმშვიდე და ყავა 🤫', 'დაიძინა! ახლა სარეცხის მანქანის დაცლის ნაცვლად, ჩამობნელებულ ოთახში ჩამოჯექით. ჩართეთ ხმის საზომი, გარემო აკონტროლეთ და 15 წუთით დატკბით სიმშვიდით.'),
  ('f72fbb7e-431d-4f4b-9a73-06637ff7bd68', 'სრულყოფილება არ არსებობს 🛑', 'დღეს არაფერი წავიდა გეგმის მიხედვით? თავს ნუ დაიდანაშაულებთ. თქვენ ნამდვილი დედა ხართ და არა სოციალურ ქსელებში ნაჩვენები გაფილტრული ილუზია. თქვენს ბავშვს მხოლოდ თქვენ სჭირდებით.'),
  ('61ffa498-18cc-4858-987c-676f525f467c', 'მოიშორეთ ემოციური ტვირთი 📝', 'რთული დღე იყო? ემოციების დღიურში ჩაწერეთ დღევანდელი სტრესისა და უარყოფითი განცდების შესახებ და გული მოიოხეთ. ყველა დედა გადის ასეთ კრიზისებს — თქვენ ნამდვილად არ ხართ მარტო.'),
  ('856b771b-5997-4eed-bc26-8b35541184c6', 'ამინდის დაზვერვა ⛅', 'გარეთ ამინდი გაურკვეველია? ამინდისა და ტანსაცმლის შერჩევის ხელსაწყო მყისიერად გეტყვით ქარის სიჩქარეს, რომელიც ფანჯრიდან არ ჩანს, და შეგირჩევთ სწორ სამოსს — ასე რომ, სასეირნოდ უყოყმანოდ გახვალთ.'),
  ('c82d9568-ae94-4492-9789-4621c2dbcabc', 'ჩემს სათამაშოს არ მოგცემ! 🧸', 'როცა რამეს ართმევთ, აპროტესტებს და ხმამაღლა ტირის? მას საკუთრებისა და ინდივიდუალურობის განცდა უვითარდება. ეს სრულიად ბუნებრივი ფსიქოლოგიური ეტაპია — ნუ შეეწინააღმდეგებით.'),
  ('bc11c415-3d46-43c3-a8ed-0a204516e9ce', 'ჯანმრთელი დედა, ჯანმრთელი ბავშვი 🥑', 'თქვენი რკინისა და კალციუმის მარაგები ამოწურულია. დააჯილდოეთ საკუთარი თავი — ჯანსაღი რეცეპტით მოამზადეთ სწრაფი, ენერგიით სავსე კერძი, რომელიც ძალების შენარჩუნებაში დაგეხმარებათ.'),
  ('e386c8f2-240d-4f0f-adaf-e43ea496b8b2', 'პატარა გონება, რომელიც წიგნებს ფურცლავს 📖', 'თავისუფლად ფურცლავს სქელგვერდიან წიგნებს და სურათებზე რეაგირებს? მისი მხედველობითი მეხსიერება შესანიშნავად მუშაობს. ერთად წაიკითხეთ და სურათებზე გამოსახული ცხოველების სახელები წარმოთქვით.'),
  ('e418c384-8ae3-455b-af14-a223e6595751', 'კადრი, რომელიც დროს აჩერებს 📸', 'როცა ოთახში საყვარლად თამაშობს, მაშინვე გახსენით ბავშვის ფოტოსესია და სპეციალური თემით სამუდამოდ აღბეჭდეთ 8 თვის ასაკთან მიახლოებული მისი შეცვლილი, გაზრდილი სახე.'),
  ('4068a45c-e5fe-4a82-8c4b-a81d556f97cc', 'გულახდილი საუბარი გჭირდებათ 💬', 'ფიქრი — „ვერ ვიჯერებ, რომ უკვე 8 თვის ხდება“ — ემოციებით გავსებთ? გაუზიარეთ ეს მშვენიერი და სათუთი განცდა Anacan-ის საზოგადოებაში მყოფ დედებს.'),
  ('90c5ba08-9d91-4669-8b26-99e0b48d4cf2', 'ცდა და შეცდომა 🧱', 'ცდილობს, ორი სათამაშო კუბი ერთმანეთზე დააწყოს, მაგრამ ისინი ცვივა. ყურადღებით ისევ ცდის. ჩუმად და სიამაყით დააკვირდით მის ამ პატარა საინჟინრო ექსპერიმენტებსა და მცდელობებს.'),
  ('ed75b4ae-9703-498c-a857-64016faef6cc', 'ჩააქრეთ შუქები 🌙', 'დაძინებამდე 1 საათით ადრე სახლში ყველა კაშკაშა შუქი და ეკრანი გამორთეთ. მელატონინი სწრაფად მხოლოდ მშვიდ და სუსტად განათებულ გარემოში გამოიყოფა.'),
  ('695238eb-b88d-4ffe-800b-82d23636ceb9', 'სახლის საქმეებს ვინ გააკეთებს? 🌪️', 'ხვალინდელი პატარა ზეიმისთვის საქმეები დაგრჩათ? დატოვეთ, როგორც არის. სთხოვეთ თქვენს პარტნიორს, დღეს სახლის საქმეები საკუთარ თავზე აიღოს. თქვენ კი ხვალისთვის დაისვენეთ.'),
  ('c96d26d0-5fe0-42f4-a1a7-44abd71bd8d8', 'მასაჟის დროა 💆‍♂️', 'როცა ბავშვი დაიძინებს, დღის სტრესის მოსახსნელად პარტნიორთან ერთად ერთმანეთს მხრების მასაჟი გაუკეთეთ. ხვალინდელი შესანიშნავი გამარჯვებისთვის ენერგიით სავსე უნდა იყოთ!'),
  ('d3b0f81b-e9b4-4b00-883d-9e8bb86131bc', 'ხვალ უკვე 8 თვისაა! 📸', 'მზად ხართ? ხვალ დიდი დღეა! ზუსტად 8 თვე! ტელეფონის მეხსიერება გაათავისუფლეთ — ხვალ ბავშვის ფოტოსესიისთვის ბევრი ადგილი დაგჭირდებათ. ტანსაცმელი კი წინასწარ დააუთოეთ.'),
  ('393a7a2a-b162-45e4-9577-0e4f2d088bf3', 'გამარჯვების ცეკვა 🥂', 'ამ საღამოს პარტნიორთან ერთად აღნიშნეთ ამ 8 თვის დაღლილობა, ცრემლები და სიხარული. სუფრაზე სანთელი დადგით და თქვენი ურყევი გუნდის გამარჯვებას გაუმარჯოს!'),
  ('4419f2fd-8e6f-4837-aa0e-9d571aac3895', 'განვლილი გზის შეჯამება 📈', 'რამხელა გზა გამოიარა თქვენმა ბავშვმა! პირველი დღეების მყიფე შიში ახლა უზარმაზარმა თავდაჯერებამ ჩაანაცვლა. ეს 8 თვე დიდი სიამაყით გაიარეთ! თქვენ მართლაც შესანიშნავი ხართ!'),
  ('b4769acb-82a0-480e-b58f-3017d46b37a4', 'შესანიშნავი 8 თვე! 🎉🎂', 'გილოცავთ! უკვე ზუსტად 240 დღეა, რაც ამ საოცარ გზას ერთად მიუყვებით! ბავშვი უკვე 8 თვისაა. დაუყოვნებლივ იზეიმეთ ეს განსაკუთრებული დღე და სიამაყით გააზიარეთ Anacan-ის საზოგადოებაში!'),
  ('075bea5d-3ab7-4404-af70-89a3de20a0ff', 'სწრაფი სია 🛒', 'გუშინ სახლში ყველა მარაგი ამოგეწურათ? გახსენით საყიდლების სია, წამებში ჩაინიშნეთ რძე, ხილი და სხვა საჭირო პროდუქტები და სია თქვენს პარტნიორს ტელეფონზე გაუგზავნეთ.'),
  ('3c7f679a-b11a-4f67-a3ae-5f350e93a451', 'პერსონალური ზღაპარი 🪄', 'ჭკვიანი ზღაპრების მეშვეობით შექმენით განსაკუთრებული ამბავი, რომლის მთავარი გმირიც თქვენი ბავშვი იქნება.'),
  ('e32c4fc2-e649-4150-9d80-08ebdc4ae2e8', 'დღესასწაულის შემდგომი ქაოსი 🌪️', 'გუშინდელი 8 თვის აღნიშვნის შემდეგ სახლში სრული ქაოსია? ნუ იჩქარებთ დალაგებას. ეს დღე თქვენს უკვე 8 თვის პატარასთან ერთად უბრალოდ დასვენებასა და ახალი სათამაშოების აღმოჩენას დაუთმეთ.'),
  ('2c9fa500-5618-49b8-a232-965da7b82ef7', 'ხმის კონტროლი 🤫', 'ჩაძინებიდან პირველი ნახევარი საათი ყველაზე მგრძნობიარე პერიოდია. ხმაურის საზომით გარემო შეამოწმეთ და მოარიდეთ ბავშვი უეცარ ხმაურს, ტელევიზორისა თუ ქუჩის ხმებს.'),
  ('87a20850-e59a-4ee2-81e8-79c4b5808e7b', 'მესმის შენი 🗣️', 'ყურადღებით გისმენთ და მსგავსი მარცვლების წარმოთქმას ცდილობს? ის თქვენ გესაუბრებათ! ხშირად გაუღიმეთ პასუხად და ხელი შეუწყვეთ ამ კომუნიკაციას.'),
  ('9c963f32-b147-4e84-aa9a-af699e50681f', 'დღეს მოთმინება დაკარგეთ და იქნებ გაბრაზდით კიდეც?  🛑', 'თავს ცუდად ნუ იგრძნობთ. მოერიდეთ ინტერნეტში შექმნილ ილუზიებს. თქვენ რეალური დედა ხართ და საკუთარი ემოციების განცდის უფლება გაქვთ.'),
  ('0cf5cff8-d958-4ec0-b6df-6f78457976fd', 'ექიმივით ჭკვიანი 🤖', 'გაქვთ ეჭვები 8 თვის შემდეგ ბავშვის განვითარების ნორმებთან დაკავშირებით? ინტერნეტში ძებნით დროს ნუ დაკარგავთ — მიიღეთ სანდო, მეცნიერულად დასაბუთებული და პედიატრების მიერ დადასტურებული პასუხები Anacan AI-სგან.'),
  ('77b45217-21e4-402a-b5dd-d0ee28c29f05', 'ხელით ჭამა 🥦', 'მას უკვე პიურე აღარ სურს — უნდა, ბოსტნეული საკუთარი ხელით დაიჭიროს! მხარი დაუჭირეთ მის მცდელობებს, დამოუკიდებლად ჭამოს და, თუნდაც ყველაფერი დასვაროს, აუცილებლად მის გვერდით იყავით და ყურადღება მიაქციეთ.'),
  ('dd6d5f01-5a48-4f85-953e-c5e21662ae95', 'მამის ღამის მორიგეობა 👨‍🍼', 'ღამით ბავშვის გაღვიძებას მარტო ნუ გაუმკლავდებით. გააღვიძეთ თქვენი პარტნიორიც — გუნდად ყოფნა პასუხისმგებლობის თანაბრად განაწილებას ნიშნავს. ამაღამ ბავშვის დაძინება მისი ჯერია.'),
  ('918fe7fd-3c85-49ee-b337-c52aba217614', 'შუაღამისას ყვირილით იღვიძებს და ვერ მშვიდდება?  😭', 'მოასმენინეთ მისი ხმა ტირილის ანალიზის ფუნქციას და გაარკვიეთ, მიზეზი მხოლოდ ღამის შიშია თუ ფიზიკური ტკივილი.'),
  ('b5dc2a4a-17b6-4c13-ad1b-8f6ccddc9f9b', 'ცეკვა მუსიკის რიტმზე 🎶', 'მხიარული მუსიკის გაგონებისას რიტმს აჰყვება და ირწევა? სმენასა და მოტორულ უნარებს შორის კავშირი შესანიშნავად ვითარდება! ჩართეთ მხიარული სიმღერა და მასთან ერთად ოთახში იცეკვეთ.'),
  ('deba3d42-726a-4e83-bbbd-900d2aee20ad', 'თუ ბავშვი დანაყრდა, ახლა თქვენი ჯერია.', 'ჯანსაღი რეცეპტებიდან ენერგიის მომცემი წასახემსებელი შეარჩიეთ და დივანზე წამოწოლით სულ მცირე 10 წუთი დაისვენეთ, რათა ძალები აღიდგინოთ.'),
  ('7580f5d5-67e6-4fe8-b318-8dd1f6c00cd6', 'ემოციების დღიური 📝', 'როდესაც თავს მარტოსულად და დაღლილად გრძნობთ, თქვენი განცდები განწყობის დღიურში გადმოიტანეთ. ყველა ქალი გადის ამ ქარიშხლიან გზას — თქვენ ძლიერი ხართ და ამას შეძლებთ!'),
  ('90ae683e-61a6-4dd5-b894-186c95367ff3', 'ღრძილების ქავილი გრძელდება? 🦷', 'ბავშვს თითები სულ პირში აქვს და უხვად გამოყოფს ნერწყვს? დროა, საყინულეში გაგრილებული კბილების ამოსაჭრელი სათამაშოები კვლავ გამოიყენოთ.'),
  ('b9bfa71c-cf95-4768-adc9-c82fe1e676ac', 'სუფთა ჰაერი წამალია 🌳', 'ბავშვი მთელი დღე ტიროდა და მოუსვენრად იყო? გამოსავალი ძალიან მარტივია: შეამოწმეთ ამინდი, შესაფერისად ჩააცვით, ჩასვით ეტლში და დაუყოვნებლივ გაისეირნეთ პარკში. ბუნება ყველაზე სწრაფი დამამშვიდებელია.'),
  ('0a0b2a9c-f56c-4830-8b42-dd0901fc3b1d', 'ობიექტის მუდმივობის თამაში! 🧸', 'ბავშვის სათამაშო რაიმე გადასაფარებლის ქვეშ დამალეთ და მიეცით საშუალება, თავად იპოვოს.'),
  ('2e5279b4-ad3c-4da7-866e-49a5932c0601', 'ყვირის, როცა სათამაშოს ართმევთ?🧸', 'საკუთრების განცდა ძლიერდება. ეს ხასიათის ჩამოყალიბების მნიშვნელოვანი ნაწილია.'),
  ('d2ac515d-c34a-47d7-a082-82f89c2863e8', 'დედის რძე კვლავ მთავარი საკვებია! 🍼', 'დამატებითი კვების მიუხედავად, ჩართეთ კვების ტაიმერი და დარწმუნდით, რომ ბავშვის რძის დღიური მოთხოვნილება დაკმაყოფილებულია.'),
  ('31a887b1-fde3-4a67-a32c-13cc6764d41e', 'ერთად წაიკითხეთ წიგნი! 📖', 'ხმოვანი და ფერადი წიგნები მის ყურადღებას ძალიან იპყრობს. წიგნის კითხვისას გატარებული შემეცნებითი წუთები ბლოგებში მოცემული რჩევებით კიდევ უფრო გაამდიდრეთ.'),
  ('a82a604d-9504-4486-86ea-c38998236871', 'დაგავიწყდათ, რომელი ძუძუთი აჭამეთ? 🤱', 'Anacan-ის ტაიმერი თქვენ ნაცვლად იმახსოვრებს, მარჯვენა თუ მარცხენა ძუძუთი აჭამეთ. კვების ტაიმერი ახლავე ჩართეთ!'),
  ('d7cab28d-37d6-4301-8e4d-28dfd96b83ab', 'წყლის სმის ჩვევას ვაყალიბებთ. 💧', 'დამატებით საკვებთან ერთად წყლის შეთავაზებაც არ დაგავიწყდეთ. შესაფერისი საწრუპი ჭიქები რეკომენდებულ პროდუქტებში იპოვეთ.'),
  ('6122dba2-692e-45e2-8027-9ab67ba2bf07', 'მოდი, მოდი 👏', 'ტაშს უკრავს ან თქვენსკენ ხელებს იშვერს? ეს ურთიერთობის შესანიშნავი ფორმაა. ჩაეხუტეთ.'),
  ('a73ae95c-98a0-4201-9af1-960893ecd116', 'გააჩერეთ დრო 📸', 'ის ისე სწრაფად იზრდება... ძილის დროს მისი ტკბილი, მშვიდი სახე ფოტოზე აღბეჭდეთ და სამახსოვროდ შეინახეთ.'),
  ('b8c9eaea-1257-487d-8647-7c1cb6d70a3a', 'კითხვა გაქვთ? 🤖', 'ბავშვის განვითარებასთან დაკავშირებით ათასობით კითხვა გაქვთ? მისწერეთ Anacan AI-ს და მიიღეთ პედიატრის ზუსტი რჩევები.'),
  ('19dff725-11f8-467a-b784-f2971b302ba0', 'ვემზადებით 250-ე დღისთვის! 🌟', 'ხვალ დიდი რიცხვია — ზუსტად 250 დღე! სახლში პატარა დღესასწაულის განწყობა შექმენით და მოემზადეთ, რომ ამ მიღწევით სიამაყე იგრძნოთ.'),
  ('c304b9f3-2045-4d2f-b423-1096223f0f83', 'დღეს დალაგება არ იქნება 🛑', 'დაიღალეთ? აცნობეთ თქვენს პარტნიორს. დღეს სახლში მომზადებული საჭმელი არ იქნება. დღეს დედის დასვენების დღეა!'),
  ('e01d3a10-f5c2-40e8-8168-d7a86ab3c73d', 'ზღაპარი არ სრულდება 📖', 'ამ საღამოს „ჭკვიან ზღაპრებში“ მამაცი და გონიერი ბავშვის ამბავი შექმენით და მშვიდი გარემო მოაწყვეთ.'),
  ('561e1f8b-1a7d-4ace-9ef9-bd3f43b083d2', 'იამაყეთ ამ 250 დღით🥂', 'ამ საღამოს, ბავშვის დაძინების შემდეგ, არ დაგავიწყდეთ პარტნიორთან ერთად აღნიშნოთ თქვენი გუნდის ეს უდიდესი გამარჯვება!'),
  ('8f3f2d4b-5b88-42ed-95c1-db9f61e1f218', 'არაჩვეულებრივი 250 დღე! 🎉', 'შეგიძლიათ დაიჯეროთ? უკვე ზუსტად 250 დღეა, რაც ამ ქარიშხლიან და ჯადოსნურ გზას ერთად მიუყვებით! ბავშვის ფოტოსესიაზე ეს მომენტი სპეციალური სტიკერით აღნიშნეთ!'),
  ('e0e283b4-8f62-4d84-98d9-c186d1f67042', 'უკან მოიხედეთ 📈', 'გაიხსენეთ პირველი დღეების შიშები. ახლა კი იმ ბავშვის დედა ხართ, რომელიც ფეხზე წამოდგომას ცდილობს! იამაყეთ საკუთარი თავით!'),
  ('01890bf6-ab5a-403c-96d2-696020ff0863', 'იატაკზე დაგებული ხაფანგები 🧸', 'ახლა ოთახები მისთვის აღმოჩენების ზონაა. ხოხვით ყველგან აღწევს. სწორედ დროა, სახლის უსაფრთხოება გულდასმით შეამოწმოთ.'),
  ('64b9a99f-59f6-4495-b5ab-9a4825037afc', 'მიზიდულობის ძალის გამოცდა 🥄', 'ხელში დაჭერილ ნივთს განზრახ აგდებს იატაკზე და შემდეგ თქვენ გიყურებთ? ის უბრალოდ მიზეზშედეგობრივ კავშირს სწავლობს. გამოიჩინეთ მოთმინება და თამაშში აჰყევით.'),
  ('b34bf0e6-4ffb-4b59-90eb-68d99299dee1', 'გაციებული ყავის რეალობა ☕', 'დღესაც გაგიცივდათ ყავა? არა უშავს, თქვენ გმირი ხართ, რომელიც გამუდმებით მოძრაობს. განწყობის დღიურში დღევანდელი ქაოსი იუმორით აღწერეთ.'),
  ('026d603e-c612-41a2-9525-f4d00f730669', 'მარტო შხაპის მიღების ფუფუნება 🛀', 'მთელი დღე მისმა დევნამ ძალა გამოგაცალათ. მეწყვილეს სთხოვეთ, ცოტა ხნით შეგცვალოთ და საკუთარ თავს 15-წუთიანი უწყვეტი წყლის თერაპია აჩუქეთ.'),
  ('1c49ef6a-c84a-47c7-a1bc-352a17833a3d', 'დივნის გასწვრივ პირველი ნაბიჯები 🛋️', 'ავეჯს ეჭიდება, დგება და გვერდულად ნაბიჯებს დგამს? ეს დამოუკიდებლობისკენ გადადგმული უდიდესი ნაბიჯია. აუცილებლად მონიშნეთ ეს მომენტი განვითარების ტრეკერში.'),
  ('b5c1158f-415c-414a-b3ec-c9879bf6e9d9', 'თავის სახელს ცნობს! 🗣️', 'როცა სხვა ოთახიდან სახელით ეძახით, ტრიალდება და გიყურებთ? მისი სმენა და აღქმა სულ უფრო უმჯობესდება. ხშირად მიმართეთ სახელით და ესაუბრეთ.'),
  ('21f7df85-0fd1-4e90-a27b-52045487116f', 'ღამით გაღვიძება 🌙', 'კბილების ამოჭრის პერიოდში ბავშვმა ღამით ხშირად გაღვიძება დაიწყო? მოთმინება გამოიჩინეთ — ღრძილების ტკივილი აწუხებს. აგრძნობინეთ, რომ მის გვერდით ხართ.'),
  ('3ad2c870-178d-449f-aabd-6c01acacefd8', 'ხოხვის მცდელობები 🐢', 'მუხლებზე დგება და წინ და უკან ირწევა? ის სახოხად ემზადება!'),
  ('b80481ba-8798-458c-83d8-f359b3802548', 'სიმშვიდის წუთი ☕', 'ოთახში არეულობა არსად გაიქცევა. სანამ ბავშვი დამოუკიდებლად თამაშობს, მაშინვე დალაგებას ნუ შეუდგებით. დივანზე დაჯექით და 10 წუთის განმავლობაში არაფერი გააკეთოთ.'),
  ('125f59de-0644-435e-8593-de05b7cc7065', 'ხმოვანი ზღაპრები 🎶', 'ვერცერთი აპლიკაცია ვერ შეცვლის დედის იავნანას. ამ საღამოს უბრალოდ გულში ჩაიკარით და ჩუმად უმღერეთ მისი საყვარელი იავნანა.'),
  ('63093c63-3ea0-4bb2-90bb-318617d51b7e', 'პიურეს ფესტივალი 🥣', 'სახე, ცხვირი და თმაც კი საჭმლით მოითხუპნა? გაბრაზების ნაცვლად, ეს საყვარელი მომენტი ბავშვის ფოტოსესიით უკვდავყავით.'),
  ('104420b5-a415-4abb-81d8-7f7b520d18bd', 'ღრძილებში აღმოჩენა 🦷', 'ყველაფერს გამეტებით ღეჭავს და ნერწყვი მოსდის? აკონტროლეთ პროცესი კბილების ამოჭრის ტრეკერში. გამაგრილებელი კბილების ამოსაჭრელი რგოლები ამ დღეებში ნამდვილი ხსნაა.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ka = v.t, body_ka = v.b
FROM (VALUES
  ('c9c8946d-7797-4bd6-8476-9f649f770a6e'::uuid, 'ჩვენ ერთი გუნდი ვართ! 💪', 'თავს მარტო და დაღლილად გრძნობთ? ღრმად ჩაისუნთქეთ. თქვენ და თქვენი პარტნიორი ამ ქარიშხლიანი დღეების ყველაზე ძლიერი გმირები ხართ.'),
  ('9ff73499-a2bd-41b7-96fa-1ec2d780279f', 'თავს დამნაშავედ ნუ იგრძნობთ 💖', 'ფიქრობთ, რომ ბავშვს საკმარის დროს ვერ უთმობთ ან საოჯახო საქმეებს ვერ აუდიხართ? შეწყვიტეთ საკუთარი თავის გაკიცხვა. თქვენ შესანიშნავად ართმევთ თავს.'),
  ('f8790842-2782-419a-aaaa-3c8c1fc497de', 'ამინდი და ტანსაცმელი ⛅', 'გარეთ გასვლისას ნუ იფიქრებთ, რა ჩააცვათ ბავშვს. ამინდისა და ტანსაცმლის ხელსაწყოში ჩაიხედეთ, წამებში შეარჩიეთ იდეალური სამოსი და სუფთა ჰაერზე გადით.'),
  ('bb4b0ba8-0880-4332-8a97-7715f01a7ba8', 'კარადის დეტექტივები 🕵️‍♂️', 'სამზარეულოს კარადები მისი საყვარელი სამიზნეა? უსაფრთხო ჭურჭელი ქვედა კარადაში მოათავსეთ და მიეცით საშუალება, საკუთარი განძი აღმოაჩინოს და საათობით ითამაშოს.'),
  ('bf07c6c2-b84c-44ed-9459-f26c37f0e099', 'ჭიტას ოსტატი 🙈', 'ხელებით სახის დაფარვა და ჭიტას თამაში მისი საყვარელი საღამოს გართობაა.'),
  ('c24149f4-cca2-46bd-ba68-2442b259ab90', 'თქვენ ქალიც ხართ 💄', 'თქვენ დედა და დამცველი ხართ, მაგრამ ამავე დროს ცალკე პიროვნებაც. სარკეში საკუთარ თავს შეხედეთ, გაუღიმეთ და დღეს თქვენთვის პატარა სასიამოვნო ჟესტი გააკეთეთ.'),
  ('4283eae1-f0b6-489a-be21-28cec6201152', 'ფორუმებში ნუ დაიკარგებით 🤖', 'კვების რეჟიმთან დაკავშირებით ეჭვი გაქვთ? საათობით ნუ ეძებთ პასუხებს — Anacan AI თქვენს შეკითხვებს ჯიბის პედიატრის ლოგიკით უპასუხებს.'),
  ('743ea03a-9755-40d4-b4aa-1eb6cf8a7495', 'მამას კითხვის საათი 📖', 'დღეს საღამოს „ჭკვიან ზღაპრებში“ შექმენით ამბავი მამაც თხაზე, რომელიც მთებზე აძვრა. მამამ წაიკითხოს, თქვენ კი ამ სიმშვიდით დატკბით.'),
  ('fc594ad6-91bd-4ee2-a759-0d1e76e468c0', 'თითებით ჭამა 🥦', 'მას უკვე პიურე კი არა, ბოსტნეულის საკუთარი ხელით აღება სურს! ხელი შეუწყვეთ მის მცდელობებს, დამოუკიდებლად ჭამოს, მაგრამ აუცილებლად მის გვერდით იყავით.'),
  ('5cafdda5-c60b-4328-9530-450093ed8026', 'სრული სიჩუმე 🤫', 'უჭირს ჩაძინება? ოთახი მთლიანად დააბნელეთ და ხმაური გამორიცხეთ. სიბნელე და სიჩუმე მისი ძილის საუკეთესო მეგობრებია.'),
  ('8ee71700-bb17-4782-940b-c0fc02328f1a', 'განავლის ფერი შეიცვალა? 💩', 'დამატებით კვებაზე გადასვლისას განავლის სხვადასხვა ფერი ნორმალურია. თუმცა, თუ შეშფოთებული ხართ, მიზეზი Anacan AI-ს ჰკითხეთ.'),
  ('9240cd01-c58e-42aa-be44-a4d2ac461bc2', 'გამოფიტვა ნორმალურია 🔋', 'როცა მოთმინება გეწურებათ, თავი ცუდ დედად არ იგრძნოთ. ეს დაღლილობა ბუნებრივია.'),
  ('288682cf-7f40-402e-a594-adaf2cbbed34', 'ფეხშიშველი აღმოჩენები 👣', 'სახლში წინდებით სიარული არ უყვარს? ტერფების ნერვული დაბოლოებების იატაკთან შეხება ტვინის განვითარებისთვის შესანიშნავია. მიეცით თავისუფლად მოძრაობის საშუალება!'),
  ('2951ca5f-9454-4562-9820-3bfb3531edfd', 'სია ცხოვრებას ამარტივებს 🛒', 'გონების დაბინდვა ისევ არ გტოვებთ? საპონი გათავდა, ხილიც შემცირდა? სანამ დაგავიწყდებათ, საყიდლების სიაში ჩაწერეთ და დანარჩენი თქვენს პარტნიორს მიანდეთ.'),
  ('5a72ebf7-bb71-45f2-8047-a9b0ffc32a13', 'გუნდური შეხვედრა 🥂', 'დღეს საღამოს, ბავშვის დაძინების შემდეგ, პარტნიორთან ერთად გახსენით განწყობის დღიური და ამ კვირის ქაოსზე ერთად იცინეთ.'),
  ('06f3c3ab-79a9-4f2f-94ed-e08927cda8e1', 'კბილები კვლავ შეტევაზე არიან 🦷', 'უმიზეზო ტირილი შესაძლოა ღრძილების დაჭიმულობით იყოს გამოწვეული. განაახლეთ კბილების ამოსვლის ტრეკერი და გამოიღეთ მაცივარში გაგრილებული კბილების ამოსაჭრელი რგოლები.'),
  ('8e728e0f-9970-4b3d-acfc-5e72bc0eb7af', 'ოთახის აკუსტიკა 🤫', 'ჩაძინებისას უმცირეს ხმაურზეც კი იღვიძებს? ხმაურის საზომით შეამოწმეთ გარემო და სტაბილური თეთრი ხმაურით ხელი შეუწყვეთ მის ძილს.'),
  ('cefb8b22-0318-4268-adf8-8f7052ad66cc', 'შორეულ საგანზე თითით მიუთითებს და ბგერებს გამოსცემს? ☝️', 'ის გეუბნებათ: „შემომხედე“ ან „ეს მინდა“. ეს კომუნიკაციის განვითარებაში დიდი ნახტომია!'),
  ('2e4d0e7a-db8d-4408-9d88-01d37ed8b303', 'ძილის ფანჯარა ვიწროვდება 🥱', 'ღამით გაღვიძებებმა გამოგფიტათ? შესაძლოა, ეს 3 ძილიდან 2 ძილზე გადასვლის ეტაპია. გადახედეთ დღის ძილებს შორის ინტერვალებს.'),
  ('b19774b6-01ed-4a77-8052-5a03aef4ba22', 'პიურე თმაში 🤦‍♀️', 'ჭამის დრო ბრძოლის ველად იქცევა? საკვებზე შეხება და მისი შესწავლა ბავშვის სენსორული განვითარების ნაწილია. ლაქებს ყურადღებას ნუ მიაქცევთ.'),
  ('f1d99477-a71b-4368-b9eb-c5c699e49b39', 'ბუნება გვშველის 🌳', 'ბავშვი ძალიან ჭირვეულობს და სახლში ვერ ჩერდება? მიიღეთ რჩევა ამინდისა და ჩაცმულობის დამხმარისგან და მაშინვე გაემართეთ პარკში 20-წუთიან გასეირნებაზე.'),
  ('2958c07b-39da-4ecb-ac79-c0f1640a7d1a', 'თავს სხვებს ნუ შეადარებთ 🛑', 'დაივიწყეთ ფრაზა: „სხვისი ბავშვი უკვე დადის“. ყველა ბავშვის განვითარების ტემპი უნიკალურია. Anacan-ის საზოგადოებაში გულახდილად ესაუბრეთ დედებს, რომლებიც თქვენსავით ფიქრობენ.'),
  ('da431940-9d6b-4ed8-a933-fd80b83687d9', 'სიტყვა „დედას“ მოლოდინი 🥰', 'ბავშვი სხვადასხვა მარცვალს წარმოთქვამს. პირველი გააზრებული სიტყვა „დედა“ ან „მამა“ უკვე ძალიან ახლოსაა! მის ხმას სიყვარულით გამოეხმაურეთ და გაამხნევეთ.'),
  ('f40e6c18-873e-481a-ba28-76a5634b977a', 'მუსიკა სულის საზრდოა 🎶', 'სცადეთ, საღამოობით დაწყებული უმიზეზო ჭირვეულობა მშვიდი კლასიკური მუსიკით შეაჩეროთ. ხშირად ეს მარტივი ხრიკი სასწაულს ახდენს.'),
  ('0c385e87-5c02-4870-85f8-9ab052891af8', 'ვიტამინები დედისთვის 🥑', 'მის დასანაყრებლად ყველაფერს აკეთებთ. თქვენზე ვინ იზრუნებს? ჯანსაღი რეცეპტების განყოფილებიდან აირჩიეთ რკინითა და კალციუმით მდიდარი მსუბუქი სადილი.'),
  ('bda4f100-98ac-4f09-9fa3-a50d4e42eedd', 'ყურადღება! 9 თვის შესრულებამდე სულ რაღაც 10 დღე დარჩა!  🎂', 'დროა, ამ განსაკუთრებული თარიღისთვის პატარა ტორტი ან ოჯახური კონცეფცია წინასწარ მოიფიქროთ.'),
  ('effeac28-8d9e-4d0e-b754-fb4004990432', 'მოშორდით ეკრანებს 📱', 'ღამის ძილამდე 1 საათით ადრე სახლში ყველა ტელევიზორი და ეკრანი გამორთეთ. მელატონინის გამომუშავება მხოლოდ მშვიდ და ბნელ გარემოში ჩქარდება.'),
  ('47fc8d5e-d99d-4104-9258-c8e18ad15266', 'რა იქნება ამ საღამოს თემა?🪄', 'ამ საღამოს ზღაპარი ხელოვნურმა ინტელექტმა დაწეროს: პატარა ციყვი, რომელიც თავის სათამაშოებს ეძებს. დაე, ღამის სიჩუმე მხოლოდ თქვენმა თბილმა ხმამ დაარღვიოს.'),
  ('856e1374-a46f-4ac4-b093-11e46392180f', 'მიმბაძველი თუთიყუში 🦜', 'თქვენს ხველას, სიცილს ან ხელის მოძრაობებს ბაძავს? ოთახში საუკეთესო სარკე თქვენ ხართ. ასწავლეთ მას ყველაზე ლამაზი მიმიკები!'),
  ('e263bb82-67f5-4f23-9107-f117b8634a27', 'მიეცით გრძნობებს თავისუფლება 📝', 'ზოგჯერ უბრალოდ კარის დაკეტვა და ტირილი გინდათ? ეს სრულიად ნორმალურია... წერა შვებას მოგგვრით. თქვენი გრძნობები განწყობის დღიურში გადაიტანეთ.'),
  ('3c29a397-ae21-4b66-9ae6-c3001d2f3e36', 'ის თქვენ გიყურებთ 👀', 'ოთახის რომელ კუთხეშიც უნდა იყოთ, მისი მზერა თქვენკენაა მოპყრობილი. თქვენ მისი უსაფრთხო სივრცე ხართ. როცა მოთმინება გეწურებათ, გაიხსენეთ მისი ეს უპირობო სიყვარული.'),
  ('b3560b09-ab82-494c-a5e9-d6be5d4cb35a', 'არეულობის ხელოვნება 🌪️', 'ყველაფერს, რითაც თამაშობს, ირგვლივ ყრის. ახლა დალაგებაზე მნიშვნელოვანი თქვენი დასვენებაა. სათამაშოები ხვალაც იქ იქნება, ბავშვს კი ენერგიული დედა დღეს სჭირდება.'),
  ('fe563692-e0de-40b2-aa34-9d6335348a54', 'ღამის სიჩუმე 🤫', 'თუ მანქანის ან გარედან შემოსული ხმები ბავშვს აწუხებს, ფონად აუცილებლად დატოვეთ თეთრი ხმაურის უწყვეტი წყარო.'),
  ('268d0edd-f8c9-45fd-af24-4b1bd27e458d', 'მამის მასაჟის სალონი 💆‍♀️', 'სთხოვეთ თქვენს პარტნიორს, ბავშვი დააძინოს, შემდეგ კი თქვენს დაჭიმულ კისრის კუნთებს 5-წუთიანი მასაჟი გაუკეთოს!'),
  ('38581365-03a6-48aa-a7b4-923dde40764d', 'კიბეებისადმი ინტერესი 🧗‍♂️', 'თუ სახლში კიბე ან შემაღლებული ადგილებია, ბავშვი მათკენ მიიწევს. სწორედ ახლაა უსაფრთხოების დამცავი კარების დამონტაჟების დრო.'),
  ('b1d60979-35c2-486a-9e3b-5e85d1d3dbdf', 'ბრძოლა ჭამის დროს 🥣', 'პიურეს გვერდზე სწევს? ძალით ნუ აჭმევთ. საკვების მიმართ ჯანსაღი დამოკიდებულება რომ არ დაურღვიოთ, პროცესი თამაშად აქციეთ და საზოგადოებაში ალტერნატიული რეცეპტები მოიძიეთ.'),
  ('73d0b947-9db1-4d57-a222-c8c22a2a895b', 'ხასიათი ყალიბდება 🌟', 'უკვე აშკარად გამოხატავს, რა მოსწონს და რა საერთოდ არ უნდა. როცა მისი სიჯიუტე დაგღლით, გახსოვდეთ, რომ სინამდვილეში ეს პიროვნების ჩამოყალიბების პროცესია.'),
  ('9596d063-607c-465f-9e92-b73f9f6f0ece', 'დედების მეგობრობა 💬', 'სირთულეების გაზიარება ტვირთს ამსუბუქებს. Anacan-ის საზოგადოებაში ათასობით ქალია, რომლებიც იმავეს გრძნობენ, რასაც თქვენ. გულახდილი საუბარი უფასოა.'),
  ('fb27143e-60bd-4519-b45e-80c5584417a4', 'მამის ნუგეში 🫂', 'ნუ ეცდებით ღამის კრიზისებთან მარტო გამკლავებას. პროცესში თქვენი პარტნიორიც ჩართეთ. ზოგჯერ განსხვავებული სურნელი და ჩახუტება ბავშვს მყისიერად ამშვიდებს.'),
  ('4e869b86-0b42-4c4a-86f7-22a0999a3387', 'ტაშის დროა 👏', 'სიხარულს ტაშის დაკვრით გამოხატავს? აღნიშნეთ ეს შესანიშნავი მოტორული მიღწევა განვითარების ტრეკერში და სახლში პატარა გამარჯვების ცეკვა შეასრულეთ.'),
  ('72a32149-c4d7-4a45-b296-5cc7c5b673ad', 'სწრაფი ჩექ-აფი 🤖', 'როგორია 9 თვის ბავშვის განვითარების მოსალოდნელი ეტაპები? დაივიწყეთ გრძელი სტატიები. შეკითხვა პირდაპირ Anacan AI-ს დაუსვით და პედიატრის დონის სიზუსტით მიიღეთ პასუხი.'),
  ('df74b674-d83b-4306-a6c3-1477bd965efe', 'ძილისთვის მომზადება 🛀', 'თბილი აბაზანა ყოველთვის ეფექტურია. საღამოს რუტინა არასოდეს დაარღვიოთ, რადგან ის ბავშვის ტვინს აძლევს სიგნალს, რომ ძილის დროა.'),
  ('5626563e-1119-4751-a2d2-ad651cb7961b', '9 თვისა და 5 დღის! 🎈', 'იუბილემდე სულ ცოტა დრო დარჩა! ტორტი, პატარა დეკორაციები ან უბრალოდ სახლში ყველაზე ლამაზი ტანსაცმელი... დააჩქარეთ ბავშვის ფოტოსესიისთვის მზადება.'),
  ('5e8f6838-89c2-40a6-940e-2ef8b752a179', 'ერთად შექმნილი მოგონებები 📸', 'რა ლამაზად იღიმის! ძილის წინ გადაუღეთ ფოტო მის უმანკო სახეს — ეს წამები აღარასოდეს განმეორდება.'),
  ('912ca02c-47d0-4e27-8bdb-7afe9ba868be', 'რკინის მარაგი 🥩', 'ანემიამ შეიძლება ბავშვს მადაც და ენერგიაც დაუქვეითოს. გადახედეთ მის კვების რეჟიმს და, საჭიროების შემთხვევაში, ჰკითხეთ Anacan AI-ს რკინით მდიდარი საკვების შესახებ.'),
  ('0135df6f-fe6e-4faf-9136-dc65b2b29e33', 'დამშვიდობების დროა 👋', 'როცა ვინმე სახლიდან მიდის, ბავშვი ხელს უქნევს და ემშვიდობება? ეს სოციალური განვითარების ძალიან საყვარელი ნიშანია! ხშირად წაახალისეთ.'),
  ('44260d05-153e-4b6b-b9dd-6f07fb02c462', 'სიმშვიდის ძიება ⛅', 'როცა დაძაბულობა იმატებს, საუკეთესო გამოსავალი სახლიდან გასვლაა. შეამოწმეთ ამინდი, ჩასვით ბავშვი ეტლში და უბრალოდ გაისეირნეთ, რომ გონება განიტვირთოთ.'),
  ('67247d93-ddf7-4fcc-adef-5828dde725b4', 'სრულყოფილების ილუზია 🛑', 'დღეს არაფერი წავიდა გეგმის მიხედვით? თავს ნუ დაიდანაშაულებთ. თქვენ ნამდვილი დედა ხართ და არა სოციალურ ქსელებში გაფილტრული ილუზია.'),
  ('4e8edba3-fd16-4c28-a7ff-08ff9853211e', 'ყოველდღიური წვრილმანები გვავიწყდება. 🛒', 'საფენები გაგითავდათ თუ სველი ხელსახოცები? დაამატეთ საყიდლების სიაში, რომ თქვენმა პარტნიორმა მაღაზიიდან დაბრუნებისას მოაგვაროს.'),
  ('5f49ad4f-107b-4550-adae-e4aab3aa9d5b', 'ძილის ორჯერად რეჟიმზე გადასვლა 🥱', 'ბავშვი, რომელსაც დღისით 3-ჯერ ეძინა, ბოლო ძილს უკვე ეწინააღმდეგება? ის იზრდება! დროა, ძილის რეჟიმი დღის განმავლობაში 2 ძილს მოარგოთ.'),
  ('8750f5ee-e089-418c-9d9b-a881ca3441c3', 'ზღაპრების ჯადოსნური სამყარო 🪄', 'ჭკვიან ზღაპრებში შექმენით დიდი გმირის ისტორია, რომელიც სულ რაღაც 5 დღეში 9 თვის გახდება.'),
  ('7ee44a70-ee6e-4b49-a487-76ff5581f580', 'გაბედული ნაბიჯები 🧗‍♂️', 'ავეჯს ეჭიდება და ცდილობს, ერთი ხელი გაუშვას? მას წონასწორობის შეგრძნება უვითარდება. ხელი ჩასჭიდეთ და ცოტა თავდაჯერება შემატეთ.'),
  ('97d44a72-2ca4-4c0f-b997-91c31aeabbef', 'გულახდილი საუბარი 🥂', 'გახსენით განწყობის დღიური და პარტნიორთან ერთად განიხილეთ, როგორ შეგცვალათ ამ თვეებმა. ერთ გუნდად ყოფნა უდიდესი ძალაა.'),
  ('ff86bc54-face-4f54-a1de-cc0ec9cccbc2', 'ყველაფერი კარგადაა ✔️', 'ზოგჯერ შიშები გძლევთ? შეხედეთ ბავშვის სუფთა ტანსაცმელს, დანაყრებულ მუცელსა და თვალებს, რომლებიც შემოგციცინებენ. თქვენ შესანიშნავად ართმევთ თავს!'),
  ('55476184-e000-441a-91f6-32b219ce5489', 'ხვალ დიდი დღეა! 🎉', 'ზუსტად 9 თვე! ტანსაცმელი მოამზადეთ? გაათავისუფლეთ ადგილი ტელეფონის მეხსიერებაში — ხვალ ბავშვის ფოტოსესიისთვის ბევრი ადგილი დაგჭირდებათ!'),
  ('801186a2-f617-44a4-bfbe-39fa8b84707d', 'ღამის იავნანა 🎶', 'ამ საღამოს ოთახი სრულად ჩააბნელეთ. არავითარი ტექნოლოგია — მხოლოდ თქვენი ჩურჩულით ნათქვამი იავნანა.'),
  ('bcabe7b8-3e78-42a9-bdf0-3f1883219079', 'სტკივა თუ დაიღალა? 😭', 'თუ უმიზეზოდ ტირის, სიმშვიდე შეინარჩუნეთ. გამოიყენეთ ტირილის ანალიზი, რათა სწრაფად აღმოაჩინოთ და მოაგვაროთ პრობლემა.'),
  ('327e6e73-14c5-44c7-86f9-1b01671cc4cc', 'მიღწეულ გზაზე თვალის გადავლება 📈', 'რამხელა გზა გამოიარა თქვენმა ბავშვმა? პირველი დღეების მღელვარება თავდაჯერებამ შეცვალა. თქვენ ეს გზა დიდი გამარჯვებით გაიარეთ!'),
  ('4b865d9a-0f66-4cb0-98d0-deaa6f061766', 'ცოტაოდენი რომანტიკა 💖', 'ამ საღამოს 9 თვის დაღლილობა და სიამაყე თქვენს პარტნიორთან ერთად, სანთლების შუქზე აღნიშნეთ. თქვენ შესანიშნავი გუნდი ხართ!'),
  ('8be43b5a-b4b9-49ba-b74f-59b204783156', 'ზუსტად 9 თვე! 🎂', 'გილოცავთ! მშობიარობიდან ზუსტად 9 თვე გავიდა. ბავშვი 9 თვე თქვენს მუცელში იზრდებოდა, შემდეგ კი 9 თვე — თქვენს მკლავებში! აღნიშნეთ ეს შესანიშნავი მომენტი და გაუზიარეთ მოგონება საზოგადოებას!'),
  ('334b387f-4019-4208-b951-95f53c679a8b', 'ენერგიის საჭიროება 🍲', 'დაღლილობა ძვალ-რბილში გაქვთ გამჯდარი. ჯანსაღი რეცეპტებიდან შეარჩიეთ რკინითა და ცილებით მდიდარი სადილი, რომელიც 10 წუთში მზადდება, და ძალები აღიდგინეთ.'),
  ('495a74f3-0952-464a-80e0-08b1cc46205c', 'მართეთ ხმაური 🤫', 'სახლში ხმაური მის ღრმა ძილს არღვევს. ხმის საზომის დახმარებით ფონური ხმაური სტაბილურ დონეზე შეინარჩუნეთ, რათა თქვენც მშვიდად დაისვენოთ.'),
  ('73c5a297-0a32-46fb-8b7c-4ca9aeac6cb1', 'სიტყვა „არას“ ძალა 🛑', 'უკვე გვერდზე სწევს საჭმელს, რომელიც არ მოსწონს, თავს აქნევს და ამბობს „არას“? მისი პიროვნება ყალიბდება! პატივი ეცით მის ნებას.'),
  ('5238f2b7-2892-49ff-9220-f07d0cf3221d', 'დღისით დაღლილობა გეყოფათ. 👨‍🍼', 'საღამოს ბავშვთან ერთად ოთახში კოტრიალი და თამაში მხოლოდ მამის მოვალეობაა.'),
  ('c89b6b27-fdbd-4cb8-a5cb-f7ddd8bc2ede', 'განძის ძიება 🧺', 'ტანსაცმლის კალათის დაცლა ან კარადებში ქექვა მისთვის ყველაზე დიდი გართობაა. მიეცით თავისუფლად თამაშის საშუალება — ეს მის მოტორულ უნარებს ავითარებს.'),
  ('f0057ec1-cc62-4ea5-9364-5327660ddc30', 'ნუ მოგერიდებათ კითხვა 🤖', 'რომელი სანელებლების გამოყენება შეიძლება ბავშვის საკვებში? ყველაფერი, რაზეც ეჭვი გეპარებათ, დაუყოვნებლივ ჰკითხეთ Anacan AI-ს და დამშვიდდით.'),
  ('00632cb5-4d20-4f2d-9bf8-82242042667b', 'ჭკვიანური ზღაპრის დრო 🪄', 'დღეს საღამოს განსხვავებული ამბავი მოუყევით: ჯადოსნური ღრუბელი, რომელსაც ჩაძინება უყვარს. დაუწიეთ ხმას და შექმენით შესაბამისი ატმოსფერო.'),
  ('61c9e192-532e-41bc-9ebb-f2c296bb0670', 'გაიზიარეთ ემოციური ტვირთი 💬', 'შეუერთდით Anacan-ის საზოგადოებას. ზოგჯერ უცნობი დედის კომენტარის წაკითხვა ყავაზე მეტ ენერგიას გვაძლევს.'),
  ('92c6be75-a837-4908-b755-b4ae97896380', 'სახიფათო ზონებზე წვდომა ⚡', 'როზეტები და სადენები მის ყურადღებას იქცევს. მკაფიოდ განსაზღვრეთ სახლში აკრძალული ზონები და კიდევ ერთხელ გადაამოწმეთ უსაფრთხოება.'),
  ('159ac401-c76f-42ec-b9e1-bb1a6d73130e', 'აღმოჩენები პინცეტისებრი მოჭიდებით 🤏', 'იატაკზე ყველაზე პატარა ნამცეცსაც კი თითის წვერებით პოულობს და იღებს! მისი ნატიფი მოტორიკა შესანიშნავად ვითარდება.'),
  ('306f7e64-ae54-408a-95b9-ac4f9c3c6684', 'ღამის სიმშვიდე 🛀', 'ნუ შეცვლით რუტინას. ყოველთვის ერთი და იგივე აბაზანა, მასაჟის ზეთი და ჩაბნელებული ოთახი მშვიდი ძილის ოქროს გასაღებია.'),
  ('f3512bb1-5e87-4250-8249-5c396829b593', 'ოთხ კედელში ყოფნის სინდრომი ☕', 'სახლში ყოფნა გაწუხებთ? დედებისთვის მეგობრულ სივრცეებს შორის იპოვეთ უახლოესი ადგილი, სადაც თქვენ სუფთა ჰაერს ჩაისუნთქავთ, ბავშვი კი თავს კომფორტულად იგრძნობს.'),
  ('1835b0bb-3338-4b12-9da9-167cd1643dc6', 'სახლის საქმეებს ვინ გააკეთებს? 🌪️', 'მტვერსასრუტის ხმა ბავშვს აშინებს და საქმეები გროვდება? დაე, დაგროვდეს. სთხოვეთ თქვენს პარტნიორს, დღეს სახლის საქმეები საკუთარ თავზე აიღოს.'),
  ('be2205ed-6711-45b7-b2f3-ab21216eef54', 'ემოციების დღიური 📝', 'როცა თავს მარტოდ გრძნობთ, განწყობის დღიურში გადმოიტანეთ თქვენი გრძნობები. ყველა ქალი გადის ამ გზას — თქვენ ძლიერი ხართ.'),
  ('cd0245fe-8c0d-4f3e-ad23-05cff2186013', 'ნაგვის მკვლევარი 🗑️', 'ბავშვი ყველაფერს, რასაც იატაკზე იპოვის, დიდი ინტერესით იკვლევს. ყველაფერს ხელიდან ნუ წაართმევთ და ნუ გაბრაზდებით — ის პატარა მკვლევარია. უბრალოდ ყურადღებით ადევნეთ თვალი.'),
  ('6ff5d725-a5bb-441a-a5ed-1b1b10bf2638', 'მამისგან მიღებული ნუგეში 🫂', 'ღამით ბავშვის გაღვიძებისას მორიგეობით ადექით — ერთხელ თქვენ, ერთხელ თქვენი პარტნიორი. ზოგჯერ ბავშვს სწორედ მამის რიტმული მოფერება ამშვიდებს.'),
  ('77c04114-1662-45d9-9778-494a99f15f4f', 'ამინდს ნუ მოტყუვდებით ⛅', 'სასეირნოდ გასვლისას მხოლოდ ფანჯრიდან გახედვით ნუ გადაწყვეტთ, როგორ ჩააცვათ ბავშვს. ამინდისა და ჩაცმის ხელსაწყოს დახმარებით, ფენებად ჩაცმისას ოქროს შუალედი იპოვეთ.'),
  ('b630415b-1d8a-4088-bd37-659e6494cb2c', 'ჩემს სათამაშოს არ მოგცემ! 🧸', 'როცა ხელიდან რამეს ართმევთ, აპროტესტებს და ტირის? მას საკუთრებისა და ინდივიდუალურობის განცდა უვითარდება. ეს სრულიად ბუნებრივი ფსიქოლოგიური ეტაპია.'),
  ('5c4470d4-31c9-42e6-98b2-6ebad58cdce5', 'მის ხმაში უცნაურობას ვერ ხვდებით?  😭', 'დაუყოვნებლივ მოასმენინეთ ტირილის ანალიზის ფუნქციას, გაარკვიეთ, პრობლემა კბილების ამოჭრაა თუ აირები და დამშვიდდით.'),
  ('906becee-91c7-4860-a453-bec23a80f855', 'სიმშვიდის საჭიროება 🤫', 'ოთახში სიმშვიდე ხმის საზომით შეინარჩუნეთ. ღამით შეწყვეტილი ძილი დილით როგორც ბავშვის, ისე თქვენს განწყობაზე უარყოფითად მოქმედებს.'),
  ('93f3b238-cc16-44a9-888c-f9d77043f372', 'ცეკვა მუსიკის თანხლებით 🎶', 'მხიარული მუსიკის გაგონებისას რიტმს აყოლილი ირწევა? ეს სმენასა და მოტორულ უნარებს შორის კავშირის ჩამოყალიბებაზე მიუთითებს! ჩართეთ მხიარული სიმღერა და მასთან ერთად იცეკვეთ.'),
  ('334464c1-4599-4dd4-83dd-d57c384eb650', 'წიგნებს ფურცლავს 📖', 'ცდილობს სქელფურცლიანი წიგნების გვერდების გადაშლას? უყიდეთ ბევრი ფერადი და სხვადასხვა ფაქტურის მქონე ზღაპრების წიგნი.'),
  ('d7009029-eb30-44cd-bedc-77f2ddcbdbe4', 'პიურედან საკვების ნაჭრებამდე! 🍲', 'უკვე შეუძლია ისეთი საკვების ჭამა, რომელსაც დაღეჭვა სჭირდება? ჩვენს აპლიკაციაში, განყოფილებაში „ბავშვები, რომლებიც დამატებით კვებას იწყებენ“, სცადეთ სხვადასხვა ტექსტურის მქონე პიურეებისა და სუპების რეცეპტები.'),
  ('f5716668-d412-4d80-9c29-0a69a23f4f4e', 'საყიდლების სია 🛒', 'საჭმლის მოსამზადებლად ბროკოლი ან შვრია გამოგელიათ? დაუყოვნებლივ შეავსეთ საყიდლების სია და საჭირო პროდუქტების ჩამონათვალი პარტნიორის ტელეფონზე გაგზავნეთ.'),
  ('16369cf1-7620-428e-8c38-c6f5104fb5ab', 'სათამაშოებს ყუთიდან იღებს! 🧸', 'მას მოსწონს ნივთების ყუთიდან სათითაოდ ამოღება და გადაყრა. ბავშვის ფოტოსესიით აღბეჭდეთ აღმოჩენების ეს მხიარული და ცოტა არეული მომენტი, რათა მოგვიანებით ღიმილით გაიხსენოთ.'),
  ('912a7ba7-5cb9-41f1-9daa-dc1c800036eb', 'პირველი ნაბიჯები ახლოვდება? 🧗‍♂️', 'დივანზე ხელის მოკიდებით წამოდგომას აღარ სჯერდება და კედლის გასწვრივ გადაადგილდება? უსაფრთხოების ზომები გააორმაგეთ.'),
  ('ec70551b-eda4-4e87-86a9-151235d2eb3e', 'ზღაპრით დაძინება 🪄', 'ჭკვიან ზღაპრებში მამაცი და საყვარელი ცხოველების ისტორიები შექმენით და ოთახი ჯადოსნურ სივრცედ აქციეთ.'),
  ('39498b75-8a2a-463e-a232-aa6ed7188810', 'თქვენი ხმის ტონს იგებს 🗣️', 'როდესაც სერიოზული ხმით ეუბნებით „არას“, ჩერდება და გიყურებთ? ის უკვე ემოციებისა და აკრძალვების აღქმას იწყებს!'),
  ('6d030e22-f99a-4fa8-829a-d62a50ce76e0', 'განვითარების შემოწმება 🤖', 'ფიქრობთ, რომ ბავშვის ფიზიკური მოძრაობების განვითარება დაგვიანებულია? Anacan AI-სგან მიიღეთ მკაფიო ინფორმაცია 9 თვის ბავშვის მოტორული უნარების შესახებ.'),
  ('e607d1aa-9be0-4388-9790-764a5c1e94da', 'საჭმლის მონელებას ვაკვირდებით. 🧷', 'მყარი საკვები განავლის გამოყოფას ცვლის. ბავშვის ჯანმრთელობის გასაანალიზებლად საფენის ყოველი გამოცვლა Anacan-ში აღრიცხეთ.'),
  ('57fa0aeb-432f-4b34-915b-98422c100236', 'კბილების ამოჭრის ტკივილი 🦷', 'ღრძილები ისევ გაუწითლდა და ნერწყვდენა არ წყდება? მოამზადეთ გასაგრილებელი კბილის ამოსაჭრელი სათამაშოები.'),
  ('bda23a3e-0646-4246-a5dc-febd245b2bb1', 'დაგავიწყდათ, რომელი ძუძუდან აჭამეთ? 🤱', 'Anacan-ის ტაიმერი თქვენ ნაცვლად იმახსოვრებს, მარჯვენა თუ მარცხენა ძუძუდან აჭამეთ. ჩართეთ კვების ტაიმერი ახლავე!'),
  ('e2296439-aad7-4bdf-a627-05d1e066a3d8', 'თვალი ადევნეთ ძილის ნორმებს. ⏱️', 'როცა თქვენს ბავშვს სძინავს, ჩართეთ ძილის ტაიმერი და გრაფიკზე შეამოწმეთ, იცავს თუ არა ის 9 თვის ბავშვის ძილის დღიურ ნორმას.'),
  ('13322f59-d734-452d-8178-1ffb4e5e9f78', 'სავარძელზე აძრომა 🧗‍♂️', 'იატაკზე სიარული აღარ აკმაყოფილებს და ავეჯზე აძრომას ცდილობს? მოტორული უნარები სწრაფად ვითარდება! აუცილებლად მეთვალყურეობის ქვეშ გყავდეთ.'),
  ('b349c13b-d822-42ec-876c-d41ccb790846', 'სუფთა ჰაერი წამალია 🌳', 'მთელი დღე ტიროდა და მოუსვენრად იყო? გამოსავალი ძალიან მარტივია: გაითვალისწინეთ ამინდი, სათანადოდ ჩააცვით, ჩასვით ეტლში და დაუყოვნებლივ წადით პარკში.'),
  ('e46eb59c-0196-4f8a-b3f3-e86458e1f828', 'ოთახის აკუსტიკა 🤫', 'ძილის დროს უმცირესი ჭრიალიც კი აღვიძებს. ხმაურის საზომით შეამოწმეთ გარემო და უზრუნველყავით უწყვეტი სიჩუმე.'),
  ('3ab1636f-ed5f-47f5-93d7-4ac521edd386', 'თავს არასაკმარისად კარგად გრძნობთ? 💬', 'ახლავე შედით Anacan-ის საზოგადოებაში, წაიკითხეთ სხვა დედების მხარდამჭერი კომენტარები და დამშვიდდით.'),
  ('62964d86-1e07-4c7f-a135-52c48581ffc5', 'დღეს ყველაფერი თავდაყირა დადგა?', 'არაუშავს — თუ ბავშვი მაძღარი და სუფთაა, თქვენ მსოფლიოში საუკეთესო დედა ხართ.'),
  ('fa0817a9-00d2-41fc-bdcb-8fdae95932ff', 'საგნების სახელებს სწავლობს 🧸', 'როდესაც ეკითხებით: „სად არის ბურთი?“, თვალებით ეძებს და პოულობს? მისი აღქმის უნარი უმჯობესდება! ითამაშეთ მასთან და თამაშისას საგნების სახელები წარმოთქვით.'),
  ('93f4fd0f-1f45-436c-b46b-7acc69d1b899', 'ორ ფეხზე წონასწორობა 🤸‍♂️', 'როდესაც იღლიებით გიჭირავთ, უფრო გამართულად და მყარად დგას ფეხებზე? აუცილებლად მონიშნეთ განვითარების მონიტორინგში ეს მნიშვნელოვანი ნაბიჯის გადადგმის რეფლექსი!'),
  ('b0bdf4f4-2902-43a5-876f-e99b39aef4f9', 'ჯადოსნური ზღაპრის დრო 🪄', '„ჭკვიან ზღაპრებში“ მოთხრობილი ამბით „პატარა გმირის დაძინების საიდუმლოებები“ საღამოს რუტინა უფრო მრავალფეროვანი გახადეთ.'),
  ('c6da7887-a402-4a11-8fbf-8de4d7696325', 'სია ნამდვილი მხსნელია 🛒', 'სახლის ყოველდღიური საჭიროებები არასდროს ილევა. თავს ნუ გადაიტვირთავთ — შეავსეთ საყიდლების სია და დაელოდეთ, როდის დაბრუნდება მამა სამსახურიდან და მხსნელად მოგევლინებათ.'),
  ('1b15944e-9198-4fc4-b86d-0b17af6cdd00', 'რა ვკითხო ექიმს? 🤖', 'არ იცით, რა უნდა ჰკითხოთ ექიმს ყოველთვიურ შემოწმებაზე წასვლამდე? სთხოვეთ Anacan AI-ს 9-თვიანი შემოწმებების სია.'),
  ('1eda7621-0a6a-4ff0-8efe-ec931b28a106', 'სახლის პატარა დამხმარე 🧺', 'სანამ ტანსაცმელს კეცავთ, ისიც მოდის და არევით გეხმარებათ? ნუ დატოვებთ პროცესის მიღმა — მიეცით ხელში ერთი პირსახოცი.'),
  ('59e058ca-af20-4537-9c74-8aa7eb175af6', 'მიეცით ემოციებს გასაქანი 📝', 'საღამოს აიღეთ ყავა და განწყობის დღიურში მცირე ჩანაწერი გააკეთეთ — შეადარეთ თქვენი ახლანდელი გრძნობები გასული თვეების ემოციებს.'),
  ('30a7e68c-862a-436f-a801-8270fce13b90', 'გაუფრთხილდით თავს 🍲', 'თუ თქვენ ჯანმრთელი ხართ, ისიც ჯანმრთელია. ჯანსაღი რეცეპტებიდან შეარჩიეთ მსუბუქი სალათი დედებისთვის, რომელიც 10 წუთში მზადდება, და მიირთვით.'),
  ('32607011-b168-4558-b64b-8c8947e8d9a9', 'თბილი აბაზანა, მასაჟი და ოთახის ჩაბნელება. 🛀', 'ძილის რეჟიმის დაცვა უწყვეტი ღამეების მთავარი საიდუმლოა.'),
  ('ca309c2b-9bd6-47c4-bfb8-da0eb88d4f08', 'სხვადასხვა მარცვალი და სრული წინადადებების წარმოთქმის მცდელობები 🗣️', 'დიდხანს საუბრობს თავის ენაზე, თითქოს სრულ წინადადებებს აწყობდეს. ყურადღებით მოუსმინეთ ოთახის ყველაზე საყვარელ წამყვანს!'),
  ('3908e4ee-6364-4b5e-bf19-9883638e23db', 'ოთახის ხმა 🤫', 'დაძინება გაგიჭირდათ? ხმის საზომით შეამოწმეთ ოთახში დეციბელების დონე და ტელევიზორის ხმა ფონურ დონემდე შეამცირეთ.'),
  ('ce7b77f8-95b5-4071-bf35-61b06d785d85', 'ჩვენ ერთი გუნდი ვართ! 💖', 'რთული დღის შემდეგ პირისპირ დაჯექით თქვენს პარტნიორთან და გულწრფელად ისაუბრეთ. ერთმანეთის მხარდაჭერა ტვირთს ანახევრებს.'),
  ('fab0e5e3-a0d0-40d0-843b-ff548b4b816f', '„მოდი, მოდი“ გუნდი 👏', 'ხელებით „მოდი, მოდი“ მოძრაობა ისწავლა? აუცილებლად გადაიღეთ ეს საყვარელი მიბაძვა ვიდეოზე და თქვენს მოგონებების ალბომში დაამატეთ.'),
  ('0b91a5b0-1518-4473-b0bb-59cec89d7f6f', 'საუბრები უფრო მრავალფეროვანი ხდება! 🗣', '️ „მა-მა“, „ბა-ბა“ მარცვლებით აწყობილი საყვარელი დიალოგები უფრო შემეცნებითი რომ გახადოთ, წაიკითხეთ ბლოგებში მოცემული რჩევები მეტყველების განვითარების შესახებ.'),
  ('ccbd5c11-509e-4b73-9eb1-b2f8b729e5b5', 'რძის გამომუშავების ხელშემწყობი საკვები. 🍲', 'დღესვე სცადეთ ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტების განყოფილებაში მოცემული რძის გამომუშავების ხელშემწყობი სუპები და გაიძლიერეთ ორგანიზმი.'),
  ('db929314-83ca-4372-8890-03ef676e68e5', 'ტირილის შეტევები, რომელთა მიზეზსაც ვერ პოულობთ, ძალას გაცლით. 😭', 'ნუ დაიღლით თავს, გამოიყენეთ ტირილის ანალიზი და გაარკვიეთ პრობლემის მიზეზი.'),
  ('72b7b721-7f37-4054-90fd-05ac29f9ff3c', 'შფოთვის საწინააღმდეგო ხმოვანი თერაპია. 🎶', 'თუ ამ საღამოს თქვენი ბავშვი აღელვებულია, თეთრი ხმებიდან ჩაურთეთ დედის საშვილოსნოს ხმა და მყისიერად დაამშვიდეთ.'),
  ('761f9ba9-87d1-4b16-a40a-f1ec2385a5fd', 'მზადება 10 თვისთვის! 🎂', 'ყურადღება! სულ რაღაც 10 დღეში თქვენი პატარა 10 თვის გახდება! არ დაგავიწყდეთ სპეციალური ტორტის შეკვეთა ორნიშნა თვეებზე გადასვლის აღსანიშნავად!'),
  ('b335cc4c-9dc2-482d-a2f2-b6bcbf3a72f9', 'ზღაპრით დაძინება 🪄', 'ჭკვიან ზღაპრებში შექმენით მამაცი და საყვარელი ცხოველების ამბავი და ოთახი ჯადოსნურ სივრცედ აქციეთ.'),
  ('19eac11a-ecf7-498d-85e1-95d4f484d466', '10 თვემდე 10 დღე დარჩა! 🎈', 'იუბილემდე 10 დღე დარჩა! ბავშვის ფოტოსესიის ხელსაწყოში სპეციალური ჩარჩოები წინასწარ შეარჩიეთ და ყველაფერი დაგეგმეთ.'),
  ('36d1de0a-5eb5-4e0f-98ce-a583a10b254e', 'ამინდმა არ მოგატყუოთ ⛅', 'სასეირნოდ გასვლისას გადაწყვეტილებას მხოლოდ ფანჯრიდან გახედვით ნუ მიიღებთ. ამინდისა და ჩაცმულობის ხელსაწყოთი იპოვეთ ფენებად ჩაცმის ოქროს შუალედი.'),
  ('ea9b5851-8f4a-4a19-990c-97e725808bb5', 'იავნანა მამისგან 👨‍🍼', 'ამაღამ ბავშვის დასაძინებლად ყველა იავნანასა და ზღაპრის წაკითხვა მამას ევალება.'),
  ('14c6187e-df8b-47e8-b44f-9bc87c4b9143', 'ღამის სიჩუმე 🤫', 'თუ მანქანის ან გარედან შემოსული ხმები ბავშვს აწუხებს, ფონად აუცილებლად დატოვეთ უწყვეტი თეთრი ხმაურის წყარო.'),
  ('36c8e54c-04ef-4b47-9a2f-c0754b0990c9', 'ცდა-ცდით სწავლა 🧗‍♂️', 'დივანს ჩაჭიდებული სიარულისას დუნდულებზე ეცემა და ისევ დგება? ასე ის სირთულეების დაძლევას სწავლობს. ნუ შეშინდებით და გაამხნევეთ.'),
  ('c0c6e209-b8c8-4325-bc8e-9d4231949abd', 'კბილების ამოჭრის ტკივილი 🦷', 'ღრძილები ისევ გაუწითლდა და ნერწყვდენა არ წყდება? მოამზადეთ ცივი კბილების საღრღნელები.'),
  ('65f53c0c-e8ea-4257-8798-e79b9ed847be', 'მასაც უნდა ის, რასაც თქვენ მიირთმევთ 🥣', 'თქვენს თეფშზე ყველაფრისკენ ხელს იწვდის? საკვებისადმი ინტერესი პიკზეა. მიეცით პატარა ნაჭრებად დაჭრილი საკვები, რომლის დამოუკიდებლად ჭამასაც შეძლებს.'),
  ('bbfc7848-e7f7-4bfa-a960-a2aeb003f7a4', 'ემოციების დღიური 📝', 'როცა თავს მარტო იგრძნობთ, თქვენი გრძნობები განწყობის დღიურში გადმოიტანეთ. წერა თავს უკეთ გაგრძნობინებთ.'),
  ('d2c3bcc6-5492-42b4-857f-d6ad8a442199', 'განვითარების შემოწმება 🤖', 'დამატებით კვებასთან დაკავშირებით კითხვები გაქვთ? სთხოვეთ Anacan AI-ს ინფორმაცია 9 თვის ბავშვის მენიუს შესახებ.'),
  ('69d7aa9d-fa7f-4594-a0de-a2ff1fbdebb6', 'ჭკვიანი ზღაპრის დრო 🪄', 'ამ საღამოს განსხვავებული ამბავი მოყევით: ჯადოსნური ღრუბელი, რომელსაც დაძინება უყვარს. ხმას დაუწიეთ და შესაბამისი ატმოსფერო შექმენით.'),
  ('ae31e811-95f5-438c-9d8f-7b39b14eed84', 'ნივთების თავის ადგილზე მოთავსების მცდელობა 🧸', 'სათამაშოს ყუთში აგდებს და ისევ იღებს? ასე შიგნით და გარეთ ცნებებს შეისწავლის.'),
  ('ed4bee35-1ea6-4f7f-ba0b-bb5c2bd4f981', 'წყლის სმის ჩვევას ვაყალიბებთ. 💧', 'დამატებით საკვებთან ერთად წყლის შეთავაზებაც არ დაგავიწყდეთ. რეკომენდებულ პროდუქტებში მარტივად იპოვით, რომელი საბავშვო ჭიქაა უფრო შესაფერისი.'),
  ('0b7b3ea8-6539-4606-ac0b-b0428466ace0', 'მიმბაძველი თუთიყუში 🦜', 'თქვენს ხველასა და სიცილს ბაძავს? ამ ოთახში საუკეთესო სარკე თქვენ ხართ. ასწავლეთ მას ყველაზე ლამაზი მიმიკები!'),
  ('380bef16-ec45-4aa3-8cc8-5ea1cf489dc2', 'ენერგიის ბომბი დედებისთვის! 🥗', 'მოუსვენარი ბავშვის დევნას ძალა სჭირდება! ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტებიდან მოამზადეთ ვიტამინებით სავსე სალათა ან სმუზი.'),
  ('a261deac-e213-48df-a6bd-e43793de79c9', 'მამიკოს მასაჟის სალონი 💆‍♀️', 'ბავშვი თქვენმა პარტნიორმა დააძინოს, შემდეგ კი დაჭიმული კისრის კუნთების მოსადუნებლად მხრებზე 5-წუთიანი მასაჟი გაგიკეთოთ!'),
  ('03f6a4bb-fc20-440d-bf19-5a474e3fa7f6', 'დრო საკუთარ თავსაც დაუთმეთ. 🛁', 'სანამ თქვენს შვილს სძინავს, მოუარეთ თმასა და კანს და დაისვენეთ.'),
  ('87dbc3cb-466d-4628-b1df-07cce718a3ab', 'დამოუკიდებლად ჭამა სიამოვნებს! 🥦', 'ბავშვებისთვის, რომლებმაც დამატებითი კვება დაიწყეს, რეცეპტების განყოფილებიდან მოამზადეთ სასარგებლო და ადვილად დასაჭერი საკვები, რომელსაც ხელით შეჭამენ.'),
  ('9b804616-ae80-4d37-b6a9-76004e3e5506', 'მარტივი მითითებები ესმის! 🧠', 'როდესაც ეუბნებით: „ეს მომეცი“, სათამაშოს გაწვდით? გონებრივი განვითარების ამ ნახტომის მხარდასაჭერად წაიკითხეთ ბლოგებში განთავსებული განმავითარებელი სტატიები.'),
  ('dffa4555-16c2-4705-a09e-e04f9ae6d25d', 'საქმეები დაგრჩათ? დარჩეს.  🌪️', 'სთხოვეთ თქვენს პარტნიორს, დღეს საოჯახო საქმეები საკუთარ თავზე აიღოს. თქვენ კი დაისვენეთ.'),
  ('f2c9cd05-6f08-42dc-b88f-310abadaba89', 'ღამის სიმშვიდე 🛀', 'თბილი აბაზანა, მასაჟი და ოთახის ჩაბნელება. ძილის რეჟიმის დაცვა მშვიდი და უწყვეტი ღამეების მთავარი საიდუმლოა.'),
  ('fad6626b-f1fb-4e8d-8e1a-679ccb7c1f85', 'ყველაფერს, რასაც იატაკზე იპოვის, დიდი ინტერესით იკვლევს.  🗑️', 'ნუ წაართმევთ ყველაფერს და ნუ გაბრაზდებით — ის პატარა მკვლევარია. უბრალოდ თვალყური ადევნეთ.'),
  ('3995ea79-4422-4b71-b376-6426966b7d85', 'სუფთა ჰაერი წამალია 🌳', 'მთელი დღე ტიროდა და მოუსვენრად იყო? გამოსავალი ძალიან მარტივია: შეამოწმეთ ამინდი, შესაფერისად ჩააცვით, ჩასვით ეტლში და დაუყოვნებლივ წადით პარკში.'),
  ('b67edfc6-e141-41a3-866c-78583fe5c77b', '10 თვემდე სულ რაღაც 5 დღე დარჩა! 🎂', 'დიდ თარიღამდე სულ ცოტა დარჩა! სწორედ ახლაა დრო, 10 თვის აღსანიშნავი ტორტი და ტანსაცმელი მოამზადოთ. პირველ დაბადების დღეს ნაბიჯ-ნაბიჯ უახლოვდებით!'),
  ('da354848-a7ac-41ba-9616-ccf0b8799a86', 'ძილის ნიშნები 🥱', 'თუ თვალებს ისრესს და ერთ წერტილს გაშტერებით უყურებს, ნუ დაელოდებით, სანამ გაღიზიანდება. დაუყოვნებლივ ჩააბნელეთ ოთახი და ძილის რუტინა დაიწყეთ.'),
  ('049b837c-5a26-4c32-95e4-e745b4a3443b', 'აპროტესტებს და ტირის, როცა რამეს ართმევთ? 🧸', 'მას უვითარდება საკუთრებისა და ინდივიდუალურობის განცდა. ეს სრულიად ბუნებრივი ფსიქოლოგიური ეტაპია.'),
  ('06a37325-84f4-4012-b4a0-ff317ba78e4c', 'ნახვამდის! 👋', 'უკვე ისწავლა ხელის დაქნევა მათთვის, ვინც მიდის? ბავშვის ფოტოსესიით დაუყოვნებლივ შემოინახეთ მისი ეს გააზრებული და საყვარელი ჟესტი სამახსოვროდ.'),
  ('69b02f6b-1a0a-4f09-860a-f56dfb370b0a', 'უსაფრთხოების ზომები სახლში! 🛡', '️ რაც უფრო ხშირად ცდილობს ფეხზე წამოდგომას, მით მეტი საფრთხე ჩნდება. აუცილებლად გაეცანით რეკომენდებული პროდუქტების ჩვენს სიას, სადაც ბავშვისგან დამცავ საკეტებსა და კუთხეების დამცავებს იპოვით.'),
  ('249e422f-5203-4598-a063-3032744aab4c', 'წყლის სმის სიჯიუტე 💧', 'სურს, თავისი ფინჯანი დამოუკიდებლად დაიჭიროს და დალიოს, მაგრამ უმეტესად ზედ ისხამს? შეაქეთ მისი დამოუკიდებლობის მცდელობები — სველი ხელსახოცებიც ხომ სწორედ ამისთვისაა.'),
  ('88ed955b-e80f-4226-9234-7112a99a4951', 'პარტნიორის დამუხტვის დრო 🔋', 'დღის განმავლობაში მთელი ენერგია ბავშვს დაუთმეთ. ამ საღამოს ბავშვთან თქვენი პარტნიორი დატოვეთ, თავად კი ოფლაინ რეჟიმში გადადით.'),
  ('d2dfb95a-94ec-43c1-97da-20aed6c6d0bb', 'პირველი წამები საყრდენის გარეშე 🧗‍♂️', 'დივანზე დაყრდნობით დგომისას მოულოდნელად ხელებს უშვებს? ის წონასწორობის შენარჩუნებას სწავლობს! ამ ხანმოკლე, მაგრამ ამაღელვებელ წამებში ყურადღებით დაიცავით დაცემისგან.'),
  ('80ecdccb-340a-49ab-94a9-ff073855c0a0', 'რა მოვუმზადო? 🍲', 'დამატებითი კვების მენიუს იდეები გამოგელიათ? ინტერნეტში ძებნით ნუ დაიკარგებით. სთხოვეთ Anacan AI-ს, 10 თვის ბავშვისთვის მარტივი ხელით საჭმელი პროდუქტების სია შეგიდგინოთ.'),
  ('b8e6e605-baf6-44b6-9e44-842e0b7a0af0', 'საუბარში ერთვება 🗣️', 'როცა ტელეფონზე საუბრობთ, ისიც თავის ენაზე რაღაცას ამბობს და ხმას უწევს? მისი კომუნიკაციის უნარი სწრაფად ვითარდება — ოთახში უკვე მეორე მოსაუბრე გყავთ!'),
  ('c9db13f9-8aff-4b71-a7fa-bdce47336917', 'უეცრად ყვირილით გაიღვიძა? 😭', 'შესაძლოა, ღამის შიშები დაეწყო. მისი ხმა ტირილის ანალიზის ფუნქციას მოასმენინეთ და გაარკვიეთ, პრობლემა ფიზიკურია თუ ფსიქოლოგიური.'),
  ('7a757f5f-8810-4a3e-a344-a9b3d9a89548', 'შია თუ დაიღალა? 😭', 'თუ ბავშვი უმიზეზოდ ტირის, ნუ დაიბნევით. გამოიყენეთ ტირილის ანალიზის ფუნქცია, რათა სწრაფად იპოვოთ პრობლემის მიზეზი და მოაგვაროთ ის.'),
  ('cc7b8905-a439-46c1-8d92-ea81667052be', 'მამისგან ნუგეში 🫂', 'ღამით ბავშვის გაღვიძებისას რიგრიგობით ადექით — ერთხელ თქვენ, ერთხელ თქვენი პარტნიორი. გუნდურად მოქმედებით ტვირთი თანაბრად გაინაწილეთ.'),
  ('df82eb33-3f1e-407f-b436-e4b5c122a87e', '300-დღიანი სიხარული! 🌟', 'ხვალ დიდი, ორმაგი იუბილეა! 10 თვეც და 300 დღეც! სახლში პატარა სადღესასწაულო განწყობა შექმენით და ტელეფონის მეხსიერება გაათავისუფლეთ.'),
  ('19b97cb2-c4a1-4649-a316-a7b34bb3eed4', 'რამხელა გზა გაიარა თქვენმა ბავშვმა!  📈', 'პირველი დღეების მღელვარება თავდაჯერებამ ჩაანაცვლა. თქვენ ეს გზა დიდი გამარჯვებით გაიარეთ — შესანიშნავი ხართ!'),
  ('1d119442-bc5b-4f46-a607-68533220e425', 'შეკითხვა გაქვთ? 🤖', 'თუ ბავშვის განვითარებასთან დაკავშირებული რომელიმე საკითხი გაწუხებთ, ღამის საათებშიც კი ჰკითხეთ ჩვენს Anacan AI ასისტენტს და მიიღეთ სპეციალისტის მხარდაჭერა.'),
  ('dd2f968e-d28b-4ab1-9758-59cda94c35f6', 'შესანიშნავი 10 თვე და 300 დღე! 🎉', 'გილოცავთ! უკვე ზუსტად 300 დღეა, მთელი 10 თვეა, რაც ამ სასწაულს ზრდით.'),
  ('63090d6e-b5fb-4db8-bce4-2e5749468a34', 'წიგნებისადმი ინტერესი 📖', 'საღამოს რუტინაში ბეჭდური წიგნებიც ჩართეთ. ბავშვი უკვე ცდილობს, გვერდები თავად გადაფურცლოს. თქვენი ხმის ტონი ზღაპრის ტემპს მოარგეთ.'),
  ('64ab60a5-a744-4f7e-a8a1-28b04eede9d6', 'საჭმლის კოშკი ჩამოინგრა 🥣', 'სკამიდან კოვზს ან საჭმელს განზრახ აგდებს და შემდეგ თქვენ გიყურებთ? ის საზღვრებსა და მიზიდულობის ძალას ამოწმებს. მოთმინება შეინარჩუნეთ.'),
  ('cd288f90-d6da-4851-9b9a-2a8e15ba81fb', 'თქვენი ცვალებადი სხეული 👗', 'სარკეში თქვენი სხეულის ფორმებს უყურებთ და გული გწყდებათ? ამ სხეულით ადამიანი შექმენით. განწყობის დღიურში საკუთარ თავს მადლობის წერილი დაუწერეთ.'),
  ('0e1a794c-f019-4037-b108-0a10db7b5f9f', 'ჩუმი გმირი 🤫', 'როგორც კი ბავშვი დაიძინებს, სახლში ყოველი ხმა ბომბის აფეთქებასავით ისმის. ხმის საზომით ოთახში დასაშვებ ზღვარს რომ დაადგენთ, თავადაც მსუბუქად იარეთ.'),
  ('cb2d76e0-4e92-41f1-9153-3b4a29404a17', 'კარადის დეტექტივი 🕵️‍♀️', 'სამზარეულოში ყველა ქვაბი იატაკზეა? მიეცით საშუალება, უსაფრთხო ნივთებით ითამაშოს — ეს მის ლოგიკურ აზროვნებას ავითარებს. უბრალოდ ბასრი საგნები მოაშორეთ.'),
  ('d194240e-ae66-4f32-83ef-39ade449ccb6', 'დედების გულახდილი საუბარი 💬', '„ჩემი ბავშვი ჯერ კიდევ რატომ არ ხოხავს?“ — მსგავსი კითხვები მოსვენებას არ გაძლევთ? დაწერეთ Anacan-ის საზოგადოებაში. დაინახავთ, რომ ყველა ბავშვს განვითარების საკუთარი, იდეალური ტემპი აქვს.'),
  ('12c2a250-54bd-4e0d-a366-20c820596148', 'სწრაფი პედიატრი 🤖', 'ბავშვს სხეულზე მცირე სიწითლეები აქვს? ექიმთან მისვლამდე Anacan AI-ისგან სწრაფად მიიღეთ ინფორმაცია კვებითი ალერგიის ნიშნების შესახებ.'),
  ('7b4d66d9-a24a-47b0-a1dd-7047f05e45ec', 'თავის სახელზე რეაგირება 🗣️', 'როცა ეძახით, არა მხოლოდ გიყურებთ, არამედ თავის საქმესაც წყვეტს და თქვენკენ მოსვლას ცდილობს.'),
  ('c7423d2f-6f9f-452c-9de2-5dea29b29f93', 'შეამცირეთ განათება 🌙', 'დაძინებამდე 1 საათით ადრე სახლში ყველა კაშკაშა შუქი და ეკრანი გამორთეთ. მელატონინი მხოლოდ მშვიდ და სუსტად განათებულ გარემოში გამოიყოფა.'),
  ('100bd53c-84e3-4c7e-8a31-2a287a02c440', 'თავი დანაშაულის გრძნობისგან გაითავისუფლეთ 📝', 'ფიქრობთ, რომ დღეს მასთან ცოტა ითამაშეთ? ხარისხიანად გატარებული 10 წუთი დაღლილ მდგომარეობაში გატარებულ 1 საათზე უფრო ღირებულია.'),
  ('42ea49cf-0e72-4699-aaf4-7633e9ea6a82', 'კადრი, რომელიც დროს აჩერებს 📸', 'ის ყოველდღე უფრო მეტად ემსგავსება მოზრდილ ბავშვს, ჩვილობის ნაკვთები კი თანდათან ქრება. ახლავე გახსენით ბავშვის ფოტოსესია და აღბეჭდეთ ეს ცვლილება.'),
  ('a0c5dfe0-02f0-4961-8b06-219cd57dde9d', 'პირველი ნიშნები 11 თვისკენ! 🎈', 'ყურადღება! სულ რაღაც 20 დღეში 11 თვის გახდება და 1 წლის იუბილემდე დიდ უკუთვლას დავიწყებთ. გაიღიმეთ!'),
  ('29cc3dd1-d28b-45c9-93d7-58bfda48629c', 'საჩვენებელი თითი გააქტიურდა ☝️', 'შორს მყოფ კატაზე ან სათამაშოზე თითით მიგითითებთ და რეაგირებს. ეს ყურადღების მიმართვის უმაღლესი ეტაპია.'),
  ('6eab5294-c731-4890-971d-ad01e35f7d7c', 'პარკი თუ სახლი? ⛅', 'გარეთ გასვლა გსურთ, მაგრამ ქარია. ამინდისა და ჩაცმულობის დამხმარე გეტყვით არა მხოლოდ ტემპერატურას, არამედ იმასაც, რა ქარგაუმტარი ტანსაცმელი ჩააცვათ ბავშვს.'),
  ('edfb2fd4-70c3-4b15-b2d1-0fc891b31501', 'მამის სასაცილო სახეები 🤡', 'ბავშვის გასაცინებლად საუკეთესო გზა მამის უცნაური ხმებია. ამ საღამოს მხიარული წუთები ბავშვის ფოტოსესიით სამუდამოდ აღბეჭდეთ.'),
  ('9b064bbe-67b8-4d62-b3a0-30f79dc81515', 'დედასთან ყოფნის დაჟინებული სურვილი 🥰', 'ტუალეტში შესვლის დროსაც კი კარს მიღმა გელოდებათ და ტირის. განშორების შფოთვამ პიკს მიაღწია. ყოველ ჯერზე უთხარით: „მე აქ ვარ“ — და თავი უსაფრთხოდ აგრძნობინეთ.'),
  ('e77deeee-d612-4dac-bea4-ec9f16608958', 'დღეს ჭკვიან ზღაპარში 🪄', 'ჭკვიან ზღაპრებში შექმენით განსაკუთრებული ამბავი, რომლის მთავარი გმირიც თქვენი შვილი იქნება: პატარა, რომელიც დღისით იღლება, ღამით კი ვარსკვლავებისკენ მიფრინავს.'),
  ('f0ba97cb-8dd2-4486-865e-1d22a5e551a6', 'სია თქვენს ჯიბეში 🛒', 'ხილის პიურეს მოსამზადებლად ვაშლი აღარ გაქვთ? სიის შედგენა თქვენს პარტნიორს მიანდეთ. ჩაამატეთ საყიდლების სიაში, მაღაზიაში წასვლა კი მისი საქმეა.'),
  ('26bb2530-b202-43eb-9226-30863365843e', 'ვაკვირდებით საჭმლის მონელების პროცესს. 🧷', 'სხვადასხვა მყარი საკვები განავლის გამოყოფას ცვლის. Anacan-ში საფენის ყოველი გამოცვლის აღნიშვნით აკონტროლეთ თქვენი ბავშვის ჯანმრთელობა.'),
  ('32966fee-53d4-4975-ad1e-195457a2fa5c', 'რთული ღამეები 🥱', 'მთელი ძალით ეწინააღმდეგება დაძინებას? შესაძლოა, დღის ერთ-ერთი ძილის ამოღების დრო დადგა. გადახედეთ დღის რეჟიმს.'),
  ('b5660557-30c8-45a9-9c75-69616076d9ce', 'სივრცე დედისთვის ☕', 'სახლში ყოფნამ ენერგია გამოგაცალათ. დედებისთვის მეგობრულ სივრცეებს შორის შეარჩიეთ კაფე, სადაც საბავშვო მენიუ და კომფორტული დასაჯდომი ადგილებია, და საკუთარ თავს დრო დაუთმეთ.'),
  ('221ab24d-c8af-4cca-b9d8-b4eae15499d0', 'შეაქეთ საკუთარი თავი 👏', 'ოთახის უწესრიგობას კი ნუ შეხედავთ, არამედ იმას, თუ როგორი ბედნიერია ის დღეს. თქვენ შესანიშნავი დედა ხართ — ისეთი, როგორად ყოფნასაც ვერცერთი წიგნი ვერ გასწავლით.'),
  ('cdf44716-8a24-472d-9ff5-449bcc14a7fe', 'სხეული, რომელიც მუსიკაზე ცეკვავს 🎶', 'როგორც კი ტელევიზორში ან ტელეფონში რიტმულ ხმას გაიგონებს, მაშინვე თეძოების რხევას იწყებს. მუსიკის აღქმის უნარი აქტიურდება — შეუერთდით და მასთან ერთად იცეკვეთ!'),
  ('d3e69c0c-c087-4266-8819-3e9aa9fc132a', 'მასაჟის დროა 💆‍♂️', 'ბავშვის დაძინების შემდეგ, დღის სტრესის მოსახსნელად, პარტნიორთან ერთად მოაწყვეთ მხრების მასაჟის სეანსი. თქვენ ერთი გუნდი ხართ!'),
  ('33fb356d-029a-4c8c-bf0d-4b2ad8ed6777', 'ზღაპრით ძილისთვის მომზადება 🪄', 'ჭკვიან ზღაპრებში შექმენით სპეციალური ფონი, რომელიც მხოლოდ მუსიკისა და ბუნების ხმებისგან შედგება. სიტყვების გარეშე — მხოლოდ სიმშვიდე.'),
  ('3e6ba90a-e6bd-4527-a0cb-94dcb9fecfac', 'პარკთან დამეგობრება 🌳', 'საბავშვო ეტლით სეირნობა მოსაწყენად ეჩვენება? შეამოწმეთ ამინდი და ბავშვის ტანსაცმელი, შემდეგ კი პარკში თავისუფლად მიუშვით, რომ ბალახსა და ფოთლებს შეეხოს.'),
  ('d3bac322-3971-4b22-8636-d789ac7ce8db', 'კედელზე ხელის მოკიდებით დადის 🧗‍♀️', 'ავეჯის კიდეზე ხელის მოკიდებით გვერდულად სიარული მისი საყვარელი ვარჯიშია. სწორედ ახლაა დრო, კიდევ ერთხელ შეამოწმოთ უსაფრთხოების დამცავები და ბასრი კუთხეები.'),
  ('6498b35b-aa8e-416f-9da1-2596c74b14d0', 'ნახვამდის ვეუბნებით 👋', 'როცა ვინმე კარიდან გადის, ბავშვი საკუთარი ინიციატივით ხელს უქნევს და ემშვიდობება! შესანიშნავი სოციალური რეფლექსია.'),
  ('b49f5612-c3e4-4568-8a0e-3494499a88d1', 'შუაღამისას უმიზეზო და შეუჩერებელი ტირილით გაიღვიძა? 😭', 'მშვიდად ჩაიხუტეთ და ნუ ეცდებით მის გაღვიძებას. ხმა ტირილის ანალიზის ფუნქციას მოასმენინეთ, რომ მიზეზში დარწმუნდეთ.'),
  ('fd05df6d-36c8-4c59-9212-7542837f9f4c', 'გულახდილი საუბარი გჭირდებათ 💬', 'გაწუხებთ აზრი, რომ ძველებური თქვენ ვეღარასოდეს იქნებით? გაუზიარეთ ეს დროებითი განცდა Anacan-ის საზოგადოებაში მყოფ დედებს — მარტო არ ხართ.'),
  ('6032f94e-69e7-4802-b291-44567c9f71d1', 'მამის იავნანა 👨‍🍼', 'ამ საღამოს ოთახში ბავშვის დამოუკიდებლად დაძინების გამოცდა თქვენმა პარტნიორმა უნდა გაიაროს.'),
  ('7b460d4a-b37e-465f-9c70-e137f59bcc07', 'დალაგება თუ დასვენება? 🛋️', 'როცა ბავშვს სძინავს, ჭურჭლის სარეცხი მანქანისკენ ნუ გაიქცევით. წამოწექით დივანზე, დახუჭეთ თვალები და 15 წუთის განმავლობაში უბრალოდ ისუნთქეთ. რობოტი ხომ არ ხართ? არა.'),
  ('a1392cb5-508d-45a8-9d3d-1985c8d19958', '„არას“ ბრძოლა იწყება 🛑', 'ახლა, როცა ისეთ რამეს აძლევთ, რაც არ მოსწონს, თავს აქნევს და ხელს ჰკრავს. მისი ნებისყოფა ყალიბდება. ეცადეთ, პატივი სცეთ მის პატარა გადაწყვეტილებებს.'),
  ('2cc5ac97-f2b1-4c92-8852-fec32f54b311', 'ხმის კონტროლი 🤫', 'ჩაძინებიდან პირველი ნახევარი საათი ყველაზე მგრძნობიარე პერიოდია. ხმაურის საზომით შეამოწმეთ გარემო და მოერიდეთ მოულოდნელ ხმაურს.'),
  ('e0b42cd5-f681-4866-a7ec-b0b890444381', 'ჯანმრთელი დედა, ჯანმრთელი ბავშვი 🥑', 'თქვენი რკინისა და კალციუმის მარაგი ამოწურულია. ჯანსაღი რეცეპტებიდან მოამზადეთ სწრაფი, ენერგიით სავსე სალათა, რომელიც ძალების შენარჩუნებაში დაგეხმარებათ.'),
  ('e83a5069-7214-47ea-9051-6406495d5723', '„მომეცი ჩემი სათამაშო!“ — სიჯიუტე 🧸', 'როცა ხელიდან რაიმეს ართმევთ, მწვავედ რეაგირებს და ტირის. საკუთრების განცდა უკვე სრულად უყალიბდება. აკრძალვის ნაცვლად, ეცადეთ, ყურადღება სხვა რამეზე გადაატანინოთ.'),
  ('188836b2-55a8-4b14-87fe-653f4e05ae3e', 'დღეს ყველაფერმა გაგაღიზიანათ?', 'როცა ბავშვი დაიძინებს, განწყობის დღიურში ჩაწერეთ თქვენი გრძნობები. ხვალ ახალი და უკეთესი დღე იქნება.'),
  ('4d566d24-14b9-45b0-be5d-1940c1563ed9', 'სწრაფი საყიდლები 🛒', 'თქვენი პარტნიორი სამსახურიდან გამოდის? დაუყოვნებლივ გახსენით საყიდლების სია და რძე, ხილი თუ სახლში საჭირო სხვა პროდუქტები წამებში გაუგზავნეთ.'),
  ('fd0252a6-07bf-4750-bd4b-be91888e16f6', 'უფროსების მიბაძვა 🧹', 'სახლს რომ ასუფთავებთ, ისიც იღებს ტილოს და ცდილობს, იგივე გააკეთოს? ის თქვენი სარკეა! ყველაფერს იმეორებს, რასაც თქვენ აკეთებთ.'),
  ('a789d8f9-cc5b-43fd-8931-a3c5dbb78c75', 'გუნდური მხარდაჭერა 🥂', 'მთელი დღის დაღლილობის მოსახსნელად პარტნიორთან ერთად ჩაი დალიეთ და ერთმანეთს უთხარით: „დღესაც შევძელით“.'),
  ('ac527e8b-ca16-4272-b6ba-964f15ba419b', 'პედიატრიული კითხვები 🤖', 'რა მოცულობის უნდა იყოს 10 თვის ბავშვის ულუფა? თავს ნუ დაიღლით — Anacan AI-ს ზუსტი, პედიატრის მიერ დამტკიცებული ცხრილი სთხოვეთ.'),
  ('e38208ca-c817-4de4-ba96-5a5ca4752901', 'ღრძილების ქავილი გრძელდება 🦷', 'თითები სულ პირში აქვს და ყველაფერს ღრღნის? შესაძლოა, უკანა კბილები ამოსდის. კბილების ამოჭრის ტრეკერში მისი მდგომარეობა აღრიცხეთ.'),
  ('0535564e-f2c8-4264-bd71-a94e3154d928', 'ამინდის დაზვერვა ⛅', 'გარეთ ამინდი ბოლომდე ნათელი არ არის? ამინდისა და ჩაცმულობის ხელსაწყო მყისიერად გეტყვით ქარის სიჩქარეს, რომელიც ფანჯრიდან არ ჩანს, და სწორ ჩაცმულობას შეგირჩევთ.'),
  ('51cec612-e243-435d-9b60-1e3269d69cee', 'მუსიკალური საღამოები 🎶', 'საღამოს დაწყებული ჭირვეულობის დასამშვიდებლად ყველაზე მარტივი გზაა, ჩაურთოთ ბავშვს საყვარელი სიმღერა, ჩაიხუტოთ და მასთან ერთად იცეკვოთ.'),
  ('533a4ec1-68c0-4cf3-92cd-723b3f8c0979', 'ფეხსაცმელს თავად იხდის 👟', 'ჩაცმა უკვე ჭიდაობას დაემსგავსა? ბავშვი წინდებსა და ფეხსაცმელს თავად იქაჩავს და იხდის. აღფრთოვანდით მისი მოტორული უნარებით!'),
  ('7bbccad8-a83a-493c-82e1-d823d261e04b', 'ლოგიკური თამაშები 🧩', 'ბავშვი სათამაშოებს ყუთში ყრის, შემდეგ კი ყველას გარეთ გადმოყრის? ასე ის „შიგნით“ და „გარეთ“ ცნებებს ითვისებს და ლოგიკურ აზროვნებას ავითარებს. ხელს ნუ შეუშლით.'),
  ('84cdedf9-5de5-49c9-887b-6f8ccc988990', 'მამის ღამის მორიგეობა 👨‍🍼', 'ღამით გაღვიძებასთან გამკლავება მხოლოდ საკუთარ თავზე ნუ აიღებთ. გააღვიძეთ პარტნიორიც — გუნდურობა პასუხისმგებლობის თანაბრად განაწილებას ნიშნავს.'),
  ('a4c45285-b9cc-4763-a80c-d694137bbb6a', 'დედებისთვის შესაფერისი ადგილების აღმოჩენა ☕', 'ამდენი დაღლილობის ფონზე თქვენც გჭირდებათ განტვირთვა. დედებისთვის შესაფერის ადგილებს შორის იპოვეთ ახლომდებარე მშვიდი კაფე და ეწვიეთ.'),
  ('37e8bf23-2dc4-4b8c-8c8f-49146922ba57', 'ცდა და შეცდომა 🧱', 'ბავშვი ცდილობს, სათამაშო ორი კუბი ერთმანეთზე დააწყოს, თუმცა ისინი ცვივა. შემდეგ ყურადღებით თავიდან ცდილობს. ჩუმად დააკვირდით მის ამ პატარა საინჟინრო მცდელობებს.'),
  ('732cb07a-0e5f-4dc9-9d15-78470db05396', 'კერძების იდეები 🍲', 'ერთი და იმავეს მომზადება მოგბეზრდათ? ჯანსაღ რეცეპტებში აღმოაჩინეთ ახალი და გემრიელი ხელით საჭმელი 10 თვის ბავშვებისთვის.'),
  ('a387d51e-9e9d-455a-be61-4650ee6ffa63', 'მშვიდი ოთახი, მშვიდი გონება 🤫', 'ძილისთვის მომზადებისას ოთახში ხმაურის დონე შეამცირეთ. ხმის საზომით შეამოწმეთ თქვენი ხმისა და გარემოს ხმაურის დონე.'),
  ('439ac8e3-ab5f-434a-bb69-d98dee8208cd', 'პერსონალური ზღაპარი 🪄', 'ჭკვიან ზღაპრებში შექმენით ისტორია გმირზე, რომელიც სულ რაღაც 10 დღეში კიდევ ერთი თვით გაიზრდება, და ოთახი ჯადოსნობით აავსეთ.'),
  ('e8d1cc1f-b4b8-4874-a0cc-8f10d75b5769', '11 თვემდე სულ რაღაც 10 დღე დარჩა! 🎂', 'დაუჯერებელია! ზუსტად 10 დღეში თქვენი პატარა 11 თვის გახდება. უკვე საუკეთესო დროა, მისი 1 წლის დაბადების დღის გეგმებზე ფიქრი დაიწყოთ!'),
  ('ff800946-b6d3-4e88-8699-fe114e37b692', 'ღიმილების ფოტო 📸', 'ის ყოველდღე სულ უფრო გამორჩეული და საყვარელი ადამიანი ხდება. ახლავე გახსენით ბავშვის ფოტოსესია, გააფორმეთ სტიკერებით და ეს მხიარული წამი სამუდამოდ შეინახეთ.'),
  ('16cae145-7589-4ff6-ae2c-368fe115d232', 'ემოციების მართვა 📝', 'ნერვები დაჭიმული გაქვთ და ნებისმიერ წამს შეიძლება აფეთქდეთ? მთელი სტრესი განწყობის დღიურში გადაიტანეთ და ღრმად ჩაისუნთქეთ.'),
  ('9b99e928-dd9a-40d6-9254-12459dac4a3d', 'სიბნელესთან დამეგობრება 🌙', 'იმისთვის, რომ ბავშვს უფრო სწრაფად ჩაეძინოს, საღამოს რუტინაში სიბნელესთან შეგუებაც ჩართეთ. ოთახში ყველა დამატებითი სინათლე გამორთეთ.'),
  ('ee2e2e79-277e-4a7f-9473-05aa36068880', 'სხეულის ნაწილებს ცნობს 👀', 'როდესაც ეკითხებით, „სად არის ცხვირი?“, თითით ეხება და გაჩვენებთ? მისი გონებრივი აღქმა პიკზეა!'),
  ('2cb20f11-aee5-456a-b969-c87733104c72', 'გამარჯვების საღამო 🥂', 'დღეს საღამოს, ბავშვის დაძინების შემდეგ, პარტნიორთან ერთად შესვით სადღეგრძელო: „ჩვენ შესანიშნავი გუნდი ვართ“. თქვენ მართლაც შესანიშნავად ართმევთ თავს!'),
  ('57b926b9-28cb-4c4e-8863-8ce72241c9fe', 'ალერგიაზე ეჭვი 🤖', 'ბავშვს ახალი საკვები მიეცით და ლოყებზე სიწითლე შენიშნეთ? სანამ შეშინდებით, პირველი ნაბიჯების შესახებ Anacan AI-ს ჰკითხეთ.'),
  ('9c11d140-acfd-48e4-9fef-141a9e34586d', '„მე თვითონ შევჭამ!“ 🥦', 'კოვზის თქვენი ხელიდან წართმევა სურს. მიეცით საშუალება, აიღოს. ტანსაცმელს დაისვრის, მაგრამ დამოუკიდებლობის ეს განცდა მისთვის ძალიან მნიშვნელოვანია.'),
  ('7fd53d22-26ef-4c4c-83bb-d44647b94560', 'ერთად გადავჭრათ 💬', 'დაიღალეთ კითხვით: „რატომ იქცევა ჩემი ბავშვი ასე?“ შეუერთდით Anacan-ის საზოგადოებას და ნახეთ, რომ ათასობით ოჯახშიც ზუსტად იგივე ხდება!'),
  ('a6ef3f7c-7550-4712-8fc9-23c742a51744', 'ძილისთვის მომზადება 🛀', 'თბილი აბაზანა ყოველთვის ეფექტურია. არასოდეს დაარღვიოთ საღამოს რუტინა, რადგან ის ბავშვის ტვინს მიანიშნებს, რომ ძილის დროა.'),
  ('d6154f3b-6df3-4af3-97e7-fdfd798b8cfb', 'ცდითა და შეცდომებით სწავლა 🧗‍♂️', 'ფეხზე დგომისას დუნდულებზე ეცემა, იცინის და ისევ დგება. ასეთი დაცემები კუნთოვან მეხსიერებას ავითარებს, ამიტომ ზედმეტად ნუ ჩაერევით.'),
  ('25903ac8-0fd6-44f0-92d8-c3e1bee035e5', 'სიჩუმის საჭიროება 🤫', 'ჩაძინებისას უმცირესი ხმაურიც აღვიძებს? ხმაურის საზომით შეაფასეთ გარემო და უზრუნველყავით უწყვეტი სიჩუმე.'),
  ('3a5c700f-e10c-4819-bba1-cddd9f951f4f', 'სიები და გულმავიწყობა 🛒', 'გონების დაბინდვა არ გტოვებთ? სახლისთვის საჭირო წვრილმანების დამახსოვრებაზე ნუ იდარდებთ — დაუყოვნებლივ დაამატეთ ისინი საყიდლების სიაში და დანარჩენი თქვენს პარტნიორს მიანდეთ.'),
  ('47b342b1-9525-44b6-b917-2eb642240cb2', 'ჩახუტება „მიყვარხარ“ 🫂', 'უეცრად მოდის, კისერზე გეხვევათ ან სახეზე გეფერებათ? ის უკვე ფიზიკურად გამოხატავს თავის სიყვარულს. დატკბით ამ მომენტით.'),
  ('09817e37-4e65-43f6-968c-dd333358e01e', 'საჭირო ნივთების სია არ ილევა 🛒', 'ყოველდღიურ ქაოსში შამპუნი გაგითავდათ თუ საფენები? ყველაფრის დამახსოვრებას ნუ ეცდებით — ჩაწერეთ საყიდლების სიაში და გაუზიარეთ პარტნიორს სინქრონულად.'),
  ('1f244347-1957-4238-988d-4563adba7bcd', 'მამის ღამის მორიგეობა 👨‍🍼', 'დღისით დაღლაც საკმარისია თქვენთვის. საღამოს ბავშვის დასაძინებლად მომზადება და ზღაპრის წაკითხვა მხოლოდ მამის მოვალეობაა.'),
  ('9f618083-9332-44d7-8a8f-8ad3af6c22ac', 'სახლში ყველაფერი სათამაშოა 🥄', 'პლასტმასის ჭურჭელი და ხის კოვზები მისთვის ყველაზე ძვირადღირებულ სათამაშოზეც კი საინტერესოა. მიეცით საშუალება, თავისუფლად შეისწავლოს სამზარეულოს ნივთები.'),
  ('354e039c-3978-4aa3-a008-1a3a7bbe85a3', 'ტირილის ანალიზი დაგეხმარებათ 😭', 'შუაღამისას გაიღვიძა და ვერ მშვიდდება? შეწყვიტეთ მიზეზის გამოცნობა — ტირილის ანალიზის დახმარებით ის მაშინვე დაადგინეთ.'),
  ('8fb53566-815d-4365-b87c-c14288ebb122', 'სუფთა ჰაერი ნამდვილი ხსნაა 🌳', 'თუ სახლში ვითარება იძაბება, შეამოწმეთ ამინდი და ბავშვის ტანსაცმელი, ჩასვით ეტლში და დაუყოვნებლივ წადით პარკში. ბუნებაში გასეირნება მისი დამშვიდების ყველაზე სწრაფი გზაა.'),
  ('c87df5f1-fbe2-4462-a617-a6649445ce77', 'ჭირვეულობა პიკს აღწევს ☁️', 'ვერაფრით ასიამოვნებთ და ყველაფერზე ტირის? მიზეზი შეიძლება ზრდის ნახტომი ან კბილების ამოჭრით გამოწვეული დისკომფორტი იყოს. უბრალოდ ხშირად და მაგრად ჩაეხუტეთ.'),
  ('361e96e8-a6ed-4fdf-a7bb-50e07abcec66', 'ღამის სიმშვიდე 🪄', '„გონიერ ზღაპრებში“ შექმენით მამაცი და საყვარელი ცხოველების ამბავი და ოთახი ჯადოსნურ ადგილად აქციეთ.'),
  ('a4baaa67-c9fb-4208-aab7-e7515b21f64f', 'ყველაფერს აკეთებთ, რომ ბავშვი დაანაყროთ. თქვენზე ვინ იზრუნებს?', 'ჯანსაღი რეცეპტების განყოფილებიდან შეარჩიეთ რკინითა და ცილებით მდიდარი სადილი და ძალები მოიკრიბეთ.'),
  ('c58c8b30-4c95-4f60-98d7-d9580eb48a38', 'წიგნის გვერდები იფურცლება 📖', 'სქელგვერდიანი წიგნის ფურცლებს უკვე სრულიად დამოუკიდებლად შლის? განვითარების ტრეკერში აღნიშნეთ ეს მოტორული უნარების გამარჯვება.'),
  ('2631ed9f-967a-4f12-9097-1f619f7f1e5f', 'დღეს არაფერი წავიდა გეგმის მიხედვით?', 'როცა ბავშვს ჩაეძინება, თავს ნუ დაიდანაშაულებთ. თქვენ ნამდვილი დედა ხართ და სწორედ ასეთი ხართ სრულყოფილი.'),
  ('34415812-3e31-43f2-99de-a1dd76bb1d9e', 'მიზანში სროლა ⚾', 'ცდილობს, ხელში დაჭერილი სათამაშო განზრახ ისროლოს კონკრეტული სამიზნისკენ. თვალისა და ხელის კოორდინაცია სწრაფად ვითარდება.'),
  ('ec7ed8d1-bb0f-4b34-a7a5-da3857dfd5d4', 'სწრაფი პედიატრი 🤖', 'რამდენ ხანს უნდა ეძინოს დღისით 11 თვის ბავშვს? ყველაფერი, რაშიც ეჭვი გეპარებათ, დაუყოვნებლივ ჰკითხეთ Anacan AI-ს და დამშვიდდით.'),
  ('78c638dd-68ed-4cf9-acf9-6738b0e5ec7f', 'სახიფათო ზონებზე წვდომა ⚡', 'ბავშვი კიდევ უფრო გაიზარდა და ახლა იმ თაროებსაც სწვდება, რომლებსაც ადრე ვერ წვდებოდა. კიდევ ერთხელ შეამოწმეთ სახლის უსაფრთხოება (ბასრი კუთხეები, მძიმე ნივთები).'),
  ('8a4a7da2-606f-4fbb-8668-101f2d47c03c', 'მუსიკის ძალა 🎶', 'სცადეთ, საღამოობით უმიზეზოდ ატეხილი ჭირვეულობა მსუბუქი კლასიკური მუსიკით დაამშვიდოთ. ხშირად ეს მარტივი ხერხი სასწაულებს ახდენს.'),
  ('a70ebacf-44d0-4367-babf-09742bda8fa8', 'პირველი დაბადების დღის ფუსფუსი იწყება! 🎈', '11 თვე უკვე გავიდა. სულ რაღაც 30 დღეში პირველი დაბადების დღეა! თემატური წვეულება, სპეციალური სივრცე თუ უბრალოდ სახლში აღნიშვნა? ნელ-ნელა დაიწყეთ დაგეგმვა.'),
  ('0387bc9b-1c64-4eae-ac49-660cb56552f8', 'ჩემს სათამაშოს თავად ვპოულობ 🧸', 'ბავშვი მიდის და პოულობს სათამაშოს იქ, სადაც მისი თვალთახედვიდან მოშორების შემდეგ დამალეთ? ეს ნიშნავს, რომ მას უკვე სრულად ესმის საგნის მუდმივობა!'),
  ('6b5c2e80-bfa3-452b-805d-82d54c6b5d2d', 'მამის ღამის მორიგეობა 👨‍🍼', 'ღამით ბავშვის გაღვიძებებთან გამკლავება მთლიანად საკუთარ თავზე ნუ აიღებთ. გააღვიძეთ თქვენი პარტნიორიც — გუნდურობა პასუხისმგებლობის თანაბრად განაწილებას ნიშნავს.'),
  ('89a2b668-b451-4cfe-a183-3183fc159297', 'მიეცით გრძნობებს თავისუფლება 📝', 'ბავშვის 1 წლის იუბილეს მოახლოებასთან ერთად უცნაური სევდა და განცდა ხომ არ გეუფლებათ, რომ ის ძალიან სწრაფად გაიზარდა? ჩაიწერეთ ეს გრძნობები განწყობის დღიურში.'),
  ('932e2f32-ffee-4b5c-9d10-16c135453b42', 'ხვალ დიდი დღეა! 🎉', 'მზად ხართ? ხვალ ბავშვს ზუსტად 11 თვე უსრულდება! 1 წლის იუბილემდე მხოლოდ 1 თვე დარჩა! ბავშვის ფოტოსესიისთვის განსხვავებული კუთხე და სამოსი მოამზადეთ.'),
  ('aac354e5-8061-403a-8cf7-d00ce05e4093', 'ერთობის სულისკვეთება 🥂', 'გახსენით განწყობის დღიური, გაიხსენეთ პარტნიორთან ერთად პირველი დღეები და გულიანად გაიცინეთ. ამ 11 თვემდე იოლად არ მოსულხართ!'),
  ('d24d332c-e00e-4b7f-8dac-28439e172c26', 'დედის შესვენება ყავისთვის ☕', 'ოთახში არეულობა არსად გაიქცევა, თქვენი ენერგია კი შეიძლება ამოიწუროს. როცა ბავშვი დამოუკიდებლად თამაშობს, მაშინვე საქმეების კეთებას ნუ შეუდგებით. ჩამოჯექით და ყავა მიირთვით.'),
  ('6ef8817b-2854-4da4-969a-fe13d344017a', 'გამარჯვების ცეკვა 💖', 'დღეს საღამოს პარტნიორთან ერთად აღნიშნეთ ამ 11 თვის დაღლილობაც და სიამაყეც. 1 წლის იუბილემდე ფინალურ ეტაპზე ხართ!'),
  ('8c48dfb8-f3cc-4402-82d4-4c81ed9fc15b', 'დედის რძე კვლავ მთავარია! 🍼', '1 წლამდე დედის რძე მნიშვნელოვანია. ჩართეთ კვების ტაიმერი და დარწმუნდით, რომ ბავშვის რძის ყოველდღიური საჭიროება დაკმაყოფილებულია.'),
  ('ad9c3e79-16bb-44a7-9f37-6f5935a4494c', 'ზუსტად 11 თვის! 🎂', 'გილოცავთ! მშობიარობიდან ზუსტად 11 თვე გავიდა! ახლავე აირჩიეთ ბავშვის ფოტოსესიის 11 თვის სტიკერი და ეს სიხარული Anacan-ის საზოგადოებას გაუზიარეთ!'),
  ('23c2a94e-cf0d-4f81-9604-79b4dcfb2460', 'ოთხი კედლიდან გაქცევა ⛅', 'სახლში ყოფნა მოგბეზრდათ? შეამოწმეთ ამინდი, სათანადოდ ჩააცვით და პარკში თავისუფლად მიუშვით, რომ მიწაზე ბალახსა და ფოთლებს შეეხოს.'),
  ('77a8c135-4a26-4877-9f24-fc51c941fb7a', 'ჩაცმისას გეხმარებათ 👕', 'როცა მაისურს აცმევთ, თვითონ იშვერს ხელებს ან ფეხს სწევს? ის თქვენთან თანამშრომლობს. განვითარების მონიტორინგში ეს პატარა დახმარებაც აღნიშნეთ.'),
  ('9df28291-b590-4e7d-a861-feb0732398b2', 'სიბნელესთან დამეგობრება 🌙', 'დაძინების დასაჩქარებლად საღამოს რუტინას სიბნელესთან შეგუებაც დაამატეთ. ოთახში ყველა დამატებითი სინათლე გამორთეთ.'),
  ('72f5aeb4-94f9-40bc-943e-fa87664da32b', 'ფორუმებში ნუ დაიკარგებით 🤖', 'ბავშვის მოძრაობაში რაიმე უცნაური შენიშნეთ? საათობით ნუ ეძებთ პასუხს ინტერნეტში — შეკითხვა პირდაპირ Anacan AI-ს დაუსვით და დამშვიდდით.')
) AS v(id, t, b)
WHERE x.id = v.id;

UPDATE public.mommy_day_notifications AS x SET title_ka = v.t, body_ka = v.b
FROM (VALUES
  ('c8b05bf8-0ed8-4eec-86f7-4cba168167e1'::uuid, 'სიტყვების მნიშვნელობა იცის 🗣️', 'როცა ეუბნებით, ბურთი მოიტანოს, მართლაც მიდის და ბურთს ეძებს. მისი ლექსიკური მარაგი (სიტყვები, რომლებიც ესმის) სწრაფად იზრდება. ესაუბრეთ უფრო რთული წინადადებებით.'),
  ('f8aae6d9-1b70-4333-a55c-1937c871c533', 'ჭკვიანი ზღაპრის დროა🪄', 'ჭკვიან ზღაპრებში შექმენით ისტორია გმირზე, რომელსაც სულ რაღაც 1 თვეში 1 წელი შეუსრულდება. დაე, ღამის სიმყუდროვე მხოლოდ ამ ზღაპარმა დაარღვიოს.'),
  ('0ca61e8f-0ab9-48ea-85e7-af32b2be41a1', 'პირველი დაბადების დღისთვის საჭირო დეკორაციები და ბუშტები?  🛒', 'თავს ნუ გადაიღლით, საყიდლების სიის შედგენა უკვე დაიწყეთ.'),
  ('519cad33-f5e8-4169-8f1d-93f4343568db', 'დაჟინებული მცდელობები 🧗‍♂️', 'სათამაშო ხელში უჭირავს და ავეჯზე დაყრდნობით წამოდგომას ცდილობს. წონასწორობის შენარჩუნების უნარი საოცრად გაუუმჯობესდა. არ ჩაერიოთ და შორიდან დააკვირდით.'),
  ('aa2fb7c9-acf7-4050-9102-4f2927091b95', 'ჩუმი გმირი 🤫', 'როგორც კი დაიძინებს, სახლში ნებისმიერი ხმა ბომბის აფეთქებასავით ისმის. ხმაურის საზომით ოთახში დასაშვები ზღვრის დაყენებისას ეცადეთ, თქვენც უფრო ჩუმად იაროთ.'),
  ('9cba5d69-92c6-472c-bb83-c5522d806018', 'დედების გულახდილი საუბრები 💬', 'ფიქრი „როგორ მოვაწყო დაბადების დღე?“ გღლით? დაწერეთ Anacan-ის საზოგადოებაში და მიიღეთ დედებისგან კრეატიული, ბიუჯეტური იდეები.'),
  ('f558e782-e140-4835-8b11-1d5f01a717bf', 'კადრი, რომელიც დროს აჩერებს 📸', 'ის ყოველდღე უფრო და უფრო ემსგავსება დიდ ბავშვს. ახლავე გახსენით ბავშვის ფოტოსესია და მისი გულწრფელი ცეკვის ეს წამი სამუდამოდ აღბეჭდეთ.'),
  ('f56842a9-3a83-4016-8e93-a096810c45d3', 'ცეკვა და რიტმები 🎶', 'ტელევიზორში ან ტელეფონში რიტმული ხმის გაგონებისთანავე ცეკვას იწყებს? მუსიკის აღქმის უნარი სრულად გააქტიურდა — შეუერთდით და მასთან ერთად იცეკვეთ!'),
  ('357cf8f4-8f26-47ee-9a7b-b3db1bd2898e', 'ჯანმრთელი დედა, ჯანმრთელი ბავშვი 🥑', 'თქვენი რკინისა და კალციუმის მარაგი ამოწურულია. ჯანსაღი რეცეპტებიდან მოამზადეთ სწრაფი, ენერგიით სავსე სალათი, რომელიც ძალების აღდგენაში დაგეხმარებათ.'),
  ('7883fd83-494d-41a3-b42d-58d452de13d7', 'მამის მხიარული ოინები 🤡', 'ბავშვის გასაცინებლად საუკეთესო გზა მამის მიერ უცნაური ხმების გამოცემაა. ამ საღამოს ბავშვთან ერთად დატკბით მხიარული წუთებით.'),
  ('981d8d60-ab26-4f64-a20b-eee1dc2fed12', 'წვრილად დაჭრილ საკვებზე სრულად გადასვლა! 🍲', 'მას უკვე შეუძლია ისეთი საკვების ჭამა, რომელსაც დაღეჭვა სჭირდება. ჩვენს აპლიკაციაში დამატებითი კვების დამწყები ბავშვებისთვის განკუთვნილი რეცეპტებიდან ახალი ტექსტურები სცადეთ.'),
  ('74f02405-1cdd-401e-bb47-01d87997f231', 'დამოუკიდებლად თამაშის დრო 🧸', 'მას უკვე შეუძლია 10-15 წუთის განმავლობაში სათამაშოებით დამოუკიდებლად გაერთოს. ეს ყურადღების კონცენტრაციის ხანგრძლივობის ზრდას ნიშნავს. შორიდან მიადევნეთ თვალი და დატკბით სიმშვიდით.'),
  ('8d91b32b-a0f2-4a07-a181-da0b746268bc', 'პარკი თუ სახლი? ⛅', 'გარეთ გასვლა გსურთ, მაგრამ ქარია. ამინდისა და ჩაცმულობის დამხმარე გეტყვით არა მხოლოდ ტემპერატურას, არამედ იმასაც, თუ რა ჩააცვათ ბავშვს ქარისგან დასაცავად.'),
  ('9890a3bf-dcd7-4d43-8ef7-e98ca087bf8e', 'ჯიუტი ღამეები 🥱', 'დაძინებას მთელი ძალით ეწინააღმდეგება? კიდევ ერთხელ გადაამოწმეთ დღის ძილის გრაფიკი და ყოველდღიური რუტინა.'),
  ('2f4fbaac-dfe4-48b5-b844-6636c2bc201a', 'სია თქვენს ჯიბეშია 🛒', '1 წლის იუბილეს ტორტის შესაკვეთად Anacan-ში ტორტის ვარიანტებს გადახედეთ.'),
  ('395ddd9b-9009-4fec-ba6f-816d156ad432', 'დიდი ემოციები, პატარა სხეული 🛑', 'როცა სასურველს ვერ იღებს, იატაკზე წვება ან ტირის? მას ჯერ არ შეუძლია ემოციების მართვა. ჩაიმუხლეთ მის სიმაღლემდე და მშვიდად ესაუბრეთ, რათა ამ კრიზისების გადალახვაში დაეხმაროთ.'),
  ('d824145b-4905-49d1-9f4f-46ade8a730f8', 'უეცრად ყვირილით გაიღვიძა? 😭', 'ეს შესაძლოა ღამის შიში იყოს. მისი ხმა ტირილის ანალიზის ფუნქციას მოასმენინეთ, რათა დაადგინოთ, პრობლემა ფიზიკურია თუ ფსიქოლოგიური.'),
  ('a7923459-9b74-4330-949d-00e94d185768', 'სიტყვა „არას“ მნიშვნელობა! 🛑', 'როცა იმას აკეთებს, რაც არ შეიძლება, უკვე თქვენს რეაქციას აკვირდება? დისციპლინის პირველი ნაბიჯების შესახებ რჩევა Anacan AI-ს ჰკითხეთ.'),
  ('ec1173c9-8c5f-4b55-8ebd-5fdf69b08da1', 'მასაჟის დროა 💆‍♂️', 'ბავშვის დაძინების შემდეგ დღის სტრესის მოსახსნელად პარტნიორთან ერთად ერთმანეთს მხრების მასაჟი გაუკეთეთ. თქვენ ერთი გუნდი ხართ!'),
  ('ef821341-2506-439d-8346-fbafb2b792ff', 'ერთ წლამდე სულ რაღაც 25 დღე დარჩა! 🎈', 'უკუთვლა ოფიციალურად დაიწყო! უკვე მოიფიქრეთ ადგილი და სამოსი 1 წლის ფოტოსესიისთვის? დააჩქარეთ მზადება!'),
  ('510bccc7-40fa-4c0b-8d0b-8a3105fd00ea', 'უსაფრთხოების ზომები სახლში! 🛡', '️ რაც უფრო თავისუფლად იწყებს გადაადგილებას, საფრთხეც იმატებს. აუცილებლად გაეცანით ჩვენს რეკომენდებული პროდუქტების სიას — იქ ნახავთ ბავშვის საკეტებსა და კიბის დამცავ ჭიშკრებს.'),
  ('959729c5-8ab6-4053-99ca-82aa5fdabc7e', 'მამასთან ერთად ზრუნვის დროა. 👨‍🍼', 'საღამოს კვების შემდეგ წიგნის წაკითხვა და ბავშვის დაძინება მამას მიანდეთ, თავად კი ცოტა წაუძინეთ.'),
  ('a478b2eb-eaec-4b54-813a-6f2ba55a5d14', 'ყველაფერზე საჩვენებელი თითით მიგანიშნებთ! ☝', '️ იმის ნაცვლად, რომ თქვას „ეს რა არის?“, ყველაფერზე თითით მიგანიშნებთ. მისი ეს ცნობისმოყვარეობა ბავშვის ალბომში უკვდავყავით.'),
  ('97023662-0ba2-4bcd-aff7-bc7adf5883ba', 'ხმის კონტროლი 🤫', 'ჩაძინებიდან პირველი ნახევარი საათი ყველაზე მგრძნობიარე პერიოდია. ხმის დონის საზომით გარემო შეამოწმეთ და მოერიდეთ მოულოდნელ ხმაურს.'),
  ('d02f135b-16bc-4fa9-978f-0e7d992c1ba4', 'დალაგება თუ დასვენება? 🛋️', 'როცა ბავშვს სძინავს, ჭურჭლის სარეცხი მანქანისკენ ნუ გაიქცევით. დივანზე წამოწექით, თვალები დახუჭეთ და 15 წუთის განმავლობაში უბრალოდ ისუნთქეთ.'),
  ('f12c7751-b89f-4d12-a843-8e331c338393', 'კუბებით ციხესიმაგრეს აშენებს 🧱', 'ცდილობს, ორი ან სამი სათამაშო კუბი ერთმანეთზე დააწყოს. ჩუმად დააკვირდით მის ამ პატარა საინჟინრო მცდელობებს და ტაში დაუკარით.'),
  ('35ab2e31-1937-4e58-b764-83729c6e330a', 'პასუხი სხეულის ენით 🗣️', 'როცა ეკითხებით „წავიდეთ?“, ხელებს მაღლა სწევს, ხოლო როცა ეუბნებით „არა“, თავს აქნევს. მისი გაგების უნარი წარმოუდგენლად გაიზარდა.'),
  ('65a36f4e-0f24-45fe-a038-a2e61c778c81', 'დააფასეთ საკუთარი თავი 👏', 'ოთახის არეულობას კი ნუ შეხედავთ, არამედ იმას, თუ როგორი ბედნიერი იყო ის დღეს. თქვენ ისეთი შესანიშნავი დედა ხართ, როგორადაც ვერცერთი წიგნი ვერ გასწავლით ყოფნას.'),
  ('7b75b0ec-d253-4e5a-bfac-9ff801269b5f', 'დღეს ჭკვიან ზღაპარში 🪄', 'ჭკვიან ზღაპრებში შექმენით განსაკუთრებული ამბავი, რომლის მთავარი გმირიც თქვენი ბავშვია: პატარა ლომი, რომელიც ერთი წლის შესასრულებლად ემზადება.'),
  ('01302c3b-60e6-4b0a-8a88-e63349585527', '1 წლის ასაკთან დაკავშირებული შფოთვა? 💬', 'გაწუხებთ კითხვები, როგორიცაა: „ჩემი ბავშვი ჯერ არ დადის, ხომ არ აგვიანდება?“ დაწერეთ Anacan-ის საზოგადოებაში. დაინახავთ, რომ ყველა ბავშვს განვითარების საკუთარი იდეალური ტემპი აქვს და თქვენ მარტო არ ხართ.'),
  ('51d3f88a-4baa-4ed5-b62c-e84a750f8166', 'მამის ღამის მორიგეობა 👨‍🍼', 'ღამით ბავშვის გაღვიძებებს სრულიად მარტო ნუ გაუმკლავდებით. გააღვიძეთ თქვენი პარტნიორიც — გუნდად ყოფნა პასუხისმგებლობის თანაბრად განაწილებას ნიშნავს.'),
  ('984d2a76-5fec-4059-86ef-85671516c9b6', 'ამინდის დაზვერვა ⛅', 'გარეთ გაურკვეველი ამინდია? ამინდისა და ჩაცმულობის ხელსაწყო მყისიერად გიჩვენებთ ქარის სიჩქარეს და შეგირჩევთ შესაფერის სამოსს.'),
  ('063ccb8e-7bd6-43e4-9c41-f30c172e10a7', 'ჯანმრთელი დედა, ჯანმრთელი ბავშვი 🥑', 'თქვენი რკინისა და კალციუმის მარაგები ამოწურულია. ჯანსაღი რეცეპტების მიხედვით მოამზადეთ სალათი, რომელიც სწრაფადაც მზადდება და ენერგიის შენარჩუნებაშიც დაგეხმარებათ.'),
  ('1bed0d5c-444a-48fc-8e21-35fd8fff35b5', '1 წლამდე სულ რაღაც 20 დღე დარჩა! 🎂', 'დრო რა სწრაფად მიფრინავს! დაიწყეთ ჩანაწერების გაკეთება დაბადების დღის მოსაწვევების, სიებისა და პატარა სიურპრიზებისთვის.'),
  ('caa0a9a0-1a0d-4362-a446-9f103d33e564', 'კადრი, რომელიც დროს აჩერებს 📸', 'როცა ოთახში საყვარლად თამაშობს, მაშინვე გახსენით ბავშვის ფოტოსესია და აღბეჭდეთ მისი უკვე დიდი ბავშვის ხასიათი.'),
  ('3cc5a97d-281f-41bf-8747-fbb71f040e65', 'ჩააქრეთ მკვეთრი განათება 🌙', 'დაძინებამდე 1 საათით ადრე გამორთეთ სახლში ყველა მკვეთრი განათება და ეკრანი. მელატონინი მხოლოდ მშვიდ და სუსტად განათებულ გარემოში გამოიყოფა.'),
  ('528b02c4-9d93-4cda-add4-eb9a04a4395a', 'რძის გამომუშავების ხელშემწყობი საკვები. 🍲', 'დღესვე სცადეთ ქალებისთვის განკუთვნილი ჯანსაღი რეცეპტების განყოფილებაში მოცემული რძის გამომუშავების ხელშემწყობი სუპები და გაიძლიერეთ ორგანიზმი.'),
  ('a889d8c9-3ffc-4f2f-8c82-a33c81ad3e8d', 'დაგავიწყდათ, რომელი ძუძუდან აჭამეთ? 🤱', 'Anacan-ის ტაიმერი თქვენ ნაცვლად იმახსოვრებს, მარჯვენა თუ მარცხენა ძუძუდან აჭამეთ. ახლავე დაიწყეთ კვება ტაიმერის გამოყენებით!'),
  ('5c42ea20-5a84-467a-b408-412bcaaf8374', 'დღის ძილი იცვლება? 🥱', 'დღის ორი ძილიდან ერთ-ერთზე უარს ამბობს? შესაძლოა, 1 წლის ასაკის მოახლოებასთან ერთად ძილის განრიგის შეცვლის დრო დადგა.'),
  ('b5252c17-b36e-4334-8221-0dc9210bbc77', 'ოჯახურ სუფრასთან თავისი ადგილი აქვს! 🍲', 'მას უკვე მოსწონს თქვენთან ერთად, ერთსა და იმავე დროს ჭამა. ჩვენს აპლიკაციაში, დამატებითი კვების დაწყების რეცეპტებიდან მთელი ოჯახისთვის გემრიელი კერძები აღმოაჩინეთ.'),
  ('ee88eee3-00d7-4463-b0db-60b939d85d4e', 'კითხვა გაქვთ? 🤖', 'როგორ გადავიყვანოთ ბავშვი ძროხის რძეზე 1 წლის შემდეგ? — მსგავსი მნიშვნელოვანი კითხვები ღამის საათებშიც შეგიძლიათ დაუსვათ ჩვენს Anacan AI ასისტენტს და მიიღოთ მხარდაჭერა.'),
  ('48047d55-0e81-4b9a-976d-56b580b1a7b7', 'პედიატრიული კითხვები 🤖', 'რა იცვლება კვებაში 1 წლის ასაკის მოახლოებასთან ერთად? თავს ნუ გადაიღლით — სთხოვეთ Anacan AI-ს ზუსტი, პედიატრის მიერ დამოწმებული სია.'),
  ('56284941-dca4-4067-9e31-d61fc4ebeb63', 'ერთმანეთის მხარდაჭერა 🥂', 'მთელი დღის დაღლილობის მოსახსნელად პარტნიორთან ერთად ჩაი დალიეთ და ერთმანეთს უთხარით: „დღესაც შევძელით!“'),
  ('c69bf08f-8c53-4bb9-8c0e-a81edd03f90e', 'მარტივ მითითებებს სრულად ასრულებს! 🧠', 'როდესაც ეუბნებით: „ბურთი მომეცი“ ან „აქ მოდი“, თქვენი ესმის. ხელი შეუწყვეთ ამ ინტელექტუალური ნახტომის შემდგომ განვითარებას ბლოგის სტატიების დახმარებით.'),
  ('152edc3c-3a8c-41ee-81bb-0df222f2c1ea', 'სულ რაღაც 2 კვირა! 🎈', 'დაბადების დღემდე მხოლოდ 14 დღე დარჩა! ნოსტალგიის დროა... გახსენით ბავშვის ფოტოსესია, დაბადების დღის ფოტო დღევანდელ ფოტოს გვერდით მოათავსეთ და თვალი ადევნეთ მის საოცარ ზრდას.'),
  ('87c2d4c6-8130-43a1-8ff7-fa406c018013', 'მამის ღამის მოვალეობა 👨‍🍼', 'დღისით დაღლაც გეყოფათ. საღამოს ბავშვის დასაძინებლად მომზადება და ზღაპრის წაკითხვა მამის მოვალეობაა. თქვენ კი უბრალოდ ყურსასმენები გაიკეთეთ.'),
  ('d1325a58-5701-4db5-a92f-ca67116c5c21', 'რამდენიმე წამი საყრდენის გარეშე 🧗‍♂️', 'დივანზე დაყრდნობით დგომისას ხელებს ცოტა ხნით უშვებს? ის წონასწორობის შენარჩუნებას სწავლობს.'),
  ('3beff563-1e72-4a1f-8490-4e977c8b0b7a', 'რა მოვამზადო? 🍲', 'ერთი წლის ასაკის მოახლოებასთან ერთად მენიუს იდეები გამოგელიათ? სთხოვეთ Anacan AI-ს მარტივი საკვების სია, რომლის დაჭერასა და ჭამასაც ბავშვი დამოუკიდებლად შეძლებს.'),
  ('eebfea92-7f8e-43d7-a45c-4a10e720b24c', 'სიბნელესთან დამეგობრება 🌙', 'უფრო სწრაფად ჩაძინებისთვის საღამოს რუტინას სიბნელეც დაამატეთ. ოთახში ყველა ზედმეტი განათება და ეკრანი გამორთეთ.'),
  ('f8f9e691-e184-414d-9abe-ae0a3969929a', 'საუბარში ერთვება 🗣️', 'როცა საუბრობთ, ისიც თავის ენაზე რაღაცას ამბობს და ხმას უწევს? მისი კომუნიკაციის უნარი სწრაფად ვითარდება — ოთახში უკვე მეორე მოსაუბრეა, ამიტომ აუცილებლად მოუსმინეთ!'),
  ('20db1e8e-1980-431d-800c-b7aa4ccf158b', 'საკუთარი კოვზით ჭამის მცდელობები! 🥄', 'უკვე იღებს კოვზს და ცდილობს, პირთან მიიტანოს? ამ სახალისო მომენტების მხარდასაჭერად დამატებითი კვების დამწყები ბავშვებისთვის შესაფერისი საკვები შეარჩიეთ.'),
  ('77cedc71-0d6f-45f7-a8a4-9ddfcd0a5be6', 'ზღაპრით ძილისთვის მომზადება 🪄', 'ჭკვიან ზღაპრებში შექმენით განსაკუთრებული ფონი, რომელიც მხოლოდ მუსიკისა და ბუნების ხმებისგან შედგება. სიტყვების გარეშე — მხოლოდ სიმშვიდე.'),
  ('eca3e78d-00de-4e77-bade-43808f152e4f', 'სიყვარულით სავსე კოცნები 🥰', 'როცა კოცნით, ისიც თქვენკენ იხრება და ტუჩებს წევს ან ლოყას გისველებთ? მის პატარა კოცნებს თქვენი მთელი დაღლილობის გაქრობა შეუძლია.'),
  ('863a6afb-427b-4143-a527-2e01fe303116', 'მამის სასაცილო მიმიკები 🤡', 'ბავშვის გაცინების საუკეთესო გზა მამის უცნაური ხმებია. დატკბით ამ საღამოს მხიარული მომენტებით ბავშვთან ერთად.'),
  ('b4676fcf-2967-4b49-adbd-12ebe6a54334', 'გულის გადაშლა გჭირდებათ 💬', 'ფიქრი, „ვერ ვიჯერებ, რომ უკვე 1 წლისაა“, ემოციებით გავსებთ? გაუზიარეთ ეს მშვენიერი განცდა Anacan-ის საზოგადოებაში მყოფ დედებს.'),
  ('b86239c1-4a1c-48b3-b49a-3fd4a012ebae', '1 წლის შესრულებამდე მხოლოდ 15 დღე დარჩა! 🎈', 'ნოსტალგია გეძალებათ! გახსოვთ ის პირველი დღე, როდესაც სამშობიაროდან გამოხვედით? ახლა კი უკვე 1 წლის იუბილესთვის ემზადებით! ბავშვის ფოტოსესიისას მისი პირველი და ახლანდელი ფოტოები გვერდიგვერდ მოათავსეთ!'),
  ('222d12a8-4347-4dce-afd7-4a0890721d0b', 'ჯიუტი ღამეები 🥱', 'ბავშვი მთელი ძალით ეწინააღმდეგება დაძინებას? შესაძლოა, დღის ძილებიდან ერთ-ერთის ამოღების დრო დადგა. გადახედეთ მის რუტინას.'),
  ('5047e51c-64dc-4fe5-bc38-0409a743d0f6', 'შევამოწმოთ სიმაღლისა და წონის მატება! 📏', '1 წლის ასაკის გეგმურ შემოწმებამდე ცოტა დრო დარჩა. განაახლეთ ბოლო მონაცემები განვითარების მონიტორინგის განყოფილებაში, გადახედეთ ჯანსაღი ზრდის გრაფიკს და იამაყეთ.'),
  ('873f2996-36df-4d67-a2df-ec60f668be2f', 'საჭმლის კოშკი დაინგრა 🥣', 'კოვზს განზრახ აგდებს იატაკზე და თქვენ გიყურებთ? ის მიზიდულობის ძალასა და თქვენს რეაქციას ცდის. შეინარჩუნეთ სიმშვიდე — ეს თამაშის ერთ-ერთი ფორმაა.'),
  ('8cd57628-b75f-4445-8bc9-6b180e6572dc', 'დღეს ჭკვიან ზღაპარში 🪄', 'ჭკვიან ზღაპრებში შექმენით განსაკუთრებული ამბავი, რომლის მთავარი გმირიც თქვენი ბავშვია.'),
  ('94b60a89-bc34-41d8-818c-174aa7ed663b', 'დალაგება თუ დასვენება? 🛋️', 'როცა ბავშვს სძინავს, ჭურჭლის სარეცხი მანქანისკენ ნუ გაიქცევით. წამოწექით დივანზე, დახუჭეთ თვალები და 15 წუთის განმავლობაში უბრალოდ ისუნთქეთ. რობოტი ხომ არ ხართ? არა.'),
  ('c7b84129-89ab-4610-b19f-84959d6194f9', 'კარადის დეტექტივი 🕵️‍♀️', 'სამზარეულოს ყველა ქვაბი იატაკზეა? უსაფრთხო ნივთებით თამაში ბავშვის ლოგიკურ აზროვნებას ავითარებს. მიეცით საშუალება, თავისუფლად ეძებოს განძი.'),
  ('11e743be-fb20-462f-8c74-07c143992d51', 'პირველ დაბადების დღემდე 10 დღე დარჩა! 🎂', 'მღელვარება მატულობს! დაბადების დღის ტორტი, ტანსაცმელი, სტუმრების სია... აზრების დასალაგებლად ყველაფერი განწყობის დღიურის სპეციალური ჩანაწერების განყოფილებაში ჩაიწერეთ.'),
  ('15436a4e-52bb-4539-9146-377403746da0', 'დედების გულახდილი საუბრები 💬', 'გღლით კითხვები, როგორიცაა: „ჩემი ბავშვი ჯერ კიდევ რატომ არ დადის?“ შეუერთდით Anacan-ის საზოგადოებას და დაინახავთ, რომ ყველა ბავშვი საკუთარი ტემპით ვითარდება.'),
  ('21394622-dd96-488a-a90a-b8f72d718390', 'პირველი ფეხსაცმლის შერჩევა! 👟', 'ნაბიჯები უფრო სწრაფი ხდება! აუცილებლად გაეცანით რეკომენდებული პროდუქტების სიას, რათა ბავშვის ტერფის განვითარებისთვის შესაფერისი, ორთოპედიული და რბილძირიანი პირველი ფეხსაცმელი შეარჩიოთ.'),
  ('c8d8ec20-b116-4c1f-93ec-b76e6f76a1b1', 'უსაფრთხოების ზომები სახლში! 🛡', '️ როდესაც ბავშვი დამოუკიდებლად სიარულს იწყებს, საფრთხეებიც მატულობს. გაეცანით რეკომენდებულ პროდუქტებს ბავშვებისგან დამცავი საკეტებისა და კიბის დამცავი ჭიშკრებისთვის.'),
  ('cbeda45d-85bc-4e45-b9c0-cc3c3d5c896b', 'თქვენი ცვალებადი სხეული 👗', 'სარკეში თქვენი სხეულის ფორმებს უყურებთ და სევდა გეუფლებათ? ამ სხეულით თქვენ ადამიანი შექმენით. ჩაეხუტეთ საკუთარ თავს და გაიხსენეთ, რამდენად ძლიერი ხართ.'),
  ('f38aba52-8d3a-44ad-96bf-7d9de570ef68', 'დედასთან ყოფნის დაჟინებული სურვილი 🥰', 'ტუალეტშიც კი რომ შედიხართ, ბავშვი კარს მიღმა გელოდებათ და ტირის. განშორების შფოთვამ პიკს მიაღწია. ყოველ ჯერზე უთხარით: „მე აქ ვარ“ და უსაფრთხოების განცდა შეუქმენით.'),
  ('03283459-7c0f-4d41-9c06-406552e1c477', 'სრულყოფილების ილუზია 🛑', 'დღეს არაფერი წავიდა გეგმის მიხედვით? თავს ნუ დაიდანაშაულებთ. თქვენ ნამდვილი დედა ხართ და არა სოციალურ ქსელებში გაფილტრული ილუზია.'),
  ('3843a02f-a85f-47a9-97ba-0e63677749e2', 'ჩუმი გმირი 🤫', 'როგორც კი ბავშვს ჩაეძინება, სახლში ყოველი ხმა ბომბის აფეთქებას ჰგავს. სანამ ხმაურის საზომით ოთახში დასაშვებ ზღვარს ადგენთ, თავადაც ფეხაკრეფით იარეთ.'),
  ('fde65599-b651-49fa-a50a-5b78bed58d9f', 'საჩვენებელი თითი გააქტიურდა ☝️', 'ბავშვი შორს მდებარე საგანზე თითით მიგანიშნებთ და რეაქციას გამოხატავს. ეს ყურადღების გაზიარების განვითარების მნიშვნელოვანი ეტაპია. მასთან ერთად შეხედეთ იმ საგანს.'),
  ('069d21f4-a2ef-4d28-91bb-979c8ca3f3f6', 'შეიძლება ძროხის რძე მივცე? 🥛', '1 წლის ასაკის მოახლოებასთან ერთად მენიუ იცვლება. თუ ძროხის რძეზე გადასვლასთან ან ისეთი საკვების მიცემასთან დაკავშირებით, როგორიცაა თაფლი, კითხვები გაქვთ, დაუყოვნებლივ ჰკითხეთ Anacan AI-ს.'),
  ('6b37b92f-5c61-4852-9ace-caab2bda465b', 'ოჯახური გასეირნება და გეგმები! ☕', 'დაბადების დღემდე ცოტა დრო დარჩა! მეგობრებთან და ოჯახის წევრებთან შესახვედრად „დედებისთვის მეგობრულ ადგილებში“ იპოვეთ კაფეები, რომლებშიც ბავშვის ეტლით თავისუფლად შეხვალთ.'),
  ('fedb8c6b-7722-4e20-9134-1af5ae254e85', 'მასაჟის დროა 💆‍♂️', 'მას შემდეგ, რაც ბავშვს ჩაეძინება, დღის სტრესის მოსახსნელად პარტნიორთან ერთად მხრების მასაჟის სესია მოაწყვეთ. თქვენ ერთი გუნდი ხართ!'),
  ('51bb1e4c-965f-4d69-b6e7-c79da0dce45c', 'სივრცე დედისთვის ☕', 'სახლში ყოფნამ ენერგია გამოგაცალათ. დედებისთვის მეგობრულ სივრცეებს შორის შეარჩიეთ კაფე, რომელსაც საბავშვო მენიუ და კომფორტული დასაჯდომი აქვს, და დრო საკუთარ თავსაც დაუთმეთ.'),
  ('814176f3-c727-409b-b14a-fa62636170f1', 'წიგნებისადმი ინტერესი 📖', 'საღამოს რუტინაში ნაბეჭდი წიგნებიც ჩართეთ. ბავშვი უკვე ცდილობს, გვერდები თავად გადაფურცლოს. თქვენი ხმის ტონი ზღაპრის ტემპს მოარგეთ.'),
  ('f73c2769-0def-42bc-93e0-9a021c41b271', 'სხეული, რომელიც მუსიკაზე ცეკვავს 🎶', 'როგორც კი ტელევიზორში რიტმულ ხმას გაიგონებს, მაშინვე საჯდომის ქნევას იწყებს. მუსიკის აღქმა უკვე ვითარდება — აჰყევით და ეს არაჩვეულებრივი მომენტი ერთად განიცადეთ.'),
  ('4c628627-3074-421f-9cfc-318df363eaf0', 'დაგავიწყდათ, რომელი ძუძუთი აჭამეთ? 🤱', 'Anacan-ის ტაიმერი თქვენ ნაცვლად იმახსოვრებს, მარჯვენა თუ მარცხენა ძუძუთი აჭამეთ. კვების აღრიცხვა ახლავე დაიწყეთ ტაიმერით!'),
  ('99abcc3d-bec9-4537-89f9-92bfe6f4056c', 'არაჩვეულებრივი დღის დასასრული. ✨', 'თქვენ საოცარი დედა ხართ და უკვე 1 წელია, ნამდვილ გმირობას სჩადიხართ! განწყობის დღიურში ჩაწერეთ, რომ საკუთარი თავით ამაყობთ, და მშვიდად დაიძინეთ.'),
  ('d58a373d-b464-4fff-9b8e-74a104499618', '1 წლამდე სულ რაღაც 5 დღე დარჩა! 🎈', 'უკუთვლა თითქმის დასრულდა! პირველი დაბადების დღე! დეკორაციები, პატარა სტუმრები... გაწევრიანდით Anacan-ის საზოგადოებაში და სხვა დედებისგან 1 წლის იუბილესთვის კრეატიული იდეები მიიღეთ.'),
  ('5a7c1a91-4811-4c74-93f4-2ee19bdbb39a', 'გაიხსენეთ პარტნიორთან ერთად პირველი დღეები და იცინეთ.', 'ამ 1 წლამდე იოლად არ მოსულხართ! ეს თქვენი, როგორც გუნდის, გამარჯვებაა.'),
  ('5c11361a-fa0a-4cbc-ab7e-82f7bcc5e4bf', 'დიდ დღემდე 2 დღე დარჩა! 🗣', '️ მისი პირველი „დედა“ ან „მამა“ თქვენთვის ყველაზე ლამაზი საჩუქარი იქნება. პირველი სიტყვების წარმოთქმის უნარის განვითარების ხელშესაწყობად წაიკითხეთ ბლოგებში მოცემული რეკომენდაციები.'),
  ('e7879bf6-3dca-4f0b-9981-d7f119d39235', 'ჩააქრეთ მკვეთრი განათება 🌙', 'დაძინებამდე 1 საათით ადრე სახლში ყველა მკვეთრი განათება და ეკრანი გამორთეთ. მელატონინი მხოლოდ მშვიდ და სუსტად განათებულ გარემოში გამოიყოფა.'),
  ('14e209af-2489-4eb6-a1f0-be21be617768', 'ზღაპრით ძილისთვის მომზადება 🪄', 'ჭკვიან ზღაპრებში შექმენით სპეციალური ფონი, რომელიც მხოლოდ მუსიკისა და ბუნების ხმებისგან შედგება. სიტყვები არ არის — მხოლოდ სიმშვიდე და მოლოდინი.'),
  ('a6e2ed87-38de-413e-9884-cda9afcbb191', 'ბოლო სამზადისი 📸', 'სანთლები, ტორტი და ტანსაცმელი მზად არის? გაათავისუფლეთ ადგილი ტელეფონის მეხსიერებაში — ხვალ ბავშვის ფოტოსესიისთვის ბევრი ადგილი დაგჭირდებათ!'),
  ('c639a352-3f59-4488-9ce0-2ba361a4790c', 'ხვალ უკვე 1 წლის გახდება! 🎉', 'ნოსტალგიის დროა! გახსოვთ ის პირველი დღე, როდესაც სამშობიაროდან გამოხვედით? გახსენით განწყობის დღიური და ამაღამ ბავშვს დაუწერეთ ემოციური წერილი, რომელსაც მომავალში წაიკითხავს.'),
  ('0549edc6-63d2-4caa-a43c-f029f7f39465', 'კბილების ამოჭრის ტკივილი 🦷', 'ღრძილები ისევ გაუწითლდა და ნერწყვდენა არ წყდება? შესაძლოა, პირველი ძირითადი კბილები უკვე ამოსვლას იწყებს.'),
  ('1c81021a-496b-49c0-86bc-4bde92ff779d', 'ხმაურის კონტროლი 🤫', 'ჩაძინებიდან პირველი ნახევარი საათი ყველაზე მგრძნობიარე პერიოდია. ხმაურის საზომით გარემო შეამოწმეთ და მოერიდეთ უეცარ ხმაურს.'),
  ('262cbb13-eb12-4831-9fe5-37ece168bdfa', 'სხეულის ენით პასუხობს 🗣️', 'როცა ეკითხებით: „წავიდეთ?“, ხელებს მაღლა სწევს, ხოლო როცა ეუბნებით „არა“, თავს აქნევს. მისი გაგების უნარი საოცრად განვითარდა!'),
  ('38f7fe28-84d1-4b40-8904-c7ef3e18b0f8', 'სუფთა ჰაერი ნამდვილი მხსნელია 🌳', 'თუ სახლში ჭირვეულობა ძლიერდება, შეამოწმეთ ამინდი და ბავშვის ტანსაცმელი, ჩასვით ეტლში და მაშინვე პარკში გაისეირნეთ. ბუნებაში გასვლა მისი დამშვიდების ყველაზე სწრაფი გზაა.'),
  ('39697061-01f6-4b41-8098-183a43f25058', 'კუბებით ციხესიმაგრეს აშენებს 🧱', 'ცდილობს, ორი ან სამი სათამაშო კუბი ერთმანეთზე დააწყოს. ჩუმად დააკვირდით მის ამ პატარა საინჟინრო მცდელობებს და ტაში დაუკარით.'),
  ('c5294433-a84c-4be9-ad57-5744718366c9', 'დღეს ყველაფერზე გაღიზიანდით? 📝', 'როცა ბავშვი დაიძინებს, თქვენი გრძნობები განწყობის დღიურში ჩაიწერეთ. ხვალ ახალი და უკეთესი დღე იქნება.'),
  ('0eb89ca2-1605-4f92-8c61-0198a966afb1', 'გამარჯვების ცეკვა 💖', 'ამ საღამოს სანთლების შუქზე, მეუღლესთან ერთად აღნიშნეთ მთელი წლის დაღლილობა და სიამაყე. თქვენ შესანიშნავი გუნდი ხართ!'),
  ('2e46d431-01ee-479e-a146-2b349cd7f234', 'ერთი წლისაა! პირველი დაბადების დღე! 🎂🎉', 'შესანიშნავი ხართ! ზუსტად 365 დღე, უძილო ღამეები, პირველი სიცილი, პირველი ნაბიჯები! ის უკვე 1 წლისაა! მოაწყვეთ ბავშვის ფოტოსესია და ეს ისტორიული დღე ულამაზესი კადრებით უკვდავყავით!'),
  ('3c2fa886-d095-424c-ad68-b439a1ffc0b9', 'ტაში დაუკარით საკუთარ თავს 👏', 'ის 9 თვე თქვენს მუცელში, შემდეგ კი 1 წელი თქვენს მკლავებში იზრდებოდა! დღეს არა მხოლოდ მისი, არამედ თქვენი დედობის დაბადების დღეცაა. იამაყეთ საკუთარი თავით!'),
  ('0944c4dc-3e95-4efb-97dc-8b4809d96d45', 'ადრეული ბავშვობის პერიოდი იწყება 🌟', 'ჩვილობის პერიოდი დასრულდა! ახლა ის უკვე ბავშვია, რომელიც ოფიციალურად ავლენს საკუთარ ინდივიდუალობას და ყველაფრის თავად გაკეთება სურს. მოთმინებითა და სიყვარულით სავსე ახალი თავგადასავალი იწყება!'),
  ('569602c0-f0cf-4229-b498-984bfdabf097', 'ჭკვიანი ზღაპრების დრო 🪄', 'განაგრძეთ ეს რუტინა და ჭკვიან ზღაპრებში შექმენით ისტორია დიდ გმირზე, რომელიც უკვე 1 წლისაა და სამყაროს იკვლევს.'),
  ('ae6d1371-ca56-433f-b6db-9c70c59094fb', 'ჭირვეულობა იცვლება 🛑', 'დაიწყო ახალი კრიზისები (ტანტრუმები), მაგალითად, იატაკზე გაწოლა და ყვირილი? ბავშვს ჯერ არ შეუძლია საკუთარი ემოციების მართვა. ჩაიმუხლეთ მის სიმაღლეზე, მშვიდად დაელაპარაკეთ და დაეხმარეთ კრიზისის გადალახვაში.'),
  ('6e25898e-24d8-4ca6-8cbe-71a271993d6f', 'ხმაურის მართვა 🤫', 'ჩაძინებიდან პირველი ნახევარი საათი ყველაზე მგრძნობიარე პერიოდია. გარემო ხმის საზომით შეამოწმეთ და მოერიდეთ უეცარ ხმაურს.'),
  ('d5e35c42-03ad-4068-b27d-3efca55a35ad', 'კოვზის დაჟინებული მოთხოვნა 🥄', 'მას სურს, კოვზი თავად დაიჭიროს და პიურეც დამოუკიდებლად მიირთვას. დაიღვრება, დასვრება, მაგრამ ეს მოტორული უნარების განვითარებისთვის ძალიან მნიშვნელოვანია. მიეცით ამის უფლება.'),
  ('f93e7290-30ca-44fe-a1e4-55044619c9a6', 'ენერგიის საჭიროება 🍲', 'ყოველდღიური ფუსფუსი კიდევ უფრო დაჩქარდა. ჯანსაღი რეცეპტებიდან შეარჩიეთ რკინითა და ცილებით მდიდარი სადილი, რომელიც ენერგიას მოგცემთ, და ძალები აღიდგინეთ.'),
  ('10a3d57b-5997-4410-8ceb-fa0dd3d4cee2', 'მამის ღამის მორიგეობა 👨‍🍼', 'ღამით ბავშვის გაღვიძებებს სრულიად მარტო ნუ გაუმკლავდებით. გააღვიძეთ პარტნიორიც — გუნდურად მოქმედება პასუხისმგებლობის თანაბრად განაწილებას ნიშნავს.'),
  ('50b26349-9946-4708-aec2-e87f1b15952f', 'პირველი დამოუკიდებელი ნაბიჯები? 🧗‍♂️', 'იქნებ დღეს, იქნებ ხვალ... ის უკვე ცდილობს, არაფერზე დაყრდნობის გარეშე ერთი-ორი ნაბიჯი გადადგას. მოემზადეთ, რომ ეს განვითარების ტრეკერში აღნიშნოთ!'),
  ('9407d96f-ca5a-4378-a7c6-ee00256c457a', 'ამინდის დაზვერვა ⛅', 'სასეირნოდ გასვლისას მხოლოდ ფანჯრიდან გახედვით ნუ მიიღებთ გადაწყვეტილებას. ამინდისა და ჩაცმულობის ინსტრუმენტი მყისიერად გიჩვენებთ ქარის სიჩქარეს და შესაფერის სამოსს.'),
  ('3ed836ab-41d4-4203-a7c8-b9e7b1394cd2', 'გულახდილი საუბარი გჭირდებათ 💬', 'გაშინებენ ისინი, ვინც ამბობს, რომ 1 წლის შემდეგ ყველაფერი უფრო რთულდება? დაწერეთ Anacan-ის საზოგადოებაში და წაიკითხეთ დედების რეალური, დადებითი გამოცდილებები.'),
  ('4c27d203-23f5-4e87-918e-d40df5e30875', 'ღამის სიმშვიდე 🛀', 'თბილი აბაზანა, მასაჟი და ოთახის ჩაბნელება. ძილის რუტინის დაცვა ღამით უწყვეტი ძილის მთავარი საიდუმლოა.'),
  ('6ad316f8-edd9-4dff-aac4-f3492d4a602a', 'მარტივ მითითებებს ასრულებს 🧸', 'როცა ეუბნებით, ბურთი მომეციო, ნამდვილად პოულობს და მოაქვს? სიტყვების გაგების უნარი პიკზეა! უფრო მეტად ჩართეთ თამაშებში.'),
  ('028a5b0d-04de-43dc-984d-eaf6e3427904', 'პირველი ფეხსაცმლის არჩევა 👟', 'სიარულისთვის ემზადება, მაგრამ სახლში ფეხსაცმელი უნდა ეცვას? ჰკითხეთ Anacan AI-ს პირველი ნაბიჯებისთვის განკუთვნილი ფეხსაცმლისა და ფეხშიშველი სიარულის სარგებლის შესახებ.'),
  ('5d68d6d5-05d2-43b4-bd93-e3f95983e445', 'სია ნამდვილი ხსნაა 🛒', '1 წლის შემდეგ მენიუ იცვლება. სახლში ძროხის რძე ან სხვა საკვები გჭირდებათ? დაუყოვნებლივ შეავსეთ საყიდლების სია და გაუგზავნეთ თქვენს პარტნიორს.'),
  ('9a073421-3e36-4699-bbbd-50a69e46f431', 'დრო საკუთარ თავსაც დაუთმეთ. 🛁', 'მთელი დღე მოსიარულე ბავშვის დევნა ადვილი არ არის. ჩაინიშნეთ თქვენი დაღლილობა განწყობის დღიურში, იგრძენით შვება და დაისვენეთ.'),
  ('2cdeb7df-f4f5-4a75-ae9b-552210a168fe', 'წიგნებს ფურცლავს 📖', 'სქელფურცლებიანი წიგნის გვერდებს სრულიად დამოუკიდებლად ფურცლავს და სურათებზე რეაგირებს? ხშირად წაუკითხეთ ფერადი ზღაპრების წიგნები.'),
  ('8b98f6cf-24e2-4a41-9bea-c77f1a82d1bd', 'პირველი დამოუკიდებელი ნაბიჯები! 🧗‍♂', '️ ავეჯს ხელს უშვებს, დამოუკიდებლად დგას და შესაძლოა, იმ ნანატრ პირველ ნაბიჯსაც დგამს! არ გამოგრჩეთ ეს დაუვიწყარი, ისტორიული მომენტი და ვიდეო დაუყოვნებლივ ატვირთეთ ბავშვის ალბომში.'),
  ('beccb06c-7cf4-4f1a-9455-17d5b952ad96', 'მუსიკალური საღამოები 🎶', 'საღამოს ჭირვეულობასთან გამკლავების ყველაზე მარტივი გზა მისი საყვარელი სიმღერის ჩართვა, ჩახუტება და ერთად ცეკვაა.'),
  ('0c97760a-2746-4ddf-ad12-5f44e1960612', 'სიმშვიდის საჭიროება 🤫', 'ოთახში სიმშვიდე ხმის საზომის დახმარებით შეინარჩუნეთ. ღამით დარღვეული ძილი დილით განწყობას როგორც ბავშვს, ისე თქვენც გაგიფუჭებთ.'),
  ('61d67656-ab73-4417-b42d-5e55ecf64b87', 'სიტყვა „არას“ ძალა 🛑', 'როდესაც რამეს სთავაზობთ, უკვე ისწავლა თავის გაქნევით უარის თქმა! ეს სიჯიუტე კი არა, საკუთარი აზრის გამოხატვაა. დაამშვიდეთ იმით, რომ არჩევანის შესაძლებლობას მისცემთ.'),
  ('b58ae5cb-ec5b-400f-b490-16ff65c6cead', 'ლოგიკური თამაშები 🧩', 'სათამაშოებს ყუთში ყრის, შემდეგ კი ყველას გარეთ იღებს? ასე უვითარდება შიგნით და გარეთ ცნებების გაგება. ამ საქმიანობაში ხელს ნუ შეუშლით.'),
  ('6b997061-a83d-4040-b848-d55a40a87a1a', 'ჯანმრთელი დედა 🥑', 'თუ ბავშვი დანაყრდა, ახლა თქვენი ჯერია. ჯანსაღი რეცეპტებიდან ენერგიის მომცემი წასახემსებელი შეარჩიეთ და დივანზე სულ მცირე 10 წუთით წამოწექით.'),
  ('8d89c421-922f-4b8a-bc83-525a380ead88', 'კიბეებისადმი ინტერესი 🧗‍♂️', 'იატაკზე სიარული აღარ ჰყოფნის და კიბეებზე თუ ავეჯზე აძრომას ცდილობს? მისი მოტორული განვითარება შეუჩერებელია! აუცილებლად თვალყური ადევნეთ.'),
  ('dacf6637-c6dd-4427-9e89-1dc06f453ae5', 'ჯადოსნური ზღაპრის დრო 🪄', 'საღამოს რუტინა „ჭკვიანი ზღაპრების“ ისტორიით „ყველაზე პატარა გმირის დაძინების საიდუმლოებები“ გაახალისეთ.'),
  ('2d2e06b1-2d94-4883-a675-93637a17ca98', 'ჭირვეულობის პიკი ☁️', 'ვერაფრით კმაყოფილდება და ყველაფერზე ტირის? შესაძლოა, უკანა ძირითადი კბილები ამოსდის. ცივი კბილის ამოსაჭრელი სათამაშოები მოამზადეთ.'),
  ('2eeb1f61-7042-48aa-9ecc-41443c68b4a8', 'მამის ღამის მორიგეობა 👨‍🍼', 'ღამით გაღვიძებისას ერთხელ თქვენ ადექით, შემდეგ კი — თქვენი პარტნიორი. ზოგჯერ ბავშვს მხოლოდ მამის რიტმული მოფერება ამშვიდებს.'),
  ('d1cf73d9-421b-4ad1-b114-e5025146d5b2', 'სახლის საქმეებს ვინ გააკეთებს? 🌪️', 'საქმეები გიგროვდებათ? დაე, დარჩეს. სთხოვეთ თქვენს პარტნიორს, დღეს სახლის საქმეები საკუთარ თავზე აიღოს. თქვენ კი დაისვენეთ.'),
  ('18cb3df2-de24-43c0-a3d0-160051dc5202', 'ემოციების დღიური 📝', 'როცა თავს მარტოდ იგრძნობთ, თქვენი გრძნობები განწყობის დღიურში გადმოიტანეთ. ყველა ქალი გადის ამ გზას — თქვენ ძლიერი ხართ.'),
  ('19c626ef-26a5-49ef-921f-4577f35ab653', 'საწოვარაზე/ბოთლზე უარის თქმა? 🍼', 'ფიქრობთ, რომ ერთი წლის შემდეგ ბავშვს საწოვარა გადააჩვიოთ? Anacan-ის საზოგადოებაში სხვა დედებს ჰკითხეთ, რომელი მეთოდებია ამისთვის ყველაზე რბილი.'),
  ('c6a284e9-0bba-433f-9823-bcc74708dbd9', 'სუფთა ჰაერი წამალია 🌳', 'მთელი დღე ტიროდა და მოუსვენრად იყო? გამოსავალი ძალიან მარტივია: შეამოწმეთ ამინდი, შეურჩიეთ შესაბამისი ტანსაცმელი, ჩასვით ეტლში და მაშინვე პარკში გაისეირნეთ.'),
  ('5f3d97d0-e211-488f-bb05-dd9ccce213a3', 'ჩვენ ერთი გუნდი ვართ! 💖', 'რთული დღის შემდეგ პარტნიორთან პირისპირ დაჯექით და გულწრფელად ისაუბრეთ. ერთმანეთის მხარდაჭერა ტვირთს ანახევრებს.'),
  ('92cb503c-c013-47cb-ab12-416c047b2693', 'განვითარების შემოწმება 🤖', 'გჭირდებათ ინფორმაცია 12 თვის ბავშვის მოტორული უნარების შესახებ? სთხოვეთ Anacan AI-ს მოკლე, ზუსტი და პედიატრის მიერ დამტკიცებული სია.'),
  ('f20aef27-fde2-489c-9dd8-fe28386cf1db', 'გეომეტრიული ფიგურები და გონების სავარჯიშო თამაშები! 🧩', 'ბავშვი ცდილობს, წრე ან კვადრატი შესაბამის ჭრილში მოათავსოს. უკვდავყავით ეს შემეცნებითი აღმოჩენები ბავშვის ალბომში.'),
  ('0955065c-ecf1-48ed-9f6f-735958386a41', 'ვიტამინები დედისთვის 🥑', 'მის დასანაყრებლად ყველაფერს აკეთებთ. თქვენზე ვინ იზრუნებს? ჯანსაღი რეცეპტების განყოფილებიდან აირჩიეთ რკინითა და კალციუმით მდიდარი მსუბუქი სადილი.'),
  ('1d781ae8-7800-48ae-b0ee-fe44c7f13291', 'დღის ძილი იცვლება? 🥱', 'ბავშვი დღის ორი ძილიდან ერთ-ერთს სრულიად ეწინააღმდეგება? 1 წლის შემდეგ ერთჯერად ძილზე გადასვლა იწყება. ნელ-ნელა შეცვალეთ მისი დღის რეჟიმი.'),
  ('61536a43-b97b-4fe8-8f6a-f358141baefc', 'ზღაპრით ჩაძინება 🪄', '„ჭკვიან ზღაპრებში“ შექმენით მამაცი და საყვარელი ცხოველების ამბავი და ოთახი ჯადოსნურ ადგილად აქციეთ.'),
  ('76e3844a-efe7-4daa-855a-4cfd4d92bfc9', 'ჩააქრეთ მკვეთრი განათება 🌙', 'დაძინებამდე 1 საათით ადრე სახლში გამორთეთ ყველა მკვეთრი განათება და ეკრანი. მელატონინი მხოლოდ მშვიდ და სუსტად განათებულ გარემოში გამოიყოფა.'),
  ('8b586560-e2d2-46b0-ba82-419bb7b56682', 'მეხსიერების დაბინდვა 🛒', 'გულმავიწყობა თავს არ განებებთ? სახლისთვის საჭირო წვრილმანების ყიდვაზე ნუ იფიქრებთ — მაშინვე დაამატეთ საყიდლების სიაში და თქვენს პარტნიორს მიანდეთ.'),
  ('b87394f8-5f2b-4eb7-a491-26b80560c8a3', 'მიზანმიმართული სროლა ⚾', 'ბავშვი ცდილობს, ხელში დაჭერილი სათამაშო განზრახ ისროლოს კონკრეტული სამიზნისკენ. თვალისა და ხელის კოორდინაცია სწრაფად ვითარდება. ერთად ითამაშეთ ბურთის სროლა-დაჭერა.'),
  ('078c86a9-a3c8-4f20-a27a-3aa00d3961ad', 'ჭამის დროის გართობა! 🥦', 'თუ ბავშვი უმადოდაა, დამატებითი კვების დამწყები ბავშვებისთვის განკუთვნილი რეცეპტების განყოფილებიდან მოამზადეთ ფერადი და თვალშისაცემი ულუფები.'),
  ('3b7df91a-7022-4a50-9438-82f89b2240b8', 'სხეულის ნაწილებს ცნობს 👀', 'როცა ეკითხებით: „თვალი სად გაქვს?“, თითით ეხება და გაჩვენებთ? მისი შემეცნებითი უნარები პიკზეა! ამ მიღწევას განვითარების მონიტორში სიამაყით მონიშნეთ.'),
  ('f55bcf4b-2f37-47d2-8e08-b8c72b1b9a56', 'თქვენ ყველაფერს საუკეთესოდ აკეთებთ! 💖', 'ბავშვის აღზრდა მარათონს ჰგავს. ამ საღამოს ცოტა დრო საკუთარ თავს დაუთმეთ, უყურეთ საყვარელ ფილმს ან უბრალოდ დაისვენეთ.'),
  ('18eaf932-80c3-47ae-a394-f6ce083ef215', '„მე თვითონ შევჭამ!“ 🥦', 'სურს, კოვზი ხელიდან გამოგართვათ. მიეცით საშუალება. ტანსაცმელი დაესვრება, მაგრამ დამოუკიდებლობის ეს განცდა მისთვის ძალიან მნიშვნელოვანია.'),
  ('b55b3812-173b-489f-a2ae-d2c78611fd35', 'სიბნელესთან დამეგობრება 🌙', 'უფრო სწრაფად რომ ჩაეძინოს, საღამოს რუტინას სიბნელესთან შეგუებაც დაამატეთ. ოთახში ყველა დამატებითი სინათლის წყარო გამორთეთ.'),
  ('c9fb44a1-ad82-4f16-a316-50d99863130e', 'ალერგიაზე ეჭვი 🤖', '1 წლის შემდეგ ახალი საკვების მიცემა დაიწყეთ? თუ რაიმე გაწუხებთ, პირველი ნაბიჯების შესახებ დაუყოვნებლივ ჰკითხეთ Anacan AI-ს.'),
  ('159279c3-df89-49cf-a71c-bb577a8dd0c3', 'სახიფათო ზონებზე წვდომა ⚡', 'მისი სიმაღლე კიდევ გაიზარდა და ახლა იმ თაროებსაც სწვდება, რომლებსაც ადრე ვერ წვდებოდა. სასწრაფოდ გადახედეთ სახლის უსაფრთხოებას.'),
  ('3b6ac273-a759-45de-9492-87af2df8cac9', 'ღამის სიჩუმე 🤫', 'თუ მანქანის ან გარედან შემოსული ხმები მას აწუხებს, აუცილებლად შეამოწმეთ გარემო ხმის საზომით და ფონად თეთრი ხმაური ჩართეთ.'),
  ('bc24cbab-3bcd-4b5b-92fb-249b861079c2', 'ყველაფერს, რითაც თამაშობს, აქეთ-იქით ყრის.  🌪️', 'მთავარი სისუფთავე კი არა, თქვენი დასვენებაა. სათამაშოები ხვალაც იქ იქნება, მაგრამ ენერგიით სავსე დედა ახლაა საჭირო.'),
  ('0693172d-9675-431e-ae2b-b1d735f8da0f', 'მთელი დაღლილობა გვერდზე გადადეთ.', 'არ დაგავიწყდეთ, ამ საღამოს, ბავშვის დაძინების შემდეგ, პარტნიორთან ერთად აღნიშნოთ თქვენი გუნდური გამარჯვება!'),
  ('3e6bfa0e-5f58-4921-bf7a-6f47b0eb1125', 'ნუ შეადარებთ საკუთარ თავს სხვებს 🛑', 'დაივიწყეთ ფრაზა: „ამა და ამ ადამიანის ბავშვმა უფრო ადრე დაიწყო ლაპარაკი“. ყველა ბავშვს განვითარების უნიკალური ტემპი აქვს. თქვენ უბრალოდ სიყვარული აჩუქეთ.'),
  ('b9520b22-b9b3-4ca3-a219-de05702404a8', '1 წლისა და ნახევარი თვის ასაკისკენ! 📸', 'ის უკვე 12.5 თვისაა! გახსენით ბავშვის ფოტოსესია და ამ მოუსვენარი, ქარიშხალივით დატრიალებული ბავშვობის პერიოდის ყველაზე სახალისო მომენტები ფოტოებზე აღბეჭდეთ.'),
  ('0c105765-0e1a-42dd-bd14-0ca4153705c0', 'წვრილი მოტორიკა ვითარდება. 🖍', '️ მას შეიძლება ძალიან მოეწონოს ფანქრით ქაღალდზე ხაზების გავლება. მიეცით მისთვის შესაფერისი სქელი ფერადი ფანქრები და თვალი ადევნეთ მის შემოქმედებით პროცესს.'),
  ('1b77ed52-4cf2-48a6-98fc-53d0a94dc968', 'ძილის რუტინა უსაფრთხოების განცდას ქმნის. 🌙', 'ყოველ საღამოს ერთი და იმავე თანმიმდევრობით შესრულებული მოქმედებები (აბაზანა, ზღაპარი, განათების ჩაბნელება) დაეხმარება, უფრო მშვიდად დაიძინოს.'),
  ('795996e4-e3e1-4fa7-b442-27c8ffa35bff', 'კბილების ამოჭრის ტკივილი 🦷', 'ღრძილები ისევ გაუწითლდა და ნერწყვდენა არ წყდება? კბილების ამოჭრის ტრეკერში მონიშნეთ ეს პროცესი და მოამზადეთ გაცივებული კბილების მოსაფხანი სათამაშოები.'),
  ('452e9fa3-8dba-4774-8bfe-d6afa50d161c', 'სია ნამდვილი მხსნელია 🛒', 'ხილი ან შვრიის ფაფა გაგითავდათ? დაუყოვნებლივ შეავსეთ საყიდლების სია და საჭირო პროდუქტების ჩამონათვალი პარტნიორის ტელეფონზე გაგზავნეთ.'),
  ('8c12c251-a9b5-45cb-92ff-f145e2484025', 'საყრდენზე ხელის მოკიდებით დადის 🧗‍♀️', 'ავეჯის კიდეზე ხელის მოკიდებით გვერდულად ნაბიჯების გადადგმა მისი საყვარელი ვარჯიშია. დამოუკიდებელ ნაბიჯებამდე სულ ცოტა დარჩა! გადახედეთ განვითარების ტრეკერს.'),
  ('c7e52a2b-46d5-4446-b455-907f7523256e', 'აკონტროლეთ ხმაური 🤫', 'ჩაძინებიდან პირველი ნახევარი საათი ყველაზე მგრძნობიარე პერიოდია. ხმაურის საზომით შეამოწმეთ გარემო და მოერიდეთ უეცარ ხმაურს.'),
  ('56403a92-c6d5-492f-b073-20bcd436f218', 'მამის ღამის მორიგეობა 👨‍🍼', 'ღამით გაღვიძების მთელი ტვირთი მარტო ნუ მოგაქვთ. გააღვიძეთ პარტნიორიც — გუნდურობა პასუხისმგებლობის თანაბრად განაწილებას ნიშნავს.'),
  ('763e2885-6f82-4d6b-8ec4-680155ad7a5f', 'დედების გულახდილი საუბარი 💬', 'ტანტრუმებთან გამკლავება გიჭირთ? დაუყოვნებლივ შეუერთდით Anacan-ის საზოგადოებას, წაიკითხეთ სხვა დედების მხარდამჭერი კომენტარები და შვება იგრძენით.'),
  ('f47e2fcf-5030-43a8-a77b-79834cb3f95a', 'დიდი ემოციები, პატარა სხეული 🛑', 'როცა სასურველს ვერ იღებს, იატაკზე წვება და ბრაზობს? მის სიმაღლეზე დაიხარეთ და მშვიდად ესაუბრეთ, რათა კრიზისული მომენტი ერთად გადალახოთ.'),
  ('a0e7f0f6-1438-4f75-acb4-559e4df47974', 'სიმშვიდის საჭიროება 🤫', 'ოთახში სიმშვიდე ხმის საზომის დახმარებით შეინარჩუნეთ. ღამით შეწყვეტილი ძილი დილით როგორც ბავშვის, ისე თქვენს განწყობაზე უარყოფითად მოქმედებს.'),
  ('dfa800b1-6c2e-4bc9-b061-4b6d1df9eb95', 'სივრცე დედისთვის ☕', 'სახლში ყოფნამ ენერგია გამოგაცალათ. დედებისთვის მეგობრული სივრცეებიდან შეარჩიეთ კაფე, სადაც კომფორტულად მოკალათდებით, და საკუთარ თავს დრო დაუთმეთ.'),
  ('f34137b7-333a-47bb-8fab-66dd8be52bfb', 'ცეკვა და რიტმები 🎶', 'ტელევიზორში ან ტელეფონში რიტმული ხმის გაგონებისთანავე ცეკვას იწყებს? მისი მუსიკალური აღქმა უკვე სრულად გააქტიურებულია — შეუერთდით და ერთად იცეკვეთ!'),
  ('8a51b6b4-96e5-40da-8e4b-a3f74c147eb5', 'საღამოს ზღაპარი ჯადოსნურია. 📖', 'ძილის წინ წაკითხული მოკლე ამბავი არა მხოლოდ წარმოსახვას ავითარებს, არამედ თქვენ შორის ემოციურ კავშირსაც აძლიერებს.'),
  ('b28c4699-a204-48ae-80c2-bef5008fdffd', 'დამოუკიდებლად თამაშის უნარი. 🧩', 'თუნდაც მცირე ხნით დამოუკიდებლად თამაში რომ შეუძლია, მისი ყურადღების განვითარების ნიშანია. ასეთ დროს სიყვარულით დააკვირდით შორიდან.'),
  ('e6b48652-88e0-49d8-b2cc-654a9f8eb626', 'ზრდას თვალყურს ვადევნებთ. 📏', 'თქვენი ბავშვის ტანსაცმელი უკვე ეპატარავება? წონის მონიტორინგის განყოფილებაში ახალი მონაცემები დაამატეთ და მისი ჯანსაღი განვითარება აღრიცხეთ.'),
  ('05e8d5ea-453b-4a35-a697-81e0b9ca911a', 'უფროსების მიბაძვა 🧹', 'როცა სახლს ალაგებთ, ისიც იღებს ხელში ტილოს და ცდილობს, იგივე გააკეთოს? ის თქვენი სარკეა! ყველაფერს იმეორებს, რასაც აკეთებთ.'),
  ('13c2fa37-beb3-4b36-a1a9-4ba3fd32e6a0', 'პარკი თუ სახლი? ⛅', 'გარეთ გასვლა გსურთ, მაგრამ ქარია. ამინდისა და ტანსაცმლის ასისტენტი მყისიერად გირჩევთ შესაფერის სამოსს.'),
  ('ecb2b9d1-a640-4303-b570-f3c7f463e0ab', 'ჭირვეული ღამეები 🥱', 'მთელი ძალით ეწინააღმდეგება დაძინებას? კიდევ ერთხელ გადაამოწმეთ დღის ძილის განრიგი და ყოველდღიური რუტინა.'),
  ('9dd82a43-7f3a-4a5e-9d01-a99d7d738015', 'დამოუკიდებლად ჩაცმის მცდელობები. 👕', 'უკვე ცდილობს წინდების დამოუკიდებლად გახდას ან ჩაცმას? მოთმინებით შეუწყვეთ ხელი მისი წვრილი მოტორული უნარების განვითარებას.'),
  ('ccf44d60-2dc0-447f-b1ea-dd06a80f0324', 'წყლის დალევა ძალიან მნიშვნელოვანია. 💧', 'აქტიურ ბავშვებს სწრაფად სწყურდებათ. არ დაგავიწყდეთ, დღის განმავლობაში, განსაკუთრებით კი ვახშმის შემდეგ, წყალი შესთავაზოთ.'),
  ('d4a01ba0-4f2b-45a3-8cb0-3f2fa493585d', 'ახალი სათამაშო გჭირდებათ? 🛒', 'თუ ბავშვის განვითარებაზე მორგებულ, შემეცნებით და გონების განმავითარებელ სათამაშოებს ეძებთ, გაეცანით რეკომენდებული პროდუქტების სიას.'),
  ('10934358-ef97-4dab-87ad-73a62aee1231', 'დალაგება თუ დასვენება? 🛋️', 'როდესაც ბავშვს სძინავს, ჭურჭლის სარეცხი მანქანისკენ ნუ გაიქცევით. წამოწექით დივანზე, დახუჭეთ თვალები და 15 წუთის განმავლობაში უბრალოდ ისუნთქეთ.'),
  ('58866969-75c5-44cd-a308-210945d7a2af', 'ცდა და შეცდომა 🧱', 'ცდილობს, ორი სათამაშო კუბი ერთმანეთზე დააწყოს, მაგრამ ისინი ცვივა. ყურადღებით აკვირდება და კვლავ ცდილობს. ჩუმად მიადევნეთ თვალი მის საინჟინრო მცდელობებს.'),
  ('94a9a306-04fb-42bb-9962-95b473b02f89', 'ემოციების დღიური 📝', 'როდესაც თავს მარტოდ გრძნობთ, თქვენი ემოციები განწყობის დღიურში გადმოიტანეთ. ყველა ქალი გადის ამ გზას — თქვენ ძლიერი ხართ.'),
  ('8a5f3751-2bcd-4454-bfef-74c90f1c3f85', 'დღის დასასრული — თქვენი დროა. 🛁', 'დღეს ძალიან დაიღალეთ? მიიღეთ თბილი შხაპი, დაისვენეთ და მადლობა გადაუხადეთ საკუთარ თავს ყველაფრისთვის, რაც გააკეთეთ.'),
  ('dcaa4b27-ca42-45e3-98f1-f11ad70e3dc8', 'სხეულის ნაწილებს ვსწავლობთ! 👃', 'როდესაც ეკითხებით: „სად არის შენი ცხვირი?“, პატარა თითით მიგითითებთ? ეს საყვარელი აღმოჩენები სარკის წინ სახალისო თამაშად აქციეთ.'),
  ('e70adad3-3a0b-4d15-ab3c-9f286916a872', 'ჯანსაღი წასახემსებლის დროა. 🍎', 'დაუშრეტელი ენერგიის მქონე ბავშვებისთვის ხილის ნაჭრები ან ბოსტნეულის ჩხირები შესანიშნავი არჩევანია. მიეცით საშუალება, თავად დაიჭიროს და მიირთვას.'),
  ('6b0a9309-594c-4f0a-a15f-6c0611c0d5c3', 'პატარა მხატვარი მუშაობს! 🖍', '️ მიეცით მსხვილი ფერადი ფანქრები და საშუალება მიეცით, ფურცელზე თავისუფლად ჯღაბნოს. ეს ძალიან სასარგებლოა ნატიფი მოტორიკისა და შემოქმედებითი უნარების განვითარებისთვის.'),
  ('ccb3a3d0-8dc5-450a-b184-37cf81a39c01', 'სუფთა ჰაერი ორივეს სასარგებლოდ მოგემსახურებათ. 🌳', 'დედებისთვის მეგობრული ადგილების ჩვენს რუკაზე იპოვეთ ახალი პარკი, სადაც ბავშვის ეტლით კომფორტულად გაისეირნებთ, და სასეირნოდ გაემართეთ.'),
  ('dd0a1e57-cbbc-4cc0-9c63-a03032174ab5', 'ძილის რუტინა უსაფრთხოების განცდას ქმნის. 🌙', 'ყოველ საღამოს ერთი და იმავე თანმიმდევრობით შესრულებული მოქმედებები (აბაზანა, ზღაპარი, განათების ჩაქრობა) ბავშვს უფრო სწრაფად დაძინებაში დაეხმარება.'),
  ('12139491-dd07-42f8-b056-98645d9880be', 'წამი, რომელიც დროს აჩერებს 📸', 'ის ყოველდღე ცოტათი უფრო იზრდება. ახლავე გახსენით ბავშვის ფოტოსესია და მისი ეს გულწრფელი მომენტი სამუდამოდ აღბეჭდეთ.'),
  ('302d3885-ce15-4277-a0cf-d95f95d7ed63', 'ჩააქრეთ შუქები 🌙', 'დაძინებამდე 1 საათით ადრე სახლში ჩააქრეთ ყველა მკვეთრი შუქი და გამორთეთ ეკრანები. მელატონინი მხოლოდ მშვიდ გარემოში გამომუშავდება.'),
  ('78f8f713-17f3-46f4-83f8-9cdbfd0c9894', 'დამოუკიდებლად თამაშის დრო 🧸', 'მას უკვე შეუძლია 10-15 წუთის განმავლობაში დამოუკიდებლად გაერთოს თავისი სათამაშოებით. შორიდან თვალი ადევნეთ და სიჩუმით დატკბით.'),
  ('a72fe5b0-0907-43fb-b4ef-fc4dd880fecd', 'ამინდის დაზვერვა ⛅', 'გარეთ ამინდი არასტაბილურია? ამინდისა და ჩაცმულობის ინსტრუმენტი მყისიერად გეტყვით ქარის სიჩქარეს და შეგირჩევთ შესაფერის სამოსს.'),
  ('bac8ff9b-6338-4b34-a5d6-84b7aefd251c', 'მამის ღამის მორიგეობა 👨‍🍼', 'ღამით ბავშვის გაღვიძებას მარტო ნუ გაუმკლავდებით. გააღვიძეთ პარტნიორიც — გუნდურობა პასუხისმგებლობის თანაბრად განაწილებას ნიშნავს.'),
  ('c1daed2c-e22f-4c5a-8534-4ff90b6b866e', 'ჩემს სათამაშოს თავად ვპოულობ 🧸', 'მიდის და პოულობს თვალს მოფარებულ სათამაშოს იქ, სადაც ის დამალეთ? ესე იგი, უკვე ესმის, რომ საგანი მაშინაც არსებობს, როცა ვერ ხედავს!'),
  ('04429520-36d1-489e-8ec7-309a2c08ae92', 'ჩვენ ერთი გუნდი ვართ! 💖', 'რთული დღის შემდეგ თქვენს პარტნიორთან პირისპირ დაჯექით და გულწრფელად ისაუბრეთ. ერთმანეთის მხარდაჭერა ტვირთს ანახევრებს.'),
  ('05fff0e7-029c-401c-bfab-497bbc099997', 'სიტყვების მნიშვნელობა ესმის 🗣️', 'როცა ეუბნებით, ბურთი მოიტანოს, მართლაც მიდის და მის ძებნას იწყებს. მისი სიტყვათა მარაგი სწრაფად იზრდება. ესაუბრეთ უფრო რთული წინადადებებით.'),
  ('ec4b2f26-3631-4fed-9578-c9539a35a5c0', 'სია თქვენს ჯიბეში 🛒', 'ყოველდღიურ ქაოსში დაგავიწყდათ, შამპუნი გათავდა თუ საფენები? ნუ ეცდებით ყველაფრის დამახსოვრებას — ჩაწერეთ საყიდლების სიაში და თქვენს პარტნიორს გაუზიარეთ.'),
  ('663824a2-b8fe-471a-b981-3eb69f3a2c7f', 'დიდი ემოციები, პატარა სხეული. 🌪', '️ როცა საკუთარი გრძნობების გამოხატვა არ შეუძლია, გაბრაზება და ტირილი ნორმალურია. მის სიმაღლემდე დაიხარეთ და მშვიდი ხმით უთხარით, რომ მისი გრძნობები გესმით.'),
  ('8be96289-58a8-4a48-89ec-c4ba0488e973', 'წყლით თამაში ამშვიდებს. 💧', 'პატარა ტაშტში წყალი ჩაასხით და შიგ პლასტმასის ჭურჭელი ჩააწყვეთ. წყლით თამაში ბავშვებს ენერგიის დახარჯვასა და მოდუნებაში ეხმარება.'),
  ('a70fb0ff-98b0-4735-ac10-846168dd5d60', 'კითხვა გაქვთ? 🤖', 'ისეთი მნიშვნელოვანი კითხვები, როგორიცაა „როგორ გავუმკლავდეთ 1 წლის ასაკის კრიზისს?“, შეგიძლიათ ღამის საათებშიც დაუსვათ ჩვენს Anacan AI ასისტენტს და ექსპერტის რჩევა მიიღოთ.'),
  ('2a991705-4255-4931-9ad5-cef8eb9bf0dd', 'თქვენი პატარა დამხმარე! 🧹', 'თქვენ გბაძავთ, ხელში ტილოს იღებს და მტვრის გადაწმენდას ცდილობს? აუცილებლად გადაიღეთ ეს საყვარელი და შემეცნებითი მომენტები და სამახსოვროდ ბავშვის ალბომში ვიდეოს სახით დაამატეთ.'),
  ('813ebcca-fa4c-42de-926c-6ca1c1526de6', 'სიმშვიდე მუსიკასთან ერთად. 🎶', 'საღამოს აქტიური თამაშების ნაცვლად უფრო მშვიდ მუსიკას მოუსმინეთ, რათა ბავშვი ძილისთვის, საკუთარი თავი კი დასვენებისთვის მოამზადოთ.'),
  ('ce071e13-068a-4c5a-8d4c-437e6f25658d', 'საკვების არჩევითობა. 🍲', 'თუ ბავშვი გარკვეულ საკვებზე უარს ამბობს, ნუ ინერვიულებთ. სხვადასხვა დღეს კვლავ შესთავაზეთ განსხვავებული სახით (მაგალითად, არა პიურედ, არამედ ხელით ასაღები საკვების სახით).'),
  ('502b8118-151f-47c7-9476-eb53fa55cfd0', 'კოშკები მაღლდება! 🧱', 'მას უკვე შეუძლია 3-4 კუბიკის ერთმანეთზე დაწყობა. შეაქეთ და მხარი დაუჭირეთ ამ თამაშში, რომელიც ყურადღებასა და თვალისა და ხელის კოორდინაციას მოითხოვს.'),
  ('af470a51-532a-4658-877a-26e61845210a', 'სოციალიზაციის დროა. 👶', 'პარკში სხვა ბავშვებს ყურადღებით აკვირდება? მართალია, ჯერ ერთად არ თამაშობენ, მაგრამ გვერდიგვერდ თამაში (პარალელური თამაში) სოციალიზაციისკენ გადადგმული პირველი დიდი ნაბიჯია.'),
  ('ceb1c77d-c486-4755-b204-47ec200fcd34', 'მას თქვენი ხმის ტონი ესმის 🗣️', 'როდესაც მკაცრი ხმით ეუბნებით „არას“, ჩერდება და გიყურებთ? ის უკვე იწყებს ემოციებისა და აკრძალვების აღქმას!'),
  ('53cb1b60-78f0-41c1-a42e-b48a4324533b', '400-დღიანი მღელვარება! 🌟', 'ხვალ დიდი, მე-400 დღეა! 1 წელსა და 1 თვეზე მეტიც კი! სახლში პატარა სადღესასწაულო განწყობა შექმენით და ტელეფონის მეხსიერებაში ადგილი გაათავისუფლეთ.'),
  ('9e145532-f5a6-48ed-a07c-a3e9fc574858', 'მასაჟის დროა 💆‍♂️', 'როცა ბავშვი დაიძინებს, დღის სტრესის მოსახსნელად პარტნიორთან ერთად ერთმანეთს მხრების მასაჟი გაუკეთეთ. თქვენ ერთი გუნდი ხართ!'),
  ('fab52013-4ea8-458f-b397-01341fb91dad', 'საკუთარი თავის პატიების საღამო 📝', 'დღეს ყველაფერზე გაღიზიანდით? როცა ბავშვი დაიძინებს, თქვენი გრძნობები განწყობის დღიურში ჩაიწერეთ. ხვალ ახალი და უფრო მშვენიერი დღე იქნება.'),
  ('165064a6-acf5-4848-b342-4a3782635921', 'შესანიშნავი 400 დღე! 🎉', 'გილოცავთ! უკვე ზუსტად 400 დღეა, რაც ამ ქარიშხლიან გზას ერთად მიუყვებით! დაუყოვნებლივ აღნიშნეთ ეს განსაკუთრებული დღე!'),
  ('894151c3-97b8-419f-9602-aa08da619716', 'განაგრძეთ დამოუკიდებლად ჭამის წახალისება. 🥄', 'ტანსაცმელიც რომ დაისვაროს, მიეცით საშუალება, საკუთარი კოვზით ჭამა სცადოს. ეს მის თავდაჯერებულობასა და კუნთების კოორდინაციას ავითარებს.'),
  ('8c8e0b49-c38c-485a-b336-5facb1258a02', 'თქვენ საუკეთესო ხართ! ✨', 'ფასდაუდებელია თავდადება, რომელსაც ამ 400 დღის განმავლობაში იჩენდით. ახლა ღრმად ჩაისუნთქეთ, კომფორტულად მოკალათდით და მშვიდად დაისვენეთ.'),
  ('05dbf09b-2a49-4886-a4e4-6f85e7cbea42', 'ოთხ კედელს მიღმა ⛅', 'ბავშვი სახლში ენერგიას ვერ ხარჯავს და ჭირვეულობს? ბუნება საუკეთესო დამამშვიდებელია. გაითვალისწინეთ ამინდი, შეურჩიეთ შესაფერისი ტანსაცმელი და პირდაპირ პარკისკენ გაემართეთ.'),
  ('3cf4affc-53f5-4c77-84f1-006d5732e36a', 'მამასთან თამაშის დრო 👨‍👧', 'მთელი დღე მისდევდით და ფეხზე ძლივს დგახართ. ახლა პარტნიორის რეჟიმის დროა. იატაკზე გორაობა და ცხენობანას თამაში მამას მიანდეთ. თქვენ კი დაისვენეთ.'),
  ('f1269e86-21d6-4d2f-83e1-31926957408a', 'ოთახებს შორის მარათონი 🏃‍♂️', 'სიარული აღარ ჰყოფნის — უკვე ოთახიდან ოთახში დარბის! ფეხზე დგომისას წონასწორობა სრულად უყალიბდება. განვითარების ტრეკერში აღნიშნეთ მსხვილი მოტორიკის ეს დიდი მიღწევა.'),
  ('7df527b0-7bf7-42d6-b9f4-0f231186e70c', 'მენიუს დიქტატორი 🥣', 'დღეს გვერდზე სწევს საჭმელს, რომელიც გუშინ უყვარდა? კვების მიმართ პრეტენზიულობა 1 წლის შემდეგ ნორმალურია. ნუ აჰყვებით პანიკას — ჯანსაღ რეცეპტებში განსხვავებული ალტერნატივები მოძებნეთ.'),
  ('85bb394b-b9a2-4a30-a34a-98479663ff2d', '„ეს რა არის?“ პერიოდი ☝️', 'ყველაფერზე თითით მიუთითებს და განსაკუთრებულ ხმას გამოსცემს. მას სურს, რომ მის გარშემო არსებულ სამყაროს სახელები თქვენ დაარქვათ. მოთმინებით უთხარით თითოეული ნივთის სახელი, რომელზეც მიგითითებთ.'),
  ('f78a5d11-ba9f-41e9-8557-2840d12964be', 'გაუშვით დანაშაულის განცდა 📝', 'დღეს ცოტა წავუკითხე, ეკრანს დიდხანს უყურა... გააჩუმეთ ეს ხმები! თქვენ მაქსიმუმს აკეთებთ. განწყობის დღიურში საკუთარი თავის მიმართ თანაგრძნობით სავსე ჩანაწერი გააკეთეთ.'),
  ('1167974e-3206-4f0f-b4e8-4d14f35444b6', 'ერთ ძილზე გადასვლა 🥱', 'ბავშვს დილით დაძინება აღარ სურს და მთელი განრიგი აირია? ის იზრდება! შესაძლოა, დღის განმავლობაში ორი ძილიდან ერთ ძილზე გადასვლის პერიოდი იწყება. თანდათან შეცვალეთ მისი ყოველდღიური რეჟიმი.'),
  ('8017b10d-4bdb-4fe5-8a0b-20ae132c6ec2', 'ჯადოსნური ოთახი 🪄', 'ჭკვიან ზღაპრებში შექმენით განსაკუთრებული ამბავი მამაც გმირზე, რომელიც სამყაროს იკვლევს. ამ საყვარელი ზღაპრით ბავშვს ღამის ძილისთვის მომზადება გაუადვილეთ.'),
  ('c7ad498c-1a79-4b6f-a5e5-0ac0b264682c', 'დედებისთვის შესაფერისი ადგილების აღმოჩენა ☕', 'სახლში ერთი და იმავე კედლების ყურებამ დაგღალათ. დედებისთვის შესაფერის ადგილებს შორის აღმოაჩინეთ კაფე, სადაც საბავშვო სათამაშო კუთხეა. ბავშვმა ითამაშოს, თქვენ კი ყავით დატკბით.'),
  ('5b41e7e4-7a14-41e6-a7a1-c4a7838db66b', 'ერთად წაიკითხეთ წიგნი. 📖', 'მას უკვე თავად სურს გვერდების გადაფურცვლა. სქელფურცლიანი წიგნები და აუდიოზღაპრები ამ პერიოდისთვის იდეალურია.'),
  ('d29d33a4-aed4-4635-9f37-3a7a39a378b0', 'საზღვრებს ამოწმებს. 🛑', 'მიუხედავად იმისა, რომ უარი უთხარით, თვალებში გიყურებთ და მაინც იმ ნივთისკენ იწევს? ეს სიჯიუტე არ არის — ბავშვი უბრალოდ საზღვრებს ამოწმებს და სწავლობს. გამოიჩინეთ მოთმინება და თანმიმდევრულობა.'),
  ('f3355fe9-0c3b-41e2-9043-0a5cb8a61740', 'ღამით გაღვიძება. 😴', 'კბილების ამოსვლამ ან ზრდის ნახტომმა შესაძლოა ძილი დაარღვიოს. საჭიროების შემთხვევაში, ძილის ტაიმერის მეშვეობით თვალი ადევნეთ და რეჟიმში მომხდარი ცვლილებები ჩაინიშნეთ.'),
  ('2e0b0129-5a3d-466c-a35f-ef4707dea065', 'მამისგან მიღებული ნუგეში 🫂', 'ღამით გაღვიძებისას აუცილებლად მონაცვლეობით იზრუნეთ ბავშვზე. ზოგჯერ სიბნელეში მხოლოდ მამის რიტმული მოფერება და სურნელი ამშვიდებს ბავშვს მყისიერად.'),
  ('812159bf-a0a9-4bf9-8e7b-97d82abbaa80', 'პატარა სარკე, რომელიც უფროსებს ბაძავს 🧹', 'როცა სახლს ალაგებთ, ისიც იღებს ტილოს და ცდილობს, იგივე გააკეთოს. ის თქვენი პატარა ასლია! მიეცით უსაფრთხო ნივთი და საოჯახო საქმეებში ჩართეთ.'),
  ('9510e83b-c10c-4166-b921-d1cd3c8f203c', 'გულმავიწყობასთან ბრძოლა 🛒', 'მეხსიერებამ კვლავ გიმტყუნათ? სახლში რაიმე წვრილმანი რომ გათავდება, მაშინვე დაამატეთ საყიდლების სიაში, რათა თქვენმა პარტნიორმა სამსახურიდან დაბრუნებისას იყიდოს.'),
  ('0a5f0553-0fcd-480d-a18f-a3ecfcfe950c', 'ლოგიკური თამაშები 🧩', 'სათამაშოებს ყუთში ყრის და შემდეგ ყველას ისევ იღებს? ასე ის „შიგნით“ და „გარეთ“ ცნებებს იაზრებს. ჩუმად დააკვირდით მის ამ განმეორებით მცდელობებს.'),
  ('302bafdb-c5ca-4389-a56e-16a2ddd6812b', 'საღამოს რუტინის ძალა 🛀', 'თბილი აბაზანა ყოველთვის ეფექტურია. საღამოს რუტინა არასოდეს დაარღვიოთ, რადგან ის ბავშვის ტვინს მკაფიო სიგნალს აძლევს, რომ ახლა ძილის დროა.'),
  ('309b39de-d5f5-4702-93e1-596dca9c9021', 'აღიდგინეთ ენერგია 🥑', 'თუ ბავშვი დანაყრდა, ახლა თქვენი ჯერია. ყოველდღიურ სირბილში სადილი ფეხზე მდგომმა არ მიირთვათ. ჯანსაღი რეცეპტებიდან ენერგიის მომცემი წასახემსებელი შეარჩიეთ და დივანზე წამოწექით.'),
  ('66b4bd9b-8226-4190-94c7-9d50f8db6c34', 'გულითადი საუბარი გჭირდებათ 💬', 'ფიქრი — „რატომ იქცევა ჩემი ბავშვი ასე?“ — მოსვენებას არ გაძლევთ? შეუერთდით Anacan-ის საზოგადოებას, წაიკითხეთ სხვა დედების მსგავსი ისტორიები და დამშვიდდით.'),
  ('80e6be85-6917-46a0-b283-acc653cca6c1', 'წიგნის ფურცვლით განვითარებული გონება 📖', 'სქელფურცლიანი წიგნების გვერდებს ფურცლავს და სურათებზე რეაგირებს? მისი მხედველობითი მეხსიერება ვითარდება. ხშირად წაუკითხეთ ფერადი ზღაპრების წიგნები.'),
  ('df1f7c26-41ff-4081-9b25-dae8d38c75e8', 'თქვენთან ერთად გატარებული დრო მშვენიერია. ✨', 'მისთვის ყოველი დღე ახალი თავგადასავალია. როცა დაიძინებს, შეხედეთ მის პატარა ხელებს და დღევანდელი მცირე მიღწევების გამო გაიღიმეთ.'),
  ('52e92eba-b885-4c30-891d-aa6e5379acf9', 'დამოუკიდებლად ჭამის სურვილი 🥄', 'კოვზს ხელიდან გართმევთ და თავად სურს ჭამა. საჭმელი დაეღვრება და დაისვრება, თუმცა ეს მისი მოტორული უნარების განვითარებისთვის მნიშვნელოვანია. მიეცით დამოუკიდებლად მოქმედების საშუალება.'),
  ('a26c1e0d-7872-4f7e-9268-2fba22c9203a', 'კითხვა გაქვთ? 🤖', 'თუ 13-14 თვის ბავშვის ქცევასა ან განვითარებასთან დაკავშირებით კითხვები გაქვთ, ჩვენი Anacan AI ასისტენტისგან რჩევის მიღება მყისიერად შეგიძლიათ.'),
  ('eb8ab523-6225-489f-8a09-0f37ba40956a', 'ენერგიის დახარჯვა! 🏃‍♂', '️ შუადღის ძილის წინ ითამაშეთ მასთან აქტიური თამაშები (დაჭერობანა, ბურთის სროლა), რომლებიც ცოტათი დაღლის და მშვიდად დაძინებაში დაეხმარება.'),
  ('5d99a4ad-d33f-448d-9f7c-32943cbfa648', 'უკანა კბილები ამოსვლას იწყებს? 🦷', 'ღრძილები შეშუპებული აქვს და ყველაფერს ღრღნის? შესაძლოა, უკანა კბილები ამოსდიოდეს. ცივი კბილების ამოსაჭრელი სათამაშოები საყინულეში მოათავსეთ.'),
  ('70d7d4ed-5c06-44bc-99e5-3871d07a9510', 'შეამცირეთ განათება 🌙', 'დაძინებამდე 1 საათით ადრე სახლში ყველა კაშკაშა სინათლე და ეკრანი გამორთეთ. მელატონინი მხოლოდ მშვიდ და სუსტად განათებულ გარემოში გამოიყოფა.'),
  ('aa9c9479-f8d5-4149-b7c4-99976958a17c', 'სახიფათო ადგილებზე წვდომა ⚡', 'ბავშვი გაიზარდა და უკვე იმ თაროებსაც სწვდება, რომლებსაც ადრე ვერ წვდებოდა. ტელევიზორის სადგამი, კუთხეები... სასწრაფოდ გადახედეთ სახლის უსაფრთხოებას.'),
  ('0872925d-e2d7-471e-ba13-22ee468f0a1f', 'უეცარი გაღვიძებები 😭', 'შუაღამისას ყვირილით იღვიძებს და ვერ მშვიდდება? მოასმენინეთ მისი ხმა ტირილის ანალიზის ფუნქციას და გაარკვიეთ პრობლემის მიზეზი.'),
  ('1fe0720b-91d5-4dc9-ad61-71e5ff522246', 'ზრდის ტემპი 📏', 'მის სწრაფ ზრდას ტანსაცმელზეც ამჩნევთ. ტრეკერში წონისა და სიმაღლის მაჩვენებლები ჩაინიშნეთ, რათა დარწმუნდეთ, რომ ბავშვი ჯანსაღად იზრდება.'),
  ('ca5a420a-5b8f-49ce-b884-6a219b8b71aa', 'დიდი ემოციები, პატარა სხეული 🛑', 'როცა სასურველს ვერ იღებს, თავს იატაკზე აგდებს? ეს ადრეული ასაკისთვის დამახასიათებელი ცნობილი ტანტრუმებია. შეინარჩუნეთ სიმშვიდე, დაამყარეთ მასთან თვალით კონტაქტი და აგრძნობინეთ, რომ მის გვერდით ხართ.'),
  ('005096a2-1549-4208-a331-7e39e1da9587', 'სწრაფი პედიატრი 🤖', 'გჭირდებათ ინფორმაცია 13.5 თვის ასაკში განვითარების ნახტომების შესახებ? თავს ნუ გადაიღლით — სთხოვეთ Anacan AI-ს ზუსტი და პედიატრის მიერ დამტკიცებული სია.'),
  ('7de487db-11d1-4c22-8b8d-e58adb31344a', 'მარტივ მითითებებს ასრულებს 🧸', 'როცა ეუბნებით, ფეხსაცმელი მოიტანოს, ნამდვილად მიდის და მოაქვს? მისი სიტყვათა მარაგი და გაგების უნარი პიკზეა! უფრო მეტად ჩართეთ თამაშებში.'),
  ('9089b5ba-67c3-48ba-a5c3-8e428c87d9ec', 'მამის სახალისო მხარე 🤡', 'ბავშვის გაცინების საუკეთესო გზა მამის მიერ უცნაური ხმების გამოცემაა. დატკბით ამ საღამოს მხიარული წუთებით ბავშვთან ერთად.'),
  ('3170ad10-66c6-4ca0-bf72-80b0daf91373', 'საღამოს რუტინა ძილისთვის ამზადებს. 🌙', 'ყოველდღე ერთსა და იმავე დროს შესრულებული პატარა ჩვევები (კბილების გახეხვა, ზღაპრის წაკითხვა) მას ჩაძინებას მნიშვნელოვნად გაუადვილებს.'),
  ('64832db8-28ac-41fb-8d33-21a72b48fa8c', 'ცნობისმოყვარე მკვლევარი! 🔍', 'სახლის ყოველი კუთხე და კარადა მისთვის ახალი სამყაროა. შეუქმენით უსაფრთხო გარემო და მიეცით საშუალება, თავისუფლად გამოიკვლიოს სახლი.'),
  ('f283f219-7efa-4926-a360-3fb653057b9b', 'სუფთა ჰაერი და ბევრი ენერგია! 🌳', 'გარეთ ენერგიის დახარჯვა ბავშვებს დღისით უფრო ადვილად დაძინებაში ეხმარება. ერთად გაეშურეთ პარკში.'),
  ('aa01a859-3ad0-4c64-9ef3-4423ccf76d24', '„არა“-ს თქმა უყვარს? 🛑', 'თქვენი უარის მიბაძვით, მანაც შეიძლება ყველაფერზე „არა“ თქვას. ამ პერიოდში მნიშვნელოვანია, მოთმინება გამოიჩინოთ და მცირე არჩევანი შესთავაზოთ.'),
  ('b8b7257f-64c5-46a3-b958-ded901da8e8d', 'წყლის სმა სახალისო გახადეთ. 💧', 'რეგულარულად შესთავაზეთ წყალი ფერადი საბავშვო ბოთლით, რათა აქტიური მოძრაობის შემდეგ მისი ორგანიზმი არ გაუწყლოვდეს.'),
  ('d2e6d5c6-90cf-4a42-ae18-383c2c592a7c', 'მამიკოს ზღაპრის დრო. 👨‍🍼', 'დღეს საღამოს ზღაპრის წაკითხვა და ბავშვის დაძინება მამას მიანდეთ, თავად კი ცოტათი დაისვენეთ.'),
  ('4484d3ee-8677-4454-8e65-371ba851a267', 'თეთრი ხმაურის ძალა. 🎶', 'თუ აქტიური დღის შემდეგ დაძინება უჭირს, ჩართეთ ოკეანის ან წვიმის ხმა თეთრი ხმაურის ჩანაწერებიდან და ოთახში მშვიდი გარემო შექმენით.'),
  ('b03cef74-ad4c-4ee6-86e3-5d55fe15d1fd', 'ტკბილი ჩახუტებები! 🤗', 'როდესაც მოულოდნელად გეხუტებათ და თქვენს კოცნას ცდილობს, ასე თავის სიყვარულს გამოხატავს. დატკბით სიყვარულის ამ განუმეორებელი წუთებით!'),
  ('fb1bbc34-c7a1-41dc-b4eb-e7444cbade21', 'საუბარში ჩართეთ. 🗣', '️ დაასახელეთ ოთახში არსებული ნივთები და დაელოდეთ, სანამ ბავშვი გაიმეორებს. მისი ლექსიკური მარაგი სწორედ ასეთი პატარა თამაშებით მდიდრდება.'),
  ('35a5e175-d9f9-4d9a-9445-a523d64bc595', 'თავად სურს ჭამა. 🥦', 'თუნდაც დაისვაროს, მიეცით საშუალება, კოვზი თავად დაიჭიროს. ეს მას დამოუკიდებლობის განცდასა და თვალისა და ხელის კოორდინაციას განუვითარებს.'),
  ('66beeaaa-0b78-4114-b41f-8d7e6f407c55', 'დასვენება თქვენი უფლებაა. 🛁', 'მთელი დღე ფეხზე იყავით. ბავშვის დაძინების შემდეგ დაისხით ცხელი ჩაი და უბრალოდ სიმშვიდით დატკბით.'),
  ('979d3d6f-0938-49ad-b47d-0cedcf8c1cf6', 'სწრაფი ნაბიჯები! 🏃‍♂', '️ ის უკვე თავისუფლად დადის ოთახიდან ოთახში და სირბილსაც კი ცდილობს. მის კვალდაკვალ სირბილი დედებისთვის ნამდვილი ვარჯიშია!'),
  ('1008f62b-ef11-490d-886c-a80a06e64454', 'თვალი სად გაქვს? 👀', 'სხეულის ნაწილების ამოცნობა კვლავ ერთ-ერთი მისი საყვარელი თამაშია. ითამაშეთ სარკის წინ, რომ კიდევ უფრო სახალისო გახდეს.'),
  ('2ca5e024-95be-449a-af7e-ee34228f8bca', 'წინასწარ დაგეგმვა სიმშვიდეს მოგგვრით. 📝', 'პატარა ჩანაწერების სახით ჩამოწერეთ, რას გააკეთებთ ხვალ ან რას მოამზადებთ საჭმელად, შემდეგ კი მშვიდად დაწექით დასაძინებლად.'),
  ('efb1280f-e8f0-4ecf-bb77-385f667aff5d', 'სიმყუდროვის ძიებაში. ☕', 'ზოგჯერ სახლიდან გასვლა და გარემოს შეცვლა გინდათ. დედებისთვის მეგობრულ სივრცეებს შორის იპოვეთ ახლომდებარე კაფე, სადაც ბავშვთან ერთად კომფორტულად მიხვალთ, და ყავით დატკბით.'),
  ('47368a03-c0f0-4e5c-a343-b4577d2ffa64', 'ღამის სიმშვიდე 🛀', 'თბილი აბაზანა, მასაჟი და ოთახის ჩაბნელება. ძილის რეჟიმის დაცვა უწყვეტი ღამის ძილის მთავარი საიდუმლოა.'),
  ('8edf71cc-a90b-4465-947f-070adc35b5f7', 'ცეკვა მუსიკაზე 🎶', 'როგორც კი ტელევიზორში რიტმულ ხმას გაიგონებს, უკანალის ქნევას იწყებს. მუსიკის აღქმის უნარი ვითარდება — აჰყევით და მასთან ერთად იცეკვეთ!')
) AS v(id, t, b)
WHERE x.id = v.id;
